/**
 * Assumes `AccessTokenGuard` has already populated `request.currentUser`.
 * Compose them via `@UseGuards(AccessTokenGuard, AdminGuard)`.
 */
@Injectable()
export class AdminGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<Partial<AuthenticatedRequest>>();
    if (request.currentUser?.role !== UserRole.Admin) {
      throw new ForbiddenException('Administrator access is required.');
    }
    return true;
  }
