import type { StaffPermission } from '../entities/staff-profile.entity';

export const STAFF_PERMISSION_METADATA = 'requiredStaffPermission';

export const RequireStaffPermission = (
  permission: StaffPermission | readonly StaffPermission[],
): MethodDecorator & ClassDecorator => SetMetadata(STAFF_PERMISSION_METADATA, permission);import { CanActivate, ExecutionContext, ForbiddenException, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

import { type AuthenticatedRequest } from '../../authentication/guards/access-token.guard';
import { STAFF_PERMISSION_METADATA } from '../decorators/require-staff-permission.decorator';
import { StaffPermission, StaffProfileEntity } from '../entities/staff-profile.entity';

@Injectable()
export class StaffPermissionGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    @InjectRepository(StaffProfileEntity)
    private readonly staffProfiles: Repository<StaffProfileEntity>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const required = this.reflector.getAllAndOverride<
      StaffPermission | readonly StaffPermission[] | undefined
    >(STAFF_PERMISSION_METADATA, [context.getHandler(), context.getClass()]);
    if (!required) return true;
    const permissionsRequired = typeof required === 'string' ? [required] : required;

    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const profile = await this.staffProfiles.findOne({
      where: { userId: request.currentUser.id },
      relations: { role: true },
    });

    // Fail closed. A missing staff profile means the account has no verified
    // authorization record and must be denied instead of silently escalated to
    // super-admin. Legacy admins must be backfilled into staff_profiles with
    // an explicit super-admin role.
    if (!profile) {
      throw new ForbiddenException('Your account does not have the required permission.');
    }
    if (profile.role?.isSuperAdmin) return true;
    const permissions = profile.role?.permissions ?? profile.permissions;
    if (permissionsRequired.some((permission) => permissions.includes(permission))) return true;
    if (
      permissionsRequired.includes(StaffPermission.StaffRead) &&
      permissions.includes(StaffPermission.StaffManage)
    ) {
      return true;
    }
    if (
      permissionsRequired.includes(StaffPermission.OrdersRead) &&
      permissions.includes(StaffPermission.OrdersManage)
    ) {
      return true;
    }
    if (
      permissionsRequired.includes(StaffPermission.CatalogRead) &&
      permissions.includes(StaffPermission.CatalogManage)
    ) {
      return true;
    }
    if (
      permissionsRequired.includes(StaffPermission.FinanceRead) &&
      permissions.includes(StaffPermission.FinanceManage)
    ) {
      return true;
    }
    throw new ForbiddenException('Your account does not have the required permission.');
  }
}import { BadRequestException, Injectable, InternalServerErrorException } from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource, type EntityManager } from 'typeorm';

import {
  type AuditLogListResponseDto,
  type AuditLogResponseDto,
  type ListAuditLogsQueryDto,
} from '../dto/audit-log.dto';
import { AuditLogCategory } from '../entities/admin-audit-log.entity';
import { type AuditRequestContext } from './audit-request-context';

interface AuditLogRow {
  id: string;
  actor_id: string | null;
  actor_label: string;
  action: string;
  category: AuditLogCategory;
  target_type: string;
  target_id: string | null;
  target_label: string;
  details: Record<string, unknown>;
  ip_address: string | null;
  user_agent: string | null;
  correlation_id: string | null;
  created_at: Date | string;
}

interface AuditCursor {
  createdAt: string;
  id: string;
}

export interface AppendAuditLogInput {
  actorId: string;
  action: string;
  category: AuditLogCategory;
  targetType: string;
  targetId: string | null;
  targetLabel: string;
  details?: Record<string, unknown>;
  context?: AuditRequestContext | undefined;
}

@Injectable()
export class AuditLogService {
  constructor(@InjectDataSource() private readonly dataSource: DataSource) {}

  async append(manager: EntityManager, input: AppendAuditLogInput): Promise<void> {
    const result = await manager.query<unknown>(
      `INSERT INTO admin_audit_logs
         (actor_id, actor_label, action, category, target_type, target_id,
          target_label, details, ip_address, user_agent, correlation_id)
       SELECT u.id, left(COALESCE(NULLIF(u.display_name, ''), u.email::text), 160),
              $2, $3, $4, $5, $6, $7::jsonb, $8::inet, $9, $10
       FROM users u WHERE u.id = $1
       RETURNING id`,
      [
        input.actorId,
        input.action,
        input.category,
        input.targetType,
        input.targetId,
        input.targetLabel.slice(0, 160),
        JSON.stringify(input.details ?? {}),
        input.context?.ipAddress ?? null,
        input.context?.userAgent ?? null,
        input.context?.correlationId ?? null,
      ],
    );
    const returnedRows = Array.isArray(result) && Array.isArray(result[0]) ? result[0] : result;
    if (!Array.isArray(returnedRows) || returnedRows.length === 0) {
      throw new InternalServerErrorException('The administrative action could not be audited.');
    }
  }

  async list(query: ListAuditLogsQueryDto): Promise<AuditLogListResponseDto> {
    if (query.from && query.to && new Date(query.from) > new Date(query.to)) {
      throw new BadRequestException('The start date must not be after the end date.');
    }
    const parameters: unknown[] = [];
    const conditions: string[] = [];
    const add = (value: unknown): string => {
      parameters.push(value);
      return `$${String(parameters.length)}`;
    };

    if (query.category) conditions.push(`category = ${add(query.category)}`);
    if (query.actorId) conditions.push(`actor_id = ${add(query.actorId)}`);
    if (query.from) conditions.push(`created_at >= ${add(query.from)}::timestamptz`);
    if (query.to) conditions.push(`created_at <= ${add(query.to)}::timestamptz`);
    if (query.search) {
      conditions.push(`search_document @@ websearch_to_tsquery('simple', ${add(query.search)})`);
    }
    if (query.cursor) {
      const cursor = this.decodeCursor(query.cursor);
      const createdAt = add(cursor.createdAt);
      const id = add(cursor.id);
      conditions.push(`(created_at, id) < (${createdAt}::timestamptz, ${id}::uuid)`);
    }

    const limitParameter = add(query.limit + 1);
    const rows = await this.dataSource.query<AuditLogRow[]>(
      `SELECT id, actor_id, actor_label, action, category, target_type, target_id,
              target_label, details, host(ip_address) AS ip_address, user_agent,
              correlation_id, created_at
       FROM admin_audit_logs
       ${conditions.length === 0 ? '' : `WHERE ${conditions.join(' AND ')}`}
       ORDER BY created_at DESC, id DESC
       LIMIT ${limitParameter}`,
      parameters,
    );
    const hasMore = rows.length > query.limit;
    const page = rows.slice(0, query.limit);
    const last = page.at(-1);
    return {
      items: page.map((row) => this.mapRow(row)),
      nextCursor:
        hasMore && last
          ? this.encodeCursor({ createdAt: new Date(last.created_at).toISOString(), id: last.id })
          : null,
    };
  }

  private mapRow(row: AuditLogRow): AuditLogResponseDto {
    return {
      id: row.id,
      actorId: row.actor_id,
      actorLabel: row.actor_label,
      action: row.action,
      category: row.category,
      targetType: row.target_type,
      targetId: row.target_id,
      targetLabel: row.target_label,
      details: row.details,
      ipAddress: row.ip_address,
      userAgent: row.user_agent,
      correlationId: row.correlation_id,
      createdAt: new Date(row.created_at).toISOString(),
    };
  }

  private encodeCursor(cursor: AuditCursor): string {
    return Buffer.from(JSON.stringify(cursor), 'utf8').toString('base64url');
  }

  private decodeCursor(value: string): AuditCursor {
    try {
      const decoded = JSON.parse(
        Buffer.from(value, 'base64url').toString('utf8'),
      ) as Partial<AuditCursor>;
      if (
        typeof decoded.createdAt !== 'string' ||
        Number.isNaN(Date.parse(decoded.createdAt)) ||
        typeof decoded.id !== 'string' ||
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
          decoded.id,
        )
      ) {
        throw new Error('Invalid cursor.');
      }
      return { createdAt: decoded.createdAt, id: decoded.id };
    } catch {
      throw new BadRequestException('The audit log cursor is invalid.');
    }
  }
