@Controller('v1/admin/finance/commission-billing')
@UseGuards(AccessTokenGuard, AdminGuard, StaffPermissionGuard)
export class AdminCommissionController {
  constructor(
    private readonly billing: CommissionBillingService,
    private readonly payments: CommissionPaymentsService,
    private readonly generator: CommissionStatementGenerator,
  ) {}
  @Get('settings')
  @RequireStaffPermission(StaffPermission.FinanceRead)
  settings(): Promise<BillingRow> {
    return this.billing.settings();
  }
  @Patch('settings') @RequireStaffPermission(StaffPermission.FinanceManage) update(
    @CurrentUser() u: UserEntity,
    @Body() dto: CommissionSettingsDto,
  ): Promise<BillingRow> {
    return this.billing.updateSettings(u.id, dto);
  }
  @Get('payment-methods')
  @RequireStaffPermission(StaffPermission.FinanceRead)
  async methods(): Promise<BillingRow> {
    return { items: await this.billing.methods(), nextCursor: null };
  }
  @Post('payment-methods') @RequireStaffPermission(StaffPermission.FinanceManage) create(
    @CurrentUser() u: UserEntity,
    @Body() dto: CompanyPaymentMethodDto,
  ): Promise<BillingRow> {
    return this.billing.upsertMethod(u.id, dto.idempotencyKey, dto, true);
  }
  @Patch('payment-methods/:id') @RequireStaffPermission(StaffPermission.FinanceManage) method(
    @CurrentUser() u: UserEntity,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: CompanyPaymentMethodDto,
  ): Promise<BillingRow> {
    return this.billing.upsertMethod(u.id, id, dto);
  }
  @Get('submissions') @RequireStaffPermission(StaffPermission.FinanceRead) submissions(
    @Query() q: BillingPageQueryDto,
  ): Promise<BillingRow> {
    return this.billing.submissions(q);
  }
  @Get('submissions/:id') @RequireStaffPermission(StaffPermission.FinanceRead) submission(
    @Param('id', ParseUUIDPipe) id: string,
  ): Promise<BillingRow> {
    return this.payments.detail(id);
  }
  @Patch('submissions/:id/review') @RequireStaffPermission(StaffPermission.FinanceManage) review(
    @CurrentUser() u: UserEntity,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: ReviewCommissionDto,
  ): Promise<BillingRow> {
    return this.payments.review(u.id, id, dto);
  }
  @Get('statements') @RequireStaffPermission(StaffPermission.FinanceRead) statements(
    @Query() q: BillingPageQueryDto,
  ): Promise<BillingRow> {
    return this.billing.statements(q);
  }
  @Get('statements/:id') @RequireStaffPermission(StaffPermission.FinanceRead) statement(
    @Param('id', ParseUUIDPipe) id: string,
  ): Promise<BillingRow> {
    return this.billing.statement(id);
  }
  @Patch('statements/:id/waive') @RequireStaffPermission(StaffPermission.FinanceManage) waive(
    @CurrentUser() u: UserEntity,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: WaiveCommissionDto,
  ): Promise<BillingRow> {
    return this.billing.waive(u.id, id, dto);
  }
  @Post('statements/generate') @RequireStaffPermission(StaffPermission.FinanceManage) generate(
    @CurrentUser() u: UserEntity,
    @Body() dto: GenerateCommissionDto,
  ): Promise<BillingRow> {
    return this.generator.generate(dto.periodMonth, u.id, dto.idempotencyKey);
  }
}import { type BillingRow } from '../services/commission-billing.service';
