@Controller('v1/technician/commission')
@UseGuards(AccessTokenGuard, ApprovedTechnicianGuard)
export class TechnicianCommissionController {
  constructor(
    private readonly billing: CommissionBillingService,
    private readonly payments: CommissionPaymentsService,
  ) {}
  @Get('summary') summary(@CurrentUser() u: UserEntity): Promise<BillingRow> {
    return this.billing.summary(u.id);
  }
  @Get('current-month') current(@CurrentUser() u: UserEntity): Promise<BillingRow> {
    return this.billing.currentMonth(u.id);
  }
  @Get('payment-methods') methods(): Promise<BillingRow[]> {
    return this.billing.methods(true);
  }
  @Get('statements') statements(
    @CurrentUser() u: UserEntity,
    @Query() q: BillingPageQueryDto,
  ): Promise<BillingRow> {
    return this.billing.statements(q, u.id);
  }
  @Get('statements/:id') statement(
    @CurrentUser() u: UserEntity,
    @Param('id', ParseUUIDPipe) id: string,
  ): Promise<BillingRow> {
    return this.billing.statement(id, u.id);
  }
  @Post('statements/:id/submissions') submit(
    @CurrentUser() u: UserEntity,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: CommissionSubmissionDto,
  ): Promise<BillingRow> {
    return this.payments.submit(u.id, id, dto);
  }
