export class BillingCommandDto {
  @IsUUID() idempotencyKey!: string;
  @IsInt() @Min(1) version!: number;
}
export class CommissionSettingsDto extends BillingCommandDto {
  @IsInt() @Min(0) @Max(5000) commissionBps!: number;
  @IsInt() @Min(1) @Max(168) reviewSlaHours!: number;
}
export class CompanyPaymentMethodDto extends BillingCommandDto {
  @IsIn([
    'vodafone_cash',
    'etisalat_cash',
    'orange_cash',
    'we_pay',
    'instapay',
    'bank_account',
    'other_wallet',
  ])
  methodType!: string;
  @Transform(({ value }: { value: unknown }) => (typeof value === 'string' ? value.trim() : value))
  @IsString()
  @MinLength(1)
  @MaxLength(120)
  label!: string;
  @Transform(({ value }: { value: unknown }) => (typeof value === 'string' ? value.trim() : value))
  @IsString()
  @MinLength(1)
  @MaxLength(160)
  accountValue!: string;
  @Transform(({ value }: { value: unknown }) => (typeof value === 'string' ? value.trim() : value))
  @IsString()
  @MinLength(1)
  @MaxLength(160)
  accountHolder!: string;
  @IsOptional() @IsString() @MaxLength(1000) instructions?: string;
  @IsBoolean() isActive!: boolean;
  @IsInt() @Min(-32768) @Max(32767) sortOrder!: number;
}
export class CommissionSubmissionDto {
  @IsUUID() paymentMethodId!: string;
  @IsUUID() proofFileId!: string;
  @IsUUID() idempotencyKey!: string;
  @IsOptional() @IsString() @MaxLength(160) senderAccount?: string;
  @IsOptional() @IsString() @MaxLength(120) transferReference?: string;
  @IsOptional() @IsString() @MaxLength(500) note?: string;
}
export class ReviewCommissionDto extends BillingCommandDto {
  @IsIn(['approve', 'reject']) decision!: 'approve' | 'reject';
  @IsOptional() @IsString() @MaxLength(500) reason?: string;
}
export class WaiveCommissionDto extends BillingCommandDto {
  @IsString() @MinLength(1) @MaxLength(500) reason!: string;
}
export class GenerateCommissionDto {
  @Matches(/^\d{4}-(0[1-9]|1[0-2])-01$/) periodMonth!: string;
  @IsUUID() idempotencyKey!: string;
}
export class BillingPageQueryDto {
  @IsOptional() @IsString() @MaxLength(500) cursor?: string;
  @IsOptional()
  @IsIn(['due', 'under_review', 'paid', 'waived', 'pending', 'approved', 'rejected'])
  status?: string;
  @IsOptional() @Matches(/^\d{4}-(0[1-9]|1[0-2])-01$/) periodMonth?: string;
  @Type(() => Number) @IsInt() @Min(1) @Max(100) limit = 30;
}import { type EntityManager } from 'typeorm';
export async function queueBillingNotification(
  manager: EntityManager,
  event: string,
  id: string,
  recipient: string,
  body: string,
  payload: Record<string, unknown> = {},
): Promise<void> {
  await manager.query(
    `INSERT INTO domain_event_outbox(event_type,aggregate_id,recipients,payload)
    VALUES($1,$2,jsonb_build_array(jsonb_build_object('kind',(SELECT role::text FROM users WHERE id=$3::uuid),'id',$3::text)),$4::jsonb)`,
    [event, id, recipient, JSON.stringify({ statementId: id, notificationBody: body, ...payload })],
  );
  await manager.query(
    `INSERT INTO user_notifications(user_id,type,title_ar,body_ar,data) VALUES($1,$2,'مستحقات المنصة',$3,$4::jsonb)`,
    [recipient, event, body, JSON.stringify({ statementId: id, ...payload })],
  );
}import { queueBillingNotification } from './billing-notifications';
import { randomUUID } from 'node:crypto';
import {
  BadRequestException,
  ConflictException,
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { DataSource, type EntityManager } from 'typeorm';
import { queryRows } from '../../../common/database/query-rows';
import { AuditLogService } from '../../administration/services/audit-log.service';
import { AuditLogCategory } from '../../administration/entities/admin-audit-log.entity';
import {
  type BillingPageQueryDto,
  type CommissionSettingsDto,
  type CompanyPaymentMethodDto,
  type WaiveCommissionDto,
} from '../dto/commission-billing.dto';

export type BillingRow = Record<string, unknown>;
export function requiredBillingRow(row: BillingRow | undefined): BillingRow {
  if (!row)
    throw new InternalServerErrorException({
      code: 'BILLING_UNAVAILABLE',
      message: 'تعذر تحميل بيانات المستحقات. حاول تاني.',
    });
  return row;
}
export function commissionMinor(labor: string | bigint, bps: number): bigint {
  return (BigInt(labor) * BigInt(bps) + 5000n) / 10000n;
}
export function moneyNumber(value: unknown): number {
  const n = Number(value ?? 0);
  if (!Number.isSafeInteger(n))
    throw new BadRequestException({
      code: 'MONEY_OUT_OF_RANGE',
      message: 'المبلغ أكبر من الحد المسموح.',
    });
  return n;
}
export function billingDto(row: BillingRow): BillingRow {
  return Object.fromEntries(
    Object.entries(row).map(([key, value]) => [
      key.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase()),
      key.endsWith('_minor') || key === 'statement_number' ? moneyNumber(value) : value,
    ]),
  );
}
export function periodLabel(value: unknown): string {
  return new Intl.DateTimeFormat('ar-EG', {
    month: 'long',
    year: 'numeric',
    timeZone: 'Africa/Cairo',
  }).format(
    new Date(
      `${(value instanceof Date ? value.toISOString() : String(value)).slice(0, 10)}T12:00:00Z`,
    ),
  );
}
// Both the preview and generator use these exact eligibility predicates.
export const BILLABLE_ORDERS = `o.status='completed' AND o.agreed_labor_minor>0
  AND (o.completed_at AT TIME ZONE 'Africa/Cairo') >= $2::date
  AND (o.completed_at AT TIME ZONE 'Africa/Cairo') < $2::date + interval '1 month'
  AND NOT EXISTS(SELECT 1 FROM technician_commission_statement_items i WHERE i.order_id=o.id)`;

@Injectable()
export class CommissionBillingService {
  constructor(
    readonly db: DataSource,
    readonly audit: AuditLogService,
  ) {}
  async settings(manager: EntityManager = this.db.manager): Promise<BillingRow> {
    const [row] = await manager.query<BillingRow[]>(
      'SELECT * FROM platform_commission_settings WHERE id=1',
    );
    return billingDto(requiredBillingRow(row));
  }
  async claimCommand(
    manager: EntityManager,
    actor: string,
    key: string,
    command: string,
    target: string,
  ): Promise<boolean> {
    const rows = await manager.query<BillingRow[]>(
      `INSERT INTO finance_admin_commands(actor_id,idempotency_key,command_type,target_id)
      VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING RETURNING target_id`,
      [actor, key, command, target],
    );
    if (rows.length) return false;
    const [old] = await manager.query<BillingRow[]>(
      'SELECT command_type,target_id FROM finance_admin_commands WHERE actor_id=$1 AND idempotency_key=$2',
      [actor, key],
    );
    if (old?.command_type !== command || old.target_id !== target)
      throw new ConflictException({
        code: 'IDEMPOTENCY_KEY_REUSED',
        message: 'مفتاح العملية مستخدم قبل كده لعملية تانية.',
      });
    return true;
  }
  async record(
    manager: EntityManager,
    actor: string,
    action: string,
    target: string | null,
    details: BillingRow = {},
  ): Promise<void> {
    await this.audit.append(manager, {
      actorId: actor,
      action,
      category: AuditLogCategory.Update,
      targetType: 'commission_billing',
      targetId: target,
      targetLabel: target ?? 'إعدادات العمولة',
      details,
    });
  }
  async summary(tech: string): Promise<BillingRow> {
    const due = await this.db.query<BillingRow[]>(
      `SELECT * FROM technician_commission_statements WHERE technician_id=$1
      AND status IN ('due','under_review') AND amount_due_minor>0 ORDER BY period_month,id`,
      [tech],
    );
    const first = due[0];
    const [latest] = await this.db.query<BillingRow[]>(
      `SELECT * FROM commission_payment_submissions WHERE technician_id=$1
      ${first ? 'AND statement_id=$2' : ''} ORDER BY created_at DESC,id DESC LIMIT 1`,
      first ? [tech, first.id] : [tech],
    );
    const latestSubmission = latest
      ? {
          id: latest.id,
          status: latest.status,
          submittedAt: latest.created_at,
          reviewDueAt: latest.review_due_at,
          rejectionReason: latest.rejection_reason,
          reviewedAt: latest.reviewed_at,
        }
      : null;
    return {
      blocked: due.length > 0,
      state: !first
        ? 'clear'
        : first.status === 'under_review'
          ? 'under_review'
          : latest?.status === 'rejected'
            ? 'rejected'
            : 'due',
      totalDueMinor: moneyNumber(
        due.reduce((sum, r) => sum + BigInt(String(r.amount_due_minor)), 0n),
      ),
      currency: 'EGP',
      commissionBps: (await this.settings()).commissionBps,
      oldestDueStatementId: first?.id ?? null,
      periodLabel: first ? periodLabel(first.period_month) : null,
      latestSubmission,
    };
  }
  async currentMonth(tech: string): Promise<BillingRow> {
    const [month] = await this.db.query<Array<{ month: string }>>(
      `SELECT to_char(now() AT TIME ZONE 'Africa/Cairo','YYYY-MM-01') AS "month"`,
    );
    const [row] = await this.db.query<BillingRow[]>(
      `SELECT count(*)::int orders_count,COALESCE(sum(o.agreed_labor_minor),0)::text labor_total_minor
      FROM service_orders o WHERE o.technician_id=$1 AND ${BILLABLE_ORDERS}`,
      [tech, requiredBillingRow(month).month],
    );
    const settings = await this.settings();
    return {
      ...billingDto(requiredBillingRow(row)),
      commissionBps: settings.commissionBps,
      estimatedCommissionMinor: moneyNumber(
        commissionMinor(
          String(requiredBillingRow(row).labor_total_minor),
          Number(settings.commissionBps),
        ),
      ),
      currency: 'EGP',
    };
  }
  async methods(activeOnly = false): Promise<BillingRow[]> {
    return (
      await this.db.query<BillingRow[]>(
        `SELECT * FROM company_payment_methods ${activeOnly ? 'WHERE is_active' : ''} ORDER BY sort_order,id`,
      )
    ).map(billingDto);
  }
  async statements(query: BillingPageQueryDto, tech?: string): Promise<BillingRow> {
    return await this.page('technician_commission_statements', query, tech);
  }
  async submissions(query: BillingPageQueryDto): Promise<BillingRow> {
    const page = await this.page('commission_payment_submissions', query);
    const [count] = await this.db.query<Array<{ count: string }>>(
      `SELECT count(*)::text count FROM commission_payment_submissions WHERE status='pending'`,
    );
    return { ...page, pendingCount: moneyNumber(count?.count) };
  }
  private async page(
    table: 'technician_commission_statements' | 'commission_payment_submissions',
    query: BillingPageQueryDto,
    tech?: string,
  ): Promise<BillingRow> {
    const params: unknown[] = [];
    const where: string[] = [];
    const add = (v: unknown): string => {
      params.push(v);
      return '$' + String(params.length);
    };
    const submissions = table === 'commission_payment_submissions';
    const sort = submissions ? 'review_due_at' : 'created_at';
    if (tech) where.push(`r.technician_id=${add(tech)}`);
    if (query.status) where.push(`r.status=${add(query.status)}`);
    if (query.periodMonth && !submissions)
      where.push(`r.period_month=${add(query.periodMonth)}::date`);
    if (query.cursor) {
      try {
        const c = JSON.parse(Buffer.from(query.cursor, 'base64url').toString()) as {
          at: string;
          id: string;
        };
        if (!c.at || !c.id || !Number.isFinite(Date.parse(c.at)) || !/^[a-f\d-]{36}$/i.test(c.id))
          throw new Error();
        where.push(
          `(r.${sort},r.id) ${submissions ? '>' : '<'} (${add(c.at)}::timestamptz,${add(c.id)}::uuid)`,
        );
      } catch {
        throw new BadRequestException({
          code: 'INVALID_CURSOR',
          message: 'بيانات الصفحة مش صحيحة.',
        });
      }
    }
    const rows = await this.db.query<BillingRow[]>(
      `SELECT r.*,u.display_name technician_name,u.phone technician_phone ${submissions ? ',m.label payment_method_label' : ",to_char(r.period_month,'YYYY-MM-DD') period_month"}
      FROM ${table} r JOIN users u ON u.id=r.technician_id ${submissions ? 'JOIN company_payment_methods m ON m.id=r.payment_method_id' : ''} ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
      ORDER BY r.${sort} ${submissions ? 'ASC' : 'DESC'},r.id ${submissions ? 'ASC' : 'DESC'} LIMIT ${add(query.limit + 1)}`,
      params,
    );
    const items = rows.slice(0, query.limit);
    const last = items.at(-1);
    return {
      items: items.map((row) =>
        submissions
          ? billingDto(row)
          : { ...billingDto(row), periodLabel: periodLabel(row.period_month) },
      ),
      nextCursor:
        rows.length > query.limit && last
          ? Buffer.from(JSON.stringify({ at: last[sort], id: last.id })).toString('base64url')
          : null,
    };
  }
  async statement(id: string, tech?: string): Promise<BillingRow> {
    const [row] = await this.db.query<BillingRow[]>(
      `SELECT *,to_char(period_month,'YYYY-MM-DD') period_month FROM technician_commission_statements WHERE id=$1 ${tech ? 'AND technician_id=$2' : ''}`,
      tech ? [id, tech] : [id],
    );
    if (!row)
      throw new NotFoundException({ code: 'STATEMENT_NOT_FOUND', message: 'كشف الحساب مش موجود.' });
    const items = await this.db.query<BillingRow[]>(
      `SELECT i.*,o.order_number,s.title_ar service_name FROM technician_commission_statement_items i JOIN service_orders o ON o.id=i.order_id LEFT JOIN services s ON s.id=o.service_id WHERE i.statement_id=$1 ORDER BY i.completed_at,i.order_id`,
      [id],
    );
    const submissions = await this.db.query<BillingRow[]>(
      'SELECT * FROM commission_payment_submissions WHERE statement_id=$1 ORDER BY created_at DESC,id DESC',
      [id],
    );
    return {
      ...billingDto(row),
      periodLabel: periodLabel(row.period_month),
      items: items.map(billingDto),
      submissions: submissions.map(billingDto),
    };
  }
  async updateSettings(actor: string, dto: CommissionSettingsDto): Promise<BillingRow> {
    return await this.db.transaction(async (m) => {
      const target = '00000000-0000-0000-0000-000000000001';
      if (
        await this.claimCommand(m, actor, dto.idempotencyKey, 'commission.settings.update', target)
      )
        return await this.settings(m);
      const rows = queryRows<BillingRow>(
        await m.query(
          `UPDATE platform_commission_settings SET commission_bps=$1,review_sla_hours=$2,updated_by=$3,version=version+1,updated_at=now() WHERE id=1 AND version=$4 RETURNING *`,
          [dto.commissionBps, dto.reviewSlaHours, actor, dto.version],
        ),
      );
      if (!rows[0]) this.stale();
      await this.record(m, actor, 'commission.settings.update', null, {
        commissionBps: dto.commissionBps,
        reviewSlaHours: dto.reviewSlaHours,
      });
      return billingDto(rows[0]);
    });
  }
  async upsertMethod(
    actor: string,
    id: string,
    dto: CompanyPaymentMethodDto,
    create = false,
  ): Promise<BillingRow> {
    return await this.db.transaction(async (m) => {
      if (create) {
        await m.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [
          `commission-method-create:${actor}:${dto.idempotencyKey}`,
        ]);
        const [command] = await m.query<Array<{ target_id: string }>>(
          'SELECT target_id FROM finance_admin_commands WHERE actor_id=$1 AND idempotency_key=$2',
          [actor, dto.idempotencyKey],
        );
        id = command?.target_id ?? randomUUID();
      }
      if (await this.claimCommand(m, actor, dto.idempotencyKey, 'commission.method.upsert', id)) {
        const [old] = await m.query<BillingRow[]>(
          'SELECT * FROM company_payment_methods WHERE id=$1',
          [id],
        );
        return billingDto(requiredBillingRow(old));
      }
      const values = [
        id,
        dto.methodType,
        dto.label.trim(),
        dto.accountValue.trim(),
        dto.accountHolder.trim(),
        dto.instructions ?? null,
        dto.isActive,
        dto.sortOrder,
        actor,
      ];
      const rows = queryRows<BillingRow>(
        await m.query(
          create
            ? `INSERT INTO company_payment_methods(id,method_type,label,account_value,account_holder,instructions,is_active,sort_order,created_by)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`
            : `UPDATE company_payment_methods SET method_type=$2,label=$3,account_value=$4,account_holder=$5,instructions=$6,is_active=$7,sort_order=$8,updated_at=now(),version=version+1 WHERE id=$1 AND version=$10 AND $9::uuid IS NOT NULL RETURNING *`,
          create ? values : [...values, dto.version],
        ),
      );
      if (!rows[0]) this.stale();
      await this.record(m, actor, 'commission.method.upsert', id);
      return billingDto(rows[0]);
    });
  }
  async waive(actor: string, id: string, dto: WaiveCommissionDto): Promise<BillingRow> {
    if (!dto.reason.trim())
      throw new BadRequestException({ code: 'REASON_REQUIRED', message: 'اكتب سبب الإعفاء.' });
    return await this.db.transaction(async (m) => {
      if (await this.claimCommand(m, actor, dto.idempotencyKey, 'commission.statement.waive', id)) {
        const [r] = await m.query<BillingRow[]>(
          'SELECT * FROM technician_commission_statements WHERE id=$1',
          [id],
        );
        return billingDto(requiredBillingRow(r));
      }
      const rows = queryRows<BillingRow>(
        await m.query(
          `UPDATE technician_commission_statements SET status='waived',waived_by=$2,waive_reason=$3,version=version+1,updated_at=now() WHERE id=$1 AND version=$4 AND status IN ('due','under_review') RETURNING *`,
          [id, actor, dto.reason.trim(), dto.version],
        ),
      );
      if (!rows[0]) this.stale();
      const closed = queryRows<BillingRow>(
        await m.query(
          `UPDATE commission_payment_submissions SET status='rejected',rejection_reason=$3,reviewed_by=$2,reviewed_at=now(),version=version+1,updated_at=now() WHERE statement_id=$1 AND status='pending' RETURNING id`,
          [id, actor, `تم إعفاء كشف الحساب: ${dto.reason.trim()}`.slice(0, 500)],
        ),
      );
      for (const proof of closed)
        await this.record(m, actor, 'commission.submission.reject', String(proof.id), {
          statementId: id,
          reason: 'statement_waived',
          idempotencyKey: dto.idempotencyKey,
        });
      await this.record(m, actor, 'commission.statement.waive', id, { reason: dto.reason });
      await queueBillingNotification(
        m,
        'billing.statement_waived',
        id,
        String(rows[0].technician_id),
        'تم إعفاؤك من مستحقات كشف الحساب.',
        { reason: dto.reason },
      );
      return billingDto(rows[0]);
    });
  }
  stale(): never {
    throw new ConflictException({
      code: 'VERSION_CONFLICT',
      message: 'البيانات اتغيرت. حدّث الصفحة وحاول تاني.',
    });
  }
}import { ForbiddenException } from '@nestjs/common';
import { type EntityManager } from 'typeorm';

export async function assertNotBillingBlocked(
  manager: EntityManager,
  technicianId: string,
): Promise<void> {
  const [row] = await manager.query<Array<{ blocked: boolean }>>(
    'SELECT technician_billing_blocked($1) AS blocked',
    [technicianId],
  );
  if (row?.blocked)
    throw new ForbiddenException({
      code: 'COMMISSION_PAYMENT_REQUIRED',
      message: 'يرجى سداد مستحقات المنصة لتستمر الخدمة.',
    });
}import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import {
  CommissionBillingService,
  billingDto,
  requiredBillingRow,
  type BillingRow,
} from './commission-billing.service';
import {
  type CommissionSubmissionDto,
  type ReviewCommissionDto,
} from '../dto/commission-billing.dto';
import { FilesService } from '../../files/files.service';
import { queueBillingNotification } from './billing-notifications';
import { queryRows } from '../../../common/database/query-rows';

@Injectable()
export class CommissionPaymentsService {
  constructor(
    private readonly billing: CommissionBillingService,
    private readonly files: FilesService,
  ) {}
  async submit(tech: string, id: string, dto: CommissionSubmissionDto): Promise<BillingRow> {
    return await this.billing.db.transaction(async (m) => {
      await m.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [tech]);
      const [s] = await m.query<BillingRow[]>(
        'SELECT * FROM technician_commission_statements WHERE id=$1 AND technician_id=$2 FOR UPDATE',
        [id, tech],
      );
      if (!s)
        throw new NotFoundException({
          code: 'STATEMENT_NOT_FOUND',
          message: 'كشف الحساب مش موجود.',
        });
      const [old] = await m.query<BillingRow[]>(
        'SELECT * FROM commission_payment_submissions WHERE technician_id=$1 AND idempotency_key=$2',
        [tech, dto.idempotencyKey],
      );
      if (old) {
        if (old.statement_id !== id)
          throw new ConflictException({
            code: 'IDEMPOTENCY_KEY_REUSED',
            message: 'مفتاح العملية مستخدم لكشف تاني.',
          });
        return billingDto(old);
      }
      if (s.status === 'under_review')
        throw new ConflictException({
          code: 'SUBMISSION_ALREADY_PENDING',
          message: 'إثبات الدفع قيد المراجعة بالفعل.',
        });
      if (s.status !== 'due')
        throw new ConflictException({
          code: 'STATEMENT_ALREADY_SETTLED',
          message: 'كشف الحساب متسدد بالفعل.',
        });
      const [method] = await m.query<BillingRow[]>(
        'SELECT id FROM company_payment_methods WHERE id=$1 AND is_active FOR SHARE',
        [dto.paymentMethodId],
      );
      if (!method)
        throw new BadRequestException({
          code: 'PAYMENT_METHOD_INACTIVE',
          message: 'اختار طريقة دفع متاحة.',
        });
      await this.files.assertCommissionPaymentProof(m, tech, dto.proofFileId);
      const [row] = await m.query<BillingRow[]>(
        `INSERT INTO commission_payment_submissions(statement_id,technician_id,payment_method_id,proof_file_id,amount_minor,sender_account,transfer_reference,note,review_due_at,idempotency_key)
        SELECT $1,$2,$3,$4,$5,$6,$7,$8,now()+make_interval(hours=>review_sla_hours),$9 FROM platform_commission_settings WHERE id=1 RETURNING *`,
        [
          id,
          tech,
          dto.paymentMethodId,
          dto.proofFileId,
          String(s.amount_due_minor),
          dto.senderAccount ?? null,
          dto.transferReference ?? null,
          dto.note ?? null,
          dto.idempotencyKey,
        ],
      );
      const updated = queryRows<BillingRow>(
        await m.query(
          `UPDATE technician_commission_statements SET status='under_review',version=version+1,updated_at=now() WHERE id=$1 AND version=$2 RETURNING id`,
          [id, s.version],
        ),
      );
      if (!updated.length) this.billing.stale();
      await this.billing.record(
        m,
        tech,
        'commission.submission.create',
        String(requiredBillingRow(row).id),
        {
          statementId: id,
          idempotencyKey: dto.idempotencyKey,
        },
      );
      // Admin recipients use the same verified role/permission records as StaffPermissionGuard.
      const admins = await m.query<
        Array<{ user_id: string }>
      >(`SELECT sp.user_id FROM staff_profiles sp LEFT JOIN admin_roles r ON r.id=sp.role_id JOIN users u ON u.id=sp.user_id
        WHERE u.status='active' AND u.deleted_at IS NULL AND (r.is_super_admin OR 'finance.read'=ANY(COALESCE(r.permissions,sp.permissions)) OR 'finance.manage'=ANY(COALESCE(r.permissions,sp.permissions)))`);
      const [sender] = await m.query<Array<{ display_name: string }>>(
        'SELECT display_name FROM users WHERE id=$1',
        [tech],
      );
      for (const a of admins)
        await queueBillingNotification(
          m,
          'billing.submission_received',
          id,
          a.user_id,
          `إثبات دفع جديد من ${sender?.display_name ?? 'فني'} بمبلغ ${String(Number(s.amount_due_minor) / 100)} ج.م`,
          { submissionId: requiredBillingRow(row).id, technicianId: tech },
        );
      return billingDto(requiredBillingRow(row));
    });
  }
  async detail(id: string): Promise<BillingRow> {
    const [row] = await this.billing.db.query<BillingRow[]>(
      `SELECT p.*,u.display_name technician_name,u.phone technician_phone,
      m.method_type,m.label,m.account_value,m.account_holder,m.instructions FROM commission_payment_submissions p
      JOIN users u ON u.id=p.technician_id JOIN company_payment_methods m ON m.id=p.payment_method_id WHERE p.id=$1`,
      [id],
    );
    if (!row)
      throw new NotFoundException({
        code: 'SUBMISSION_NOT_FOUND',
        message: 'إثبات الدفع مش موجود.',
      });
    return {
      ...billingDto(row),
      proof: await this.files.createCommissionProofDownload(String(row.proof_file_id)),
    };
  }
  async review(actor: string, id: string, dto: ReviewCommissionDto): Promise<BillingRow> {
    if (dto.decision === 'reject' && !dto.reason?.trim())
      throw new BadRequestException({ code: 'REASON_REQUIRED', message: 'اكتب سبب رفض التحويل.' });
    return await this.billing.db.transaction(async (m) => {
      if (
        await this.billing.claimCommand(
          m,
          actor,
          dto.idempotencyKey,
          `commission.submission.${dto.decision}`,
          id,
        )
      ) {
        const [old] = await m.query<BillingRow[]>(
          'SELECT * FROM commission_payment_submissions WHERE id=$1',
          [id],
        );
        return billingDto(requiredBillingRow(old));
      }
      const [located] = await m.query<BillingRow[]>(
        'SELECT statement_id,technician_id FROM commission_payment_submissions WHERE id=$1',
        [id],
      );
      if (!located)
        throw new NotFoundException({
          code: 'SUBMISSION_NOT_FOUND',
          message: 'إثبات الدفع مش موجود.',
        });
      await m.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [
        located.technician_id,
      ]);
      const [s] = await m.query<BillingRow[]>(
        'SELECT * FROM technician_commission_statements WHERE id=$1 FOR UPDATE',
        [located.statement_id],
      );
      const [p] = await m.query<BillingRow[]>(
        'SELECT * FROM commission_payment_submissions WHERE id=$1 FOR UPDATE',
        [id],
      );
      if (p?.status !== 'pending' || p.version !== dto.version || s?.status !== 'under_review')
        this.billing.stale();
      const approved = dto.decision === 'approve';
      const [result] = queryRows<BillingRow>(
        await m.query(
          `UPDATE commission_payment_submissions SET status=$2,rejection_reason=$3,reviewed_by=$4,reviewed_at=now(),version=version+1,updated_at=now() WHERE id=$1 AND version=$5 RETURNING *`,
          [
            id,
            approved ? 'approved' : 'rejected',
            approved ? null : (dto.reason?.trim() ?? null),
            actor,
            dto.version,
          ],
        ),
      );
      const updated = queryRows<BillingRow>(
        await m.query(
          `UPDATE technician_commission_statements SET status=$2::varchar,paid_at=CASE WHEN $2::varchar='paid' THEN now() ELSE NULL END,version=version+1,updated_at=now() WHERE id=$1 AND version=$3 RETURNING id`,
          [s.id, approved ? 'paid' : 'due', s.version],
        ),
      );
      if (!updated.length) this.billing.stale();
      await this.billing.record(m, actor, `commission.submission.${dto.decision}`, id, {
        reason: dto.reason ?? null,
        statementId: s.id,
      });
      await queueBillingNotification(
        m,
        approved ? 'billing.payment_approved' : 'billing.payment_rejected',
        String(s.id),
        String(p.technician_id),
        approved
          ? 'تم تأكيد دفعك. الخدمة رجعت تشتغل، بالتوفيق!'
          : `التحويل ما اتأكدش: ${dto.reason ?? ''}. ارفع إثبات جديد.`,
        { reason: dto.reason ?? null, submissionId: id },
      );
      return billingDto(requiredBillingRow(result));
    });
  }
}import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { randomUUID } from 'node:crypto';
import {
  CommissionBillingService,
  BILLABLE_ORDERS,
  commissionMinor,
  periodLabel,
  requiredBillingRow,
  type BillingRow,
} from './commission-billing.service';
import { queueBillingNotification } from './billing-notifications';
import { withdrawTechnicianPendingOffers } from '../../orders/withdraw-technician-pending-offers';

@Injectable()
export class CommissionStatementGenerator {
  private readonly logger = new Logger(CommissionStatementGenerator.name);
  private running = false;
  constructor(private readonly billing: CommissionBillingService) {}
  @Cron('0 * * * *')
  async sweep(): Promise<void> {
    if (this.running) return;
    this.running = true;
    try {
      const [month] = await this.billing.db.query<Array<{ month: string }>>(
        `SELECT to_char(date_trunc('month',now() AT TIME ZONE 'Africa/Cairo')-interval '1 month','YYYY-MM-DD') AS "month"`,
      );
      await this.generate(String(requiredBillingRow(month).month));
      await this.reminders();
    } catch (error) {
      this.logger.error('Commission billing sweep failed', error);
    } finally {
      this.running = false;
    }
  }
  async generate(month: string, actor?: string, key?: string): Promise<{ generated: number }> {
    if (!/^\d{4}-(0[1-9]|1[0-2])-01$/.test(month))
      throw new BadRequestException({ code: 'INVALID_PERIOD', message: 'اختار شهر صحيح.' });
    // Transaction-scoped advisory locks are released by PostgreSQL even if a connection dies.
    return await this.billing.db.transaction(async (coordinator) => {
      const [lock] = await coordinator.query<Array<{ ok: boolean }>>(
        `SELECT pg_try_advisory_xact_lock(hashtextextended('commission-billing-generation',0)) ok`,
      );
      if (!lock?.ok) return { generated: 0 };
      const [valid] = await coordinator.query<Array<{ ok: boolean }>>(
        `SELECT $1::date < date_trunc('month',now() AT TIME ZONE 'Africa/Cairo') AS ok`,
        [month],
      );
      if (!valid?.ok)
        throw new BadRequestException({
          code: 'PERIOD_NOT_CLOSED',
          message: 'الشهر ده لسه ما خلصش.',
        });
      const techs = await coordinator.query<Array<{ technician_id: string }>>(
        `SELECT DISTINCT o.technician_id FROM service_orders o WHERE o.technician_id IS NOT NULL AND ${BILLABLE_ORDERS.replaceAll('$2', '$1')}`,
        [month],
      );
      let generated = 0;
      for (const tech of techs) {
        const created = await this.billing.db.transaction(async (m) => {
          await m.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [
            tech.technician_id,
          ]);
          await m.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [
            `tech:${tech.technician_id}`,
          ]);
          const settings = await this.billing.settings(m);
          const orders = await m.query<
            Array<{ id: string; agreed_labor_minor: string; completed_at: Date }>
          >(
            `SELECT o.id,o.agreed_labor_minor::text,o.completed_at FROM service_orders o WHERE o.technician_id=$1 AND ${BILLABLE_ORDERS} ORDER BY o.id FOR UPDATE OF o`,
            [tech.technician_id, month],
          );
          if (!orders.length) return false;
          const labor = orders.reduce((sum, o) => sum + BigInt(o.agreed_labor_minor), 0n);
          const amount = commissionMinor(labor, Number(settings.commissionBps));
          const [statement] = await m.query<BillingRow[]>(
            `INSERT INTO technician_commission_statements(technician_id,period_month,orders_count,labor_total_minor,commission_bps,amount_due_minor,status,paid_at)
            VALUES($1,$2,$3,$4,$5,$6,$7::varchar,CASE WHEN $7::varchar='paid' THEN now() ELSE NULL END)
            ON CONFLICT(technician_id,period_month) DO NOTHING RETURNING id`,
            [
              tech.technician_id,
              month,
              orders.length,
              labor.toString(),
              settings.commissionBps,
              amount.toString(),
              amount === 0n ? 'paid' : 'due',
            ],
          );
          if (!statement) return false;
          for (const order of orders)
            await m.query(
              `INSERT INTO technician_commission_statement_items(statement_id,order_id,labor_minor,completed_at) VALUES($1,$2,$3,$4)`,
              [statement.id, order.id, order.agreed_labor_minor, order.completed_at],
            );
          if (amount > 0n) {
            await m.query(
              'UPDATE technician_profiles SET is_online=false,break_until=NULL,updated_at=now() WHERE user_id=$1',
              [tech.technician_id],
            );
            await withdrawTechnicianPendingOffers(m, tech.technician_id);
          }
          await queueBillingNotification(
            m,
            'billing.statement_issued',
            String(statement.id),
            tech.technician_id,
            `كشف مستحقات شهر ${periodLabel(month)} جاهز: ${String(Number(amount) / 100)} ج.م. ادفع عشان تفضل تستقبل طلبات.`,
            { amountDueMinor: amount.toString(), periodMonth: month },
          );
          await this.billing.record(
            m,
            actor ?? tech.technician_id,
            'commission.statement.generate',
            String(statement.id),
            { periodMonth: month, idempotencyKey: key ?? randomUUID(), version: 1 },
          );
          return true;
        });
        if (created) generated++;
      }
      return { generated };
    });
  }
  private async reminders(): Promise<void> {
    await this.billing.db.transaction(async (m) => {
      const due = await m.query<
        BillingRow[]
      >(`SELECT s.id,s.technician_id FROM technician_commission_statements s WHERE s.status='due' AND s.amount_due_minor>0
        AND s.issued_at<now()-interval '24 hours' AND NOT EXISTS(SELECT 1 FROM commission_payment_submissions p WHERE p.statement_id=s.id)
        AND NOT EXISTS(SELECT 1 FROM commission_billing_reminders r WHERE r.aggregate_id=s.id AND r.reminder_type='due') ORDER BY s.id LIMIT 100 FOR UPDATE SKIP LOCKED`);
      for (const s of due) {
        await m.query(
          `INSERT INTO commission_billing_reminders(aggregate_id,reminder_type) VALUES($1,'due')`,
          [s.id],
        );
        await queueBillingNotification(
          m,
          'billing.payment_reminder',
          String(s.id),
          String(s.technician_id),
          'لسه مستني تحويلك عشان ترجع تستقبل طلبات',
        );
      }
      const pending = await m.query<
        BillingRow[]
      >(`SELECT p.id,p.statement_id FROM commission_payment_submissions p WHERE p.status='pending' AND p.review_due_at<=now()+interval '2 hours'
        AND NOT EXISTS(SELECT 1 FROM commission_billing_reminders r WHERE r.aggregate_id=p.id AND r.reminder_type='sla') ORDER BY p.review_due_at LIMIT 100 FOR UPDATE SKIP LOCKED`);
      const admins = await m.query<Array<{ user_id: string }>>(
        `SELECT sp.user_id FROM staff_profiles sp LEFT JOIN admin_roles r ON r.id=sp.role_id JOIN users u ON u.id=sp.user_id WHERE u.status='active' AND u.deleted_at IS NULL AND (r.is_super_admin OR 'finance.read'=ANY(COALESCE(r.permissions,sp.permissions)) OR 'finance.manage'=ANY(COALESCE(r.permissions,sp.permissions)))`,
      );
      for (const p of pending) {
        if (!admins.length) continue;
        await m.query(
          `INSERT INTO commission_billing_reminders(aggregate_id,reminder_type) VALUES($1,'sla')`,
          [p.id],
        );
        for (const a of admins)
          await queueBillingNotification(
            m,
            'billing.review_reminder',
            String(p.statement_id),
            a.user_id,
            'إثبات دفع مستني المراجعة، باقي ساعتين أو أقل على ميعاد المراجعة.',
            { submissionId: p.id },
          );
      }
    });
  }
