@Entity('stored_files')
export class StoredFileEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ name: 'owner_id', type: 'uuid' })
  ownerId!: string;

  @ManyToOne(() => UserEntity, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'owner_id' })
  owner!: UserEntity;

  @Column({ type: 'enum', enum: MediaKind })
  kind!: MediaKind;

  @Column({ type: 'enum', enum: MediaPurpose })
  purpose!: MediaPurpose;

  @Column({ type: 'enum', enum: StoredFileStatus, default: StoredFileStatus.Pending })
  status!: StoredFileStatus;

  @Column({ name: 'upload_protocol', type: 'enum', enum: UploadProtocol })
  uploadProtocol!: UploadProtocol;

  @Column({ name: 'object_key', type: 'text', unique: true })
  objectKey!: string;

  @Column({ name: 'original_name', type: 'varchar', length: 255 })
  originalName!: string;

  @Column({ name: 'content_type', type: 'varchar', length: 100 })
  contentType!: string;

  @Column({ name: 'expected_size', type: 'bigint' })
  expectedSize!: string;

  @Column({ name: 'actual_size', type: 'bigint', nullable: true })
  actualSize!: string | null;

  @Column({ name: 'duration_ms', type: 'integer', nullable: true })
  durationMs!: number | null;

  @Column({ type: 'varchar', length: 200, nullable: true })
  etag!: string | null;

  @Column({ name: 'multipart_upload_id', type: 'text', nullable: true })
  multipartUploadId!: string | null;

  @Column({ name: 'multipart_part_size', type: 'integer', nullable: true })
  multipartPartSize!: number | null;

  @Column({ name: 'upload_expires_at', type: 'timestamptz' })
  uploadExpiresAt!: Date;

  @Column({ name: 'completed_at', type: 'timestamptz', nullable: true })
  completedAt!: Date | null;

  @Column({ name: 'deleted_at', type: 'timestamptz', nullable: true })
  deletedAt!: Date | null;

  @Column({ name: 'deletion_target_status', type: 'enum', enum: StoredFileStatus, nullable: true })
  deletionTargetStatus!: StoredFileStatus | null;

  @Column({ name: 'retention_attempts', type: 'integer', default: 0 })
  retentionAttempts!: number;

  @Column({ name: 'retention_next_attempt_at', type: 'timestamptz', nullable: true })
  retentionNextAttemptAt!: Date | null;

  @Column({ name: 'retention_last_error', type: 'text', nullable: true })
  retentionLastError!: string | null;

  @Column({ name: 'retention_failed_at', type: 'timestamptz', nullable: true })
  retentionFailedAt!: Date | null;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt!: Date;
