function createSilentWav(durationSeconds: number, sampleRate = 8_000): Buffer {
  const dataSize = durationSeconds * sampleRate * 2;
  const buffer = Buffer.alloc(44 + dataSize);
  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(36 + dataSize, 4);
  buffer.write('WAVE', 8);
  buffer.write('fmt ', 12);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write('data', 36);
  buffer.writeUInt32LE(dataSize, 40);
  return buffer;
}

function box(type: string, payload: Buffer): Buffer {
  const result = Buffer.alloc(8 + payload.length);
  result.writeUInt32BE(result.length, 0);
  result.write(type, 4, 4, 'ascii');
  payload.copy(result, 8);
  return result;
}

function createMinimalMp4(durationSeconds: number): Buffer {
  const ftyp = box('ftyp', Buffer.from('isom\x00\x00\x02\x00isomiso2mp41', 'binary'));
  const mvhd = Buffer.alloc(100);
  mvhd.writeUInt32BE(1_000, 12);
  mvhd.writeUInt32BE(durationSeconds * 1_000, 16);
  const handler = Buffer.alloc(12);
  handler.write('vide', 8, 4, 'ascii');
  const track = box('trak', box('mdia', box('hdlr', handler)));
  return Buffer.concat([ftyp, box('moov', Buffer.concat([box('mvhd', mvhd), track]))]);
}

describe('FilesService commission proofs', () => {
  it('normalizes JPEG evidence to private WebP and removes metadata', async () => {
    const bytes = await sharp({
      create: { width: 32, height: 32, channels: 3, background: '#123456' },
    })
      .jpeg()
      .withMetadata()
      .toBuffer();
    const file = Object.assign(createPendingAvatar(bytes), {
      purpose: MediaPurpose.CommissionPaymentProof,
      status: StoredFileStatus.Completing,
      objectKey: 'media/proof.webp',
    });
    const { service, storage } = createHarness(file, bytes);
    const putObject = vi.fn().mockResolvedValue(undefined);
    Object.assign(storage, { putObject });
    await (
      service as unknown as { normalizeCompletionPhoto: (f: StoredFileEntity) => Promise<void> }
    ).normalizeCompletionPhoto(file);
    const output = putObject.mock.calls[0]?.[1] as Buffer;
    expect(Buffer.isBuffer(output)).toBe(true);
    const metadata = await sharp(output).metadata();
    expect(metadata.format).toBe('webp');
    expect(metadata.exif).toBeUndefined();
    expect(metadata.icc).toBeUndefined();
    expect(file.contentType).toBe('image/webp');
    expect(file.objectKey).toBe('media/proof.webp');
  });
  it('rejects an eleventh commission-proof reservation in the same hour', async () => {
    const file = Object.assign(createPendingAvatar(Buffer.from('image')), {
      purpose: MediaPurpose.CommissionPaymentProof,
    });
    const { service, managerQuery } = createHarness(file, Buffer.from('image'));
    managerQuery.mockResolvedValueOnce([]).mockResolvedValueOnce([{ count: '10' }] as never);
    await expect(
      (
        service as unknown as { reserveUpload: (f: StoredFileEntity) => Promise<void> }
      ).reserveUpload(file),
    ).rejects.toMatchObject({ status: 429, response: { code: 'PROOF_UPLOAD_LIMIT' } });
  });
  it('signs private proof downloads for only five minutes', async () => {
    const { service, storage, dataSourceQuery } = createHarness(null, Buffer.from('image'));
    dataSourceQuery.mockResolvedValueOnce([
      { object_key: 'private/proof.webp', content_type: 'image/webp' },
    ] as never);
    const createDownloadUrl = vi.fn().mockResolvedValue('https://private.example/proof');
    Object.assign(storage, { createDownloadUrl });
    expect(await service.createCommissionProofDownload('proof')).toEqual({
      url: 'https://private.example/proof',
      expiresInSeconds: 300,
    });
    expect(createDownloadUrl).toHaveBeenCalledWith(
      'private/proof.webp',
      'transfer.webp',
      'image/webp',
      300,
    );
  });
});

