function createHarness(
  file: StoredFileEntity | null,
  bytes: Buffer,
): {
  repository: Repository<StoredFileEntity>;
  storage: R2StorageService;
  service: FilesService;
  deleteObject: ReturnType<typeof vi.fn>;
  headObject: ReturnType<typeof vi.fn>;
  getObjectBuffer: ReturnType<typeof vi.fn>;
  createPartUploadUrl: ReturnType<typeof vi.fn>;
  findFiles: ReturnType<typeof vi.fn>;
  updateFile: ReturnType<typeof vi.fn>;
  managerQuery: ReturnType<typeof vi.fn>;
  dataSourceQuery: ReturnType<typeof vi.fn>;
} {
  const updateFile = vi.fn(
    (criteria: { status?: StoredFileStatus | object }, partial: Partial<StoredFileEntity>) => {
      if (!file) return Promise.resolve({ affected: 0 });
      const expected = criteria.status;
      if (typeof expected === 'string' && file.status !== expected) {
        return Promise.resolve({ affected: 0 });
      }
      Object.assign(file, partial);
      return Promise.resolve({ affected: 1 });
    },
  );
  const findFiles = vi.fn(() => Promise.resolve([]));
  const repository = {
    find: findFiles,
    findOne: vi.fn(() => Promise.resolve(file)),
    save: vi.fn((value: StoredFileEntity) => Promise.resolve(value)),
    update: updateFile,
  } as unknown as Repository<StoredFileEntity>;
  const headObject = vi.fn(() =>
    Promise.resolve({
      contentLength: bytes.length,
      contentType: file?.contentType ?? 'audio/wav',
      etag: 'etag',
      metadata: {
        'file-id': file?.id ?? '',
        'owner-id': file?.ownerId ?? '',
        'duration-ms': String(file?.durationMs ?? ''),
      },
    }),
  );
  const deleteObject = vi.fn(() => Promise.resolve());
  const createPartUploadUrl = vi.fn(() => Promise.resolve('https://upload.example/part'));
  const getObjectBuffer = vi.fn(() => Promise.resolve(bytes));
  const storage = {
    settings,
    headObject,
    getObjectBuffer,
    getObjectRange: vi.fn(() => Promise.resolve(bytes.subarray(0, 64 * 1024))),
    deleteObject,
    createPartUploadUrl,
  } as unknown as R2StorageService;
  const managerQuery = vi.fn(() => Promise.resolve([]));
  const manager = {
    getRepository: vi.fn(() => repository),
    query: managerQuery,
  } as unknown as EntityManager;
  const dataSourceQuery = vi.fn(() => Promise.resolve([]));
  const dataSource = {
    transaction: vi.fn((operation: (transactionManager: EntityManager) => Promise<unknown>) =>
      operation(manager),
    ),
    query: dataSourceQuery,
  } as unknown as DataSource;
  return {
    repository,
    storage,
    service: new FilesService(
      repository,
      storage,
      new AudioMetadataService(),
      new VideoMetadataService(),
      dataSource,
    ),
    deleteObject,
    headObject,
    getObjectBuffer,
    createPartUploadUrl,
    findFiles,
    updateFile,
    managerQuery,
    dataSourceQuery,
  };
}

describe('FilesService multipart lifecycle', () => {
  const owner = { id: '2673a734-31ce-42c0-a652-586e3877cf18' } as UserEntity;
  const partSize = 5 * 1024 * 1024;

  it('does not claim an upload when the completed part list is invalid', async () => {
    const file = createPendingMultipart(partSize + 7, partSize);
    const { service, updateFile } = createHarness(file, Buffer.alloc(1));

    await expect(
      service.completeMultipart(owner, file.id, {
        parts: [{ partNumber: 1, etag: 'etag-1' }],
      }),
    ).rejects.toBeInstanceOf(BadRequestException);

    expect(file.status).toBe(StoredFileStatus.Pending);
    expect(updateFile).not.toHaveBeenCalled();
  });

  it('signs the exact length of every part including the final part', async () => {
    const file = createPendingMultipart(partSize + 7, partSize);
    const { createPartUploadUrl, service } = createHarness(file, Buffer.alloc(1));

    const result = await service.presignParts(owner, file.id, { partNumbers: [1, 2] });

    expect(createPartUploadUrl).toHaveBeenNthCalledWith(
      1,
      file.objectKey,
      file.multipartUploadId,
      1,
      partSize,
    );
    expect(createPartUploadUrl).toHaveBeenNthCalledWith(
      2,
      file.objectKey,
      file.multipartUploadId,
      2,
      7,
    );
    expect(result).toMatchObject({
      parts: [
        { partNumber: 1, contentLength: partSize },
        { partNumber: 2, contentLength: 7 },
      ],
    });
  });
});

describe('FilesService booking voice notes', () => {
  const owner = { id: '2673a734-31ce-42c0-a652-586e3877cf18' } as UserEntity;

  it('uses decoded audio duration instead of trusting the client claim', async () => {
    const bytes = createSilentWav(2);
    const file = createPendingVoiceNote(bytes);
    const { service } = createHarness(file, bytes);

    await expect(service.completeSingle(owner, file.id)).resolves.toMatchObject({
      file: { status: StoredFileStatus.Ready, durationMs: 2_000 },
    });
    expect(file.durationMs).toBe(2_000);
  });

  it('rejects and removes an uploaded object whose real duration exceeds two minutes', async () => {
    const bytes = createSilentWav(121);
    const file = createPendingVoiceNote(bytes);
    const { deleteObject, service } = createHarness(file, bytes);

    await expect(service.completeSingle(owner, file.id)).rejects.toBeInstanceOf(
      BadRequestException,
    );
    expect(file.status).toBe(StoredFileStatus.Failed);
    expect(deleteObject).toHaveBeenCalledWith(file.objectKey);
  });

  it("does not expose another owner's file", async () => {
    const bytes = createSilentWav(1);
    const { headObject, service } = createHarness(null, bytes);
    const otherOwner = { id: '79ef1c2c-663a-4081-9615-e16fe1c9a75f' } as UserEntity;

    await expect(
      service.completeSingle(otherOwner, '7f30b21c-07ad-4f63-90de-f1c0c51cdcdf'),
    ).rejects.toBeInstanceOf(NotFoundException);
    expect(headObject).not.toHaveBeenCalled();
  });

  it('does not let deletion take ownership while completion is verifying', async () => {
    const bytes = createSilentWav(1);
    const file = createPendingVoiceNote(bytes);
    const { headObject, service } = createHarness(file, bytes);
    let resolveHead!: (value: {
      contentLength: number;
      contentType: string;
      etag: string;
      metadata: Record<string, string>;
    }) => void;
    const pendingHead = new Promise<Parameters<typeof resolveHead>[0]>((resolve) => {
      resolveHead = resolve;
    });
    headObject.mockReturnValueOnce(pendingHead);

    const completion = service.completeSingle(owner, file.id);
    await vi.waitFor(() => {
      expect(headObject).toHaveBeenCalledOnce();
    });
    await expect(service.remove(owner, file.id)).rejects.toBeInstanceOf(ConflictException);
    resolveHead({
      contentLength: bytes.length,
      contentType: file.contentType,
      etag: 'etag',
      metadata: {
        'file-id': file.id,
        'owner-id': file.ownerId,
        'duration-ms': String(file.durationMs),
      },
    });
    await expect(completion).resolves.toMatchObject({
      file: { status: StoredFileStatus.Ready },
    });
  });

  it('reconciles an expired completing object instead of deleting it', async () => {
    const bytes = createSilentWav(1);
    const file = createPendingVoiceNote(bytes);
    file.status = StoredFileStatus.Completing;
    file.uploadExpiresAt = new Date(Date.now() - 60_000);
    file.updatedAt = new Date(Date.now() - 60 * 60_000);
    const { deleteObject, findFiles, service } = createHarness(file, bytes);
    findFiles.mockResolvedValueOnce([file]).mockResolvedValueOnce([]);

    await expect(service.cleanupExpiredUploads()).resolves.toEqual({ cleaned: 1 });
    expect(file.status).toBe(StoredFileStatus.Ready);
    expect(deleteObject).not.toHaveBeenCalled();
  });

  it('returns a truthful pending result when a deleting file cannot reach storage', async () => {
    const bytes = createSilentWav(1);
    const file = createPendingVoiceNote(bytes);
    file.status = StoredFileStatus.Deleting;
    file.deletionTargetStatus = StoredFileStatus.Deleted;
    const { deleteObject, service } = createHarness(file, bytes);
    deleteObject.mockRejectedValueOnce(new Error('storage unavailable'));

    await expect(service.remove(owner, file.id)).resolves.toEqual({
      deleted: false,
      deletionPending: true,
    });
    expect(file.status).toBe(StoredFileStatus.Deleting);
  });

  it('accepts an identical deletion finalized concurrently by another worker', async () => {
    const bytes = createSilentWav(1);
    const file = createPendingVoiceNote(bytes);
    file.status = StoredFileStatus.Deleting;
    file.deletionTargetStatus = StoredFileStatus.Deleted;
    const { service, updateFile } = createHarness(file, bytes);
    updateFile.mockImplementationOnce(
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      () => {
        file.status = StoredFileStatus.Deleted;
        file.deletedAt = new Date();
        return Promise.resolve({ affected: 0 });
      },
    );

    await expect(service.resumeAvatarRetirement(owner.id, file.id)).resolves.toBeUndefined();
    expect(file.status).toBe(StoredFileStatus.Deleted);
  });
});

describe('FilesService onboarding orphan cleanup', () => {
  it('deletes an old ready verification upload that was never attached', async () => {
    const bytes = Buffer.from('unused verification image');
    const file = Object.assign(createPendingAvatar(bytes), {
      purpose: MediaPurpose.Verification,
      status: StoredFileStatus.Ready,
      completedAt: new Date(Date.now() - 72 * 60 * 60_000),
    });
    const { deleteObject, managerQuery, service } = createHarness(file, bytes);
    // The mocked CTE below represents the atomic ready -> deleting claim.
    file.status = StoredFileStatus.Deleting;
    file.deletionTargetStatus = StoredFileStatus.Deleted;
    managerQuery
      .mockResolvedValueOnce([]) // commission proof candidates
      .mockResolvedValueOnce([]) // avatar candidates
      .mockResolvedValueOnce([{ id: file.id }]) // onboarding candidates
      .mockResolvedValueOnce([]); // reference re-check

    await expect(service.cleanupExpiredUploads()).resolves.toEqual({ cleaned: 1 });

    expect(deleteObject).toHaveBeenCalledWith(file.objectKey);
    expect(file.status).toBe(StoredFileStatus.Deleted);
  });
});

describe('FilesService catalog orphan cleanup', () => {
  it.each([false, true])(
    'rechecks all file references before deleting a catalog orphan (referenced=%s)',
    async (referenced) => {
      const bytes = Buffer.from('old catalog image');
      const file = Object.assign(createPendingAvatar(bytes), {
        purpose: MediaPurpose.Other,
        status: StoredFileStatus.Deleting,
        deletionTargetStatus: StoredFileStatus.Deleted,
      });
      const { service, managerQuery, deleteObject } = createHarness(file, bytes);
      managerQuery
        .mockResolvedValueOnce([{ id: file.id }])
        .mockResolvedValueOnce([])
        .mockResolvedValueOnce([])
        .mockResolvedValueOnce(referenced ? [{ exists: 1 }] : []);
      const cleaner = service as unknown as {
        cleanupOrphanedCatalogFiles(limit: number): Promise<number>;
      };
      expect(await cleaner.cleanupOrphanedCatalogFiles(10)).toBe(referenced ? 0 : 1);
      const sql = managerQuery.mock.calls[0]?.[0];
      expect(sql).toContain("interval '24 hours'");
      expect(sql).toContain('FOR UPDATE SKIP LOCKED');
      expect(sql).toContain('SELECT image_file_id FROM service_categories');
      expect(sql).toContain('SELECT icon_file_id FROM services');
      expect(deleteObject).toHaveBeenCalledTimes(referenced ? 0 : 1);
      expect(file.status).toBe(referenced ? StoredFileStatus.Ready : StoredFileStatus.Deleted);
    },
  );

  it('leaves a durable deletion claim for retry when storage is unavailable', async () => {
    const bytes = Buffer.from('old catalog image');
    const file = Object.assign(createPendingAvatar(bytes), {
      status: StoredFileStatus.Deleting,
      deletionTargetStatus: StoredFileStatus.Deleted,
    });
    const { service, managerQuery, deleteObject } = createHarness(file, bytes);
    managerQuery.mockResolvedValueOnce([{ id: file.id }]).mockResolvedValue([]);
    deleteObject.mockRejectedValueOnce(new Error('storage offline'));
    const cleaner = service as unknown as {
      cleanupOrphanedCatalogFiles(limit: number): Promise<number>;
    };
    expect(await cleaner.cleanupOrphanedCatalogFiles(10)).toBe(0);
    expect(file.status).toBe(StoredFileStatus.Deleting);
  });
});

