});import { BadRequestException, PayloadTooLargeException } from '@nestjs/common';

import { type StorageConfig } from '../../config/storage/storage.config';
import { MediaKind, MediaPurpose } from './entities/stored-file.entity';

export const MAX_BOOKING_VOICE_NOTE_DURATION_MS = 120_000;
export const MAX_BOOKING_VIDEO_DURATION_MS = 30_000;
export const MAX_BOOKING_VIDEO_BYTES = 10 * 1024 * 1024;
export const MAX_AVATAR_BYTES = 5 * 1024 * 1024;
export const MAX_CHAT_VOICE_DURATION_MS = 180_000;
export const MAX_CHAT_VIDEO_DURATION_MS = 120_000;
export const MAX_CHAT_VIDEO_BYTES = 50 * 1024 * 1024;
export const MAX_CHAT_IMAGE_BYTES = 10 * 1024 * 1024;
export const MAX_COMPLETION_PHOTO_BYTES = 10 * 1024 * 1024;
const COMPLETION_PHOTO_CONTENT_TYPES: ReadonlySet<string> = new Set([
  'image/heic',
  'image/jpeg',
  'image/png',
  'image/webp',
]);

const ALLOWED_CONTENT_TYPES: Readonly<Record<MediaKind, ReadonlySet<string>>> = {
  [MediaKind.Image]: new Set([
    'image/avif',
    'image/heic',
    'image/heif',
    'image/jpeg',
    'image/png',
    'image/webp',
  ]),
  [MediaKind.Video]: new Set([
    'video/3gpp',
    'video/mp4',
    'video/mpeg',
    'video/quicktime',
    'video/webm',
  ]),
  [MediaKind.Audio]: new Set([
    'audio/aac',
    'audio/flac',
    'audio/mp4',
    'audio/mpeg',
    'audio/ogg',
    'audio/wav',
    'audio/webm',
    'audio/x-m4a',
  ]),
};

const MIME_EXTENSIONS: Readonly<Record<string, string>> = {
  'image/avif': 'avif',
  'image/heic': 'heic',
  'image/heif': 'heif',
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'video/3gpp': '3gp',
  'video/mp4': 'mp4',
  'video/mpeg': 'mpeg',
  'video/quicktime': 'mov',
  'video/webm': 'webm',
  'audio/aac': 'aac',
  'audio/flac': 'flac',
  'audio/mp4': 'm4a',
  'audio/mpeg': 'mp3',
  'audio/ogg': 'ogg',
  'audio/wav': 'wav',
  'audio/webm': 'webm',
  'audio/x-m4a': 'm4a',
};

export function normalizeContentType(contentType: string): string {
  return contentType.split(';', 1)[0]?.trim().toLowerCase() ?? '';
}

export function validateMediaPolicy(
  kind: MediaKind,
  rawContentType: string,
  size: number,
  config: StorageConfig,
): { contentType: string; extension: string } {
  const contentType = normalizeContentType(rawContentType);
  if (!ALLOWED_CONTENT_TYPES[kind].has(contentType)) {
    throw new BadRequestException(
      `Content type ${contentType || '(empty)'} is not allowed for ${kind}.`,
    );
  }

  const maxBytes = {
    [MediaKind.Image]: config.maxImageBytes,
    [MediaKind.Audio]: config.maxAudioBytes,
    [MediaKind.Video]: config.maxVideoBytes,
  }[kind];
  if (size > maxBytes) {
    throw new PayloadTooLargeException(
      `${kind} exceeds the configured ${String(maxBytes)} byte limit.`,
    );
  }

  const extension = MIME_EXTENSIONS[contentType];
  if (!extension) throw new BadRequestException('Unsupported content type.');
  return { contentType, extension };
}

export function validateMediaDuration(
  kind: MediaKind,
  purpose: MediaPurpose,
  durationMs: number | undefined,
): number | null {
  const isBookingVoiceNote = kind === MediaKind.Audio && purpose === MediaPurpose.Booking;
  const isChatMedia =
    purpose === MediaPurpose.Chat && (kind === MediaKind.Audio || kind === MediaKind.Video);
  if (!isBookingVoiceNote && !isChatMedia) {
    if (durationMs !== undefined) {
      throw new BadRequestException('durationMs is only accepted for booking voice notes.');
    }
    return null;
  }

  if (isChatMedia && durationMs === undefined) {
    throw new BadRequestException('durationMs is required for chat audio and video.');
  }
  if (!Number.isSafeInteger(durationMs) || (durationMs ?? 0) <= 0) {
    if (isChatMedia) throw new BadRequestException('durationMs must be a positive integer.');
    throw new BadRequestException('durationMs is required for booking voice notes.');
  }
  const maxDuration =
    purpose === MediaPurpose.Chat && kind === MediaKind.Audio
      ? MAX_CHAT_VOICE_DURATION_MS
      : purpose === MediaPurpose.Chat && kind === MediaKind.Video
        ? MAX_CHAT_VIDEO_DURATION_MS
        : MAX_BOOKING_VOICE_NOTE_DURATION_MS;
  if ((durationMs ?? 0) > maxDuration) {
    if (purpose === MediaPurpose.Chat && kind === MediaKind.Audio) {
      throw new BadRequestException('Chat voice messages must not exceed 180 seconds.');
    }
    if (purpose === MediaPurpose.Chat && kind === MediaKind.Video) {
      throw new BadRequestException('Chat videos must not exceed 120 seconds.');
    }
    throw new BadRequestException('Booking voice notes must not exceed 120 seconds.');
  }
  return durationMs ?? null;
}

export function validatePurposeMediaPolicy(
  kind: MediaKind,
  purpose: MediaPurpose,
  size: number,
  contentType?: string,
): void {
  if (purpose === MediaPurpose.CommissionPaymentProof) {
    if (
      kind !== MediaKind.Image ||
      !contentType ||
      !COMPLETION_PHOTO_CONTENT_TYPES.has(normalizeContentType(contentType))
    )
      throw new BadRequestException('إثبات الدفع لازم يكون صورة JPEG أو PNG أو WebP أو HEIC.');
    if (size > 8 * 1024 * 1024)
      throw new PayloadTooLargeException('صورة التحويل لازم تكون أقل من ٨ ميجابايت.');
  }
  if (purpose === MediaPurpose.JobEvidence || purpose === MediaPurpose.Review) {
    if (kind !== MediaKind.Image) {
      throw new BadRequestException('Completion evidence and review uploads must be images.');
    }
    if (size > MAX_COMPLETION_PHOTO_BYTES) {
      throw new PayloadTooLargeException(
        'Completion evidence and review images must not exceed 10 MiB.',
      );
    }
    if (!contentType || !COMPLETION_PHOTO_CONTENT_TYPES.has(normalizeContentType(contentType))) {
      throw new BadRequestException(
        'Completion evidence and review images must be JPEG, PNG, WebP, or HEIC.',
      );
    }
  }
  if (purpose === MediaPurpose.SparePart) {
    if (kind !== MediaKind.Image)
      throw new BadRequestException('Spare-part attachments must be images.');
    if (size > 10 * 1024 * 1024)
      throw new PayloadTooLargeException('Spare-part images must not exceed 10 MiB.');
  }
  if (purpose === MediaPurpose.Avatar) {
    if (kind !== MediaKind.Image) {
      throw new BadRequestException('Avatars must be images.');
    }
    if (size > MAX_AVATAR_BYTES) {
      throw new PayloadTooLargeException('Avatar images must not exceed 5 MiB.');
    }
  }
  if (
    kind === MediaKind.Video &&
    purpose === MediaPurpose.Booking &&
    size > MAX_BOOKING_VIDEO_BYTES
  ) {
    throw new PayloadTooLargeException('Booking videos must not exceed 10 MiB.');
  }
  if (
    kind === MediaKind.Video &&
    purpose === MediaPurpose.Booking &&
    contentType === 'video/mpeg'
  ) {
    throw new BadRequestException('MPEG video is not supported for booking attachments.');
  }
  if (purpose === MediaPurpose.Chat && kind === MediaKind.Image && size > MAX_CHAT_IMAGE_BYTES) {
    throw new PayloadTooLargeException('Chat images must not exceed 10 MiB.');
  }
  if (purpose === MediaPurpose.Chat && kind === MediaKind.Video && size > MAX_CHAT_VIDEO_BYTES) {
    throw new PayloadTooLargeException('Chat videos must not exceed 50 MiB.');
  }
  if (purpose === MediaPurpose.Chat && kind === MediaKind.Video && contentType === 'video/mpeg') {
    throw new BadRequestException('MPEG video is not supported for chat attachments.');
  }
}import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { describe, expect, it, vi } from 'vitest';

import { DISPATCH_ELIGIBILITY_SQL } from './dispatch-eligibility.sql';
import { OrderOffersService } from './order-offers.service';

const order = (overrides: Record<string, unknown> = {}): Record<string, unknown> => ({
  id: 'order-1',
  customer_id: 'customer-1',
  status: 'searching',
  customer_offer_minor: '10000',
  offer_cap_minor: '30000',
  customer_offer_raises: 0,
  search_expires_at: new Date(Date.now() + 60_000),
  currency: 'EGP',
  pricing_type: 'estimate',
  promotion_grant_id: null,
  ...overrides,
});

// Billing and advisory locks have their own integration coverage; don't consume
// the negotiation fixtures for these independent queries.
function withBilling(query: ReturnType<typeof vi.fn>) {
  return async (sql: string, ...args: unknown[]) => {
    if (sql.includes('SELECT technician_billing_blocked($1) AS blocked'))
      return [{ blocked: false }];
    if (sql.includes('pg_advisory_xact_lock') || sql.startsWith('SET LOCAL')) return [];
    return await (query as unknown as (sql:string,...args:unknown[])=>Promise<unknown>)(sql, ...args);
  };
}
function transactional(query: ReturnType<typeof vi.fn>): OrderOffersService {
  const manager = { query: withBilling(query) };
  return new OrderOffersService({
    transaction: (callback: (value: typeof manager) => Promise<unknown>) => callback(manager),
  } as never);
}

describe('OrderOffersService negotiation rules', () => {
  it('closes pending and accepted offers when cancelling an assigned order and notifies its technician', async () => {
    const query = vi.fn(async (sql: string) => {
      await Promise.resolve();
      if (sql.includes('FOR UPDATE'))
        return [order({ status: 'assigned', technician_id: 'tech-1' })];
      if (sql.includes('UPDATE service_order_offers'))
        return [{ id: 'offer-1', technician_id: 'tech-1' }];
      return [];
    });
    const service = transactional(query);
    await expect(service.cancel('customer-1', 'order-1')).resolves.toEqual({ status: 'cancelled' });
    const close = query.mock.calls.find(([sql]) =>
      sql.includes('UPDATE service_order_offers'),
    )?.[0];
    expect(close).toContain("status IN ('pending', 'accepted')");
    expect(close).toContain("close_reason = 'order_cancelled'");
    expect(query.mock.calls.some(([sql]) => sql.includes('INSERT INTO domain_event_outbox'))).toBe(
      true,
    );
  });
  it('rejects counters at/below the customer offer and above the cap', async () => {
    for (const amount of ['10000', '30001']) {
      const service = transactional(vi.fn().mockResolvedValueOnce([order()]));
      await expect(service.counterOffer('tech-1', 'order-1', amount)).rejects.toBeInstanceOf(
        BadRequestException,
      );
    }
  });

  it('allows negotiation for legacy fixed catalog entries', async () => {
    const query = vi
      .fn()
      .mockResolvedValueOnce([order({ pricing_type: 'fixed' })])
      .mockResolvedValueOnce([{ total: '0' }])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([
        { id: 'offer-1', amount_minor: '12000', expires_at: new Date(Date.now() + 120_000) },
      ])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([]);
    const service = transactional(query);

    await expect(service.counterOffer('tech-1', 'order-1', '12000')).resolves.toEqual(
      expect.objectContaining({ id: 'offer-1', status: 'pending' }),
    );
  });

  it('rejects a third counter from the same technician', async () => {
    const service = transactional(
      vi
        .fn()
        .mockResolvedValueOnce([order()])
        .mockResolvedValueOnce([{ total: '2' }]),
    );
    await expect(service.counterOffer('tech-1', 'order-1', '12000')).rejects.toBeInstanceOf(
      BadRequestException,
    );
  });

  it('does not reopen a closed scheduled matching window', async () => {
    const service = transactional(
      vi.fn().mockResolvedValueOnce([
        order({
          scheduled_at: new Date(Date.now() + 20 * 60_000),
          search_starts_at: new Date(Date.now() - 100 * 60_000),
          search_expires_at: new Date(Date.now() - 1_000),
        }),
      ]),
    );

    await expect(service.raiseCustomerOffer('customer-1', 'order-1', '12000')).rejects.toThrow(
      'The scheduled matching window has closed.',
    );
  });

  it('commits expiration before returning 409 for an expired offer', async () => {
    const query = vi
      .fn()
      .mockResolvedValueOnce([order()])
      .mockResolvedValueOnce([
        {
          id: 'offer-1',
          order_id: 'order-1',
          technician_id: 'tech-1',
          amount_minor: '12000',
          status: 'pending',
          expires_at: new Date(Date.now() - 1000),
        },
      ])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([]);
    const service = transactional(query);
    await expect(
      service.acceptCustomerOffer('customer-1', 'order-1', 'offer-1'),
    ).rejects.toBeInstanceOf(ConflictException);
    expect(String(query.mock.calls[2]?.[0])).toContain("status = 'expired'");
  });

  it('never exposes the detailed address or customer phone in technician requests', async () => {
    const query = vi.fn().mockResolvedValueOnce([
      {
        id: 'order-1',
        reference: 'FX-1',
        serviceTitleAr: 'خدمة',
        description: 'وصف',
        area: 'nasr-city',
        customerOfferMinor: '10000',
        capMinor: '30000',
        currency: 'EGP',
