      },
    ]);
    const service = new OrderOffersService({ query: withBilling(query) } as never);
    const result = await service.listTechnicianRequests('tech-1');
    expect(result.data[0]).not.toHaveProperty('addressText');
    expect(result.data[0]).not.toHaveProperty('customerPhone');
    expect(String(query.mock.calls[0]?.[0])).not.toContain('o.address_text');
  });

  it('uses one shared eligibility fragment in the feed, details, and both confirmation paths under v2', async () => {
    const config = new ConfigService({ dispatch: { v2Enabled: true } });
    const feedQuery = vi.fn().mockResolvedValue([]);
    const feedService = new OrderOffersService({ query: withBilling(feedQuery) } as never, config);
    await feedService.listTechnicianRequests('tech-1');
