          status: 'pending',
          expires_at: new Date(Date.now() + 60_000),
        },
      ])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([]);
    const customerAcceptService = new OrderOffersService(
      {
        transaction: (
          callback: (value: { query: typeof customerAcceptQuery }) => Promise<unknown>,
        ) =>
          callback({
            query: ((sql: string, ...args: unknown[]) =>
