  });

  it('does not enable v2 eligibility or the new detail endpoint when the feature flag is absent', async () => {
    const query = vi.fn().mockResolvedValue([]);
    const transaction = vi.fn();
    const service = new OrderOffersService({ query: withBilling(query), transaction } as never);
    await service.listTechnicianRequests('tech-1');
    expect(String(query.mock.calls[0]?.[0])).not.toContain(DISPATCH_ELIGIBILITY_SQL.trim());
    await expect(service.getTechnicianRequest('tech-1', 'order-1')).rejects.toBeInstanceOf(
      NotFoundException,
    );
    let disabled: unknown;
    try {
      await service.createOffer('tech-1', 'order-1', {
        kind: 'accept',
        serviceLocation: 'customer_site',
      });
    } catch (error) {
      disabled = error;
    }
    expect(disabled).toBeInstanceOf(NotFoundException);
    expect((disabled as NotFoundException).getResponse()).toMatchObject({
      code: 'DISPATCH_V2_DISABLED',
    });
    expect(transaction).not.toHaveBeenCalled();
    expect(query).toHaveBeenCalledTimes(1);
  });

  it('returns the dispatch feed contract and encodes the four-part keyset cursor', async () => {
    const createdAt = new Date('2026-10-08T00:00:00.000Z');
    const visibleUntil = new Date('2026-10-08T01:00:00.000Z');
    const row = {
      orderId: '11111111-1111-4111-8111-111111111111',
      serviceTitle: 'إصلاح',
      area: 'مدينة نصر',
      distanceRounded: '0.5',
      customerOfferMinor: '10000',
      offerCapMinor: '30000',
      scheduledAt: createdAt,
