    };
    const feedQuery = vi
      .fn()
      .mockResolvedValueOnce([row, { ...row, orderId: '22222222-2222-4222-8222-222222222222' }])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([{ ...row, orderId: '22222222-2222-4222-8222-222222222222' }])
      .mockResolvedValueOnce([]);
    const service = new OrderOffersService(
      { query: withBilling(feedQuery) } as never,
      new ConfigService({ dispatch: { v2Enabled: true } }),
    );

    const firstPage = await service.listTechnicianRequests('tech-1', { limit: 1 });
    expect(firstPage.data[0]).toEqual({
      orderId: row.orderId,
      serviceTitle: row.serviceTitle,
      area: row.area,
      distanceKm: 0.5,
      customerOfferMinor: row.customerOfferMinor,
      offerCapMinor: row.offerCapMinor,
      scheduledAt: createdAt.toISOString(),
      isEmergency: false,
      visibleUntil: visibleUntil.toISOString(),
      createdAt: createdAt.toISOString(),
      isNew: true,
      offersCount: 1,
      myOffer: row.myOffer,
      locationPreference: row.locationPreference,
    });
    expect(firstPage.data[0]).not.toHaveProperty('countdownSeconds');
    expect(firstPage.nextCursor).toBeTypeOf('string');
    const cursor = firstPage.nextCursor;
    if (cursor == null) throw new Error('Expected a next cursor for the first page.');
    expect(JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'))).toEqual([
      1,
      0.5,
      createdAt.toISOString(),
      row.orderId,
    ]);
    expect(String(feedQuery.mock.calls[0]?.[0])).toContain('o.pending_offers_count < $2 OR EXISTS');
    expect(String(feedQuery.mock.calls[0]?.[0])).toContain(
      'ORDER BY sort_bucket ASC, distance_rounded ASC NULLS LAST,',
    );
    expect(String(feedQuery.mock.calls[0]?.[0])).toContain(DISPATCH_ELIGIBILITY_SQL.trim());

    await service.listTechnicianRequests('tech-1', { limit: 1, cursor });
    expect(feedQuery.mock.calls[2]?.[1]).toEqual([
      'tech-1',
      8,
      120,
      1,
      0.5,
      createdAt.toISOString(),
      row.orderId,
      2,
