  it('rejects malformed dispatch feed cursor tuples before querying the database', async () => {
    const query = vi.fn();
    const service = new OrderOffersService(
      { query: withBilling(query) } as never,
      new ConfigService({ dispatch: { v2Enabled: true } }),
    );
    await expect(
      service.listTechnicianRequests('tech-1', { cursor: 'not-base64-json' } as never),
    ).rejects.toBeInstanceOf(BadRequestException);
    expect(query).not.toHaveBeenCalled();
  });
