@Injectable()
export class OrderOffersService {
  constructor(
    @InjectDataSource() private readonly dataSource: DataSource,
    @Optional() private readonly config?: ConfigService,
    @Optional()
    @Inject(CUSTOMER_OFFER_RANKING_STRATEGY)
    private readonly customerOfferRanking?: CustomerOfferRankingStrategy,
    @Optional() private readonly files?: FilesService,
  ) {}

  async listTechnicianRequests(
    technicianId: string,
    query: ListTechnicianRequestsQueryDto = new ListTechnicianRequestsQueryDto(),
  ): Promise<{ data: unknown[]; nextCursor?: string; billingBlocked?: boolean }> {
    if (query.cursor != null) {
      if (this.isDispatchV2Enabled()) this.decodeDispatchFeedCursor(query.cursor);
      else this.decodeTechnicianCursor(query.cursor);
    }
    const [billing] = await this.dataSource.query<Array<{ blocked: boolean }>>(
      'SELECT technician_billing_blocked($1) AS blocked',
      [technicianId],
    );
    if (billing?.blocked) return { data: [], billingBlocked: true };
    if (this.isDispatchV2Enabled()) {
      return await this.listDispatchTechnicianRequests(technicianId, query);
    }
    const dispatchV2Enabled = this.isDispatchV2Enabled();
    const providerSettingsMatchingEnabled = this.isProviderSettingsMatchingEnabled();
    const cursor = query.cursor == null ? null : this.decodeTechnicianCursor(query.cursor);
    const schedulePredicate =
      !dispatchV2Enabled && providerSettingsMatchingEnabled
        ? `AND NOT technician_on_time_off($1, COALESCE(o.scheduled_at, now()))
         AND technician_within_work_hours($1, COALESCE(o.scheduled_at, now()), o.is_emergency)`
        : !dispatchV2Enabled
          ? 'AND NOT technician_on_time_off($1, o.scheduled_at)'
          : '';
    const areaPredicate =
      !dispatchV2Enabled && providerSettingsMatchingEnabled
        ? `AND (
             NOT EXISTS (
               SELECT 1 FROM technician_work_areas w WHERE w.technician_id = $1
             )
             OR EXISTS (
               SELECT 1 FROM technician_work_areas w
               WHERE w.technician_id = $1 AND w.area_code = a.area_code
             )
             OR (
               a.area_code IS NULL AND a.latitude IS NOT NULL
               AND tp.work_center_lat IS NOT NULL AND tp.work_center_lng IS NOT NULL
               AND geo_distance_km(
                     tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude
                   ) <= COALESCE(tp.max_request_distance_km, 15)
             )
           )`
        : '';
    const distanceProjection =
      providerSettingsMatchingEnabled || dispatchV2Enabled
        ? `CASE WHEN tp.work_center_lat IS NOT NULL AND a.latitude IS NOT NULL
                   THEN round(geo_distance_km(
                     tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude
                   )::numeric, 1)
               END AS "distanceKm"`
        : 'NULL::numeric AS "distanceKm"';
    const dispatchJoins = dispatchV2Enabled
      ? `JOIN users u ON u.id = tp.user_id
         LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id`
      : '';
    const rows = await this.dataSource.query<
      Array<{
        id: string;
        reference: string;
        serviceTitleAr: string;
        description: string;
        area: string | null;
        customerOfferMinor: string;
        capMinor: string;
        currency: string;
        pricingMode: string;
        offerCount: string;
        createdAt: Date | string;
        searchExpiresAt: Date | string;
        distanceKm: number | string | null;
      }>
    >(
      `SELECT o.id, 'FX-' || o.order_number::text AS reference,
              s.title_ar AS "serviceTitleAr", o.description,
              COALESCE(a.area_code, tp.city) AS area,
              o.customer_offer_minor::text AS "customerOfferMinor",
              o.offer_cap_minor::text AS "capMinor", o.currency,
              s.pricing_type::text AS "pricingMode",
              (SELECT COUNT(*)::text FROM service_order_offers own_offer
                WHERE own_offer.order_id = o.id
                  AND own_offer.technician_id = $1
                  AND own_offer.kind = 'counter') AS "offerCount",
              o.created_at AS "createdAt",
              o.search_expires_at AS "searchExpiresAt",
              ${distanceProjection}
       FROM service_orders o
       JOIN services s ON s.id = o.service_id
       JOIN technician_profiles tp ON tp.user_id = $1
       ${dispatchJoins}
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       WHERE o.status = 'searching'
         AND o.search_expires_at > now()
         ${schedulePredicate} AND NOT technician_billing_blocked(tp.user_id)
         ${areaPredicate}
         AND o.customer_offer_minor IS NOT NULL
         AND tp.application_status = 'approved'
         ${dispatchV2Enabled ? '' : 'AND tp.is_busy = false'}
         AND EXISTS (
           SELECT 1 FROM provider_application_services pas
           WHERE pas.technician_id = $1 AND pas.service_id = o.service_id
         )
         AND NOT EXISTS (
           SELECT 1 FROM service_order_technician_skips skip
           WHERE skip.order_id = o.id AND skip.technician_id = $1
         )
         ${
           dispatchV2Enabled
             ? ''
             : `AND NOT EXISTS (
           SELECT 1 FROM service_orders busy
           WHERE busy.id <> o.id
             AND busy.status IN ('assigned','on_way','in_progress','paused','delayed','emergency')
             AND ($1 = busy.technician_id OR $1 = busy.backup_technician_id)
         )`
         }
         ${dispatchV2Enabled ? getDispatchEligibilitySql() : ''}
       ${cursor == null ? '' : 'AND (o.search_expires_at, o.id) > ($2::timestamptz, $3::uuid)'}
       ORDER BY o.search_expires_at ASC, o.id ASC
       LIMIT ${cursor == null ? '$2' : '$4'}`,
      cursor == null
        ? [technicianId, query.limit + 1]
        : [technicianId, cursor.expiresAt, cursor.id, query.limit + 1],
    );
    const hasMore = rows.length > query.limit;
    const page = hasMore ? rows.slice(0, query.limit) : rows;
    const lastPageRow = page.at(-1);
    const nextCursor =
      hasMore && lastPageRow != null ? this.encodeTechnicianCursor(lastPageRow) : undefined;
    return {
      data: page.map((row) => ({
        id: row.id,
        reference: row.reference,
        serviceTitleAr: row.serviceTitleAr,
        description: row.description,
        area: row.area,
        customerOfferMinor: row.customerOfferMinor,
        capMinor: row.capMinor,
        currency: row.currency,
        canCounter: Number(row.offerCount) < 2,
        distanceKm: row.distanceKm == null ? null : Number(row.distanceKm),
        createdAt: new Date(row.createdAt).toISOString(),
      })),
      ...(nextCursor == null ? {} : { nextCursor }),
    };
  }

  private async listDispatchTechnicianRequests(
    technicianId: string,
    query: ListTechnicianRequestsQueryDto,
  ): Promise<{ data: unknown[]; nextCursor?: string; billingBlocked?: boolean }> {
    const cursor = query.cursor == null ? null : this.decodeDispatchFeedCursor(query.cursor);
    const cursorPredicate =
      cursor == null
        ? ''
        : `WHERE (
           sort_bucket > $4
           OR (sort_bucket = $4 AND (
             (distance_rounded IS NULL AND $5::numeric IS NOT NULL)
             OR (distance_rounded IS NOT NULL AND $5::numeric IS NOT NULL
                 AND distance_rounded > $5::numeric)
             OR (distance_rounded IS NOT DISTINCT FROM $5::numeric
                 AND (created_at, order_id) < ($6::timestamptz, $7::uuid))
           ))
         )`;
    const limitParameter = cursor == null ? '$4' : '$8';
    const parameters =
      cursor == null
        ? [
            technicianId,
            DISPATCH.MAX_PENDING_OFFERS_PER_ORDER,
            DISPATCH.NEW_BADGE_SECONDS,
            query.limit + 1,
          ]
        : [
            technicianId,
            DISPATCH.MAX_PENDING_OFFERS_PER_ORDER,
            DISPATCH.NEW_BADGE_SECONDS,
            cursor.sortBucket,
            cursor.distanceRounded,
            cursor.createdAt,
            cursor.id,
            query.limit + 1,
          ];
    const rows = await this.dataSource.query<DispatchFeedRow[]>(
      `WITH eligible_requests AS (
         SELECT o.id AS order_id,
                s.title_ar AS service_title,
                COALESCE(ga.name_ar, a.area_code, tp.city) AS area,
                CASE WHEN a.latitude IS NOT NULL AND a.longitude IS NOT NULL
                          AND tp.work_center_lat IS NOT NULL AND tp.work_center_lng IS NOT NULL
                     THEN round((geo_distance_km(
                       tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude
                     )::numeric) * 2) / 2
                END AS distance_rounded,
                o.customer_offer_minor::text AS customer_offer_minor,
                o.offer_cap_minor::text AS offer_cap_minor,
                o.scheduled_at,
                o.is_emergency,
                o.search_expires_at AS visible_until,
                o.created_at,
                o.created_at >= now() - make_interval(secs => $3::int) AS is_new,
                o.location_preference,
                CASE WHEN o.is_emergency THEN 0 ELSE 1 END AS sort_bucket
         FROM service_orders o
         JOIN services s ON s.id = o.service_id
         JOIN technician_profiles tp ON tp.user_id = $1
         JOIN users u ON u.id = tp.user_id
         LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
         LEFT JOIN user_addresses a ON a.id = o.selected_address_id
         LEFT JOIN geo_areas ga ON ga.code = a.area_code
         WHERE o.status = 'searching'
           AND o.search_expires_at > now()
           AND o.customer_offer_minor IS NOT NULL
           AND (o.pending_offers_count < $2 OR EXISTS (
             SELECT 1 FROM service_order_offers own_pending
             WHERE own_pending.order_id = o.id
               AND own_pending.technician_id = $1
               AND own_pending.status = 'pending'
               AND own_pending.expires_at > now()
           ))
           ${getDispatchEligibilitySql()}
       ), page AS MATERIALIZED (
         SELECT * FROM eligible_requests
         ${cursorPredicate}
         ORDER BY sort_bucket ASC, distance_rounded ASC NULLS LAST,
                  created_at DESC, order_id DESC
         LIMIT ${limitParameter}
       )
       SELECT order_id AS "orderId", service_title AS "serviceTitle", area,
              distance_rounded AS "distanceRounded", customer_offer_minor AS "customerOfferMinor",
              offer_cap_minor AS "offerCapMinor", scheduled_at AS "scheduledAt",
              is_emergency AS "isEmergency", visible_until AS "visibleUntil",
              created_at AS "createdAt", to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS "createdAtCursor", is_new AS "isNew",
              (SELECT COUNT(*)::int FROM service_order_offers counted_offer
               WHERE counted_offer.order_id = page.order_id AND counted_offer.status = 'pending'
                 AND counted_offer.expires_at > now()) AS "offersCount",
              (SELECT jsonb_build_object('offerId', own_offer.id, 'status', own_offer.status,
                 'amountMinor', own_offer.amount_minor::text, 'serviceLocation', own_offer.service_location,
                 'etaMinutes', own_offer.eta_minutes, 'note', own_offer.note,
                 'expiresAt', own_offer.expires_at, 'revision', own_offer.revision)
               FROM service_order_offers own_offer WHERE own_offer.order_id = page.order_id
                 AND own_offer.technician_id = $1 AND own_offer.status = 'pending' AND own_offer.expires_at > now()
               ORDER BY own_offer.created_at DESC LIMIT 1) AS "myOffer",
              location_preference AS "locationPreference",
              sort_bucket AS "sortBucket"
       FROM page
       ORDER BY sort_bucket ASC, distance_rounded ASC NULLS LAST,
                created_at DESC, order_id DESC`,
      parameters,
    );
    const hasMore = rows.length > query.limit;
    const page = hasMore ? rows.slice(0, query.limit) : rows;
    const lastPageRow = page.at(-1);
    const nextCursor =
      hasMore && lastPageRow != null ? this.encodeDispatchFeedCursor(lastPageRow) : undefined;
    if (page.length > 0) {
      await this.dataSource.query(
        `INSERT INTO request_feed_views (order_id, technician_id)
        SELECT order_id, $2::uuid FROM unnest($1::uuid[]) AS order_id
        ON CONFLICT (order_id, technician_id) DO UPDATE SET last_seen_at = now()`,
        [page.map((row) => row.orderId), technicianId],
      );
    }

    return {
      data: page.map((row) => ({
        orderId: row.orderId,
        serviceTitle: row.serviceTitle,
        area: row.area,
        distanceKm: row.distanceRounded == null ? null : Number(row.distanceRounded),
        customerOfferMinor: row.customerOfferMinor,
        offerCapMinor: row.offerCapMinor,
        scheduledAt: new Date(row.scheduledAt).toISOString(),
        isEmergency: row.isEmergency,
        visibleUntil: new Date(row.visibleUntil).toISOString(),
        createdAt: new Date(row.createdAt).toISOString(),
        isNew: row.isNew,
        offersCount: Number(row.offersCount),
        myOffer: row.myOffer,
        locationPreference: row.locationPreference,
      })),
      ...(nextCursor == null ? {} : { nextCursor }),
    };
  }

  async getTechnicianRequest(
    technicianId: string,
    orderId: string,
  ): Promise<{ data: Record<string, unknown> }> {
    if (!this.isDispatchV2Enabled()) throw new NotFoundException('Order not found.');
    const rows = await this.dataSource.query<
      Array<{
        id: string;
        reference: string;
        serviceTitleAr: string;
        description: string;
        area: string | null;
        customerOfferMinor: string;
        capMinor: string;
        currency: string;
        pricingMode: string;
        scheduledAt: Date | string;
        locationPreference: string;
        distanceKm: number | string | null;
        customerFirstName: string | null;
        customerScore: number | string;
        pendingOffersCount: number | string;
        paymentMethod: string | null;
        visibleUntil: Date | string;
        acceptsWorkshopJobs: boolean;
      }>
    >(
      `SELECT o.id, 'FX-' || o.order_number::text AS reference,
              s.title_ar AS "serviceTitleAr", o.description,
              COALESCE(ga.name_ar, a.area_code, tp.city) AS area,
              o.customer_offer_minor::text AS "customerOfferMinor",
              o.offer_cap_minor::text AS "capMinor", o.currency,
              s.pricing_type::text AS "pricingMode", o.scheduled_at AS "scheduledAt",
              o.location_preference AS "locationPreference",
              o.search_expires_at AS "visibleUntil",
              COALESCE(tw.accepts_workshop_jobs, false) AS "acceptsWorkshopJobs",
              NULLIF(split_part(regexp_replace(COALESCE(btrim(customer.display_name), ''), '[[:space:]]+', ' ', 'g'), ' ', 1), '') AS "customerFirstName",
              customer.score AS "customerScore",
              (SELECT COUNT(*)::int FROM service_order_offers current_offer
               WHERE current_offer.order_id = o.id AND current_offer.status = 'pending'
                 AND current_offer.expires_at > now()) AS "pendingOffersCount",
              o.payment_selection->>'method' AS "paymentMethod",
              CASE WHEN tp.work_center_lat IS NOT NULL AND a.latitude IS NOT NULL
                         AND tp.work_center_lng IS NOT NULL AND a.longitude IS NOT NULL
                   THEN round(geo_distance_km(
                     tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude
                   )::numeric * 2) / 2
              END AS "distanceKm"
       FROM service_orders o
       JOIN services s ON s.id = o.service_id
       JOIN technician_profiles tp ON tp.user_id = $2
       JOIN users u ON u.id = tp.user_id
       JOIN users customer ON customer.id = o.customer_id
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       LEFT JOIN geo_areas ga ON ga.code = a.area_code
       LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
       WHERE o.id = $1 AND o.status = 'searching' AND o.search_expires_at > now()
         AND o.customer_offer_minor IS NOT NULL
         ${getDispatchEligibilitySql()}
       LIMIT 1`,
      [orderId, technicianId],
    );
    const row = rows[0];
    if (row == null) throw new NotFoundException('Order not found.');
    const [photos, answers] = await Promise.all([
      this.dataSource.query<Array<{ fileId: string; contentType: string; position: number }>>(
        `SELECT a.file_id AS "fileId", f.content_type AS "contentType", a.position
         FROM service_order_attachments a
         JOIN service_orders o ON o.id = a.order_id
         JOIN stored_files f ON f.id = a.file_id AND f.owner_id = o.customer_id
         WHERE a.order_id = $1 AND a.role = 'photo' AND f.kind = 'image'
           AND f.purpose = 'booking' AND f.status = 'ready' AND f.deleted_at IS NULL
         ORDER BY a.position, a.file_id`,
        [orderId],
      ),
      this.dataSource.query<Array<{ questionSnapshot: Record<string, unknown>; answer: unknown }>>(
        `SELECT question_snapshot AS "questionSnapshot", answer
         FROM service_order_answers WHERE order_id = $1 ORDER BY question_id`,
        [orderId],
      ),
    ]);
    const fileService = this.files;
    return {
      data: {
        id: row.id,
        reference: row.reference,
        serviceTitleAr: row.serviceTitleAr,
        description: row.description,
        area: row.area,
        customerOfferMinor: row.customerOfferMinor,
        capMinor: row.capMinor,
        currency: row.currency,
        pricingMode: row.pricingMode,
        scheduledAt: new Date(row.scheduledAt).toISOString(),
        locationPreference: row.locationPreference,
        visibleUntil: new Date(row.visibleUntil).toISOString(),
        acceptsWorkshopJobs: row.acceptsWorkshopJobs,
        distanceKm: row.distanceKm == null ? null : Number(row.distanceKm),
        customerFirstName: row.customerFirstName,
        customerScore: Number(row.customerScore),
        customerRating: null,
        paymentMethod: row.paymentMethod,
        pendingOffersCount: Number(row.pendingOffersCount),
        photos:
          fileService == null
            ? photos
            : await Promise.all(
                photos.map(async (photo) => ({
                  ...photo,
                  ...(await fileService.createBookingDownload(row.id, technicianId, photo.fileId)),
                })),
              ),
        answers,
      },
    };
  }

  async recordTechnicianRequestView(technicianId: string, orderId: string): Promise<void> {
    try {
      await this.dataSource.query(
        `INSERT INTO request_views (order_id, technician_id)
         VALUES ($1, $2)
         ON CONFLICT (order_id, technician_id) DO UPDATE SET viewed_at = now()`,
        [orderId, technicianId],
      );
    } catch {
      // Measurement must never turn a valid detail request into a 500 while
      // an older deployment is still waiting for migration 0142.
    }
  }

  async getTechnicianAssignment(
    technicianId: string,
    orderId: string,
  ): Promise<{ data: Record<string, unknown> }> {
    this.assertDispatchV2Enabled();
    const [row] = await this.dataSource.query<Array<Record<string, unknown>>>(
      `SELECT o.id, o.status::text AS status, 'FX-' || o.order_number::text AS reference, s.title_ar AS "serviceTitleAr",
        o.description, o.scheduled_at AS "scheduledAt", o.payment_selection->>'method' AS "paymentMethod",
        o.agreed_labor_minor::text AS "customerOfferMinor", o.agreed_labor_minor::text AS "offerCapMinor",
        o.service_location AS "serviceLocation", o.location_preference AS "locationPreference",
        customer.display_name AS "customerFullName", customer.phone AS "customerPhone",
        CASE WHEN o.service_location = 'provider_workshop' THEN offer.workshop_address
          ELSE COALESCE(a.formatted_address, o.address_text) END AS address,
        CASE WHEN o.service_location = 'provider_workshop' THEN offer.workshop_lat ELSE COALESCE(a.latitude, o.latitude) END AS latitude,
        CASE WHEN o.service_location = 'provider_workshop' THEN offer.workshop_lng ELSE COALESCE(a.longitude, o.longitude) END AS longitude,
        COALESCE(ga.name_ar, a.area_code) AS area, offer.eta_minutes AS "etaMinutes"
       FROM service_orders o JOIN services s ON s.id = o.service_id
       JOIN users customer ON customer.id = o.customer_id
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       LEFT JOIN geo_areas ga ON ga.code = a.area_code
       LEFT JOIN service_order_offers offer ON offer.id = o.assigned_offer_id
       WHERE o.id = $1 AND (o.technician_id = $2 OR o.backup_technician_id = $2)
         AND o.status IN ('assigned','on_way','in_progress','paused','delayed','emergency')`,
      [orderId, technicianId],
    );
    if (!row) throw new NotFoundException('Assigned order not found.');
    return { data: row };
  }

  async currentTechnicianAssignment(
    technicianId: string,
  ): Promise<{ data: Record<string, unknown> | null }> {
    this.assertDispatchV2Enabled();
    const [row] = await this.dataSource.query<Array<{ id: string }>>(
      `SELECT id FROM service_orders WHERE (technician_id = $1 OR backup_technician_id = $1)
        AND status IN ('assigned','on_way','in_progress','paused','delayed','emergency')
       ORDER BY scheduled_at, id LIMIT 1`,
      [technicianId],
    );
    return row == null ? { data: null } : await this.getTechnicianAssignment(technicianId, row.id);
  }

  async createOffer(
    technicianId: string,
    orderId: string,
    dto: CreateTechnicianOfferDto,
    idempotencyKey?: string,
  ): Promise<{ id: string; status: string; amountMinor: string; expiresAt: string }> {
    this.assertDispatchV2Enabled();
    return await dispatchMutation(
      this.dataSource,
      true,
      'offer.create',
      technicianId,
      idempotencyKey,
      { orderId, dto },
      async (manager) => {
        await this.lockTechnicianOffers(manager, technicianId);
        const order = await this.lockOrder(manager, orderId);
        await assertNotBillingBlocked(manager, technicianId);
        if (
          order.status !== 'searching' ||
          order.search_expires_at == null ||
          new Date(order.search_expires_at).getTime() <= Date.now()
        ) {
          throw new ConflictException({
            code: 'ORDER_NOT_AVAILABLE',
            message: 'This order is no longer available.',
          });
        }

        const eligibleRows = queryRows<{ eligible: boolean }>(
          await manager.query(
            `SELECT EXISTS (
             SELECT 1
             FROM service_orders o
             JOIN technician_profiles tp ON tp.user_id = $2
             JOIN users u ON u.id = tp.user_id
             LEFT JOIN user_addresses a ON a.id = o.selected_address_id
             LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
             WHERE o.id = $1 ${getDispatchEligibilitySql()}
           ) AS eligible`,
            [orderId, technicianId],
          ),
        );
        if (eligibleRows[0]?.eligible !== true) {
          throw new ForbiddenException({
            code: 'NOT_ELIGIBLE',
            message: 'The technician is not eligible for this order.',
          });
        }

        const serviceLocation = dto.serviceLocation;
        if (
          (serviceLocation === 'provider_workshop' &&
            order.location_preference === 'customer_site_only') ||
          (serviceLocation === 'customer_site' && order.location_preference === 'workshop_only')
        ) {
          throw new BadRequestException({
            code: 'SERVICE_LOCATION_NOT_ALLOWED',
            message: 'The selected service location is not allowed for this order.',
          });
        }
        let workshop: {
          lat: number | string;
          lng: number | string;
          address_line: string;
          area_code: string | null;
        } | null = null;
        if (serviceLocation === 'provider_workshop') {
          const workshops = queryRows<{
            accepts_workshop_jobs: boolean;
            lat: number | string;
            lng: number | string;
            address_line: string;
            area_code: string | null;
          }>(
            await manager.query(
              `SELECT accepts_workshop_jobs, lat, lng, address_line, area_code
             FROM technician_workshops
             WHERE technician_id = $1 AND is_active IS TRUE`,
              [technicianId],
            ),
          );
          const candidate = workshops[0];
          if (candidate?.accepts_workshop_jobs !== true) {
            throw new ForbiddenException({
              code: 'WORKSHOP_NOT_ACCEPTED',
              message: 'The technician does not accept workshop jobs.',
            });
          }
          workshop = candidate;
        }

        if (order.customer_offer_minor == null || order.offer_cap_minor == null) {
          throw new ConflictException({
            code: 'ORDER_PRICING_UNAVAILABLE',
            message: 'Order pricing is unavailable.',
          });
        }
        let amountMinor = order.customer_offer_minor;
        if (dto.kind === 'accept') {
          if (dto.amountMinor != null && dto.amountMinor !== order.customer_offer_minor) {
            throw new BadRequestException({
              code: 'INVALID_ACCEPT_AMOUNT',
              message: 'An accept offer must match the current customer offer.',
            });
          }
        } else {
          if (dto.amountMinor == null) {
            throw new BadRequestException({
              code: 'INVALID_COUNTER_AMOUNT',
              message: 'Counter offers require an amount.',
            });
          }
          const amount = this.parseMinorAmount(dto.amountMinor);
          if (
            amount <= BigInt(order.customer_offer_minor) ||
            amount > BigInt(order.offer_cap_minor)
          ) {
            throw new BadRequestException({
              code: 'INVALID_COUNTER_AMOUNT',
              message: 'Counter offer must exceed the customer offer and not exceed the cap.',
            });
          }
          amountMinor = amount.toString();
        }

        await manager.query(
          `UPDATE service_order_offers
         SET status = 'expired', close_reason = 'expired', responded_at = now()
         WHERE order_id = $1 AND status = 'pending' AND expires_at <= now()`,
          [order.id],
        );
        const existing = queryRows<{
          id: string;
          amount_minor: string;
          expires_at: Date | string;
        }>(
          await manager.query(
            `SELECT id, amount_minor::text, expires_at
           FROM service_order_offers
           WHERE order_id = $1 AND technician_id = $2 AND status = 'pending'
             AND expires_at > now()
           ORDER BY created_at DESC, id DESC LIMIT 1`,
            [order.id, technicianId],
          ),
        )[0];
        if (existing != null) {
          return {
            id: existing.id,
            status: 'pending',
            amountMinor: existing.amount_minor,
            expiresAt: new Date(existing.expires_at).toISOString(),
          };
        }

        const pendingRows = queryRows<{ pending_count: number | string }>(
          await manager.query(
            `UPDATE service_orders o
           SET pending_offers_count = (
             SELECT COUNT(*)::int FROM service_order_offers current_offer
             WHERE current_offer.order_id = o.id AND current_offer.status = 'pending'
               AND current_offer.expires_at > now()
           )
           WHERE o.id = $1
           RETURNING pending_offers_count AS pending_count`,
            [order.id],
          ),
        );
        if (Number(pendingRows[0]?.pending_count ?? 0) >= DISPATCH.MAX_PENDING_OFFERS_PER_ORDER) {
          throw new ConflictException({
            code: 'ORDER_OFFERS_FULL',
            message: 'The maximum number of pending offers for this order has been reached.',
          });
        }

        if (!this.isScheduledOrder(order)) {
          const activeRows = queryRows<{ active_count: number | string }>(
            await manager.query(
              `SELECT COUNT(*)::int AS active_count
             FROM service_order_offers offer
             JOIN service_orders existing_order ON existing_order.id = offer.order_id
             WHERE offer.technician_id = $1 AND offer.status = 'pending'
               AND offer.expires_at > now() AND existing_order.status = 'searching'
               AND (existing_order.search_starts_at IS NULL
                    OR existing_order.search_starts_at >= existing_order.scheduled_at - interval '1 minute')`,
              [technicianId],
            ),
          );
          if (Number(activeRows[0]?.active_count ?? 0) >= DISPATCH.MAX_ACTIVE_OFFERS_PER_TECH) {
            throw new ConflictException({
              code: 'TOO_MANY_ACTIVE_OFFERS',
              message: 'The technician has reached the active offer limit.',
            });
          }
        }

        const [history] = await manager.query<Array<{ last_revision: number }>>(
          `SELECT COALESCE(MAX(revision), 0)::int AS last_revision FROM service_order_offers
           WHERE order_id = $1 AND technician_id = $2 AND kind <> 'ops'`,
          [order.id, technicianId],
        );
        const revision = (history?.last_revision ?? 0) + 1;
        if (revision > DISPATCH.MAX_OFFER_REVISIONS) {
          throw new ConflictException({
            code: 'OFFER_REVISION_LIMIT',
            message: 'The offer revision limit has been reached.',
          });
        }

        const inserted = queryRows<{ id: string; expires_at: Date | string }>(
          await manager.query(
            `INSERT INTO service_order_offers
             (order_id, technician_id, kind, amount_minor, currency, status, expires_at,
              service_location, workshop_lat, workshop_lng, workshop_address,
              workshop_area_code, eta_minutes, note, idempotency_key, revision)
           VALUES ($1, $2, $3, $4, $5, 'pending',
                   LEAST(now() + make_interval(mins => $12::int), $13::timestamptz),
                   $6, $7, $8, $9, $10, $11, $14, $15::uuid, $16)
           ON CONFLICT (order_id, technician_id) WHERE status = 'pending' DO NOTHING
           RETURNING id, expires_at`,
            [
              order.id,
              technicianId,
              dto.kind,
              amountMinor,
              order.currency,
              serviceLocation,
              workshop?.lat ?? null,
              workshop?.lng ?? null,
              workshop?.address_line ?? null,
              workshop?.area_code ?? null,
              dto.etaMinutes ?? null,
              DISPATCH.OFFER_TTL_MIN,
              order.search_expires_at,
              dto.note ?? null,
              idempotencyKey?.trim() ?? null,
              revision,
            ],
          ),
        );
        const offer = inserted[0];
        if (offer == null) {
          const duplicate = queryRows<{
            id: string;
            amount_minor: string;
            expires_at: Date | string;
          }>(
            await manager.query(
              `SELECT id, amount_minor::text, expires_at
             FROM service_order_offers
             WHERE order_id = $1 AND technician_id = $2 AND status = 'pending'
             ORDER BY created_at DESC, id DESC LIMIT 1`,
              [order.id, technicianId],
            ),
          )[0];
          if (duplicate == null) throw new ConflictException('Offer could not be created.');
          return {
            id: duplicate.id,
            status: 'pending',
            amountMinor: duplicate.amount_minor,
            expiresAt: new Date(duplicate.expires_at).toISOString(),
          };
        }

        await manager.query(
          `UPDATE service_orders
         SET pending_offers_count = pending_offers_count + 1,
             first_offer_at = COALESCE(first_offer_at, now()),
             version = version + 1, updated_at = now()
         WHERE id = $1`,
          [order.id],
        );
        const eventPayload = {
          offerId: offer.id,
          orderId: order.id,
          kind: dto.kind,
          amountMinor,
          currency: order.currency,
          serviceLocation,
          etaMinutes: dto.etaMinutes ?? null,
          note: dto.note ?? null,
        };
        await this.timeline(manager, order.id, 'offer_received', 'تم استلام عرض جديد', null, null, {
          offerId: offer.id,
          technicianId,
          kind: dto.kind,
        });
        await this.queueOutbox(
          manager,
          'offer.received',
          order.id,
          order.customer_id,
          eventPayload,
        );
        return {
          id: offer.id,
          status: 'pending',
          amountMinor,
          expiresAt: new Date(offer.expires_at).toISOString(),
        };
      },
    );
  }

  async listTechnicianOffers(
    technicianId: string,
    status: ListTechnicianOffersQueryDto['status'] = 'pending',
    requestedLimit = 50,
    cursor?: string,
  ): Promise<ListTechnicianOffersResponseDto> {
    this.assertDispatchV2Enabled();
    const limit = Math.min(Math.max(requestedLimit || 50, 1), 100);
    const decodedCursor = cursor ? this.decodeTechnicianOfferCursor(cursor) : null;
    const rows = await this.dataSource.query<
      Array<
        Omit<
          TechnicianOfferDto,
          'expiresAt' | 'createdAt' | 'scheduledAt' | 'maxOfferRevisions'
        > & {
          expiresAt: Date | string;
          createdAt: Date | string;
          scheduledAt: Date | string;
        }
      >
    >(
      `SELECT offer.id, o.id AS "orderId", 'FX-' || o.order_number::text AS reference,
              s.title_ar AS "serviceTitleAr", offer.kind, offer.amount_minor::text AS "amountMinor",
              offer.currency, offer.status::text, offer.expires_at AS "expiresAt",
              offer.created_at AS "createdAt", offer.revision,
              offer.service_location AS "serviceLocation", offer.eta_minutes AS "etaMinutes",
              o.scheduled_at AS "scheduledAt", COALESCE(ga.name_ar, a.area_code) AS area,
              offer.note, offer.close_reason AS "closeReason"
       FROM service_order_offers offer
       JOIN service_orders o ON o.id = offer.order_id
       JOIN services s ON s.id = o.service_id
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       LEFT JOIN geo_areas ga ON ga.code = a.area_code
       WHERE offer.technician_id = $1 AND ($2 = 'all' OR offer.status::text = $2)
         AND (offer.status <> 'pending' OR offer.expires_at > now())
         AND ($3::timestamptz IS NULL OR (offer.created_at, offer.id) < ($3::timestamptz, $4::uuid))
       ORDER BY offer.created_at DESC, offer.id DESC
       LIMIT $5`,
      [
        technicianId,
        status,
        decodedCursor?.createdAt ?? null,
        decodedCursor?.id ?? null,
        limit + 1,
      ],
    );
    const hasMore = rows.length > limit;
    const pageRows = hasMore ? rows.slice(0, limit) : rows;
    const lastPageRow = pageRows.at(-1);
    const data = pageRows.map((row): TechnicianOfferDto => ({
      id: row.id,
      orderId: row.orderId,
      reference: row.reference,
      serviceTitleAr: row.serviceTitleAr,
      kind: row.kind,
      amountMinor: row.amountMinor,
      currency: row.currency,
      status: row.status,
      expiresAt: new Date(row.expiresAt).toISOString(),
      createdAt: new Date(row.createdAt).toISOString(),
      revision: row.revision,
      serviceLocation: row.serviceLocation,
      etaMinutes: row.etaMinutes,
      scheduledAt: new Date(row.scheduledAt).toISOString(),
      area: row.area,
      note: row.note,
      closeReason: row.closeReason,
      maxOfferRevisions: DISPATCH.MAX_OFFER_REVISIONS,
    }));
    return {
      data,
      nextCursor: hasMore && lastPageRow ? this.encodeTechnicianOfferCursor(lastPageRow) : null,
      limit,
    };
  }

  private encodeTechnicianOfferCursor(row: { id: string; createdAt: Date | string }): string {
    const createdAt = new Date(row.createdAt);
    if (!row.id || Number.isNaN(createdAt.getTime())) {
      throw new BadRequestException('The technician offer query returned an invalid cursor row.');
    }
    return Buffer.from(JSON.stringify({ createdAt: createdAt.toISOString(), id: row.id })).toString(
      'base64url',
    );
  }

  private decodeTechnicianOfferCursor(value: string): { createdAt: string; id: string } {
    try {
      const decoded = JSON.parse(Buffer.from(value, 'base64url').toString('utf8')) as {
        createdAt?: unknown;
        id?: unknown;
      };
      const createdAt = typeof decoded.createdAt === 'string' ? new Date(decoded.createdAt) : null;
      const id = decoded.id;
      if (
        !createdAt ||
        Number.isNaN(createdAt.getTime()) ||
        typeof id !== 'string' ||
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)
      ) {
        throw new Error('invalid cursor');
      }
      return { createdAt: createdAt.toISOString(), id };
    } catch {
      throw new BadRequestException('Invalid technician offer cursor.');
    }
  }

  async updateTechnicianOffer(
    technicianId: string,
    offerId: string,
    dto: UpdateTechnicianOfferDto,
    idempotencyKey?: string,
  ): Promise<{ id: string; status: string; revision: number; amountMinor: string }> {
    this.assertDispatchV2Enabled();
    const hasChanges =
      dto.amountMinor !== undefined ||
      dto.serviceLocation !== undefined ||
      dto.etaMinutes !== undefined ||
      dto.note !== undefined;
    if (!hasChanges) {
      throw new BadRequestException({
        code: 'EMPTY_OFFER_PATCH',
        message: 'At least one offer field must be updated.',
      });
    }
    return await dispatchMutation(
      this.dataSource,
      true,
      'offer.update',
      technicianId,
      idempotencyKey,
      { offerId, dto },
      async (manager) => {
        const located = queryRows<{ order_id: string }>(
          await manager.query(
            `SELECT order_id FROM service_order_offers WHERE id = $1 AND technician_id = $2`,
            [offerId, technicianId],
          ),
        )[0];
        if (located == null) {
          throw new NotFoundException({ code: 'OFFER_NOT_FOUND', message: 'Offer not found.' });
        }
        await this.lockTechnicianOffers(manager, technicianId);
        const order = await this.lockOrder(manager, located.order_id);
        await assertNotBillingBlocked(manager, technicianId);
        if (
          order.status !== 'searching' ||
          order.search_expires_at == null ||
          new Date(order.search_expires_at).getTime() <= Date.now()
        ) {
          throw new ConflictException({
            code: 'ORDER_NOT_AVAILABLE',
            message: 'This order is no longer available.',
          });
        }
        const current = queryRows<DispatchOfferRow>(
          await manager.query(
            `SELECT offer.id, offer.order_id, offer.technician_id, offer.kind,
                  offer.amount_minor::text, offer.status::text, offer.expires_at,
                  offer.service_location, offer.eta_minutes, offer.note, offer.revision,
                  o.customer_offer_minor::text, o.offer_cap_minor::text, o.location_preference
           FROM service_order_offers offer
           JOIN service_orders o ON o.id = offer.order_id
           WHERE offer.id = $1 AND offer.technician_id = $2
           FOR UPDATE OF offer`,
            [offerId, technicianId],
          ),
        )[0];
        if (current == null) {
          throw new NotFoundException({ code: 'OFFER_NOT_FOUND', message: 'Offer not found.' });
        }
        if (current.status !== 'pending' || new Date(current.expires_at).getTime() <= Date.now()) {
          throw new ConflictException({
            code: 'OFFER_NOT_PENDING',
            message: 'Only unexpired pending offers can be revised.',
          });
        }
        if (current.revision >= DISPATCH.MAX_OFFER_REVISIONS) {
          throw new ConflictException({
            code: 'OFFER_REVISION_LIMIT',
            message: 'The offer revision limit has been reached.',
          });
        }

        const serviceLocation = dto.serviceLocation ?? current.service_location;
        if (
          (serviceLocation === 'provider_workshop' &&
            order.location_preference === 'customer_site_only') ||
          (serviceLocation === 'customer_site' && order.location_preference === 'workshop_only')
        ) {
          throw new BadRequestException({
            code: 'SERVICE_LOCATION_NOT_ALLOWED',
            message: 'The selected service location is not allowed for this order.',
          });
        }
        let workshop: {
          lat: number | string;
          lng: number | string;
          address_line: string;
          area_code: string | null;
        } | null = null;
        if (serviceLocation === 'provider_workshop') {
          const workshops = queryRows<{
            accepts_workshop_jobs: boolean;
            lat: number | string;
            lng: number | string;
            address_line: string;
            area_code: string | null;
          }>(
            await manager.query(
              `SELECT accepts_workshop_jobs, lat, lng, address_line, area_code
             FROM technician_workshops
             WHERE technician_id = $1 AND is_active IS TRUE`,
              [technicianId],
            ),
          );
          const candidate = workshops[0];
          if (candidate?.accepts_workshop_jobs !== true) {
            throw new ForbiddenException({
              code: 'WORKSHOP_NOT_ACCEPTED',
              message: 'The technician does not accept workshop jobs.',
            });
          }
          workshop = candidate;
        }
        let amountMinor = dto.amountMinor ?? current.amount_minor;
        let kind = current.kind;
        if (dto.amountMinor !== undefined && amountMinor !== current.amount_minor) {
          if (current.customer_offer_minor == null || current.offer_cap_minor == null) {
            throw new ConflictException({
              code: 'ORDER_PRICING_UNAVAILABLE',
              message: 'Order pricing is unavailable.',
            });
          }
          const parsedAmount = this.parseMinorAmount(amountMinor);
          if (
            parsedAmount < BigInt(current.customer_offer_minor) ||
            parsedAmount > BigInt(current.offer_cap_minor)
          ) {
            throw new BadRequestException({
              code: 'INVALID_COUNTER_AMOUNT',
              message: 'Counter offer must exceed the customer offer and not exceed the cap.',
            });
          }
          amountMinor = parsedAmount.toString();
          kind = amountMinor === current.customer_offer_minor ? 'accept' : 'counter';
        }
        const revision = current.revision + 1;
        const etaMinutes = dto.etaMinutes ?? current.eta_minutes;
        const note = dto.note ?? current.note;
        await manager.query(
          `UPDATE service_order_offers
         SET amount_minor = $3, service_location = $4, workshop_lat = $5,
             workshop_lng = $6, workshop_address = $7, workshop_area_code = $8,
             eta_minutes = $9, note = $10, revision = $11, kind = $13
         WHERE id = $1 AND technician_id = $2 AND status = 'pending' AND revision = $12`,
          [
            offerId,
            technicianId,
            amountMinor,
            serviceLocation,
            workshop?.lat ?? null,
            workshop?.lng ?? null,
            workshop?.address_line ?? null,
            workshop?.area_code ?? null,
            etaMinutes,
            note,
            revision,
            current.revision,
            kind,
          ],
        );
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        const payload = {
          offerId,
          orderId: order.id,
          amountMinor,
          serviceLocation,
          etaMinutes,
          note,
          revision,
        };
        await this.queueOutbox(manager, 'offer.updated', order.id, order.customer_id, payload);
        await this.timeline(manager, order.id, 'offer_updated', 'تم تعديل عرض فني', null, null, {
          offerId,
          revision,
        });
        return { id: offerId, status: 'pending', revision, amountMinor };
      },
    );
  }

  private isDispatchV2Enabled(): boolean {
    return this.config?.get<boolean>('dispatch.v2Enabled') === true;
  }

  private assertDispatchV2Enabled(): void {
    if (!this.isDispatchV2Enabled()) {
      throw new NotFoundException({
        code: 'DISPATCH_V2_DISABLED',
        message: 'Dispatch v2 is not enabled.',
      });
    }
  }

  private async lockTechnicianDispatchSettings(
    manager: EntityManager,
    technicianId: string,
    enabled = this.isDispatchV2Enabled(),
  ): Promise<void> {
    void enabled;
    await manager.query("SET LOCAL lock_timeout = '5s'");
    await manager.query('SELECT pg_advisory_xact_lock(hashtextextended($1, 0))', [technicianId]);
  }

  private async lockTechnicianOffers(manager: EntityManager, technicianId: string): Promise<void> {
    await manager.query("SET LOCAL lock_timeout = '5s'");
    // Retain the existing settings lock and add the namespaced lock shared by v2 dispatch actions.
    await manager.query('SELECT pg_advisory_xact_lock(hashtextextended($1, 0))', [technicianId]);
    await manager.query('SELECT pg_advisory_xact_lock(hashtextextended($1, 0))', [
      `tech:${technicianId}`,
    ]);
  }

  private async refreshPendingOfferCount(manager: EntityManager, orderId: string): Promise<void> {
    await manager.query(
      `UPDATE service_orders o
       SET pending_offers_count = (
         SELECT COUNT(*)::int FROM service_order_offers current_offer
         WHERE current_offer.order_id = o.id AND current_offer.status = 'pending'
           AND current_offer.expires_at > now()
       )
       WHERE o.id = $1`,
      [orderId],
    );
  }

  private isScheduledOrder(order: LockedOrderRow): boolean {
    return (
      order.search_starts_at != null &&
      new Date(order.search_starts_at).getTime() < new Date(order.scheduled_at).getTime() - 60_000
    );
  }

  private isProviderSettingsMatchingEnabled(): boolean {
    return (process.env.PROVIDER_SETTINGS_MATCHING_ENABLED ?? 'false') === 'true';
  }

  private encodeTechnicianCursor(row: { searchExpiresAt: Date | string; id: string }): string {
    return Buffer.from(
      JSON.stringify({ expiresAt: new Date(row.searchExpiresAt).toISOString(), id: row.id }),
      'utf8',
    ).toString('base64url');
  }

  private decodeTechnicianCursor(value: string): { expiresAt: string; id: string } {
    try {
      if (value.length > 200) throw new Error('cursor too long');
      const parsed = JSON.parse(Buffer.from(value, 'base64url').toString('utf8')) as {
        expiresAt?: unknown;
        id?: unknown;
      };
      if (
        typeof parsed.expiresAt !== 'string' ||
        Number.isNaN(Date.parse(parsed.expiresAt)) ||
        typeof parsed.id !== 'string' ||
        !/^[0-9a-f-]{36}$/i.test(parsed.id)
      )
        throw new Error('invalid cursor');
      return { expiresAt: new Date(parsed.expiresAt).toISOString(), id: parsed.id };
    } catch {
      throw new BadRequestException('Invalid technician requests cursor.');
    }
  }

  private encodeDispatchFeedCursor(row: DispatchFeedRow): string {
    const distance = row.distanceRounded == null ? null : Number(row.distanceRounded);
    const tuple: [number, number | null, string, string] = [
      row.sortBucket,
      distance,
      row.createdAtCursor ?? new Date(row.createdAt).toISOString(),
      row.orderId,
    ];
    return Buffer.from(JSON.stringify(tuple), 'utf8').toString('base64url');
  }

  private decodeDispatchFeedCursor(value: string): DispatchFeedCursor {
    try {
      if (value.length > 200) throw new Error('cursor too long');
      const parsed: unknown = JSON.parse(Buffer.from(value, 'base64url').toString('utf8'));
      if (!Array.isArray(parsed) || parsed.length !== 4) throw new Error('invalid tuple');
      const [sortBucket, distanceRounded, createdAt, id] = parsed as unknown[];
      if (
        (sortBucket !== 0 && sortBucket !== 1) ||
        (distanceRounded !== null &&
          (typeof distanceRounded !== 'number' ||
            !Number.isFinite(distanceRounded) ||
            distanceRounded < 0)) ||
        typeof createdAt !== 'string' ||
        Number.isNaN(Date.parse(createdAt)) ||
        typeof id !== 'string' ||
        !isUUID(id)
      ) {
        throw new Error('invalid cursor');
      }
      return {
        sortBucket,
        distanceRounded,
        createdAt,
        id,
      };
    } catch {
      throw new BadRequestException('Invalid technician requests cursor.');
    }
  }

  async acceptByTechnician(
    technicianId: string,
    orderId: string,
    idempotencyKey?: string,
  ): Promise<{ status: string }> {
    if (this.isDispatchV2Enabled()) {
      return await this.createOffer(
        technicianId,
        orderId,
        {
          kind: 'accept',
          serviceLocation: 'customer_site',
        },
        idempotencyKey,
      );
    }
    return await this.dataSource.transaction(async (manager) => {
      const dispatchV2Enabled = this.isDispatchV2Enabled();
      await this.lockTechnicianDispatchSettings(
        manager,
        technicianId,
        this.isProviderSettingsMatchingEnabled() || dispatchV2Enabled,
      );
      await assertNotBillingBlocked(manager, technicianId);
      const order = await this.lockEligibleOrder(
        manager,
        orderId,
        technicianId,
        this.isProviderSettingsMatchingEnabled() || dispatchV2Enabled,
        dispatchV2Enabled,
      );
      if (order.status === 'assigned' && order.technician_id === technicianId) {
        return { status: 'assigned' };
      }
      this.assertSearchable(order);
      const customerOfferMinor = order.customer_offer_minor;
      if (customerOfferMinor == null) throw new ConflictException('Order pricing is unavailable.');
      if (dispatchV2Enabled && this.isScheduledOrder(order)) {
        await reserveScheduledTechnician(
          manager,
          order.id,
          technicianId,
          order.scheduled_at,
          DISPATCH.DEFAULT_JOB_DURATION_MIN,
        );
      } else {
        await reserveActiveTechnicians(manager, order.id, [technicianId]);
      }
      await manager.query(
        `UPDATE service_order_offers
         SET status = 'superseded', close_reason = 'other_offer_chosen', responded_at = now()
         WHERE order_id = $1 AND status = 'pending'`,
        [order.id],
      );
      const acceptedOffer = queryRows<{ id: string }>(
        await manager.query(
          `INSERT INTO service_order_offers
           (order_id, technician_id, kind, amount_minor, currency, status, expires_at, responded_at)
         VALUES ($1, $2, 'accept', $3, $4, 'accepted', now() + interval '120 seconds', now())
         RETURNING id`,
          [order.id, technicianId, customerOfferMinor, order.currency],
        ),
      )[0];
      if (acceptedOffer == null) throw new Error('Accepted offer insert returned no row.');
      await this.assignOrder(manager, order, technicianId, customerOfferMinor, {
        offerId: acceptedOffer.id,
        serviceLocation: 'customer_site',
      });
      return { status: 'assigned' };
    });
  }

  async counterOffer(
    technicianId: string,
    orderId: string,
    amountMinor: string,
    idempotencyKey?: string,
  ): Promise<{ id: string; status: string; expiresAt: string }> {
    if (this.isDispatchV2Enabled()) {
      const created = await this.createOffer(
        technicianId,
        orderId,
        {
          kind: 'counter',
          amountMinor,
          serviceLocation: 'customer_site',
        },
        idempotencyKey,
      );
      return { id: created.id, status: created.status, expiresAt: created.expiresAt };
    }
    return await this.dataSource.transaction(async (manager) => {
      const dispatchV2Enabled = this.isDispatchV2Enabled();
      await this.lockTechnicianDispatchSettings(manager, technicianId);
      await assertNotBillingBlocked(manager, technicianId);
      const order = await this.lockEligibleOrder(
        manager,
        orderId,
        technicianId,
        dispatchV2Enabled,
        dispatchV2Enabled,
      );
      this.assertSearchable(order);
      const amount = this.parseMinorAmount(amountMinor);
      if (
        order.customer_offer_minor == null ||
        order.offer_cap_minor == null ||
        amount <= BigInt(order.customer_offer_minor) ||
        amount > BigInt(order.offer_cap_minor)
      ) {
        throw new BadRequestException('Counter offer is outside the allowed range.');
      }
      const counts = queryRows<{
        total: string;
        existing_id: string | null;
        existing_expires_at: Date | string | null;
      }>(
        await manager.query(
          `SELECT COUNT(*)::text AS total,
                  (SELECT id FROM service_order_offers
                   WHERE order_id = $1 AND technician_id = $2 AND kind = 'counter'
                     AND status = 'pending' AND expires_at > now() AND amount_minor = $3
                   ORDER BY created_at DESC, id DESC LIMIT 1) AS existing_id,
                  (SELECT expires_at FROM service_order_offers
                   WHERE order_id = $1 AND technician_id = $2 AND kind = 'counter'
                     AND status = 'pending' AND expires_at > now() AND amount_minor = $3
                   ORDER BY created_at DESC, id DESC LIMIT 1) AS existing_expires_at
           FROM service_order_offers
           WHERE order_id = $1 AND technician_id = $2 AND kind = 'counter'`,
          [order.id, technicianId, amountMinor],
        ),
      );
      const count = counts[0];
      if (Number(count?.total ?? 0) >= 2) {
        throw new BadRequestException('Technician offer limit reached.');
      }
      if (count?.existing_id != null && count.existing_expires_at != null) {
        return {
          id: count.existing_id,
          status: 'pending',
          expiresAt: new Date(count.existing_expires_at).toISOString(),
        };
      }
      await manager.query(
        `UPDATE service_order_offers
         SET status = CASE WHEN expires_at <= now() THEN 'expired' ELSE 'superseded' END,
             responded_at = now()
         WHERE order_id = $1 AND technician_id = $2 AND status = 'pending'`,
        [order.id, technicianId],
      );
      let inserted: { id: string; expires_at: Date | string } | undefined;
      try {
        inserted = queryRows<{ id: string; expires_at: Date | string }>(
          await manager.query(
            `INSERT INTO service_order_offers
               (order_id, technician_id, kind, amount_minor, currency, expires_at)
             VALUES ($1, $2, 'counter', $3, $4, now() + interval '120 seconds')
             RETURNING id, expires_at`,
            [order.id, technicianId, amountMinor, order.currency],
          ),
        )[0];
      } catch (error) {
        if ((error as { code?: string }).code === '23505') {
          throw new ConflictException('A technician offer is already pending.');
        }
        throw error;
      }
      if (inserted == null) throw new ConflictException('Offer could not be created.');
      await manager.query(
        `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
        [order.id],
      );
      await this.timeline(manager, order.id, 'offer_received', 'تم استلام عرض جديد', null, null);
      return {
        id: inserted.id,
        status: 'pending',
        expiresAt: new Date(inserted.expires_at).toISOString(),
      };
    });
  }

  private async skipLegacy(
    technicianId: string,
    orderId: string,
    reason?: string,
  ): Promise<{ skipped: true }> {
    return await this.dataSource.transaction(async (manager) => {
      const order = await this.lockEligibleOrder(manager, orderId, technicianId, false, false);
      this.assertSearchable(order);
      const inserted = queryRows<{ order_id: string }>(
        await manager.query(
          `INSERT INTO service_order_technician_skips (order_id, technician_id, reason)
           VALUES ($1, $2, $3) ON CONFLICT DO NOTHING RETURNING order_id`,
          [order.id, technicianId, reason ?? null],
        ),
      );
      if (inserted.length > 0) {
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        await this.timeline(manager, order.id, 'technician_skipped', 'تخطى فني الطلب', null, null);
      }
      return { skipped: true as const };
    });
  }

  async skip(
    technicianId: string,
    orderId: string,
    reason?: string,
    idempotencyKey?: string,
  ): Promise<{ skipped: true }> {
    if (!this.isDispatchV2Enabled()) {
      return await this.skipLegacy(technicianId, orderId, reason);
    }
    return await dispatchMutation(
      this.dataSource,
      true,
      'request.skip',
      technicianId,
      idempotencyKey,
      { orderId, reason },
      async (manager) => {
        await this.lockTechnicianOffers(manager, technicianId);
        const order = await this.lockOrder(manager, orderId);
        if (
          order.status !== 'searching' ||
          order.search_expires_at == null ||
          new Date(order.search_expires_at).getTime() <= Date.now()
        ) {
          throw new ConflictException({
            code: 'ORDER_NOT_AVAILABLE',
            message: 'This order is no longer available.',
          });
        }
        const previousSkip = queryRows<{ present: boolean }>(
          await manager.query(
            `SELECT EXISTS (SELECT 1 FROM service_order_technician_skips
                          WHERE order_id = $1 AND technician_id = $2) AS present`,
            [order.id, technicianId],
          ),
        )[0];
        if (previousSkip?.present === true) return { skipped: true as const };

        const eligibleRows = queryRows<{ eligible: boolean }>(
          await manager.query(
            `SELECT EXISTS (
             SELECT 1 FROM service_orders o
             JOIN technician_profiles tp ON tp.user_id = $2
             JOIN users u ON u.id = tp.user_id
             LEFT JOIN user_addresses a ON a.id = o.selected_address_id
             LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
             WHERE o.id = $1 ${getDispatchEligibilitySql()}
           ) AS eligible`,
            [order.id, technicianId],
          ),
        );
        if (eligibleRows[0]?.eligible !== true) {
          throw new ForbiddenException({
            code: 'NOT_ELIGIBLE',
            message: 'The technician is not eligible for this order.',
          });
        }
        const inserted = queryRows<{ order_id: string }>(
          await manager.query(
            `INSERT INTO service_order_technician_skips (order_id, technician_id, reason)
           VALUES ($1, $2, $3) ON CONFLICT DO NOTHING RETURNING order_id`,
            [order.id, technicianId, reason ?? null],
          ),
        );
        if (inserted.length === 0) return { skipped: true as const };
        const withdrawn = queryRows<{ id: string }>(
          await manager.query(
            `UPDATE service_order_offers
           SET status = 'withdrawn', close_reason = 'withdrawn', responded_at = now()
           WHERE order_id = $1 AND technician_id = $2 AND status = 'pending'
           RETURNING id`,
            [order.id, technicianId],
          ),
        );
        if (withdrawn.length > 0) {
          await this.refreshPendingOfferCount(manager, order.id);
          await manager.query(
            `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
            [order.id],
          );
          await this.queueOutbox(manager, 'offer.withdrawn', order.id, order.customer_id, {
            offerId: withdrawn[0]?.id,
            orderId: order.id,
            reason: 'technician_skipped',
          });
        }
        return { skipped: true };
      },
    );
  }

  async withdraw(
    technicianId: string,
    offerId: string,
    idempotencyKey?: string,
  ): Promise<{ status: string }> {
    this.assertDispatchV2Enabled();
    return await dispatchMutation(
      this.dataSource,
      true,
      'offer.withdraw',
      technicianId,
      idempotencyKey,
      { offerId },
      async (manager) => {
        await this.lockTechnicianOffers(manager, technicianId);
        const located = queryRows<{ order_id: string; status: string }>(
          await manager.query(
            `SELECT order_id, status FROM service_order_offers WHERE id = $1 AND technician_id = $2`,
            [offerId, technicianId],
          ),
        )[0];
        if (located == null) {
          throw new NotFoundException({ code: 'OFFER_NOT_FOUND', message: 'Offer not found.' });
        }
        if (located.status === 'withdrawn') return { status: 'withdrawn' as const };
        const order = await this.lockOrder(manager, located.order_id);
        const updated = queryRows<{ id: string }>(
          await manager.query(
            `UPDATE service_order_offers
           SET status = 'withdrawn', close_reason = 'withdrawn', responded_at = now()
           WHERE id = $1 AND technician_id = $2 AND status = 'pending'
           RETURNING id`,
            [offerId, technicianId],
          ),
        );
        if (updated[0] == null) {
          throw new ConflictException({
            code: 'OFFER_NOT_PENDING',
            message: 'Offer is no longer pending.',
          });
        }
        await this.refreshPendingOfferCount(manager, located.order_id);
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [located.order_id],
        );
        await this.timeline(
          manager,
          located.order_id,
          'offer_withdrawn',
          'تم سحب عرض',
          null,
          null,
          {
            offerId,
            technicianId,
          },
        );
        await this.queueOutbox(manager, 'offer.withdrawn', located.order_id, order.customer_id, {
          offerId,
          orderId: located.order_id,
          reason: 'technician_withdrew',
        });
        return { status: 'withdrawn' };
      },
    );
  }

  async listCustomerOffers(customerId: string, orderId: string): Promise<{ data: unknown[] }> {
    const rows = await this.dataSource.query<
      Array<{
        id: string;
        amountMinor: string;
        currency: string;
        expiresAt: Date | string;
        createdAt: Date | string;
        technicianId: string;
        displayName: string | null;
        avatarUrl: string | null;
        rating: string | number | null;
        completedJobs: string;
        reviewCount: string;
        onTimeRate: number | string;
        acceptanceRate: number | string;
        serviceLocation: 'customer_site' | 'provider_workshop';
        etaMinutes: number | null;
        note: string | null;
        area: string | null;
        rankingDistanceKm: number | string | null;
        promotionDiscountType: string | null;
        promotionDiscountValue: string | null;
        promotionMaxDiscountMinor: string | null;
        riskScore: number | string;
        riskLevel: string;
        dailyOrderLimit: number | null;
      }>
    >(
      `SELECT offer.id, offer.amount_minor::text AS "amountMinor", offer.currency,
              offer.expires_at AS "expiresAt", offer.created_at AS "createdAt",
              tech.id AS "technicianId", tech.display_name AS "displayName",
              tech.avatar_url AS "avatarUrl", review_stats.rating,
              COALESCE(review_stats.review_count, 0)::text AS "reviewCount",
              COALESCE(history_stats.completed_jobs, 0)::text AS "completedJobs",
              tp.on_time_rate AS "onTimeRate", ${this.isDispatchV2Enabled() ? `(SELECT COALESCE(100.0 * (SELECT COUNT(*) FROM service_order_offers submitted WHERE submitted.technician_id = tp.user_id AND submitted.kind <> 'ops') / NULLIF(COUNT(*), 0), 0) FROM request_views viewed WHERE viewed.technician_id = tp.user_id)` : 'tp.acceptance_rate'} AS "acceptanceRate",
              offer.service_location AS "serviceLocation", offer.eta_minutes AS "etaMinutes",
              offer.note,
              o.promotion_discount_type AS "promotionDiscountType",
              o.promotion_discount_value::text AS "promotionDiscountValue",
              o.promotion_max_discount_minor::text AS "promotionMaxDiscountMinor",
              COALESCE(rp.score,0)::int AS "riskScore",COALESCE(rp.level,'low') AS "riskLevel",
              rp.daily_order_limit AS "dailyOrderLimit",
              CASE WHEN offer.service_location = 'provider_workshop'
                   THEN COALESCE(workshop_area.name_ar, offer.workshop_area_code)
                   ELSE COALESCE(address_area.name_ar, address.area_code)
              END AS area,
              CASE
                WHEN address.latitude IS NULL OR address.longitude IS NULL THEN NULL
                WHEN offer.service_location = 'provider_workshop'
                  AND offer.workshop_lat IS NOT NULL AND offer.workshop_lng IS NOT NULL
                  THEN geo_distance_km(offer.workshop_lat, offer.workshop_lng,
                                       address.latitude, address.longitude)
                WHEN tp.work_center_lat IS NOT NULL AND tp.work_center_lng IS NOT NULL
                  THEN geo_distance_km(tp.work_center_lat, tp.work_center_lng,
                                       address.latitude, address.longitude)
                ELSE NULL
              END AS "rankingDistanceKm"
       FROM service_order_offers offer
       JOIN service_orders o ON o.id = offer.order_id AND o.customer_id = $2
       JOIN users tech ON tech.id = offer.technician_id
       JOIN technician_profiles tp ON tp.user_id = tech.id
       LEFT JOIN risk_profiles rp ON rp.user_id = tech.id
       LEFT JOIN user_addresses address ON address.id = o.selected_address_id
       LEFT JOIN geo_areas address_area ON address_area.code = address.area_code
       LEFT JOIN geo_areas workshop_area ON workshop_area.code = offer.workshop_area_code
       LEFT JOIN technician_rating_stats review_stats ON review_stats.technician_id = tech.id
       LEFT JOIN (
         SELECT technician_id, COUNT(*)::bigint AS completed_jobs
         FROM technician_order_history WHERE status = 'completed'
         GROUP BY technician_id
       ) history_stats ON history_stats.technician_id = tech.id
       WHERE offer.order_id = $1 AND offer.status = 'pending' AND offer.expires_at > now()
       AND NOT technician_billing_blocked(tp.user_id)
       ORDER BY offer.created_at, offer.id
       LIMIT 50`,
      [orderId, customerId],
    );

    if (!this.isDispatchV2Enabled()) {
      return {
        data: rows.map((row) => ({
          id: row.id,
          amountMinor: row.amountMinor,
          currency: row.currency,
          expiresAt: new Date(row.expiresAt).toISOString(),
          technician: {
            id: row.technicianId,
            displayName: row.displayName,
            rating: row.rating == null ? null : Number(row.rating),
            completedJobs: Number(row.completedJobs),
            distanceKm: row.rankingDistanceKm == null ? null : Number(row.rankingDistanceKm),
          },
        })),
      };
    }
    const inputs: CustomerOfferRankingInput[] = rows.map((row) => ({
      amountMinor: row.amountMinor,
      rating: row.rating == null ? null : Number(row.rating),
      distanceKm: row.rankingDistanceKm == null ? null : Number(row.rankingDistanceKm),
      onTimeRate: Number(row.onTimeRate),
      acceptanceRate: Number(row.acceptanceRate),
    }));
    const scores = (this.customerOfferRanking ?? new WeightedCustomerOfferRankingStrategy()).score(
      inputs,
    );
    const ranked = rows
      .map((row, index) => ({
        id: row.id,
        amountMinor: row.amountMinor,
        ...(this.isDispatchV2Enabled()
          ? {
              discountMinor: this.snapshotDiscount(
                row.amountMinor,
                row.promotionDiscountType,
                row.promotionDiscountValue,
                row.promotionMaxDiscountMinor,
              ).toString(),
              finalAmountMinor: (
                BigInt(row.amountMinor) -
                this.snapshotDiscount(
                  row.amountMinor,
                  row.promotionDiscountType,
                  row.promotionDiscountValue,
                  row.promotionMaxDiscountMinor,
                )
              ).toString(),
            }
          : {}),
        currency: row.currency,
        expiresAt: new Date(row.expiresAt).toISOString(),
        score: applyRiskRankingMultiplier(
          scores[index] ?? 0,
          Number(row.riskScore),
          row.dailyOrderLimit != null &&
            ['restricted', 'suspension_review', 'ban_review'].includes(row.riskLevel),
        ),
        isBestFit: false,
        serviceLocation: row.serviceLocation,
        area: row.area,
        distanceKm:
          row.serviceLocation === 'provider_workshop' && row.rankingDistanceKm != null
            ? Number(row.rankingDistanceKm)
            : null,
        etaMinutes: row.etaMinutes,
        note: row.note,
        technician: {
          id: row.technicianId,
          displayName: row.displayName,
          avatarUrl: row.avatarUrl,
          rating: row.rating == null ? null : Number(row.rating),
          reviewCount: Number(row.reviewCount),
          completedJobs: Number(row.completedJobs),
          onTimeRate: Number(row.onTimeRate),
          acceptanceRate: Number(row.acceptanceRate),
        },
        createdAt: new Date(row.createdAt).toISOString(),
      }))
      .sort(
        (left, right) =>
          right.score - left.score ||
          (BigInt(left.amountMinor) < BigInt(right.amountMinor)
            ? -1
            : BigInt(left.amountMinor) > BigInt(right.amountMinor)
              ? 1
              : left.id.localeCompare(right.id)),
      );
    return {
      data: ranked.map(({ createdAt: _createdAt, ...offer }, index) => ({
        ...offer,
        isBestFit: index === 0,
      })),
    };
  }

  async acceptCustomerOffer(
    customerId: string,
    orderId: string,
    offerId: string,
    idempotencyKey?: string,
  ): Promise<{ status: string }> {
    if (!this.isDispatchV2Enabled()) {
      return await this.acceptCustomerOfferLegacy(customerId, orderId, offerId);
    }
    const confirmed = await this.confirmCustomerOffer(customerId, orderId, offerId, idempotencyKey);
    return { status: confirmed.status };
  }

  private async acceptCustomerOfferLegacy(
    customerId: string,
    orderId: string,
    offerId: string,
  ): Promise<{ status: string }> {
    const result = await this.dataSource.transaction(async (manager) => {
      const order = await this.lockOwnedOrder(manager, orderId, customerId);
      const offer = await this.lockOffer(manager, offerId, order.id);
      if (order.status === 'assigned' && offer.status === 'accepted') {
        return { unavailable: false as const };
      }
      this.assertSearchable(order);
      if (offer.status !== 'pending' || new Date(offer.expires_at).getTime() <= Date.now()) {
        if (offer.status === 'pending') {
          await manager.query(
            `UPDATE service_order_offers SET status = 'expired', responded_at = now() WHERE id = $1`,
            [offer.id],
          );
          await manager.query(
            `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
            [order.id],
          );
        }
        return { unavailable: true as const };
      }
      await this.assertDailyOrderLimit(manager, offer.technician_id, order.scheduled_at);
      try {
        await reserveActiveTechnicians(manager, order.id, [offer.technician_id]);
      } catch (error) {
        if (!(error instanceof ConflictException) && !(error instanceof NotFoundException)) {
          throw error;
        }
        await manager.query(
          `UPDATE service_order_offers SET status = 'expired', responded_at = now() WHERE id = $1`,
          [offer.id],
        );
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        return { unavailable: true as const };
      }
      await manager.query(
        `UPDATE service_order_offers SET status = 'accepted', responded_at = now() WHERE id = $1`,
        [offer.id],
      );
      await manager.query(
        `UPDATE service_order_offers SET status = 'superseded', responded_at = now()
         WHERE order_id = $1 AND status = 'pending' AND id <> $2`,
        [order.id, offer.id],
      );
      await this.assignOrder(manager, order, offer.technician_id, offer.amount_minor);
      return { unavailable: false as const };
    });
    if (result.unavailable) {
      throw new ConflictException('الفني ده مبقاش متاح، اختار عرض تاني.');
    }
    return { status: 'assigned' };
  }

  async confirmCustomerOffer(
    customerId: string,
    orderId: string,
    offerId: string,
    idempotencyKey?: string,
    transactionManager?: EntityManager,
  ): Promise<ActiveOrderDto> {
    this.assertDispatchV2Enabled();
    const normalizedKey = idempotencyKey?.trim();
    if (normalizedKey != null && !isUUID(normalizedKey)) {
      throw new BadRequestException({
        code: 'INVALID_IDEMPOTENCY_KEY',
        message: 'Idempotency-Key must be a UUID.',
      });
    }

    const result = await this.inTransaction(transactionManager, async (manager) => {
      const loadIdempotentOrder = async (): Promise<ActiveOrderDto | null> => {
        if (normalizedKey == null) return null;
        const saved = queryRows<{ response: unknown }>(
          await manager.query(
            `SELECT response FROM idempotent_responses
             WHERE scope = 'order.confirm' AND actor_id = $1 AND key = $2::uuid`,
            [customerId, normalizedKey],
          ),
        )[0]?.response;
        if (saved == null) return null;
        const response =
          typeof saved === 'string' ? (JSON.parse(saved) as Record<string, unknown>) : saved;
        if (typeof response !== 'object') {
          throw new ConflictException({
            code: 'IDEMPOTENCY_KEY_REUSED',
            message: 'This idempotency key has already been used for another request.',
          });
        }
        const record = response as {
          request?: { orderId?: string; offerId?: string };
          order?: ActiveOrderDto;
        };
        if (
          record.request?.orderId !== orderId ||
          record.request.offerId !== offerId ||
          record.order == null
        ) {
          throw new ConflictException({
            code: 'IDEMPOTENCY_KEY_REUSED',
            message: 'This idempotency key has already been used for another request.',
          });
        }
        return record.order;
      };

      if (normalizedKey != null) {
        await manager.query(`SELECT pg_advisory_xact_lock(hashtextextended($1, 0))`, [
          `order-confirm-idem:${customerId}:${normalizedKey}`,
        ]);
        const previous = await loadIdempotentOrder();
        if (previous != null) return { order: previous };
      }

      const candidate = queryRows<{ technician_id: string }>(
        await manager.query(
          `SELECT technician_id FROM service_order_offers WHERE id = $1 AND order_id = $2`,
          [offerId, orderId],
        ),
      )[0];
      if (candidate == null) {
        throw new NotFoundException({ code: 'OFFER_NOT_FOUND', message: 'Offer not found.' });
      }
      await this.lockTechnicianOffers(manager, candidate.technician_id);
      if (normalizedKey != null) {
        const previous = await loadIdempotentOrder();
        if (previous != null) return { order: previous };
      }

      const order = await this.lockOwnedOrder(manager, orderId, customerId);
      if (order.status === 'assigned') {
        if (order.assigned_offer_id === offerId) {
          const confirmedOrder = await this.loadConfirmedOrder(manager, customerId, order.id);
          if (normalizedKey != null) {
            await manager.query(
              `INSERT INTO idempotent_responses (scope, actor_id, key, response)
               VALUES ('order.confirm', $1, $2::uuid, $3::jsonb)
               ON CONFLICT (scope, actor_id, key) DO NOTHING`,
              [
                customerId,
                normalizedKey,
                JSON.stringify({ request: { orderId, offerId }, order: confirmedOrder }),
              ],
            );
          }
          return { order: confirmedOrder };
        }
        return { error: 'ORDER_ALREADY_ASSIGNED' as const };
      }
      if (order.status !== 'searching') return { error: 'ORDER_NOT_AVAILABLE' as const };
      const [billing] = await manager.query<Array<{ blocked: boolean }>>(
        'SELECT technician_billing_blocked($1) AS blocked',
        [candidate.technician_id],
      );
      if (billing?.blocked) return { error: 'TECHNICIAN_UNAVAILABLE' as const };
      const offer = await this.lockOffer(manager, offerId, order.id);
      if (candidate.technician_id !== offer.technician_id) {
        throw new ConflictException({
          code: 'OFFER_CHANGED',
          message: 'The offer changed while it was being confirmed.',
        });
      }
      if (offer.status !== 'pending') {
        if (offer.status === 'expired') return { error: 'OFFER_EXPIRED' as const };
        if (offer.close_reason === 'technician_unavailable') {
          await this.timeline(
            manager,
            order.id,
            'technician_unavailable',
            'الفني لم يعد متاحًا',
            null,
            null,
            { offerId },
          );
          return { error: 'TECHNICIAN_UNAVAILABLE' as const };
        }
        return { error: 'OFFER_EXPIRED' as const };
      }
      if (new Date(offer.expires_at).getTime() <= Date.now()) {
        await manager.query(
          `UPDATE service_order_offers
           SET status = 'expired', close_reason = 'expired', responded_at = now()
           WHERE id = $1 AND status = 'pending'`,
          [offer.id],
        );
        await this.refreshPendingOfferCount(manager, order.id);
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        await this.queueOutbox(
          manager,
          'offer.expired',
          orderId,
          [customerId, offer.technician_id],
          { orderId, offerId, reason: 'expired' },
        );
        return { error: 'OFFER_EXPIRED' as const };
      }
      if (
        order.search_expires_at == null ||
        new Date(order.search_expires_at).getTime() <= Date.now()
      ) {
        return { error: 'ORDER_NOT_AVAILABLE' as const };
      }

      await this.assertDailyOrderLimit(manager, offer.technician_id, order.scheduled_at);
      try {
        if (this.isDispatchV2Enabled()) {
          await this.lockEligibleOrder(manager, order.id, offer.technician_id, true, true);
        }
        if (this.isDispatchV2Enabled() && this.isScheduledOrder(order)) {
          await reserveScheduledTechnician(
            manager,
            order.id,
            offer.technician_id,
            order.scheduled_at,
            DISPATCH.DEFAULT_JOB_DURATION_MIN,
          );
        } else {
          await reserveActiveTechnicians(manager, order.id, [offer.technician_id]);
        }
      } catch (error) {
        if (!(error instanceof ConflictException) && !(error instanceof NotFoundException)) {
          throw error;
        }
        await manager.query(
          `UPDATE service_order_offers
           SET status = 'superseded', close_reason = 'technician_unavailable', responded_at = now()
           WHERE id = $1 AND status = 'pending'`,
          [offer.id],
        );
        await this.refreshPendingOfferCount(manager, order.id);
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        await this.timeline(
          manager,
          order.id,
          'technician_unavailable',
          'الفني لم يعد متاحًا',
          null,
          null,
          { offerId },
        );
        await this.queueOutbox(manager, 'offer.lost', order.id, [customerId, offer.technician_id], {
          orderId,
          offerId,
          reason: 'technician_unavailable',
        });
        return { error: 'TECHNICIAN_UNAVAILABLE' as const };
      }

      const accepted = queryRows<{ id: string }>(
        await manager.query(
          `UPDATE service_order_offers
           SET status = 'accepted', responded_at = now(), close_reason = NULL
           WHERE id = $1 AND order_id = $2 AND status = 'pending'
           RETURNING id`,
          [offer.id, order.id],
        ),
      )[0];
      if (accepted == null) return { error: 'OFFER_EXPIRED' as const };

      const recipients = await this.orderRequestRecipients(manager, order.id);
      const lostOffers = queryRows<{ id: string; technician_id: string }>(
        await manager.query(
          `UPDATE service_order_offers
           SET status = 'superseded', close_reason = 'other_offer_chosen', responded_at = now()
           WHERE order_id = $1 AND status = 'pending' AND id <> $2
           RETURNING id, technician_id`,
          [order.id, offer.id],
        ),
      );
      await this.assignOrder(manager, order, offer.technician_id, offer.amount_minor, {
        offerId: offer.id,
        serviceLocation: offer.service_location ?? 'customer_site',
      });
      await this.supersedeConflictingTechnicianOffers(manager, order, offer.technician_id);
      for (const lost of lostOffers) {
        await this.queueOutbox(manager, 'offer.lost', order.id, lost.technician_id, {
          offerId: lost.id,
          orderId: order.id,
          reason: 'another_offer_accepted',
        });
      }

      const confirmedOrder = await this.loadConfirmedOrder(manager, customerId, order.id);
      const assignmentPayload = {
        orderId: order.id,
        offerId: offer.id,
        technicianId: offer.technician_id,
        amountMinor: offer.amount_minor,
        serviceLocation: confirmedOrder.serviceLocation,
        serviceAddress: confirmedOrder.serviceAddress,
        serviceArea: confirmedOrder.serviceArea,
      };
      await this.queueOutbox(manager, 'order.assigned', order.id, customerId, assignmentPayload);
      await this.queueOutbox(
        manager,
        'order.assigned',
        order.id,
        offer.technician_id,
        assignmentPayload,
      );
      for (const recipientId of recipients) {
        await this.queueOutbox(manager, 'request.removed', order.id, recipientId, {
          orderId: order.id,
          reason: 'order_assigned',
        });
      }

      if (normalizedKey != null) {
        const storedResponse = JSON.stringify({
          request: { orderId, offerId },
          order: confirmedOrder,
        });
        await manager.query(
          `INSERT INTO idempotent_responses (scope, actor_id, key, response)
           VALUES ('order.confirm', $1, $2::uuid, $3::jsonb)
           ON CONFLICT (scope, actor_id, key) DO NOTHING`,
          [customerId, normalizedKey, storedResponse],
        );
      }
      return { order: confirmedOrder };
    });

    if ('error' in result) {
      const errors = {
        ORDER_ALREADY_ASSIGNED: 'Another offer has already been assigned to this order.',
        ORDER_NOT_AVAILABLE: 'This order is no longer available.',
        OFFER_EXPIRED: 'This offer has expired.',
        TECHNICIAN_UNAVAILABLE: 'The technician is no longer available for this order.',
      } as const;
      throw new ConflictException({ code: result.error, message: errors[result.error] });
    }
    return result.order;
  }

  private async inTransaction<T>(
    manager: EntityManager | undefined,
    operation: (manager: EntityManager) => Promise<T>,
  ): Promise<T> {
    return manager == null
      ? await dispatchTransaction(this.dataSource, operation)
      : await operation(manager);
  }

  async confirmOpsAssignment(
    manager: EntityManager,
    orderId: string,
    technicianId: string,
    amountMinor: string,
    serviceLocation: 'customer_site' | 'provider_workshop',
  ): Promise<{ orderId: string; offerId: string; status: 'assigned' }> {
    this.assertDispatchV2Enabled();
    this.parseMinorAmount(amountMinor);
    await this.lockTechnicianOffers(manager, technicianId);
    const order = await this.lockOrder(manager, orderId);
    if (!['new', 'searching', 'no_provider_found'].includes(order.status)) {
      throw new ConflictException({
        code: 'ORDER_ALREADY_ASSIGNED',
        message: 'The order is already assigned or closed.',
      });
    }
    if (
      (serviceLocation === 'provider_workshop' &&
        order.location_preference === 'customer_site_only') ||
      (serviceLocation === 'customer_site' && order.location_preference === 'workshop_only')
    ) {
      throw new BadRequestException({
        code: 'SERVICE_LOCATION_NOT_ALLOWED',
        message: 'The service location is not allowed.',
      });
    }
    const workshops = await manager.query<
      Array<{ lat: number; lng: number; address_line: string; area_code: string | null }>
    >(
      `SELECT lat, lng, address_line, area_code FROM technician_workshops
       WHERE technician_id = $1 AND is_active IS TRUE AND accepts_workshop_jobs IS TRUE`,
      [technicianId],
    );
    if (serviceLocation === 'provider_workshop' && !workshops[0]) {
      throw new ForbiddenException({
        code: 'WORKSHOP_NOT_ACCEPTED',
        message: 'The technician does not accept workshop jobs.',
      });
    }
    if (
      order.status !== 'searching' ||
      order.search_expires_at == null ||
      new Date(order.search_expires_at).getTime() <= Date.now()
    ) {
      await manager.query(
        `UPDATE service_orders SET status = 'searching', search_expires_at = now() + make_interval(mins => $2::int)
        WHERE id = $1`,
        [orderId, DISPATCH.OFFER_TTL_MIN],
      );
    }
    await manager.query(
      `UPDATE service_order_offers SET status = 'superseded', close_reason = 'other_offer_chosen', responded_at = now()
      WHERE order_id = $1 AND technician_id = $2 AND status = 'pending'`,
      [orderId, technicianId],
    );
    const workshop = serviceLocation === 'provider_workshop' ? workshops[0] : null;
    const [offer] = await manager.query<Array<{ id: string }>>(
      `INSERT INTO service_order_offers (order_id, technician_id, kind, amount_minor, currency, status, expires_at,
        service_location, workshop_lat, workshop_lng, workshop_address, workshop_area_code)
       VALUES ($1, $2, 'ops', $3::bigint, $4, 'pending', now() + make_interval(mins => $5::int), $6, $7, $8, $9, $10) RETURNING id`,
      [
        orderId,
        technicianId,
        amountMinor,
        order.currency,
        DISPATCH.OFFER_TTL_MIN,
        serviceLocation,
        workshop?.lat ?? null,
        workshop?.lng ?? null,
        workshop?.address_line ?? null,
        workshop?.area_code ?? null,
      ],
    );
    if (!offer) throw new ConflictException('The Ops offer could not be created.');
    await this.confirmCustomerOffer(order.customer_id, orderId, offer.id, undefined, manager);
    return { orderId, offerId: offer.id, status: 'assigned' };
  }

  async rejectCustomerOffer(
    customerId: string,
    orderId: string,
    offerId: string,
    idempotencyKey?: string,
  ): Promise<{ status: string }> {
    const result = await dispatchMutation(
      this.dataSource,
      this.isDispatchV2Enabled(),
      'offer.reject',
      customerId,
      idempotencyKey,
      { orderId, offerId },
      async (manager) => {
        const order = await this.lockOwnedOrder(manager, orderId, customerId);
        const offer = await this.lockOffer(manager, offerId, order.id);
        if (offer.status === 'rejected') return { status: 'rejected' as const };
        if (offer.status !== 'pending') {
          throw new ConflictException({
            code: 'OFFER_NOT_PENDING',
            message: 'Offer is no longer pending.',
          });
        }
        const expired = new Date(offer.expires_at).getTime() <= Date.now();
        await manager.query(
          `UPDATE service_order_offers
         SET status = $2, close_reason = $3, responded_at = now() WHERE id = $1`,
          [offer.id, expired ? 'expired' : 'rejected', expired ? 'expired' : 'customer_rejected'],
        );
        await this.refreshPendingOfferCount(manager, order.id);
        await manager.query(
          `UPDATE service_orders SET version = version + 1, updated_at = now() WHERE id = $1`,
          [order.id],
        );
        if (!expired) {
          await this.timeline(manager, order.id, 'offer_rejected', 'تم رفض عرض', null, null, {
            offerId: offer.id,
            technicianId: offer.technician_id,
          });
          await this.queueOutbox(manager, 'offer.rejected', order.id, offer.technician_id, {
            offerId: offer.id,
            orderId: order.id,
            reason: 'customer_rejected',
          });
        }
        return { status: expired ? 'expired' : 'rejected' };
      },
    );
    if (result.status === 'expired') {
      throw new ConflictException({ code: 'OFFER_EXPIRED', message: 'Offer has expired.' });
    }
    return result;
  }

  async raiseCustomerOffer(
    customerId: string,
    orderId: string,
    amountMinor: string,
    idempotencyKey?: string,
  ): Promise<{ customerOfferMinor: string; raises: number }> {
    return await dispatchMutation(
      this.dataSource,
      this.isDispatchV2Enabled(),
      'order.raise',
      customerId,
      idempotencyKey,
      { orderId, amountMinor },
      async (manager) => {
        const order = await this.lockOwnedOrder(manager, orderId, customerId);
        this.assertSearchable(order, true);
        const isScheduled =
          order.search_starts_at != null &&
          new Date(order.search_starts_at).getTime() <
            new Date(order.scheduled_at).getTime() - 60_000;
        if (
          isScheduled &&
          (order.search_expires_at == null ||
            new Date(order.search_expires_at).getTime() <= Date.now())
        ) {
          throw new ConflictException('The scheduled matching window has closed.');
        }
        if (
          order.customer_offer_raises >=
          (this.isDispatchV2Enabled() ? DISPATCH.MAX_CUSTOMER_RAISES : 3)
        ) {
          throw new BadRequestException('Customer offer raise limit reached.');
        }
        if (order.customer_offer_minor == null || order.offer_cap_minor == null) {
          throw new ConflictException('Order pricing is unavailable.');
        }
        const amount = this.parseMinorAmount(amountMinor);
        if (
          amount <= BigInt(order.customer_offer_minor) ||
          amount > BigInt(order.offer_cap_minor)
        ) {
          throw new BadRequestException('Raised offer is outside the allowed range.');
        }
        const raises = order.customer_offer_raises + 1;
        const recipients = await this.orderRequestRecipients(manager, order.id);
        const updated = queryRows<{ search_expires_at: Date | string | null }>(
          await manager.query(
            `UPDATE service_orders
         SET customer_offer_minor = $2, customer_offer_raises = $3,
             search_expires_at = CASE
               WHEN search_starts_at < scheduled_at - interval '1 minute'
                 THEN ${this.isDispatchV2Enabled() ? 'LEAST(search_expires_at + make_interval(mins => $4::int), scheduled_at - make_interval(mins => $5::int))' : "LEAST(search_expires_at, now() + interval '10 minutes')"}
               ELSE ${this.isDispatchV2Enabled() ? 'GREATEST(search_expires_at, now()) + make_interval(mins => $4::int)' : "now() + interval '10 minutes'"}
             END,
             version = version + 1, updated_at = now()
         WHERE id = $1
         RETURNING search_expires_at`,
            this.isDispatchV2Enabled()
              ? [
                  order.id,
                  amountMinor,
                  raises,
                  DISPATCH.RAISE_EXTENSION_MIN,
                  DISPATCH.SCHEDULED_SEARCH_CLOSE_BEFORE_MIN,
                ]
              : [order.id, amountMinor, raises],
          ),
        )[0];
        await this.timeline(
          manager,
          order.id,
          'customer_offer_raised',
          'رفع العميل سعره',
          null,
          null,
        );
        const payload = {
          orderId: order.id,
          customerOfferMinor: amountMinor,
          raises,
          visibleUntil:
            updated?.search_expires_at == null
              ? null
              : new Date(updated.search_expires_at).toISOString(),
        };
        for (const recipientId of recipients) {
          await this.queueOutbox(manager, 'request.updated', order.id, recipientId, payload);
        }
        return { customerOfferMinor: amountMinor, raises };
      },
    );
  }

  async cancel(
    customerId: string,
    orderId: string,
    idempotencyKey?: string,
  ): Promise<{ status: string }> {
    return await dispatchMutation(
      this.dataSource,
      this.isDispatchV2Enabled(),
      'order.cancel',
      customerId,
      idempotencyKey,
      { orderId },
      async (manager) => {
        const order = await this.lockOwnedOrder(manager, orderId, customerId);
        if (order.status === 'cancelled') return { status: 'cancelled' };
        if (
          !(
            this.isDispatchV2Enabled()
              ? ['scheduled_pending', 'searching', 'assigned', 'no_provider_found']
              : ['scheduled_pending', 'searching', 'assigned']
          ).includes(order.status)
        ) {
          throw new ConflictException('This order can no longer be cancelled.');
        }
        const recipients = await this.orderRequestRecipients(manager, order.id);
        await manager.query(
          `UPDATE service_orders
         SET status = 'cancelled', cancelled_at = now(), pending_offers_count = 0,
             version = version + 1, updated_at = now()
         WHERE id = $1`,
          [order.id],
        );
        const cancelledOffers = queryRows<{ id: string; technician_id: string }>(
          await manager.query(
            `UPDATE service_order_offers
           SET status = 'superseded', close_reason = 'order_cancelled', responded_at = now()
           WHERE order_id = $1 AND status IN ('pending', 'accepted')
           RETURNING id, technician_id`,
            [order.id],
          ),
        );
        for (const offer of cancelledOffers) {
          await this.queueOutbox(manager, 'offer.lost', order.id, offer.technician_id, {
            offerId: offer.id,
            orderId: order.id,
            reason: 'order_cancelled',
          });
        }
        await settlePromotionGrant(manager, order.id, 'cancelled');
        await this.timeline(
          manager,
          order.id,
          'order_cancelled',
          'ألغى العميل الطلب',
          order.status,
          'cancelled',
        );
        for (const recipientId of recipients) {
          await this.queueOutbox(manager, 'request.removed', order.id, recipientId, {
            orderId: order.id,
            reason: 'order_cancelled',
          });
        }
        await this.queueOutbox(manager, 'order.cancelled', order.id, customerId, {
          orderId: order.id,
        });
        if (order.technician_id != null) {
          await this.queueOutbox(manager, 'order.cancelled', order.id, order.technician_id, {
            orderId: order.id,
          });
        }
        return { status: 'cancelled' };
      },
    );
  }

  async active(customerId: string): Promise<{ order: ActiveOrderDto | null }> {
    const rows = await this.dataSource.query<
      Array<{
        id: string;
        reference: string;
        status: string;
        version: number;
        serviceTitleAr: string;
        customerOfferMinor: string;
        agreedLaborMinor: string | null;
        currency: string;
        pendingOffersCount: string;
        bestOfferMinor: string | null;
        searchExpired: boolean;
        scheduledAt: Date | string;
        searchStartsAt: Date | string | null;
        searchExpiresAt: Date | string | null;
        technicianId: string | null;
        technicianDisplayName: string | null;
        technicianRating: string | number | null;
        updatedAt: Date | string;
        serviceLocation: string | null;
        serviceAddress: string | null;
        serviceArea: string | null;
        visibleTechniciansCount: number | string;
        createdAt: Date | string;
        raiseSuggested: boolean;
      }>
    >(
      `SELECT o.id, 'FX-' || o.order_number::text AS reference, o.status::text,
              o.version, s.title_ar AS "serviceTitleAr",
              o.created_at AS "createdAt",
              ${this.isDispatchV2Enabled() ? `o.raise_suggestion_sent_at IS NOT NULL` : 'false'} AS "raiseSuggested",
              ${
                this.isDispatchV2Enabled()
                  ? `(SELECT COUNT(*)::int FROM technician_profiles tp JOIN users u ON u.id = tp.user_id
                LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
                LEFT JOIN user_addresses a ON a.id = o.selected_address_id
                WHERE o.status = 'searching' AND o.search_expires_at > now()
                  AND o.pending_offers_count < ${String(DISPATCH.MAX_PENDING_OFFERS_PER_ORDER)} ${getDispatchEligibilitySql()})`
                  : '0'
              } AS "visibleTechniciansCount",
              o.customer_offer_minor::text AS "customerOfferMinor",
              o.agreed_labor_minor::text AS "agreedLaborMinor", o.currency,
              (SELECT COUNT(*)::text FROM service_order_offers pending
                WHERE pending.order_id = o.id AND pending.status = 'pending'
                  AND pending.expires_at > now()) AS "pendingOffersCount",
              (SELECT MIN(best.amount_minor)::text FROM service_order_offers best
                WHERE best.order_id = o.id AND best.status = 'pending'
                  AND best.expires_at > now()) AS "bestOfferMinor",
              (o.status = 'no_provider_found' OR (o.status = 'searching' AND o.search_expires_at <= now())) AS "searchExpired",
              o.scheduled_at AS "scheduledAt", o.search_starts_at AS "searchStartsAt",
              o.search_expires_at AS "searchExpiresAt",
              tech.id AS "technicianId", tech.display_name AS "technicianDisplayName",
              (SELECT AVG(r.rating)::numeric(3,2) FROM technician_reviews r
                WHERE r.technician_id = tech.id) AS "technicianRating",
              o.updated_at AS "updatedAt",
              CASE WHEN o.status = 'assigned' THEN o.service_location ELSE NULL END AS "serviceLocation",
              CASE WHEN o.status <> 'assigned' THEN NULL
                   WHEN o.service_location = 'provider_workshop' THEN accepted_offer.workshop_address
                   ELSE customer_address.formatted_address
              END AS "serviceAddress",
              CASE WHEN o.status <> 'assigned' THEN NULL
                   WHEN o.service_location = 'provider_workshop'
                     THEN COALESCE(workshop_area.name_ar, accepted_offer.workshop_area_code)
                   ELSE COALESCE(customer_area.name_ar, customer_address.area_code)
              END AS "serviceArea"
       FROM service_orders o
       JOIN services s ON s.id = o.service_id
       LEFT JOIN users tech ON tech.id = o.technician_id
       LEFT JOIN service_order_offers accepted_offer ON accepted_offer.id = o.assigned_offer_id
       LEFT JOIN user_addresses customer_address ON customer_address.id = o.selected_address_id
       LEFT JOIN geo_areas customer_area ON customer_area.code = customer_address.area_code
       LEFT JOIN geo_areas workshop_area ON workshop_area.code = accepted_offer.workshop_area_code
       WHERE o.customer_id = $1 AND o.status = ANY($2::service_order_status[])
         ${this.isDispatchV2Enabled() ? '' : "AND NOT (o.status = 'searching' AND o.search_expires_at <= now())"}
       ORDER BY o.updated_at DESC, o.id DESC
       LIMIT 1`,
      [
        customerId,
        this.isDispatchV2Enabled()
          ? [...IN_FLIGHT_ORDER_STATUSES, 'no_provider_found']
          : IN_FLIGHT_ORDER_STATUSES,
      ],
    );
    const row = rows[0];
    if (row == null) return { order: null };
    return {
      order: {
        id: row.id,
        reference: row.reference,
        status: row.status,
        version: row.version,
        serviceTitleAr: row.serviceTitleAr,
        customerOfferMinor: row.customerOfferMinor,
        agreedLaborMinor: row.agreedLaborMinor,
        currency: row.currency,
        pendingOffersCount: Number(row.pendingOffersCount),
        bestOfferMinor: row.bestOfferMinor,
        searchExpired: row.searchExpired,
        ...(this.isDispatchV2Enabled()
          ? {
              visibleTechniciansCount: Number(row.visibleTechniciansCount),
              createdAt: new Date(row.createdAt).toISOString(),
              raiseSuggested: row.raiseSuggested,
              dispatchV2Enabled: true,
            }
          : {}),
        scheduledAt: new Date(row.scheduledAt).toISOString(),
        searchStartsAt:
          row.searchStartsAt == null ? null : new Date(row.searchStartsAt).toISOString(),
        searchExpiresAt:
          row.searchExpiresAt == null ? null : new Date(row.searchExpiresAt).toISOString(),
        technician:
          row.technicianId == null
            ? null
            : {
                id: row.technicianId,
                displayName: row.technicianDisplayName,
                rating: row.technicianRating == null ? null : Number(row.technicianRating),
              },
        updatedAt: new Date(row.updatedAt).toISOString(),
        serviceLocation: row.serviceLocation,
        serviceAddress: row.serviceAddress,
        serviceArea: row.serviceArea,
      },
    };
  }

  private async lockEligibleOrder(
    manager: EntityManager,
    orderId: string,
    technicianId: string,
    enforceProviderSettings = false,
    dispatchV2Enabled = this.isDispatchV2Enabled(),
  ): Promise<LockedOrderRow> {
    const enforceEligibility = enforceProviderSettings || dispatchV2Enabled;
    const settingsJoin = enforceEligibility
      ? `LEFT JOIN user_addresses a ON a.id = o.selected_address_id
         LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id`
      : '';
    const settingsPredicate = dispatchV2Enabled
      ? getDispatchEligibilitySql()
      : enforceProviderSettings
        ? `AND NOT technician_on_time_off($2, COALESCE(o.scheduled_at, now()))
           AND technician_within_work_hours($2, COALESCE(o.scheduled_at, now()), o.is_emergency)
           AND (
             NOT EXISTS (
               SELECT 1 FROM technician_work_areas w WHERE w.technician_id = $2
             )
             OR EXISTS (
               SELECT 1 FROM technician_work_areas w
               WHERE w.technician_id = $2 AND w.area_code = a.area_code
             )
             OR (
               a.area_code IS NULL AND a.latitude IS NOT NULL
               AND tp.work_center_lat IS NOT NULL AND tp.work_center_lng IS NOT NULL
               AND geo_distance_km(
                     tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude
                   ) <= COALESCE(tp.max_request_distance_km, 15)
             )
           )`
        : '';
    const lockClause = enforceEligibility ? 'FOR UPDATE OF o, tp' : 'FOR UPDATE OF o';
    const rows = queryRows<LockedOrderRow>(
      await manager.query(
        `SELECT o.id, o.customer_id, o.status::text, o.customer_offer_minor::text,
                o.offer_cap_minor::text, o.customer_offer_raises, o.scheduled_at,
                o.search_starts_at, o.search_expires_at, o.currency,
                o.payment_selection->>'method' AS payment_method, s.pricing_type::text,
                o.promotion_grant_id, o.promotion_discount_type,
                o.promotion_discount_value::text, o.promotion_max_discount_minor::text,
                o.technician_id, o.location_preference
         FROM service_orders o
         JOIN services s ON s.id = o.service_id
         JOIN technician_profiles tp ON tp.user_id = $2 AND tp.application_status = 'approved'
         JOIN users u ON u.id = $2 AND u.status = 'active' AND u.deleted_at IS NULL
         ${settingsJoin}
         WHERE o.id = $1
           AND EXISTS (SELECT 1 FROM provider_application_services pas
                       WHERE pas.technician_id = $2 AND pas.service_id = o.service_id)
           ${settingsPredicate}
         ${lockClause}`,
        [orderId, technicianId],
      ),
    );
    if (rows[0] == null) throw new NotFoundException('Order not found.');
    return rows[0];
  }

  private async assertDailyOrderLimit(
    manager: EntityManager,
    technicianId: string,
    scheduledAt?: Date | string,
  ): Promise<void> {
    const rows = queryRows<{ daily_order_limit: number | null }>(
      await manager.query(
        `SELECT daily_order_limit FROM risk_profiles WHERE user_id=$1 AND daily_order_limit IS NOT NULL FOR UPDATE`,
        [technicianId],
      ),
    );
    const limit = rows[0]?.daily_order_limit;
    if (limit == null) return;
    const counts = queryRows<{ count: number | string }>(
      await manager.query(
        `SELECT count(*)::int AS count FROM service_orders
         WHERE technician_id=$1
           AND scheduled_at >= date_trunc('day',$2::timestamptz AT TIME ZONE 'Africa/Cairo') AT TIME ZONE 'Africa/Cairo'
           AND scheduled_at < (date_trunc('day',$2::timestamptz AT TIME ZONE 'Africa/Cairo')+interval '1 day') AT TIME ZONE 'Africa/Cairo'
           AND status::text NOT IN ('cancelled','refunded')`,
        [technicianId, new Date(scheduledAt ?? Date.now()).toISOString()],
      ),
    );
    if (Number(counts[0]?.count ?? 0) >= limit) {
      throw new ConflictException({
        code: 'TECHNICIAN_DAILY_ORDER_LIMIT',
        message: 'الفني وصل للحد اليومي للطلبات المتاحة له. اختار عرضًا آخر.',
      });
    }
  }

  private async lockOrder(manager: EntityManager, orderId: string): Promise<LockedOrderRow> {
    const rows = queryRows<LockedOrderRow>(
      await manager.query(
        `SELECT o.id, o.customer_id, o.status::text, o.customer_offer_minor::text,
                o.offer_cap_minor::text, o.customer_offer_raises, o.scheduled_at,
                o.search_starts_at, o.search_expires_at,
                o.currency, o.payment_selection->>'method' AS payment_method,
                s.pricing_type::text, o.promotion_grant_id,
                o.promotion_discount_type, o.promotion_discount_value::text,
                o.promotion_max_discount_minor::text, o.technician_id, o.location_preference,
                o.assigned_offer_id, o.version
         FROM service_orders o JOIN services s ON s.id = o.service_id
         WHERE o.id = $1 FOR UPDATE OF o`,
        [orderId],
      ),
    );
    if (rows[0] == null) throw new NotFoundException('Order not found.');
    return rows[0];
  }

  private async lockOwnedOrder(
    manager: EntityManager,
    orderId: string,
    customerId: string,
  ): Promise<LockedOrderRow> {
    const order = await this.lockOrder(manager, orderId);
    if (order.customer_id !== customerId) throw new NotFoundException('Order not found.');
    return order;
  }

  private async lockOffer(
    manager: EntityManager,
    offerId: string,
    orderId: string,
  ): Promise<LockedOfferRow> {
    const rows = queryRows<LockedOfferRow>(
      await manager.query(
        `SELECT id, order_id, technician_id, amount_minor::text, status::text, expires_at,
                service_location, workshop_address, workshop_area_code, eta_minutes, note, close_reason
         FROM service_order_offers WHERE id = $1 AND order_id = $2 FOR UPDATE`,
        [offerId, orderId],
      ),
    );
    if (rows[0] == null) throw new NotFoundException('Offer not found.');
    return rows[0];
  }

  private assertSearchable(order: LockedOrderRow, allowExpired = false): void {
    if (order.status !== 'searching') throw new ConflictException('Order is no longer searching.');
    if (
      !allowExpired &&
      (order.search_expires_at == null || new Date(order.search_expires_at).getTime() <= Date.now())
    ) {
      throw new ConflictException('Order search has expired.');
    }
  }

  private async orderRequestRecipients(manager: EntityManager, orderId: string): Promise<string[]> {
    const rows = queryRows<{ recipient_id: string }>(
      await manager.query(
        `SELECT recipient_id FROM (
           SELECT COALESCE(recipient.value->>'id', recipient.value #>> '{}') AS recipient_id
           FROM domain_event_outbox outbox
           CROSS JOIN LATERAL jsonb_array_elements(outbox.recipients) recipient(value)
           WHERE outbox.aggregate_id = $1 AND outbox.event_type = 'request.new'
           UNION
           SELECT offer.technician_id::text AS recipient_id
           FROM service_order_offers offer WHERE offer.order_id = $1
           UNION
           SELECT viewed.technician_id::text AS recipient_id FROM request_views viewed WHERE viewed.order_id = $1
           ${this.isDispatchV2Enabled() ? 'UNION SELECT feed.technician_id::text AS recipient_id FROM request_feed_views feed WHERE feed.order_id = $1' : ''}
         ) recipients
         WHERE recipient_id <> '' ORDER BY recipient_id`,
        [orderId],
      ),
    );
    return [...new Set(rows.map((row) => row.recipient_id))];
  }

  private async supersedeConflictingTechnicianOffers(
    manager: EntityManager,
    winningOrder: LockedOrderRow,
    technicianId: string,
  ): Promise<void> {
    const scheduled = this.isScheduledOrder(winningOrder);
    const durationMinutes = String(DISPATCH.DEFAULT_JOB_DURATION_MIN);
    // Lock orders before their offers. A deadlock victim retries the complete
    // transaction so assignment, offer closure, wallet and outbox stay atomic.
    const otherOrders = await manager.query<Array<{ id: string }>>(
      `SELECT o.id FROM service_orders o WHERE o.id <> $1 AND o.status = 'searching'
        AND EXISTS (SELECT 1 FROM service_order_offers offer WHERE offer.order_id = o.id
          AND offer.technician_id = $2 AND offer.status = 'pending' AND offer.expires_at > now())
       ORDER BY o.id FOR UPDATE OF o`,
      [winningOrder.id, technicianId],
    );
    if (otherOrders.length === 0) return;
    const superseded = queryRows<{
      id: string;
      order_id: string;
      customer_id: string;
      technician_id: string;
    }>(
      await manager.query(
        `UPDATE service_order_offers offer
         SET status = 'superseded', close_reason = 'technician_unavailable', responded_at = now()
         FROM service_orders other_order, service_orders winning_order
         WHERE offer.order_id = other_order.id
           AND winning_order.id = $1
           AND offer.technician_id = $2
           AND offer.order_id <> winning_order.id
           AND offer.status = 'pending' AND offer.expires_at > now()
           AND other_order.status = 'searching'
           AND other_order.id = ANY($5::uuid[])
           AND (
             (
               $3::boolean IS FALSE
               AND (
                 COALESCE(other_order.search_starts_at, other_order.created_at)
                   >= other_order.scheduled_at - interval '1 minute'
                 OR (
                   other_order.scheduled_at < now() + make_interval(mins => $4::int)
                   AND other_order.scheduled_at + make_interval(mins => $4::int) > now()
                 )
               )
             )
             OR (
               $3::boolean IS TRUE
               AND (
                 (
                   COALESCE(other_order.search_starts_at, other_order.created_at)
                     < other_order.scheduled_at - interval '1 minute'
                   AND tstzrange(
                         other_order.scheduled_at,
                         other_order.scheduled_at + make_interval(mins => $4::int), '[)'
                       ) && tstzrange(
                         winning_order.scheduled_at,
                         winning_order.scheduled_at + make_interval(mins => $4::int), '[)'
                       )
                 )
                 OR (
                   COALESCE(other_order.search_starts_at, other_order.created_at)
                     >= other_order.scheduled_at - interval '1 minute'
                   AND winning_order.scheduled_at < now() + make_interval(mins => $4::int)
                   AND winning_order.scheduled_at + make_interval(mins => $4::int) > now()
                 )
               )
             )
           )
         RETURNING offer.id, offer.order_id, offer.technician_id, other_order.customer_id`,
        [winningOrder.id, technicianId, scheduled, durationMinutes, otherOrders.map((o) => o.id)],
      ),
    );
    if (superseded.length === 0) return;

    const affectedOrderIds = [...new Set(superseded.map((offer) => offer.order_id))];
    await manager.query(
      `UPDATE service_orders order_row
       SET pending_offers_count = (
         SELECT COUNT(*)::int FROM service_order_offers pending
         WHERE pending.order_id = order_row.id AND pending.status = 'pending'
           AND pending.expires_at > now()
       ), version = version + 1, updated_at = now()
       WHERE order_row.id = ANY($1::uuid[])`,
      [affectedOrderIds],
    );
    for (const offer of superseded) {
      const payload = {
        offerId: offer.id,
        orderId: offer.order_id,
        reason: 'technician_unavailable',
      };
      await this.queueOutbox(manager, 'offer.lost', offer.order_id, offer.technician_id, payload);
      await this.queueOutbox(manager, 'offer.lost', offer.order_id, offer.customer_id, payload);
    }
  }

  private async loadConfirmedOrder(
    manager: EntityManager,
    customerId: string,
    orderId: string,
  ): Promise<ActiveOrderDto> {
    const row = queryRows<{
      id: string;
      reference: string;
      status: string;
      version: number;
      serviceTitleAr: string;
      customerOfferMinor: string;
      agreedLaborMinor: string | null;
      currency: string;
      pendingOffersCount: string;
      bestOfferMinor: string | null;
      searchExpired: boolean;
      scheduledAt: Date | string;
      searchStartsAt: Date | string | null;
      searchExpiresAt: Date | string | null;
      technicianId: string | null;
      technicianDisplayName: string | null;
      technicianRating: string | number | null;
      updatedAt: Date | string;
      serviceLocation: string | null;
      serviceAddress: string | null;
      serviceArea: string | null;
    }>(
      await manager.query(
        `SELECT o.id, 'FX-' || o.order_number::text AS reference, o.status::text,
                o.version, s.title_ar AS "serviceTitleAr",
                o.customer_offer_minor::text AS "customerOfferMinor",
                o.agreed_labor_minor::text AS "agreedLaborMinor", o.currency,
                (SELECT COUNT(*)::text FROM service_order_offers pending
                  WHERE pending.order_id = o.id AND pending.status = 'pending'
                    AND pending.expires_at > now()) AS "pendingOffersCount",
                (SELECT MIN(best.amount_minor)::text FROM service_order_offers best
                  WHERE best.order_id = o.id AND best.status = 'pending'
                    AND best.expires_at > now()) AS "bestOfferMinor",
                (o.status = 'searching' AND o.search_expires_at <= now()) AS "searchExpired",
                o.scheduled_at AS "scheduledAt", o.search_starts_at AS "searchStartsAt",
                o.search_expires_at AS "searchExpiresAt",
                tech.id AS "technicianId", tech.display_name AS "technicianDisplayName",
                (SELECT AVG(review.rating)::numeric(3,2) FROM technician_reviews review
                  WHERE review.technician_id = tech.id) AS "technicianRating",
                o.updated_at AS "updatedAt",
                CASE WHEN o.status = 'assigned' THEN o.service_location ELSE NULL END AS "serviceLocation",
                CASE WHEN o.status <> 'assigned' THEN NULL
                     WHEN o.service_location = 'provider_workshop' THEN accepted_offer.workshop_address
                     ELSE customer_address.formatted_address
                END AS "serviceAddress",
                CASE WHEN o.status <> 'assigned' THEN NULL
                     WHEN o.service_location = 'provider_workshop'
                       THEN COALESCE(workshop_area.name_ar, accepted_offer.workshop_area_code)
                     ELSE COALESCE(customer_area.name_ar, customer_address.area_code)
                END AS "serviceArea"
         FROM service_orders o
         JOIN services s ON s.id = o.service_id
         LEFT JOIN users tech ON tech.id = o.technician_id
         LEFT JOIN service_order_offers accepted_offer ON accepted_offer.id = o.assigned_offer_id
         LEFT JOIN user_addresses customer_address ON customer_address.id = o.selected_address_id
         LEFT JOIN geo_areas customer_area ON customer_area.code = customer_address.area_code
         LEFT JOIN geo_areas workshop_area ON workshop_area.code = accepted_offer.workshop_area_code
         WHERE o.id = $1 AND o.customer_id = $2`,
        [orderId, customerId],
      ),
    )[0];
    if (row == null) throw new NotFoundException('Order not found.');
    return {
      id: row.id,
      reference: row.reference,
      status: row.status,
      version: row.version,
      serviceTitleAr: row.serviceTitleAr,
      customerOfferMinor: row.customerOfferMinor,
      agreedLaborMinor: row.agreedLaborMinor,
      currency: row.currency,
      pendingOffersCount: Number(row.pendingOffersCount),
      bestOfferMinor: row.bestOfferMinor,
      searchExpired: row.searchExpired,
      scheduledAt: new Date(row.scheduledAt).toISOString(),
      searchStartsAt:
        row.searchStartsAt == null ? null : new Date(row.searchStartsAt).toISOString(),
      searchExpiresAt:
        row.searchExpiresAt == null ? null : new Date(row.searchExpiresAt).toISOString(),
      technician:
        row.technicianId == null
          ? null
          : {
              id: row.technicianId,
              displayName: row.technicianDisplayName,
              rating: row.technicianRating == null ? null : Number(row.technicianRating),
            },
      updatedAt: new Date(row.updatedAt).toISOString(),
      serviceLocation: row.serviceLocation,
      serviceAddress: row.serviceAddress,
      serviceArea: row.serviceArea,
    };
  }

  private async assignOrder(
    manager: EntityManager,
    order: LockedOrderRow,
    technicianId: string,
    amountMinor: string,
    assignment: {
      offerId?: string | null;
      serviceLocation?: 'customer_site' | 'provider_workshop';
    } = {},
  ): Promise<void> {
    await manager.query("SET LOCAL lock_timeout = '5s'");
    const [billing] = await manager.query<Array<{ blocked: boolean }>>(
      'SELECT technician_billing_blocked($1) AS blocked',
      [technicianId],
    );
    if (billing?.blocked)
      throw new ConflictException({
        code: 'TECHNICIAN_UNAVAILABLE',
        message: 'الفني مش متاح دلوقتي. اختار عرض تاني.',
      });
    const timeOffRows = await manager.query<Array<{ is_on_time_off: boolean }>>(
      'SELECT technician_on_time_off($1, $2::timestamptz) AS is_on_time_off',
      [technicianId, order.scheduled_at],
    );
    if (timeOffRows[0]?.is_on_time_off === true) {
      throw new ConflictException('الفني في إجازة في موعد هذا الطلب.');
    }
    const discountMinor = await this.discountFor(
      manager,
      order.id,
      order.promotion_grant_id,
      amountMinor,
    );
    const totalMinor = BigInt(amountMinor) - discountMinor;
    const assigned = queryRows<{ id: string }>(
      await manager.query(
        `UPDATE service_orders
         SET technician_id = $2, status = 'assigned', agreed_labor_minor = $3,
             subtotal_price_minor = $3, discount_minor = $4, total_price_minor = $5,
             quoted_price_minor = $5, pending_offers_count = 0,
             assigned_offer_id = $6, service_location = $7,
             version = version + 1, updated_at = now()
         WHERE id = $1 AND status = 'searching'
         RETURNING id`,
        [
          order.id,
          technicianId,
          amountMinor,
          discountMinor.toString(),
          totalMinor.toString(),
          assignment.offerId ?? null,
          assignment.serviceLocation ?? 'customer_site',
        ],
      ),
    )[0];
    if (assigned == null) {
      throw new ConflictException({
        code: 'ORDER_ALREADY_ASSIGNED',
        message: 'Another offer has already been assigned to this order.',
      });
    }
    if (order.payment_method === 'app_wallet') {
      await reserveOrderWallet(manager, {
        orderId: order.id,
        userId: order.customer_id,
        amountMinor: totalMinor,
        currency: order.currency,
      });
    }
    await settlePromotionGrant(manager, order.id, 'assigned');
    await this.timeline(
      manager,
      order.id,
      'technician_assigned',
      'تم تعيين الفني',
      'searching',
      'assigned',
    );
  }

  private async discountFor(
    manager: EntityManager,
    orderId: string,
    promotionGrantId: string | null,
    amountMinor: string,
  ): Promise<bigint> {
    if (promotionGrantId == null) return 0n;
    const rows = queryRows<PromotionRow>(
      await manager.query(
        `SELECT o.promotion_discount_type AS discount_type,
                o.promotion_discount_value AS discount_value,
                o.promotion_max_discount_minor AS max_discount_minor
         FROM service_orders o
         WHERE o.id = $1 AND o.promotion_discount_type IS NOT NULL
         UNION ALL
         SELECT p.discount_type::text, p.discount_value, p.max_discount_minor::text
         FROM user_promotion_grants g JOIN promotion_codes p ON p.id = g.promotion_id
         WHERE g.id = $2 AND g.status = 'reserved'
           AND NOT EXISTS (
             SELECT 1 FROM service_orders so
             WHERE so.id = $1 AND so.promotion_discount_type IS NOT NULL
           )
         LIMIT 1`,
        [orderId, promotionGrantId],
      ),
    );
    const promotion = rows[0];
    if (promotion == null) return 0n;
    const amount = BigInt(amountMinor);
    let discount =
      promotion.discount_type === 'percentage'
        ? (amount * BigInt(promotion.discount_value)) / 100n
        : BigInt(promotion.discount_value);
    if (promotion.max_discount_minor != null) {
      const cap = BigInt(promotion.max_discount_minor);
      if (discount > cap) discount = cap;
    }
    return discount > amount ? amount : discount;
  }

  private parseMinorAmount(raw: string): bigint {
    if (!/^[1-9]\d{0,18}$/.test(raw)) {
      throw new BadRequestException({ code: 'INVALID_AMOUNT', message: 'Amount is invalid.' });
    }
    const amount = BigInt(raw);
    if (amount > 9_223_372_036_854_775_807n) {
      throw new BadRequestException({ code: 'INVALID_AMOUNT', message: 'Amount is too large.' });
    }
    return amount;
  }
  private snapshotDiscount(
    amountMinor: string,
    type: string | null,
    value: string | null,
    cap: string | null,
  ): bigint {
    if (type == null || value == null) return 0n;
    const amount = BigInt(amountMinor);
    let discount = type === 'percentage' ? (amount * BigInt(value)) / 100n : BigInt(value);
    if (cap != null && discount > BigInt(cap)) discount = BigInt(cap);
    return discount > amount ? amount : discount;
  }
  private async timeline(
    manager: EntityManager,
    orderId: string,
    eventType: string,
    title: string,
    fromStatus: string | null,
    toStatus: string | null,
    metadata: Record<string, unknown> = {},
  ): Promise<void> {
    await manager.query(
      `INSERT INTO service_order_timeline
         (order_id, event_type, title, from_status, to_status, metadata)
       VALUES ($1, $2, $3, $4::service_order_status, $5::service_order_status, $6::jsonb)`,
      [orderId, eventType, title, fromStatus, toStatus, JSON.stringify(metadata)],
    );
  }

  private async queueOutbox(
    manager: EntityManager,
    eventType: string,
    orderId: string,
    recipientId: string | string[],
    payload: Record<string, unknown>,
  ): Promise<void> {
    if (Array.isArray(recipientId)) {
      for (const id of recipientId)
        await this.queueOutbox(manager, eventType, orderId, id, payload);
      return;
    }
    await manager.query(
      `INSERT INTO domain_event_outbox (event_type, aggregate_id, recipients, payload)
       VALUES ($1, $2, jsonb_build_array(jsonb_build_object(
         'kind', (SELECT role::text FROM users WHERE id = $3::uuid), 'id', $3::text)), $4::jsonb)`,
      [eventType, orderId, recipientId, JSON.stringify(payload)],
    );
  }
}import { ConflictException } from '@nestjs/common';
import { type ConfigService } from '@nestjs/config';
import { type DataSource, type EntityManager } from 'typeorm';
import { describe, expect, it, vi } from 'vitest';
import { TechnicianPresenceService } from './technician-presence.service';

const userId = '35b68610-df1f-47a2-b021-021a942ce7f3';

describe('TechnicianPresenceService online schedule requirement', () => {
  it('rejects going online without configured hours before updating presence', async () => {
    const query = vi.fn((sql: string) =>
      Promise.resolve(sql.includes('AS schedule_ready') ? [{ schedule_ready: false }] : []),
    );
    const source = {
      transaction: vi.fn(
        async (callback: (manager: EntityManager) => Promise<unknown>) =>
          await callback({ query } as unknown as EntityManager),
      ),
    } as unknown as DataSource;
    const config = { get: vi.fn().mockReturnValue(true) } as unknown as ConfigService;
    await expect(
      new TechnicianPresenceService(source, config).update(userId, { online: true }),
    ).rejects.toMatchObject({ response: { code: 'WORK_HOURS_REQUIRED' } });
    expect(query.mock.calls.some(([sql]) => sql.includes('UPDATE technician_profiles'))).toBe(
      false,
    );
  });
});

function createService(rows: Array<Record<string, unknown>> = []): {
  service: TechnicianPresenceService;
  query: ReturnType<typeof vi.fn>;
  transaction: ReturnType<typeof vi.fn>;
} {
  const query = vi.fn().mockResolvedValue(rows);
  const transaction = vi.fn(async (cb: (manager: EntityManager) => Promise<unknown>) =>
    await cb({
      query: async (sql: string):Promise<unknown> => {
        if(sql.includes('technician_billing_blocked')) return [{blocked:false}];
        if(sql.includes('pg_advisory_xact_lock') || sql.startsWith('SET LOCAL')) return [];
        const result:unknown=await query(sql);return result;
      },
    } as unknown as EntityManager),
  );
  const dataSource = { query, transaction } as unknown as DataSource;
  const config = {
    get: vi.fn().mockReturnValue(true),
  } as unknown as ConfigService;
  return {
    service: new TechnicianPresenceService(dataSource, config),
    query,
    transaction,
  };
}

describe('TechnicianPresenceService heartbeat', () => {
  it('reconciles billing under a transaction lock before the throttled heartbeat', async () => {
    const lastSeenAt = new Date('2026-10-08T12:00:00.000Z');
    const { service, query, transaction } = createService([
      { is_online: true, break_until: null, last_seen_at: lastSeenAt },
    ]);

    await expect(service.heartbeat(userId)).resolves.toEqual({
      lastSeenAt: lastSeenAt.toISOString(),
    });

    expect(query).toHaveBeenCalledOnce();
    const sql = String(query.mock.calls[0]?.[0]);
    expect(sql).toContain("interval '20 seconds'");
    expect(sql).toContain('NOT EXISTS (SELECT 1 FROM updated)');
    expect(sql).not.toContain('updated_at');
    expect(transaction).toHaveBeenCalledOnce(); // centralized billing reconciliation
  });

  it('rejects a heartbeat when the technician is not active and online', async () => {
    const { service } = createService();

    await expect(service.heartbeat(userId)).rejects.toBeInstanceOf(ConflictException);
  });
});

describe('TechnicianPresenceService get', () => {
  it('only reads presence for an approved technician with an active account', async () => {
    const { service, query } = createService([
      {
        is_online: true,
        break_until: null,
        last_seen_at: new Date('2026-10-08T12:00:00.000Z'),
      },
    ]);

    await service.get(userId);

    const sql = String(query.mock.calls[0]?.[0]);
    expect(sql).toContain("tp.application_status = 'approved'");
    expect(sql).toContain("u.status = 'active'");
    expect(sql).toContain('u.deleted_at IS NULL');
    expect(sql).toContain('tp.break_until > now()');
  });
});import { assertNotBillingBlocked } from '../commission-billing/services/commission-enforcement';
import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { ConfigService } from '@nestjs/config';
import { DataSource, type EntityManager } from 'typeorm';

import { queryRows } from '../../common/database/query-rows';
import { type UpdateTechnicianPresenceDto } from './dto/update-technician-presence.dto';
import { dispatchMutation } from './dispatch-idempotency';
import { withdrawTechnicianPendingOffers } from './withdraw-technician-pending-offers';

interface PresenceRow {
  is_online: boolean;
  break_until: Date | string | null;
  last_seen_at: Date | string | null;
}

@Injectable()
export class TechnicianPresenceService {
  constructor(
    @InjectDataSource() private readonly dataSource: DataSource,
    @Optional() private readonly config?: ConfigService,
  ) {}

  async update(
    userId: string,
    dto: UpdateTechnicianPresenceDto,
    idempotencyKey?: string,
  ): Promise<{
    online: boolean;
    breakUntil: string | null;
  }> {
    this.assertEnabled();
    const hasOnline = dto.online !== undefined;
    const hasBreak = dto.breakMinutes !== undefined;
    if (hasOnline === hasBreak) {
      throw new BadRequestException({
        code: 'INVALID_PRESENCE_REQUEST',
        message: 'Provide exactly one of online or breakMinutes.',
      });
    }

    return await dispatchMutation(
      this.dataSource,
      true,
      'technician.presence',
      userId,
      idempotencyKey,
      dto,
      async (manager) => {
        await this.lockPresence(manager, userId);
        if (dto.online === true || hasBreak) await assertNotBillingBlocked(manager, userId);
        if (dto.online === true) {
          const [schedule] = await manager.query<Array<{ schedule_ready: boolean }>>(
            `SELECT CASE WHEN NOT valid_technician_availability(tp.availability) THEN false
                         ELSE jsonb_array_length(tp.availability) > 0 END AS schedule_ready
             FROM technician_profiles tp JOIN users u ON u.id = tp.user_id
             WHERE tp.user_id = $1 AND tp.application_status = 'approved'
               AND u.status = 'active' AND u.deleted_at IS NULL`,
            [userId],
          );
          if (schedule === undefined)
            throw new ForbiddenException({
              code: 'TECHNICIAN_NOT_APPROVED',
              message: 'Approved active technicians only.',
            });
          if (!schedule.schedule_ready)
            throw new ConflictException({
              code: 'WORK_HOURS_REQUIRED',
              message: 'اضبط مواعيد عمل صحيحة قبل الاتصال واستقبال الطلبات.',
            });
        }
        if (hasBreak) {
          const current = queryRows<{ is_online: boolean }>(
            await manager.query(
              `SELECT tp.is_online FROM technician_profiles tp
               JOIN users u ON u.id = tp.user_id
               WHERE tp.user_id = $1 AND tp.application_status = 'approved'
                 AND u.status = 'active' AND u.deleted_at IS NULL FOR UPDATE OF tp`,
              [userId],
            ),
          )[0];
          if (current != null && !current.is_online) {
            throw new ConflictException({
              code: 'PRESENCE_OFFLINE',
              message: 'Connect before starting a break.',
            });
          }
        }
        const rows = hasOnline
          ? queryRows<PresenceRow>(
              await manager.query(
                `UPDATE technician_profiles tp
               SET is_online = $2,
                   online_changed_at = CASE WHEN tp.is_online IS DISTINCT FROM $2 THEN now() ELSE tp.online_changed_at END,
                   last_seen_at = CASE WHEN $2 THEN now() ELSE tp.last_seen_at END,
                   break_until = NULL,
                   updated_at = now()
               FROM users u
               WHERE tp.user_id = $1 AND tp.application_status = 'approved'
                 AND u.id = tp.user_id AND u.status = 'active' AND u.deleted_at IS NULL
               RETURNING tp.is_online, tp.break_until, tp.last_seen_at`,
                [userId, dto.online],
              ),
            )
          : queryRows<PresenceRow>(
              await manager.query(
                `UPDATE technician_profiles tp
               SET break_until = now() + make_interval(mins => $2::int),
                   last_seen_at = now(),
                   updated_at = now()
               FROM users u
               WHERE tp.user_id = $1 AND tp.application_status = 'approved'
                 AND tp.is_online IS TRUE
                 AND u.id = tp.user_id AND u.status = 'active' AND u.deleted_at IS NULL
               RETURNING tp.is_online, tp.break_until, tp.last_seen_at`,
                [userId, dto.breakMinutes],
              ),
            );
        const row = rows[0];
        if (row == null) {
          throw new ForbiddenException({
            code: 'TECHNICIAN_NOT_APPROVED',
            message: 'Approved active technicians only.',
          });
        }
        if (!row.is_online || hasBreak) {
          await withdrawTechnicianPendingOffers(manager, userId);
        }
        return {
          online: row.is_online,
          breakUntil: row.break_until == null ? null : new Date(row.break_until).toISOString(),
        };
      },
    );
  }

  async heartbeat(userId: string): Promise<{ lastSeenAt: string }> {
    this.assertEnabled();
    return await this.dataSource.transaction(async (manager) => {
      await this.lockPresence(manager, userId);
      const [billingRow] = await manager.query<Array<{ blocked: boolean }>>(
        'SELECT technician_billing_blocked($1) AS blocked',
        [userId],
      );
      if (billingRow?.blocked) {
        await manager.query(
          'UPDATE technician_profiles SET is_online=false,break_until=NULL,updated_at=now() WHERE user_id=$1',
          [userId],
        );
        await withdrawTechnicianPendingOffers(manager, userId);
        return { lastSeenAt: new Date().toISOString() };
      }
      const rows = queryRows<PresenceRow>(
        await manager.query<PresenceRow[]>(
          `WITH updated AS (
           UPDATE technician_profiles tp
           SET last_seen_at = now()
           FROM users u
           WHERE tp.user_id = $1 AND tp.application_status = 'approved'
             AND tp.is_online IS TRUE
             AND (tp.last_seen_at IS NULL
                  OR tp.last_seen_at < now() - interval '20 seconds')
             AND u.id = tp.user_id AND u.status = 'active' AND u.deleted_at IS NULL
           RETURNING tp.is_online, tp.break_until, tp.last_seen_at
         )
         SELECT is_online, break_until, last_seen_at FROM updated
         UNION ALL
         SELECT tp.is_online, tp.break_until, tp.last_seen_at
         FROM technician_profiles tp
         JOIN users u ON u.id = tp.user_id
         WHERE tp.user_id = $1 AND tp.application_status = 'approved'
           AND tp.is_online IS TRUE
           AND u.status = 'active' AND u.deleted_at IS NULL
           AND NOT EXISTS (SELECT 1 FROM updated)
         LIMIT 1`,
          [userId],
        ),
      );
      const row = rows[0];
      if (row?.last_seen_at == null) {
        throw new ConflictException({
          code: 'PRESENCE_OFFLINE',
          message: 'Heartbeat is accepted only while the technician is online.',
        });
      }
      return { lastSeenAt: new Date(row.last_seen_at).toISOString() };
    });
  }

  private async lockPresence(manager: EntityManager, userId: string): Promise<void> {
    await manager.query("SET LOCAL lock_timeout = '5s'");
    // Keep compatible with the stage-3 settings lock and serialize new dispatch actions too.
    await manager.query('SELECT pg_advisory_xact_lock(hashtextextended($1, 0))', [userId]);
    await manager.query('SELECT pg_advisory_xact_lock(hashtextextended($1, 0))', [
      `tech:${userId}`,
    ]);
  }

  async get(userId: string): Promise<{ online: boolean; breakUntil: string | null }> {
    this.assertEnabled();
    const [row] = await this.dataSource.query<PresenceRow[]>(
      `SELECT (tp.is_online IS TRUE AND (
                (tp.last_seen_at > now() - interval '3 minutes') IS TRUE
                OR (tp.break_until > now()) IS TRUE
              )) AS is_online,
              tp.break_until, tp.last_seen_at
       FROM technician_profiles tp
       JOIN users u ON u.id = tp.user_id
       WHERE tp.user_id = $1 AND tp.application_status = 'approved'
         AND u.status = 'active' AND u.deleted_at IS NULL`,
      [userId],
    );
    if (!row) throw new NotFoundException('Technician profile not found.');
    return {
      online: row.is_online,
      breakUntil: row.break_until == null ? null : new Date(row.break_until).toISOString(),
    };
  }

  private assertEnabled(): void {
    if (this.config?.get<boolean>('dispatch.v2Enabled') !== true) {
      throw new NotFoundException({
        code: 'DISPATCH_V2_DISABLED',
        message: 'Dispatch v2 is disabled.',
      });
    }
  }
}import {
