@UseGuards(AccessTokenGuard)
@Controller('v1/technician')
export class TechnicianRequestsController {
  constructor(
    private readonly offers: OrderOffersService,
    private readonly presence: TechnicianPresenceService,
  ) {}

  @Put('presence')
  updatePresence(
    @CurrentUser() user: UserEntity,
    @Body() dto: UpdateTechnicianPresenceDto,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ online: boolean; breakUntil: string | null }> {
    this.assertTechnician(user);
    return key == null
      ? this.presence.update(user.id, dto)
      : this.presence.update(user.id, dto, key);
  }

  @Post('presence/heartbeat')
  heartbeat(@CurrentUser() user: UserEntity): Promise<{ lastSeenAt: string }> {
    this.assertTechnician(user);
    return this.presence.heartbeat(user.id);
  }

  @Get('presence')
  getPresence(
    @CurrentUser() user: UserEntity,
  ): Promise<{ online: boolean; breakUntil: string | null }> {
    this.assertTechnician(user);
    return this.presence.get(user.id);
  }

  @Get('requests')
  list(
    @CurrentUser() user: UserEntity,
    @Query() query: ListTechnicianRequestsQueryDto,
  ): Promise<{ data: unknown[]; nextCursor?: string }> {
    this.assertTechnician(user);
    return this.offers.listTechnicianRequests(user.id, query);
  }

  @Get('requests/:id')
  async get(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
  ): Promise<{ data: Record<string, unknown> }> {
    this.assertTechnician(user);
    const result = await this.offers.getTechnicianRequest(user.id, id);
    await this.offers.recordTechnicianRequestView(user.id, id);
    return result;
  }

  @Post('requests/:id/offers')
  createOffer(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
    @Body() dto: CreateTechnicianOfferDto,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ id: string; status: string; amountMinor: string; expiresAt: string }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.createOffer(user.id, id, dto)
      : this.offers.createOffer(user.id, id, dto, key);
  }

  @Get('orders/:id/dispatch-details')
  assignment(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
  ): Promise<{ data: Record<string, unknown> }> {
    this.assertTechnician(user);
    return this.offers.getTechnicianAssignment(user.id, id);
  }

  @Get('active-order')
  currentAssignment(
    @CurrentUser() user: UserEntity,
  ): Promise<{ data: Record<string, unknown> | null }> {
    this.assertTechnician(user);
    return this.offers.currentTechnicianAssignment(user.id);
  }

  @Post('requests/:id/accept')
  accept(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ status: string }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.acceptByTechnician(user.id, id)
      : this.offers.acceptByTechnician(user.id, id, key);
  }

  @Post('requests/:id/counter-offer')
  counter(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
    @Body() dto: CounterOfferDto,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ id: string; status: string; expiresAt: string }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.counterOffer(user.id, id, dto.amountMinor)
      : this.offers.counterOffer(user.id, id, dto.amountMinor, key);
  }

  @Post('requests/:id/skip')
  skip(
    @CurrentUser() user: UserEntity,
    @Param('id', new ParseUUIDPipe()) id: string,
    @Body() dto: SkipTechnicianRequestDto = new SkipTechnicianRequestDto(),
    @Headers('idempotency-key') key?: string,
  ): Promise<{ skipped: true }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.skip(user.id, id, dto.reason)
      : this.offers.skip(user.id, id, dto.reason, key);
  }

  @Get('offers')
  listOffers(
    @CurrentUser() user: UserEntity,
    @Query() query: ListTechnicianOffersQueryDto,
  ): Promise<ListTechnicianOffersResponseDto> {
    this.assertTechnician(user);
    return this.offers.listTechnicianOffers(user.id, query.status, query.limit, query.cursor);
  }

  @Patch('offers/:offerId')
  updateOffer(
    @CurrentUser() user: UserEntity,
    @Param('offerId', new ParseUUIDPipe()) offerId: string,
    @Body() dto: UpdateTechnicianOfferDto,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ id: string; status: string; revision: number; amountMinor: string }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.updateTechnicianOffer(user.id, offerId, dto)
      : this.offers.updateTechnicianOffer(user.id, offerId, dto, key);
  }

  @Delete('offers/:offerId')
  withdraw(
    @CurrentUser() user: UserEntity,
    @Param('offerId', new ParseUUIDPipe()) offerId: string,
    @Headers('idempotency-key') key?: string,
  ): Promise<{ status: string }> {
    this.assertTechnician(user);
    return key == null
      ? this.offers.withdraw(user.id, offerId)
      : this.offers.withdraw(user.id, offerId, key);
  }

  private assertTechnician(user: UserEntity): void {
    if (user.role !== UserRole.Technician) {
      throw new ForbiddenException('Only technician accounts can access technician requests.');
    }
  }
