const PUSH_EVENTS = new Set([
  'billing.statement_issued',
  'billing.payment_approved',
  'billing.payment_rejected',
  'billing.submission_received',
  'billing.payment_reminder',
  'billing.review_reminder',
  'billing.statement_waived',
  'request.new',
  'spare_part.request.new',
  'spare_part.offer.received',
  'spare_part.offer.revised',
  'spare_part.offer.withdrawn',
  'spare_part.offer.rejected',
  'spare_part.offer.accepted',
  'spare_part.offer.on_hold',
  'spare_part.offer.lost',
  'spare_part.deal.updated',
  'spare_part.request.expiring',
  'spare_part.offer.needs_review',
  'offer.received',
  'offer.needs_review',
  'order.assigned',
  'offer.lost',
  'order.no_provider_found',
  'phone.changed',
  'phone_verification.transferred',
  'risk.warning',
  'discipline.escalated',
  'discipline.safety_hold',
  'chat.message.created',
]);

export class PushDeliveryError extends Error {
  constructor(
    message: string,
    readonly failedTokens: readonly string[],
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = 'PushDeliveryError';
  }
}

@Injectable()
export class RealtimePushService {
  private readonly logger = new Logger(RealtimePushService.name);
  private messaging: Messaging | null | undefined;

  constructor(private readonly config: ConfigService) {}

  async notify(
    manager: EntityManager,
    eventType: string,
    recipientIds: readonly string[],
    payload: Record<string, unknown>,
    options: { persistInApp?: boolean; tokenAllowlist?: readonly string[] } = {},
  ): Promise<void> {
    if (!PUSH_EVENTS.has(eventType) || recipientIds.length === 0) return;
    const deliveryPayload: Record<string, unknown> = {
      ...payload,
      eventId:
        typeof payload.eventId === 'string' && payload.eventId.length > 0
          ? payload.eventId
          : randomUUID(),
    };
    const tokenAllowlist = options.tokenAllowlist;
    const tokens = await manager.query<Array<{ token: string; user_id: string }>>(
      `SELECT token, user_id
       FROM user_push_tokens
       WHERE user_id = ANY($1::uuid[]) AND last_seen_at > now() - interval '30 days'
         AND ($3::text[] IS NULL OR token = ANY($3::text[]))
         AND ($2 <> 'request.new' OR (is_background IS TRUE AND EXISTS (
           SELECT 1 FROM technician_profiles tp WHERE tp.user_id = user_push_tokens.user_id
             AND tp.is_online IS TRUE
             AND tp.last_seen_at > now() - interval '3 minutes'
             AND (tp.break_until IS NULL OR tp.break_until <= now())
         )))`,
      [recipientIds, eventType, tokenAllowlist == null ? null : [...tokenAllowlist]],
    );
    if (tokens.length > 0) {
      const messaging = this.getMessaging();
      if (messaging != null) {
        try {
          const senderName =
            eventType === 'chat.message.created' && typeof deliveryPayload.senderId === 'string'
              ? (
                  await manager.query<Array<{ display_name: string | null }>>(
                    `SELECT display_name FROM users WHERE id=$1 LIMIT 1`,
                    [deliveryPayload.senderId],
                  )
                )[0]?.display_name
              : undefined;
          const data: Record<string, string> =
            eventType === 'chat.message.created' ? { type: 'chat' } : { eventType };
          for (const key of [
            'eventId',
            'orderId',
            ...(eventType.startsWith('billing.') ? ['statementId', 'submissionId'] : []),
            ...(eventType.startsWith('spare_part.') ? ['requestId', 'dealId'] : []),
            ...(eventType === 'chat.message.created' ? [] : ['offerId']),
          ]) {
            const value = deliveryPayload[key];
            if (value != null) data[key] = this.serializeDataValue(value);
          }
          const collapseId =
            typeof deliveryPayload.eventId === 'string'
              ? deliveryPayload.eventId.slice(0, 64)
              : undefined;
          const message = {
            ...(collapseId
              ? {
                  android: { notification: { tag: collapseId } },
                  apns: { headers: { 'apns-collapse-id': collapseId } },
                }
              : {}),
            notification: {
              title: this.titleFor(eventType, senderName),
              body: this.bodyFor(eventType, deliveryPayload),
            },
            data,
          };
          // Firebase Admin's multicast helper is deprecated in v14. sendEach
          // preserves per-token results, which we retain across outbox retries.
          const failedTokens: string[] = [];
          const invalidTokens: string[] = [];
          for (let offset = 0; offset < tokens.length; offset += 500) {
            const batch = tokens.slice(offset, offset + 500);
            let delivery;
            try {
              delivery = await messaging.sendEach(
                batch.map((row) => ({ ...message, token: row.token })),
              );
            } catch (error) {
              failedTokens.push(...batch.map((row) => row.token));
              this.logger.warn(`FCM batch failed for ${eventType}: ${this.errorMessage(error)}`);
              continue;
            }
            for (let index = 0; index < batch.length; index += 1) {
              const token = batch[index]?.token;
              if (token == null) continue;
              const response = delivery.responses[index];
              if (response?.success) continue;
              const code = response?.error?.code ?? '';
              if (
                code === 'messaging/registration-token-not-registered' ||
                code === 'messaging/invalid-registration-token'
              ) {
                invalidTokens.push(token);
              } else {
                failedTokens.push(token);
              }
            }
          }
          if (invalidTokens.length > 0) {
            try {
              await manager.query('DELETE FROM user_push_tokens WHERE token = ANY($1::text[])', [
                invalidTokens,
              ]);
            } catch (error) {
              // Token cleanup must not replay already delivered notifications.
              this.logger.warn(`Unable to remove invalid FCM tokens: ${this.errorMessage(error)}`);
            }
          }
          if (failedTokens.length > 0) {
            throw new PushDeliveryError('FCM delivery failed.', [...new Set(failedTokens)]);
          }
          return;
        } catch (error) {
          this.logger.warn(`FCM delivery failed for ${eventType}: ${this.errorMessage(error)}`);
          if (options.persistInApp !== false) {
            try {
              await this.writeInAppFallback(manager, eventType, recipientIds, deliveryPayload);
            } catch (fallbackError) {
              if (error instanceof PushDeliveryError) {
                throw new PushDeliveryError(
                  `FCM delivery and in-app fallback failed for ${eventType}.`,
                  error.failedTokens,
                  { cause: fallbackError },
                );
              }
              throw new PushDeliveryError(
                `FCM delivery and in-app fallback failed for ${eventType}.`,
                tokens.map((row) => row.token),
                { cause: fallbackError },
              );
            }
          }
          if (error instanceof PushDeliveryError) throw error;
          throw new PushDeliveryError(
            `FCM delivery failed for ${eventType}.`,
            tokens.map((row) => row.token),
            { cause: error },
          );
        }
      }
    }
    if (options.persistInApp !== false)
      await this.writeInAppFallback(manager, eventType, recipientIds, deliveryPayload);
  }

  private async writeInAppFallback(
    manager: EntityManager,
    eventType: string,
    recipientIds: readonly string[],
    payload: Record<string, unknown>,
  ): Promise<void> {
    await manager.query(
      `INSERT INTO user_notifications (user_id, type, title_ar, body_ar, data, event_id)
       SELECT recipient_id, $1, $2, $3, $4::jsonb, $6
       FROM unnest($5::uuid[]) AS recipient_id
       ON CONFLICT (user_id, event_id, type) WHERE event_id IS NOT NULL DO NOTHING`,
      [
        eventType,
        this.titleFor(eventType),
        this.bodyFor(eventType, payload),
        JSON.stringify(payload),
        recipientIds,
        typeof payload.eventId === 'string' ? payload.eventId : null,
      ],
    );
  }

  private getMessaging(): Messaging | null {
    if (this.messaging !== undefined) return this.messaging;
    try {
      const projectId = this.config.get<string>('authentication.firebaseProjectId');
      const app =
        getApps().find((candidate) => candidate.name === 'fixit-pro-auth') ??
        initializeApp(
          {
            credential: applicationDefault(),
            ...(projectId == null ? {} : { projectId }),
          },
          'fixit-pro-realtime',
        );
      this.messaging = getMessaging(app);
    } catch {
      this.messaging = null;
    }
    return this.messaging;
  }

  private titleFor(eventType: string, senderName?: string | null): string {
    if (eventType.startsWith('billing.')) return 'مستحقات المنصة';
    if (eventType === 'chat.message.created') return senderName?.trim() ?? 'رسالة جديدة';
    const titles: Record<string, string> = {
      'request.new': 'طلب خدمة جديد',
      'spare_part.request.new': 'طلب قطعة غيار جديد',
      'spare_part.offer.revised': 'تم تعديل عرض قطعة الغيار',
      'spare_part.offer.withdrawn': 'تم سحب عرض قطعة الغيار',
      'spare_part.offer.rejected': 'لم يتم اختيار عرضك',
      'spare_part.offer.received': 'وصلك عرض جديد لقطعة الغيار',
      'spare_part.offer.accepted': 'تم قبول عرضك',
      'spare_part.offer.on_hold': 'عرضك في الانتظار',
      'spare_part.offer.lost': 'انتهى عرضك',
      'spare_part.deal.updated': 'تحديث في اتفاق قطعة الغيار',
      'spare_part.request.expiring': 'طلب قطعة الغيار قرب ينتهي',
      'spare_part.offer.needs_review': 'عرض قطعة الغيار يحتاج مراجعة',
      'offer.received': 'وصلك عرض جديد',
      'offer.needs_review': 'الطلب اتعدّل ويحتاج مراجعة',
      'order.assigned': 'تم تعيين فني لطلبك',
      'offer.lost': 'العرض لم يعد متاحًا',
      'order.no_provider_found': 'لم نجد فنيًا',
      'phone.changed': 'تم تغيير رقم الموبايل',
      'phone_verification.transferred': 'تم نقل رقم الموبايل',
      'risk.warning': 'تنبيه بخصوص حسابك',
      'discipline.escalated': 'حالة تحتاج مراجعة إدارية',
      'discipline.safety_hold': 'تم إيقاف استقبال الطلبات مؤقتًا',
    };
    return titles[eventType] ?? 'تحديث جديد';
  }

  private bodyFor(eventType: string, payload: Record<string, unknown>): string {
    if (eventType.startsWith('billing.') && typeof payload.notificationBody === 'string')
      return payload.notificationBody;
    if (eventType === 'chat.message.created') {
      if (typeof payload.text === 'string' && payload.text.trim() !== '') {
        return payload.text.trim().slice(0, 80);
      }
      const attachment = payload.attachment;
      if (attachment != null && typeof attachment === 'object') {
        const kind = (attachment as { kind?: unknown }).kind;
        if (kind === 'image') return '📷 صورة';
        if (kind === 'video') return '🎬 فيديو';
        if (kind === 'audio') {
          const durationMs = Number((attachment as { durationMs?: unknown }).durationMs ?? 0);
          const seconds = Math.max(0, Math.floor(durationMs / 1000));
          return `🎤 رسالة صوتية (0:${String(seconds).padStart(2, '0')})`;
        }
      }
      if (payload.kind === 'system')
        return typeof payload.text === 'string' ? payload.text : 'تحديث الطلب';
      return 'رسالة جديدة';
    }
    if (typeof payload.message === 'string') return payload.message;
    if (eventType === 'offer.needs_review')
      return 'صاحب الطلب عدّل تفاصيل القطعة أو حالتها. راجع التفاصيل قبل تأكيد عرضك.';
    if (eventType === 'risk.warning')
      return 'اتأخرت عن عدة مواعيد مؤخرًا. راجع التزاماتك ومواعيدك القادمة.';
    if (eventType === 'discipline.escalated')
      return 'هناك حالة لم تُحسم في موعدها وتحتاج مراجعة المدير.';
    if (eventType === 'discipline.safety_hold')
      return 'تم إيقاف الطلبات مؤقتًا لحين مراجعة الحالة.';
    if (eventType === 'phone.changed') return 'رقم موبايلك اتغير. لو مش إنت، كلّم الدعم.';
    if (eventType === 'request.new') return 'هناك طلب خدمة جديد قريب منك.';
    if (eventType === 'spare_part.request.new') return 'هناك طلب قطعة غيار مناسب لتخصصك ومنطقتك.';
    if (eventType === 'order.no_provider_found')
      return 'مالقيناش فني. تحب ترفع السعر أو تغيّر الموعد أو تلغي؟';
    return 'افتح التطبيق لمعرفة التفاصيل.';
  }

  private serializeDataValue(value: unknown): string {
    if (typeof value === 'string') return value;
    const serialized = JSON.stringify(value);
    return serialized;
  }

  private errorMessage(error: unknown): string {
    return error instanceof Error ? error.message : 'unknown error';
  }
}import { CanActivate, ExecutionContext, ForbiddenException, Injectable } from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { type AuthenticatedRequest } from '../../authentication/guards/access-token.guard';
import { UserRole } from '../../users/entities/user.entity';

@Injectable()
export class ApprovedTechnicianGuard implements CanActivate {
  constructor(@InjectDataSource() private readonly dataSource: DataSource) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const user = request.currentUser;
    const rows: Array<{ application_status: string }> = await this.dataSource.query(
      `SELECT tp.application_status
       FROM technician_profiles tp
       JOIN users u ON u.id = tp.user_id
       WHERE tp.user_id = $1 AND u.role = $2
         AND u.status = 'active' AND u.deleted_at IS NULL`,
      [user.id, UserRole.Technician],
    );
    if (rows[0]?.application_status !== 'approved') {
      throw new ForbiddenException('Approved technicians only.');
    }
    return true;
  }
}import 'reflect-metadata';
import { randomUUID } from 'node:crypto';
import { DataSource } from 'typeorm';
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { ConfigService } from '@nestjs/config';
import { OrderOffersService } from '../../src/modules/orders/order-offers.service';
import { TechnicianPresenceService } from '../../src/modules/orders/technician-presence.service';
import { CreateTechnicianCommissionBilling1700000000227 } from '../../src/database/migrations/1700000000227-create-technician-commission-billing';
import {
  CommissionBillingService,
  commissionMinor,
} from '../../src/modules/commission-billing/services/commission-billing.service';
import { CommissionStatementGenerator } from '../../src/modules/commission-billing/services/commission-statement.generator';
import { CommissionPaymentsService } from '../../src/modules/commission-billing/services/commission-payments.service';
import { assertNotBillingBlocked } from '../../src/modules/commission-billing/services/commission-enforcement';
import { AuditLogService } from '../../src/modules/administration/services/audit-log.service';
import { FilesService } from '../../src/modules/files/files.service';
import { type BillingRow } from '../../src/modules/commission-billing/services/commission-billing.service';

const url = process.env.TEST_DATABASE_URL ?? '';
const run = process.env.RUN_INTEGRATION_TESTS === 'true' && !!url;
const schema = `commission_test_${randomUUID().replaceAll('-', '')}`;
describe('commission integer rounding', () => {
  it('rounds half up without floating point loss', () => {
    expect(commissionMinor('1234', 1000)).toBe(123n);
    expect(commissionMinor('1235', 1000)).toBe(124n);
    expect(commissionMinor('900719925474099300', 1000)).toBe(90071992547409930n);
    expect(commissionMinor('1235', 0)).toBe(0n);
  });
});
(run ? describe : describe.skip)('commission billing PostgreSQL lifecycle', () => {
  let admin: DataSource,
    db: DataSource,
    billing: CommissionBillingService,
    generator: CommissionStatementGenerator,
    payments: CommissionPaymentsService;
  const tech = randomUUID(),
    other = randomUUID(),
    actor = randomUUID(),
    method = randomUUID(),
    file = randomUUID();
  const migrate = new CreateTechnicianCommissionBilling1700000000227();
  const connections: DataSource[] = [];
  beforeAll(async () => {
    const parsed = new URL(url);
    if (!['localhost', '127.0.0.1', '::1'].includes(parsed.hostname))
      throw new Error('Commission integration tests require a local database.');
    admin = await new DataSource({ type: 'postgres', url }).initialize();
    connections.push(admin);
    await admin.query(`CREATE SCHEMA "${schema}"`);
    parsed.searchParams.set('options', `-c search_path=${schema},public`);
    db = await new DataSource({ type: 'postgres', url: parsed.toString() }).initialize();
    connections.push(db);
    await db.query(`CREATE TYPE ${schema}.media_purpose AS ENUM('other');
      CREATE TABLE users(id uuid PRIMARY KEY,display_name text,email text,phone text,role text,status text DEFAULT 'active',deleted_at timestamptz);
      CREATE TABLE services(id uuid PRIMARY KEY,title_ar text);
      CREATE TABLE service_orders(id uuid PRIMARY KEY,order_number bigint,technician_id uuid,customer_id uuid,status text,agreed_labor_minor bigint,completed_at timestamptz,service_id uuid,pending_offers_count int DEFAULT 0,updated_at timestamptz DEFAULT now());
      CREATE TABLE technician_profiles(user_id uuid PRIMARY KEY,is_online boolean DEFAULT true,break_until timestamptz,updated_at timestamptz DEFAULT now(),application_status text DEFAULT 'approved',availability jsonb DEFAULT '[{"dayOfWeek":0,"startMinute":0,"endMinute":1440}]',last_seen_at timestamptz,online_changed_at timestamptz);
      CREATE FUNCTION valid_technician_availability(value jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_typeof(value)='array' AND jsonb_array_length(value)>0 $$;
      CREATE TABLE stored_files(id uuid PRIMARY KEY,owner_id uuid,purpose ${schema}.media_purpose,status text,deleted_at timestamptz);
      CREATE TABLE service_order_offers(id uuid PRIMARY KEY,order_id uuid,technician_id uuid,status text,close_reason text,responded_at timestamptz,expires_at timestamptz);
      CREATE TABLE domain_event_outbox(id bigserial PRIMARY KEY,event_type text,aggregate_id uuid,recipients jsonb,payload jsonb);
      CREATE TABLE user_notifications(id uuid DEFAULT gen_random_uuid(),user_id uuid,type text,title_ar text,body_ar text,data jsonb);
      CREATE TABLE finance_admin_commands(actor_id uuid,idempotency_key uuid,command_type varchar(40),target_id uuid,PRIMARY KEY(actor_id,idempotency_key));
      CREATE TABLE admin_audit_logs(id uuid DEFAULT gen_random_uuid(),actor_id uuid,actor_label text,action text,category text,target_type text,target_id uuid,target_label text,details jsonb,ip_address inet,user_agent text,correlation_id text);
      CREATE TABLE admin_roles(id uuid PRIMARY KEY,is_super_admin boolean,permissions text[]);
      CREATE TABLE staff_profiles(user_id uuid,role_id uuid,permissions text[]);`);
    const r = db.createQueryRunner();
    await r.connect();
    try {
      await migrate.up(r);
      await migrate.down(r);
      await migrate.up(r);
    } finally {
      await r.release();
    }
    billing = new CommissionBillingService(db, new AuditLogService(db));
    generator = new CommissionStatementGenerator(billing);
    const files = Object.create(FilesService.prototype) as FilesService;
    payments = new CommissionPaymentsService(billing, files);
  }, 30000);
  afterAll(async () => {
    for (const connection of [...connections].reverse()) {
      if (connection === admin) await connection.query(`DROP SCHEMA "${schema}" CASCADE`);
      if (connection.isInitialized) await connection.destroy();
    }
  });
  beforeEach(async () => {
    await db.query(`TRUNCATE commission_billing_reminders,commission_payment_submissions,technician_commission_statement_items,technician_commission_statements,company_payment_methods,stored_files,service_order_offers,service_orders,technician_profiles,finance_admin_commands,admin_audit_logs,domain_event_outbox,user_notifications,staff_profiles,admin_roles,users CASCADE;
      INSERT INTO platform_commission_settings(id) VALUES(1) ON CONFLICT(id) DO UPDATE SET commission_bps=1000,review_sla_hours=12,version=1,updated_by=NULL;`);
    await db.query(
      `INSERT INTO users(id,display_name,email,role) VALUES($1,'فني','tech@test','technician'),($2,'فني تاني','other@test','technician'),($3,'أدمن','admin@test','admin');
      `,
      [tech, other, actor],
    );
    await db.query('INSERT INTO technician_profiles(user_id) VALUES($1),($2)', [tech, other]);
    await db.query(`INSERT INTO admin_roles(id,is_super_admin,permissions) VALUES($1,true,'{}')`, [
      actor,
    ]);
    await db.query(`INSERT INTO staff_profiles(user_id,role_id,permissions) VALUES($1,$1,'{}')`, [
      actor,
    ]);
    await db.query(
      `INSERT INTO company_payment_methods(id,method_type,label,account_value,account_holder) VALUES($1,'instapay','إنستاباي','company@instapay','الشركة')`,
      [method],
    );
    await db.query(
      `INSERT INTO stored_files(id,owner_id,purpose,status) VALUES($1,$2,'commission_payment_proof','ready')`,
      [file, tech],
    );
  });
  async function order(
    completed = '2026-08-31T23:30:00+03:00',
    amount = '1234',
    status = 'completed',
  ): Promise<string> {
    const id = randomUUID();
    await db.query(
      `INSERT INTO service_orders(id,technician_id,status,agreed_labor_minor,completed_at) VALUES($1,$2,$3,$4,$5)`,
      [id, tech, status, amount, completed],
    );
    return id;
  }
  async function statement(): Promise<BillingRow> {
    await order();
    await generator.generate('2026-08-01');
    const [s] = await db.query<BillingRow[]>(
      'SELECT * FROM technician_commission_statements WHERE technician_id=$1',
      [tech],
    );
    if (!s) throw new Error('Statement was not generated.');
    return s;
  }
  async function submit(id: string, key = randomUUID()): Promise<BillingRow> {
    return await payments.submit(tech, id, {
      paymentMethodId: method,
      proofFileId: file,
      idempotencyKey: key,
    });
  }
  it('migration up/down/up and no-debt function work', async () => {
    expect(await db.query('SELECT technician_billing_blocked($1) blocked', [tech])).toEqual([
      { blocked: false },
    ]);
  });
  it('uses Cairo month bounds, excludes idle techs and in-progress jobs, and generates only once', async () => {
    const last = await order();
    await order('2026-09-01T00:30:00+03:00', '500');
    await order('2026-08-20T12:00:00Z', '500', 'in_progress');
    expect(await generator.generate('2026-08-01')).toEqual({ generated: 1 });
    expect(await generator.generate('2026-08-01')).toEqual({ generated: 0 });
    const [s] = await db.query<BillingRow[]>('SELECT * FROM technician_commission_statements');
    expect(s).toMatchObject({
      orders_count: 1,
      labor_total_minor: '1234',
      amount_due_minor: '123',
      commission_bps: 1000,
    });
    expect(await db.query('SELECT order_id FROM technician_commission_statement_items')).toEqual([
      { order_id: last },
    ]);
    expect(
      (
        await db.query<Array<{ is_online: boolean }>>(
          'SELECT is_online FROM technician_profiles WHERE user_id=$1',
          [tech],
        )
      )[0]?.is_online,
    ).toBe(false);
    await expect(assertNotBillingBlocked(db.manager, tech)).rejects.toMatchObject({
      status: 403,
      response: { code: 'COMMISSION_PAYMENT_REQUIRED' },
    });
    expect((await billing.summary(tech)).blocked).toBe(true);
  });
  it('snapshots the rate and marks zero-rate statements paid', async () => {
    const s = await statement();
    await billing.updateSettings(actor, {
      commissionBps: 0,
      reviewSlaHours: 12,
      version: 1,
      idempotencyKey: randomUUID(),
    });
    expect((await billing.statement(String(s.id), tech)).commissionBps).toBe(1000);
    await order('2026-09-10T12:00:00Z');
    await generator.generate('2026-09-01');
    const [zero] = await db.query<BillingRow[]>(
      `SELECT * FROM technician_commission_statements WHERE period_month='2026-09-01'`,
    );
    expect(zero).toMatchObject({ amount_due_minor: '0', status: 'paid' });
    expect(zero?.paid_at).toBeInstanceOf(Date);
  });
  it('takes the server amount and replays submissions without duplicates, rejects another pending proof', async () => {
    const s = await statement();
    const key = randomUUID();
    const p = await submit(String(s.id), key);
    expect(p.amountMinor).toBe(123);
    expect((await submit(String(s.id), key)).id).toBe(p.id);
    await expect(submit(String(s.id))).rejects.toMatchObject({
      status: 409,
      response: { code: 'SUBMISSION_ALREADY_PENDING' },
    });
    expect((await billing.summary(tech)).state).toBe('under_review');
  });
  it('rejects a proof without reason (400) and an old review version (409)', async () => {
    const s = await statement();
    const p = await submit(String(s.id));
    await expect(
      payments.review(actor, String(p.id), {
        decision: 'reject',
        version: 1,
        idempotencyKey: randomUUID(),
      }),
    ).rejects.toMatchObject({ status: 400 });
    await expect(
      payments.review(actor, String(p.id), {
        decision: 'approve',
        version: 99,
        idempotencyKey: randomUUID(),
      }),
    ).rejects.toMatchObject({ status: 409 });
  });
  it('reject, resubmit, approve, retry review, and automatic unblock complete the lifecycle', async () => {
    const s = await statement();
    const first = await submit(String(s.id));
    await payments.review(actor, String(first.id), {
      decision: 'reject',
      reason: 'الصورة مش واضحة',
      version: 1,
      idempotencyKey: randomUUID(),
    });
    expect((await billing.summary(tech)).state).toBe('rejected');
    const second = await submit(String(s.id));
    const dto = { decision: 'approve' as const, version: 1, idempotencyKey: randomUUID() };
    const result = await payments.review(actor, String(second.id), dto);
    expect(result.status).toBe('approved');
    expect((await payments.review(actor, String(second.id), dto)).id).toBe(second.id);
    await expect(assertNotBillingBlocked(db.manager, tech)).resolves.toBeUndefined();
    expect((await billing.summary(tech)).state).toBe('clear');
    const [countRow] = await db.query<Array<{ count: string }>>(
      `SELECT count(*) FROM admin_audit_logs WHERE action='commission.submission.approve'`,
    );
    expect(countRow?.count).toBe('1');
  });
  it('denies another technician statement, another owner proof, and an inactive method', async () => {
    const s = await statement();
    await expect(billing.statement(String(s.id), other)).rejects.toMatchObject({ status: 404 });
    await expect(
      payments.submit(other, String(s.id), {
        paymentMethodId: method,
        proofFileId: file,
        idempotencyKey: randomUUID(),
      }),
    ).rejects.toMatchObject({ status: 404 });
    await db.query('UPDATE stored_files SET owner_id=$1 WHERE id=$2', [other, file]);
    await expect(submit(String(s.id))).rejects.toMatchObject({ status: 400 });
    await db.query('UPDATE stored_files SET owner_id=$1 WHERE id=$2', [tech, file]);
    await db.query('UPDATE company_payment_methods SET is_active=false WHERE id=$1', [method]);
    await expect(submit(String(s.id))).rejects.toMatchObject({ status: 400 });
  });
  it('waives debt with a reason and rejects stale settings updates', async () => {
    const s = await statement();
    await billing.waive(actor, String(s.id), {
      reason: 'إعفاء إداري',
      version: 1,
      idempotencyKey: randomUUID(),
    });
    expect((await billing.summary(tech)).blocked).toBe(false);
    await expect(
      billing.updateSettings(actor, {
        commissionBps: 2000,
        reviewSlaHours: 12,
        version: 99,
        idempotencyKey: randomUUID(),
      }),
    ).rejects.toMatchObject({ status: 409 });
  });
  it('enforces online, breaks, heartbeat, legacy accept/counter, v2 create/patch, customer assignment and feed', async () => {
    await statement();
    const config = new ConfigService({ dispatch: { v2Enabled: true } });
    const presence = new TechnicianPresenceService(db, config);
    const blocked = { status: 403, response: { code: 'COMMISSION_PAYMENT_REQUIRED' } };
    await expect(presence.update(tech, { online: true })).rejects.toMatchObject(blocked);
    await expect(presence.update(tech, { breakMinutes: 15 })).rejects.toMatchObject(blocked);
    await expect(presence.heartbeat(tech)).resolves.toHaveProperty('lastSeenAt');
    const offers = new OrderOffersService(db);
    await expect(offers.listTechnicianRequests(tech)).resolves.toEqual({
      data: [],
      billingBlocked: true,
    });
    await expect(offers.acceptByTechnician(tech, randomUUID())).rejects.toMatchObject(blocked);
    await expect(offers.counterOffer(tech, randomUUID(), '500')).rejects.toMatchObject(blocked);
    const active = await order('2026-08-10T12:00:00Z', '100', 'in_progress');
    const v2 = new OrderOffersService(db, config);
    const internals = v2 as unknown as {
      lockOrder: () => Promise<unknown>;
      assignOrder: (m: typeof db.manager, o: unknown, t: string, a: string) => Promise<void>;
    };
    vi.spyOn(internals, 'lockOrder').mockResolvedValue({ id: active, status: 'searching' });
    await expect(
      v2.createOffer(tech, active, { kind: 'accept', serviceLocation: 'customer_site' }),
    ).rejects.toMatchObject(blocked);
    const offer = randomUUID();
    await db.query(
      `INSERT INTO service_order_offers(id,order_id,technician_id,status) VALUES($1,$2,$3,'pending')`,
      [offer, active, tech],
    );
    await expect(v2.updateTechnicianOffer(tech, offer, { note: 'تعديل' })).rejects.toMatchObject(
      blocked,
    );
    await expect(
      db.transaction((m) => internals.assignOrder(m, { id: active }, tech, '100')),
    ).rejects.toMatchObject({ status: 409, response: { code: 'TECHNICIAN_UNAVAILABLE' } });
    expect(
      (
        await db.query<Array<{ status: string }>>('SELECT status FROM service_orders WHERE id=$1', [
          active,
        ])
      )[0]?.status,
    ).toBe('in_progress');
    expect(
      await db.query(
        'SELECT user_id FROM technician_profiles WHERE user_id=$1 AND NOT technician_billing_blocked(user_id)',
        [tech],
      ),
    ).toEqual([]);
  });
  it('sends each overdue debt and review SLA reminder exactly once', async () => {
    const s = await statement();
    await db.query(
      `UPDATE technician_commission_statements SET issued_at=now()-interval '25 hours' WHERE id=$1`,
      [s.id],
    );
    const reminders = generator as unknown as { reminders: () => Promise<void> };
    await reminders.reminders();
    await reminders.reminders();
    expect(
      (
        await db.query<Array<{ count: string }>>(
          `SELECT count(*)::text count FROM user_notifications WHERE type='billing.payment_reminder'`,
        )
      )[0]?.count,
    ).toBe('1');
    const p = await submit(String(s.id));
    await db.query(
      `UPDATE commission_payment_submissions SET review_due_at=now()+interval '1 hour' WHERE id=$1`,
      [p.id],
    );
    await reminders.reminders();
    await reminders.reminders();
    expect(
      (
        await db.query<Array<{ count: string }>>(
          `SELECT count(*)::text count FROM user_notifications WHERE type='billing.review_reminder'`,
        )
      )[0]?.count,
    ).toBe('1');
    expect((await billing.submissions({ limit: 30 })).pendingCount).toBe(1);
  });
  it('replays concurrent submissions and reviews with only one mutation and audit record', async () => {
    const s = await statement(),
      key = randomUUID();
    const [a, b] = await Promise.all([submit(String(s.id), key), submit(String(s.id), key)]);
    expect(a.id).toBe(b.id);
    const dto = { decision: 'approve' as const, version: 1, idempotencyKey: randomUUID() };
    const [x, y] = await Promise.all([
      payments.review(actor, String(a.id), dto),
      payments.review(actor, String(a.id), dto),
    ]);
    expect(x.id).toBe(y.id);
    expect(
      (
        await db.query<Array<{ count: string }>>(
          `SELECT count(*)::text count FROM admin_audit_logs WHERE action='commission.submission.approve'`,
        )
      )[0]?.count,
    ).toBe('1');
  });
  it('updates payment methods optimistically and keeps current-month estimates in minor units', async () => {
    const dto = {
      methodType: 'instapay',
      label: 'حساب جديد',
      accountValue: 'new@instapay',
      accountHolder: 'الشركة',
      isActive: true,
      sortOrder: 2,
      version: 1,
      idempotencyKey: randomUUID(),
    };
    const saved = await billing.upsertMethod(actor, method, dto);
    const createDto = { ...dto, idempotencyKey: randomUUID() };
    const [createdA, createdB] = await Promise.all([
      billing.upsertMethod(actor, createDto.idempotencyKey, createDto, true),
      billing.upsertMethod(actor, createDto.idempotencyKey, createDto, true),
    ]);
    expect(createdA.id).toBe(createdB.id);
    expect(createdA.id).not.toBe(createDto.idempotencyKey);
    expect(saved.version).toBe(2);
    expect((await billing.upsertMethod(actor, method, dto)).version).toBe(2);
    await expect(
      billing.upsertMethod(actor, method, { ...dto, idempotencyKey: randomUUID() }),
    ).rejects.toMatchObject({ status: 409 });
    await db.query(
      `INSERT INTO service_orders(id,technician_id,status,agreed_labor_minor,completed_at) VALUES($1,$2,'completed',1234,now())`,
      [randomUUID(), tech],
    );
    expect(await billing.currentMonth(tech)).toMatchObject({
      ordersCount: 1,
      laborTotalMinor: 1234,
      estimatedCommissionMinor: 123,
    });
  });
  it('recovers the previous month on the hourly sweep without duplicate statements', async () => {
    await db.query(
      `INSERT INTO service_orders(id,technician_id,status,agreed_labor_minor,completed_at)
      VALUES($1,$2,'completed',10000,(date_trunc('month',now() AT TIME ZONE 'Africa/Cairo')-interval '1 day') AT TIME ZONE 'Africa/Cairo')`,
      [randomUUID(), tech],
    );
    await generator.sweep();
    await generator.sweep();
    expect(
      (
        await db.query<Array<{ count: string }>>(
          'SELECT count(*)::text count FROM technician_commission_statements',
        )
      )[0]?.count,
    ).toBe('1');
  });
  it('three completed jobs, rejection, replacement proof and approval restore online immediately', async () => {
    for (const amount of ['10000', '20000', '30000']) await order('2026-08-20T12:00:00Z', amount);
    await generator.generate('2026-08-01');
    const [s] = await db.query<BillingRow[]>(
      'SELECT * FROM technician_commission_statements WHERE technician_id=$1',
      [tech],
    );
    if (!s) throw new Error('Missing statement');
    expect(s.amount_due_minor).toBe('6000');
    const presence = new TechnicianPresenceService(
      db,
      new ConfigService({ dispatch: { v2Enabled: true } }),
    );
    await expect(presence.update(tech, { online: true })).rejects.toMatchObject({ status: 403 });
    const a = await submit(String(s.id));
    await payments.review(actor, String(a.id), {
      decision: 'reject',
      reason: 'الصورة مش واضحة',
      version: 1,
      idempotencyKey: randomUUID(),
    });
    const b = await submit(String(s.id));
    await payments.review(actor, String(b.id), {
      decision: 'approve',
      version: 1,
      idempotencyKey: randomUUID(),
    });
    await expect(presence.update(tech, { online: true })).resolves.toMatchObject({ online: true });
  });
  it('waives a statement under review and closes its pending proof atomically', async () => {
    const s = await statement(),
      p = await submit(String(s.id));
    const dto = { reason: 'إعفاء إداري', version: 2, idempotencyKey: randomUUID() };
    expect((await billing.waive(actor, String(s.id), dto)).status).toBe('waived');
    expect((await billing.waive(actor, String(s.id), dto)).status).toBe('waived');
    const [proof] = await db.query<BillingRow[]>(
      'SELECT * FROM commission_payment_submissions WHERE id=$1',
      [p.id],
    );
    expect(proof).toMatchObject({ status: 'rejected', version: 2 });
    expect((await billing.summary(tech)).blocked).toBe(false);
  });
});import 'package:fixit_pro/features/admin/data/services/admin_finance_api.dart';
import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';

abstract interface class AdminFinanceRepository {
  Future<AdminTransactionsPage> listTransactions({
    String? status,
    String? method,
    String? cursor,
  });
  Future<AdminFinancePage<PayoutRequestEntity>> listPayouts();
  Future<PayoutRequestEntity> reviewPayout({
    required PayoutRequestEntity payout,
    required String decision,
    required String idempotencyKey,
    String? reason,
  });
  Future<AdminFinancePage<RefundRequestEntity>> listRefunds();
  Future<RefundRequestEntity> executeRefund({
    required RefundRequestEntity refund,
    required String idempotencyKey,
  });
  Future<AdminFinancePage<PaymentDisputeEntity>> listDisputes();
  Future<PaymentDisputeEntity> resolveDispute({
    required PaymentDisputeEntity dispute,
    required String resolution,
    required String idempotencyKey,
  });
  Future<AdminFinancePage<PaymentInvoiceEntity>> listInvoices();
  Future<CommissionSummaryEntity> getCommissions();
}

abstract interface class AdminCommissionBillingRepository {
  Future<CommissionBillingSettingsEntity> commissionSettings();
  Future<void> updateCommissionSettings(Map<String, Object?> body);
  Future<AdminFinancePage<AdminCommissionRecord>> commissionPage(
    String resource, {
    String? status,
    String? cursor,
    String? periodMonth,
  });
  Future<AdminCommissionRecord> commissionDetail(String id);
  Future<AdminCommissionRecord> commissionCommand(
    String resource,
    Map<String, Object?> body, {
    bool create = false,
  });
  Future<void> generateCommissionStatements(Map<String, Object?> body);
}

class HttpAdminFinanceRepository
    implements AdminFinanceRepository, AdminCommissionBillingRepository {
  HttpAdminFinanceRepository([AdminFinanceApi? api])
    : _api = api ?? AdminFinanceApi.standard();
  final AdminFinanceApi _api;

  @override
  Future<AdminTransactionsPage> listTransactions({
    String? status,
    String? method,
    String? cursor,
  }) => _api.listTransactions(status: status, method: method, cursor: cursor);
  @override
  Future<AdminFinancePage<PayoutRequestEntity>> listPayouts() =>
      _api.listPayouts();
  @override
  Future<PayoutRequestEntity> reviewPayout({
    required PayoutRequestEntity payout,
    required String decision,
    required String idempotencyKey,
    String? reason,
  }) => _api.reviewPayout(
    payout: payout,
    decision: decision,
    idempotencyKey: idempotencyKey,
    reason: reason,
  );
  @override
