import 'package:fixit_pro/app/configuration/app_config.dart';
import 'package:fixit_pro/core/networking/backend_http_client.dart';
import 'package:fixit_pro/core/storage/secure/auth_session_store.dart';
import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';
import 'package:http/http.dart' as http;

class AdminFinanceApiException implements Exception {
  const AdminFinanceApiException(this.message, {this.statusCode});
  final String message;
  final int? statusCode;
  @override
  String toString() => message;
}

class AdminFinancePage<T> {
  const AdminFinancePage({
    required this.items,
    required this.nextCursor,
    this.totalCount,
  });
  final List<T> items;
  final String? nextCursor;
  final int? totalCount;
}

class AdminTransactionsPage extends AdminFinancePage<AdminTransactionEntity> {
  const AdminTransactionsPage({
    required super.items,
    required super.nextCursor,
    required this.summary,
  });
  final FinanceTransactionSummary summary;
}

class AdminFinanceApi {
  AdminFinanceApi({
    required Uri baseUri,
    required AuthSessionStore sessionStore,
    http.Client? client,
  }) : _baseUri = baseUri,
       _sessionStore = sessionStore,
       _client = client ?? BackendHttpClient();

  factory AdminFinanceApi.standard({
    Uri? baseUri,
    AuthSessionStore? sessionStore,
    http.Client? client,
  }) => AdminFinanceApi(
    baseUri: baseUri ?? AppConfig.fromEnvironment().backendBaseUri,
    sessionStore: sessionStore ?? SecureAuthSessionStore(),
    client: client,
  );

  final Uri _baseUri;
  final AuthSessionStore _sessionStore;
  final http.Client _client;

  Future<AdminTransactionsPage> listTransactions({
    int limit = 100,
    String? status,
    String? method,
    String? cursor,
  }) async {
    final json = await _request(
      'GET',
      '/v1/admin/finance/transactions',
      query: {
        'limit': '$limit',
        'status': ?status,
        'method': ?method,
        'cursor': ?cursor,
      },
    );
    return AdminTransactionsPage(
      items: _items(json, AdminTransactionEntity.fromJson),
      nextCursor: _cursor(json),
      summary: FinanceTransactionSummary.fromJson(
        Json.from(json.value['summary']),
      ),
    );
  }

  Future<AdminFinancePage<PayoutRequestEntity>> listPayouts() =>
      _list('/v1/admin/finance/payouts', PayoutRequestEntity.fromJson);

  Future<PayoutRequestEntity> reviewPayout({
    required PayoutRequestEntity payout,
    required String decision,
    required String idempotencyKey,
    String? reason,
  }) async => PayoutRequestEntity.fromJson(
    await _request(
      'PATCH',
      '/v1/admin/finance/payouts/${payout.id}/review',
      body: {
        'decision': decision,
        'version': payout.version,
        'idempotencyKey': idempotencyKey,
        'reason': ?reason,
      },
    ),
  );

  Future<AdminFinancePage<RefundRequestEntity>> listRefunds() =>
      _list('/v1/admin/finance/refunds', RefundRequestEntity.fromJson);

  Future<RefundRequestEntity> executeRefund({
    required RefundRequestEntity refund,
    required String idempotencyKey,
  }) async => RefundRequestEntity.fromJson(
    await _request(
      'POST',
      '/v1/admin/finance/refunds/${refund.id}/execute',
      body: {'version': refund.version, 'idempotencyKey': idempotencyKey},
    ),
  );

  Future<AdminFinancePage<PaymentDisputeEntity>> listDisputes() =>
      _list('/v1/admin/finance/disputes', PaymentDisputeEntity.fromJson);

  Future<PaymentDisputeEntity> resolveDispute({
    required PaymentDisputeEntity dispute,
    required String resolution,
    required String idempotencyKey,
    String? note,
  }) async => PaymentDisputeEntity.fromJson(
    await _request(
      'PATCH',
      '/v1/admin/finance/disputes/${dispute.id}/resolve',
      body: {
        'resolution': resolution,
        'version': dispute.version,
        'idempotencyKey': idempotencyKey,
        'note': ?note,
      },
    ),
  );

  Future<AdminFinancePage<PaymentInvoiceEntity>> listInvoices() =>
      _list('/v1/admin/finance/invoices', PaymentInvoiceEntity.fromJson);

  Future<CommissionSummaryEntity> getCommissions() async =>
      CommissionSummaryEntity.fromJson(
        await _request('GET', '/v1/admin/finance/commissions'),
      );

  Future<AdminFinancePage<T>> _list<T>(
    String path,
    T Function(Json) mapper,
  ) async {
    final json = await _request('GET', path, query: const {'limit': '100'});
    return AdminFinancePage(
      items: _items(json, mapper),
      nextCursor: _cursor(json),
    );
  }

  List<T> _items<T>(Json json, T Function(Json) mapper) => json
      .list('items')
      .map((item) => mapper(Json.from(item)))
      .toList(growable: false);

  String? _cursor(Json json) => json.nullableString('nextCursor');

  Future<Json> _request(
    String method,
    String path, {
    Map<String, String>? query,
    Map<String, Object?>? body,
  }) async {
    final session = await _sessionStore.readSession();
    if (session == null) {
      throw const AdminFinanceApiException(
        'انتهت جلسة الدخول.',
        statusCode: 401,
      );
    }
    final uri = _baseUri.replace(path: path, queryParameters: query);
    final headers = {
      'accept': 'application/json',
      'authorization': 'Bearer ${session.accessToken}',
      if (body != null) 'content-type': 'application/json',
    };
    late http.Response response;
    try {
      response = switch (method) {
        'GET' => await _client.get(uri, headers: headers),
        'POST' => await _client.post(
          uri,
          headers: headers,
          body: jsonEncode(body),
        ),
        'PATCH' => await _client.patch(
          uri,
          headers: headers,
          body: jsonEncode(body),
        ),
        _ => throw StateError('Unsupported method'),
      };
    } on http.ClientException {
      throw const AdminFinanceApiException(
        'تعذر الاتصال بالخادم. حاول مرة أخرى.',
      );
    }
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw AdminFinanceApiException(switch (response.statusCode) {
        400 => 'بيانات العملية المالية غير صالحة.',
        401 => 'انتهت جلسة الدخول.',
        403 => 'ليست لديك صلاحية إدارة المدفوعات.',
        404 => 'لم يعد السجل المالي موجودًا.',
        409 => 'تم تحديث السجل بواسطة مسؤول آخر. حدّث الصفحة.',
        _ => 'تعذر إتمام العملية المالية حاليًا.',
      }, statusCode: response.statusCode);
    }
    try {
      return Json.from(jsonDecode(utf8.decode(response.bodyBytes)));
    } on Object {
      throw const AdminFinanceApiException('استجابة الخادم غير صالحة.');
    }
  }

  static const _billing = '/v1/admin/finance/commission-billing';
  Future<CommissionBillingSettingsEntity> commissionSettings() async =>
      CommissionBillingSettingsEntity.fromJson(
        await _request('GET', '$_billing/settings'),
      );
  Future<void> updateCommissionSettings(Map<String, Object?> body) async {
    await _request('PATCH', '$_billing/settings', body: body);
  }

  Future<AdminFinancePage<AdminCommissionRecord>> commissionPage(
    String resource, {
    String? status,
    String? cursor,
    String? periodMonth,
  }) async {
    final j = await _request(
      'GET',
      '$_billing/$resource',
      query: {
        'limit': '50',
        'status': ?status,
        'cursor': ?cursor,
        'periodMonth': ?periodMonth,
      },
    );
    return AdminFinancePage(
      items: _items(j, AdminCommissionRecord.fromJson),
      nextCursor: _cursor(j),
      totalCount: j.value['pendingCount'] as int?,
    );
  }

  Future<AdminCommissionRecord> commissionDetail(String id) async =>
      AdminCommissionRecord.fromJson(
        await _request('GET', '$_billing/submissions/$id'),
      );
  Future<AdminCommissionRecord> commissionCommand(
    String resource,
    Map<String, Object?> body, {
    bool create = false,
  }) async => AdminCommissionRecord.fromJson(
    await _request(
      create ? 'POST' : 'PATCH',
      '$_billing/$resource',
      body: body,
    ),
  );
  Future<void> generateCommissionStatements(Map<String, Object?> body) async {
    await _request('POST', '$_billing/statements/generate', body: body);
  }

  void dispose() => _client.close();
}import 'package:fixit_pro/app/theme/colors/app_colors.dart';
