enum PaymentMethodType {
  visa('Visa', AppColors.v2PrimaryDark, Colors.white),
  mastercard('Mastercard', Color(0xFFEB001B), Colors.white),
  wallet('محفظة إلكترونية', Color(0xFFFEF3C7), Color(0xFFB45309)),
  cash('نقدي (كاش)', Color(0xFFDCF5EC), Color(0xFF0E7C5E)),
  fawry('فوري Fawry', Color(0xFFFFEDD5), Color(0xFFEA580C)),
  instapay('InstaPay', AppColors.infoSurface, AppColors.info);

  const PaymentMethodType(this.label, this.bgColor, this.fgColor);
  final String label;
  final Color bgColor;
  final Color fgColor;

  static PaymentMethodType fromApi(String value) => values.firstWhere(
    (item) => item.name == value,
    orElse: () => throw FormatException('Unknown payment method: $value'),
  );
}

enum TransactionStatus {
  success('ناجحة', Color(0xFFDCF5EC), Color(0xFF0E7C5E)),
  failed('فاشلة', Color(0xFFFEE2E2), Color(0xFFDC2626)),
  pending('معلقة', Color(0xFFFEF3C7), Color(0xFFB45309)),
  refunded('مستردة', Color(0xFFEDE9FE), Color(0xFF7E22CE)),
  partiallyRefunded('مستردة جزئيًا', Color(0xFFEDE9FE), Color(0xFF7E22CE));

  const TransactionStatus(this.label, this.bgColor, this.fgColor);
  final String label;
  final Color bgColor;
  final Color fgColor;

  static TransactionStatus fromApi(String value) => switch (value) {
    'success' => success,
    'failed' => failed,
    'pending' => pending,
    'refunded' => refunded,
    'partially_refunded' => partiallyRefunded,
    _ => throw FormatException('Unknown transaction status: $value'),
  };
}

