String formatMinorAmount(int amountMinor, {String currency = 'EGP'}) {
  final whole = amountMinor ~/ 100;
  final fraction = amountMinor.remainder(100).toString().padLeft(2, '0');
  final amount = fraction == '00' ? '$whole' : '$whole.$fraction';
  return '$amount ${currency == 'EGP' ? 'ج.م' : currency}';
}

String _displayDate(DateTime value) {
  final local = value.toLocal();
  String two(int number) => number.toString().padLeft(2, '0');
  return '${local.year}/${two(local.month)}/${two(local.day)} ${two(local.hour)}:${two(local.minute)}';
}

