class Json {
  const Json(this.value);
  factory Json.from(Object? value) {
    if (value is! Map) throw const FormatException('Expected object');
    return Json(Map<String, Object?>.from(value));
  }
  final Map<String, Object?> value;

  String string(String key) {
    final item = value[key];
    if (item is! String || item.isEmpty) throw FormatException('Invalid $key');
    return item;
  }

  String? nullableString(String key) {
    final item = value[key];
    if (item == null) return null;
    if (item is! String || item.isEmpty) throw FormatException('Invalid $key');
    return item;
  }

  int integer(String key) {
    final item = value[key];
    if (item is! int || item < 0) throw FormatException('Invalid $key');
    return item;
  }

  int positiveInteger(String key) {
    final item = integer(key);
    if (item == 0) throw FormatException('Invalid $key');
    return item;
  }

  List<Object?> list(String key) {
    final item = value[key];
    if (item is! List) throw FormatException('Invalid $key');
    return item;
  }

  DateTime date(String key) {
    final item = DateTime.tryParse(string(key));
    if (item == null) throw FormatException('Invalid $key');
    return item.toLocal();
  }

  DateTime? nullableDate(String key) => value[key] == null ? null : date(key);
}import 'dart:async';
