  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    if (widget.repository == null && _repo is HttpAdminFinanceRepository)
      _repo.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final s = await _repo.commissionSettings();
      if (mounted)
        setState(() {
          _settings = s;
          _error = null;
        });
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    }
  }

  Future<void> _edit() async {
    final s = _settings;
    if (s == null || _busy) return;
    double bps = s.commissionBps.toDouble();
    final input = TextEditingController(text: '${bps / 100}');
    final sla = TextEditingController(text: '${s.reviewSlaHours}');
    final result = await showDialog<(int, int)>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, set) => AlertDialog(
          title: const Text('نسبة عمولة الفنيين'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Slider(
                  value: bps,
                  min: 0,
                  max: 5000,
                  divisions: 500,
                  label: '${bps / 100}٪',
                  onChanged: (v) => set(() {
                    bps = v;
                    input.text = '${v / 100}';
                  }),
                ),
                TextField(
                  controller: input,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: const InputDecoration(
                    labelText: 'النسبة من ٠ إلى ٥٠٪',
                  ),
                  onChanged: (v) {
                    final p = double.tryParse(v);
                    if (p != null && p >= 0 && p <= 50)
                      set(() => bps = p * 100);
                  },
                ),
                TextField(
                  controller: sla,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'مدة المراجعة بالساعات (١–١٦٨)',
                  ),
                ),
                const SizedBox(height: 16),
                const Text('التغيير هيسري على كشوف الشهور الجاية بس'),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () {
                final p = double.tryParse(input.text),
                    h = int.tryParse(sla.text);
                if (p != null &&
                    p >= 0 &&
                    p <= 50 &&
                    h != null &&
                    h >= 1 &&
                    h <= 168)
                  Navigator.pop(ctx, ((p * 100).round(), h));
              },
              child: const Text('حفظ'),
            ),
          ],
        ),
      ),
    );
    input.dispose();
    sla.dispose();
    if (result == null || !mounted) return;
    setState(() => _busy = true);
    try {
      await _repo.updateCommissionSettings({
        'commissionBps': result.$1,
        'reviewSlaHours': result.$2,
        'version': s.version,
        'idempotencyKey': _key ??= const Uuid().v4(),
      });
      _key = null;
      await _load();
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) => Card(
    child: ListTile(
      title: const Text('نسبة عمولة الفنيين'),
      subtitle: Text(
        _error ??
            (_settings == null
                ? 'جاري التحميل…'
                : '${billingDigits('${_settings!.commissionBps / 100}')}٪ · المراجعة خلال ${billingDigits('${_settings!.reviewSlaHours}')} ساعة'),
      ),
      trailing: _busy
          ? const CircularProgressIndicator()
          : TextButton(
              onPressed: _settings == null ? _load : _edit,
              child: Text(_settings == null ? 'إعادة المحاولة' : 'تعديل'),
            ),
    ),
  );
}

class CommissionAdminLinks extends StatefulWidget {
  const CommissionAdminLinks({super.key});
  @override
  State<CommissionAdminLinks> createState() => _CommissionAdminLinksState();
}

class _CommissionAdminLinksState extends State<CommissionAdminLinks> {
  final _repo = HttpAdminFinanceRepository();
  int? _pending;
  Timer? _timer;
  @override
  void initState() {
    super.initState();
    _load();
    _timer = Timer.periodic(const Duration(minutes: 1), (_) => _load());
  }

  Future<void> _load() async {
    try {
      final page = await _repo.commissionPage('submissions', status: 'pending');
      if (mounted)
        setState(() => _pending = page.totalCount ?? page.items.length);
    } catch (_) {}
  }

  @override
  void dispose() {
    _timer?.cancel();
    _repo.dispose();
    super.dispose();
  }

  Future<void> _open(String route) async {
    await Navigator.of(context).pushNamed(route);
    if (mounted) _load();
  }

  @override
  Widget build(BuildContext context) => Column(
    children: [
      ListTile(
        leading: const Icon(Icons.account_balance_outlined),
        title: const Text('طرق دفع الشركة'),
        onTap: () => _open(AppRoutes.adminCompanyMethods),
      ),
      ListTile(
        leading: const Icon(Icons.fact_check_outlined),
        title: const Text('إثباتات دفع العمولة'),
        trailing: Badge(
          isLabelVisible: (_pending ?? 0) > 0,
          label: Text('$_pending'),
          child: const Icon(Icons.chevron_left),
        ),
        onTap: () => _open(AppRoutes.adminCommissionProofs),
      ),
      ListTile(
        leading: const Icon(Icons.receipt_long_outlined),
        title: const Text('كشوف عمولة الفنيين'),
        onTap: () => _open(AppRoutes.adminCommissionStatements),
      ),
    ],
  );
}

Future<String?> commissionReason(
  BuildContext context, {
  bool reject = false,
}) async {
  final controller = TextEditingController();
  final result = await showDialog<String>(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, set) => AlertDialog(
        title: Text(reject ? 'سبب رفض التحويل' : 'سبب الإعفاء'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (reject)
                Wrap(
                  spacing: 8,
                  children:
                      const [
                            'الصورة مش واضحة',
                            'المبلغ مش مطابق',
                            'التحويل مش ظاهر عندنا',
                            'اتحول على رقم غلط',
                          ]
                          .map(
                            (s) => ActionChip(
                              label: Text(s),
                              onPressed: () => set(() => controller.text = s),
                            ),
                          )
                          .toList(),
                ),
              TextField(
                controller: controller,
                maxLength: 500,
                maxLines: 3,
                decoration: const InputDecoration(labelText: 'السبب (إجباري)'),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('إلغاء'),
          ),
          FilledButton(
            onPressed: () {
              if (controller.text.trim().isNotEmpty)
                Navigator.pop(ctx, controller.text.trim());
            },
            child: const Text('تأكيد'),
          ),
        ],
      ),
    ),
  );
  controller.dispose();
  return result;
