  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final page = await _repository.listTransactions();
      if (!mounted) return;
      setState(() {
        _transactions = page.items;
        _summary = page.summary;
        _loading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
