  List<AdminTransactionEntity> get _filteredTransactions {
    return _transactions.where((tx) {
      if (_selectedTab == 'success' && tx.status != TransactionStatus.success) {
        return false;
      }
      if (_selectedTab == 'failed' && tx.status != TransactionStatus.failed) {
        return false;
      }
      if (_selectedTab == 'cash' && tx.method != PaymentMethodType.cash) {
        return false;
      }
      return true;
    }).toList();
  }

