          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'المدفوعات والمعاملات المالية',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w900,
                color: V2Colors.ink,
              ),
            ),
            Text(
              'سجل المدفوعات والفواتير والتحصيلات',
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: V2Colors.inkLight,
              ),
            ),
          ],
        ),
        actions: [
          IconButton(
            tooltip: 'تصدير كشف حساب',
            onPressed: () {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('تم تصدير ملف المعاملات المالية Excel بنجاح'),
                ),
              );
            },
            icon: const Icon(Icons.download_rounded, color: V2Colors.primary),
          ),
        ],
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _error != null
          ? Center(
              child: TextButton.icon(
                onPressed: _load,
                icon: const Icon(Icons.refresh_rounded),
                label: Text(_error!),
              ),
            )
          : ListView(
              padding: const EdgeInsets.all(16),
