  Widget _buildFinanceKpi(
    String label,
    String val,
    String delta,
    Color color,
    IconData icon,
  ) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: V2Colors.surface,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: V2Colors.border),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Icon(icon, color: color, size: 20),
                Text(
                  delta,
                  style: TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    color: color,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              label,
              style: const TextStyle(
                fontSize: 10.5,
                color: V2Colors.inkLight,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 2),
            Text(
              val,
              style: const TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w900,
                color: V2Colors.ink,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildBar(double heightFactor, String day, {bool isHighest = false}) {
    // Scale to max 60px so bar + spacing + label fit within 80px parent
    final barHeight = heightFactor * 0.7;
    return Column(
      mainAxisAlignment: MainAxisAlignment.end,
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: 24,
          height: barHeight,
          decoration: BoxDecoration(
            color: isHighest
                ? V2Colors.primary
                : V2Colors.primary.withValues(alpha: 0.35),
            borderRadius: BorderRadius.circular(6),
          ),
        ),
        const SizedBox(height: 4),
        Text(
          day,
          style: const TextStyle(
            fontSize: 10,
            color: V2Colors.inkLight,
            fontWeight: FontWeight.w700,
          ),
        ),
      ],
    );
  }

  List<Widget> _buildDailyBars() {
    final days = _summary.dailyAmountMinor;
    if (days.isEmpty) {
      return List.generate(7, (index) => _buildBar(10, '—'));
    }
    final maxAmount = days
        .map((item) => item.amountMinor)
        .fold<int>(0, (maximum, value) => value > maximum ? value : maximum);
    const labels = ['ح', 'ن', 'ث', 'ر', 'خ', 'ج', 'س'];
    return List.generate(days.length, (index) {
      final amount = days[index].amountMinor;
      final height = maxAmount == 0 ? 10.0 : 10 + (amount / maxAmount * 70);
      return _buildBar(
        height,
        labels[days[index].date.weekday % 7],
        isHighest: maxAmount > 0 && amount == maxAmount,
      );
    });
  }

  Widget _buildTab(String label, String id) {
    final isSelected = _selectedTab == id;
    return Expanded(
      child: InkWell(
        onTap: () => setState(() => _selectedTab = id),
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 8),
          decoration: BoxDecoration(
            color: isSelected ? V2Colors.surface : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Center(
            child: Text(
              label,
              style: TextStyle(
                fontSize: 11.5,
                fontWeight: isSelected ? FontWeight.w900 : FontWeight.w600,
                color: isSelected ? V2Colors.ink : V2Colors.inkMuted,
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildTxTile(AdminTransactionEntity tx) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: V2Colors.surface,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: V2Colors.border),
      ),
      child: Row(
        children: [
          Container(
            width: 40,
            height: 40,
            decoration: BoxDecoration(
              color: tx.method.bgColor,
              borderRadius: BorderRadius.circular(10),
            ),
            child: Center(
              child: Text(
                tx.method == PaymentMethodType.visa
                    ? 'VISA'
                    : tx.method == PaymentMethodType.mastercard
                    ? 'MC'
                    : tx.method == PaymentMethodType.instapay
                    ? 'IP'
                    : '💵',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w900,
                  color: tx.method.fgColor,
                ),
              ),
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Text(
                      tx.customerName,
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                        color: V2Colors.ink,
                      ),
                    ),
                    const SizedBox(width: 6),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 6,
                        vertical: 2,
                      ),
                      decoration: BoxDecoration(
                        color: tx.status.bgColor,
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: Text(
                        tx.status.label,
                        style: TextStyle(
                          fontSize: 9.5,
                          fontWeight: FontWeight.w800,
                          color: tx.status.fgColor,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 2),
                Text(
                  '${tx.serviceName} · ${tx.timeAgo}',
                  style: const TextStyle(
                    fontSize: 10.5,
                    color: V2Colors.inkLight,
                  ),
                ),
              ],
            ),
          ),
          Text(
            '${toArabicDigits(tx.amount)} ج.م',
            style: const TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w900,
              color: V2Colors.ink,
            ),
          ),
        ],
      ),
    );
  }
