class PayCommissionProofsPage extends StatefulWidget {
  const PayCommissionProofsPage({super.key});
  @override
  State<PayCommissionProofsPage> createState() =>
      _PayCommissionProofsPageState();
}

class _PayCommissionProofsPageState extends State<PayCommissionProofsPage> {
  final _repo = HttpAdminFinanceRepository();
  final Map<String, String> _idempotencyKeys = {};
  List<AdminCommissionRecord> _items = [];
  String _status = 'pending';
  String? _cursor, _error;
  bool _loading = true;
  Timer? _timer;
  int _generation = 0;
  @override
  void initState() {
    super.initState();
    _load();
    _timer = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    _repo.dispose();
    super.dispose();
  }

  Future<void> _load({bool more = false}) async {
    final generation = ++_generation;
    setState(() => _loading = true);
    try {
      final page = await _repo.commissionPage(
        'submissions',
        status: _status,
        cursor: more ? _cursor : null,
      );
      if (mounted && generation == _generation)
        setState(() {
          _items = more ? [..._items, ...page.items] : page.items;
          _cursor = page.nextCursor;
          _error = null;
        });
    } catch (e) {
      if (mounted && generation == _generation)
        setState(() => _error = e.toString());
    } finally {
      if (mounted && generation == _generation)
        setState(() => _loading = false);
    }
  }

  Future<void> _detail(AdminCommissionRecord item) async {
    try {
      final detail = await _repo.commissionDetail(item.id);
      if (!mounted) return;
      final d = detail.data;
      final proof = d['proof'] as Map;
      bool busy = false;
      String? error;
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        showDragHandle: true,
        builder: (ctx) => StatefulBuilder(
          builder: (ctx, set) => FractionallySizedBox(
            heightFactor: .9,
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    d['technicianName']?.toString() ?? 'الفني',
                    style: Theme.of(ctx).textTheme.titleLarge,
                  ),
                  Text(
                    '${d['technicianPhone'] ?? ''} · ${billingMoney(d['amountMinor'] as int)}',
                  ),
                  Expanded(
                    child: GestureDetector(
                      onTap: () => Navigator.of(ctx).push(
                        MaterialPageRoute<void>(
                          builder: (_) => Scaffold(
                            backgroundColor: Colors.black,
                            appBar: AppBar(
                              title: const Text('صورة إثبات التحويل'),
                            ),
                            body: Center(
                              child: InteractiveViewer(
                                minScale: .5,
                                maxScale: 6,
                                child: Image.network(
                                  proof['url'] as String,
                                  errorBuilder: (_, _, _) => const Text(
                                    'تعذر تحميل الصورة. افتح التفاصيل تاني لتجديد الرابط.',
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                      child: InteractiveViewer(
                        minScale: .5,
                        maxScale: 5,
                        child: Image.network(
                          proof['url'] as String,
                          fit: BoxFit.contain,
                          errorBuilder: (_, _, _) => const Center(
                            child: Text(
                              'تعذر تحميل الصورة. افتح التفاصيل تاني.',
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                  Text('الحساب المطلوب التحويل عليه: ${d['label']}'),
                  SelectableText(
                    '${d['accountValue']} · ${d['accountHolder']}',
                  ),
                  Text(
                    'حساب المرسل: ${d['senderAccount'] ?? 'غير مذكور'}\nرقم العملية: ${d['transferReference'] ?? 'غير مذكور'}\n${d['note'] ?? ''}',
                  ),
                  if (error != null)
                    Text(
                      error!,
                      style: TextStyle(color: Theme.of(ctx).colorScheme.error),
                    ),
                  if (detail.status == 'pending')
                    Wrap(
                      spacing: 12,
                      children: [
                        for (final decision in ['approve', 'reject'])
                          FilledButton.tonal(
                            onPressed: busy
                                ? null
                                : () async {
                                    final reason = decision == 'reject'
                                        ? await commissionReason(
                                            ctx,
                                            reject: true,
                                          )
                                        : null;
                                    if (decision == 'reject' && reason == null)
                                      return;
                                    set(() => busy = true);
                                    try {
                                      await _repo.commissionCommand(
                                        'submissions/${detail.id}/review',
                                        {
                                          'decision': decision,
                                          'reason': ?reason,
                                          'version': detail.version,
                                          'idempotencyKey': _idempotencyKeys
                                              .putIfAbsent(
                                                '${detail.id}:$decision',
                                                () => const Uuid().v4(),
                                              ),
                                        },
                                      );
                                      _idempotencyKeys.remove(
                                        '${detail.id}:$decision',
                                      );
                                      if (ctx.mounted) Navigator.pop(ctx);
                                      await _load();
                                    } catch (e) {
                                      if (ctx.mounted)
                                        set(() {
                                          busy = false;
                                          error = e.toString();
                                        });
                                    }
                                  },
                            child: Text(
                              decision == 'approve' ? 'تأكيد الدفع' : 'رفض',
                            ),
                          ),
                      ],
                    ),
                ],
              ),
            ),
          ),
        ),
      );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(e.toString())));
    }
  }

  @override
  Widget build(BuildContext context) => DefaultTabController(
    length: 3,
    child: Scaffold(
      appBar: AppBar(
        title: const Text('إثباتات دفع العمولة'),
        bottom: TabBar(
          onTap: (i) {
            _status = ['pending', 'approved', 'rejected'][i];
            _items = [];
            _cursor = null;
            _load();
          },
          tabs: const [
            Tab(text: 'قيد المراجعة'),
            Tab(text: 'اتأكد'),
            Tab(text: 'مرفوض'),
          ],
        ),
      ),
      body: RefreshIndicator(
        onRefresh: () => _load(),
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            if (_error != null)
              TextButton(onPressed: () => _load(), child: Text(_error!)),
            if (!_loading && _items.isEmpty)
              const Padding(
                padding: EdgeInsets.all(32),
                child: Text('مفيش إثباتات في الحالة دي.'),
              ),
            for (final p in _items)
              Card(
                child: ListTile(
                  onTap: () => _detail(p),
                  title: Text(p.data['technicianName']?.toString() ?? 'الفني'),
                  subtitle: Text(
                    '${p.data['technicianPhone'] ?? ''}\n${billingMoney(p.data['amountMinor'] as int)} · ${p.data['paymentMethodLabel'] ?? ''}\nوقت الرفع: ${billingDate(p.data['createdAt'])}\n${_sla(p)}',
                  ),
                  isThreeLine: true,
                  trailing: const Icon(Icons.chevron_left),
                ),
              ),
            if (_loading) const Center(child: CircularProgressIndicator()),
            if (_cursor != null && !_loading)
              TextButton(
                onPressed: () => _load(more: true),
                child: const Text('عرض المزيد'),
              ),
          ],
        ),
      ),
    ),
  );
  String _sla(AdminCommissionRecord p) {
    if (p.status != 'pending') return billingStateLabel(p.status);
    final remaining = DateTime.parse(
      p.data['reviewDueAt'] as String,
    ).difference(DateTime.now());
    return remaining.isNegative
        ? 'متأخر عن ميعاد المراجعة'
        : 'فاضل ${billingDigits('${remaining.inHours}')} ساعة و${billingDigits('${remaining.inMinutes % 60}')} دقيقة';
  }
}import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import 'package:fixit_pro/features/admin/data/repositories/admin_finance_repository.dart';
import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';
import 'package:fixit_pro/features/technician-billing/presentation/widgets/billing_status_banner.dart';
import 'commission_billing_widgets.dart';

class PayCommissionStatementsPage extends StatefulWidget {
  const PayCommissionStatementsPage({super.key});
  @override
  State<PayCommissionStatementsPage> createState() =>
      _PayCommissionStatementsPageState();
}

class _PayCommissionStatementsPageState
    extends State<PayCommissionStatementsPage> {
  final _repo = HttpAdminFinanceRepository();
  final _month = TextEditingController();
  final Map<String, String> _idempotencyKeys = {};
  List<AdminCommissionRecord> _items = [];
  String? _status, _period, _cursor, _error;
  bool _loading = true, _generating = false;
  final Set<String> _busy = {};
  int _generation = 0;
  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _repo.dispose();
    _month.dispose();
    super.dispose();
  }

  Future<void> _load({bool more = false}) async {
    final generation = ++_generation;
    setState(() => _loading = true);
    try {
      final p = await _repo.commissionPage(
        'statements',
        status: _status,
        periodMonth: _period,
        cursor: more ? _cursor : null,
      );
      if (mounted && generation == _generation)
        setState(() {
          _items = more ? [..._items, ...p.items] : p.items;
          _cursor = p.nextCursor;
          _error = null;
        });
    } catch (e) {
      if (mounted && generation == _generation)
        setState(() => _error = e.toString());
    } finally {
      if (mounted && generation == _generation)
        setState(() => _loading = false);
    }
  }

  Future<void> _waive(AdminCommissionRecord s) async {
    final reason = await commissionReason(context);
    if (reason == null || !mounted || !_busy.add(s.id)) return;
    setState(() {});
    try {
      await _repo.commissionCommand('statements/${s.id}/waive', {
        'reason': reason,
        'version': s.version,
        'idempotencyKey': _idempotencyKeys.putIfAbsent(
          s.id,
          () => const Uuid().v4(),
        ),
      });
      _idempotencyKeys.remove(s.id);
      await _load();
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      _busy.remove(s.id);
      if (mounted) setState(() {});
    }
  }

  Future<void> _generate() async {
    final date = await showDatePicker(
      context: context,
      initialDate: DateTime(DateTime.now().year, DateTime.now().month - 1),
      firstDate: DateTime(2020),
      lastDate: DateTime(DateTime.now().year, DateTime.now().month, 0),
      helpText: 'اختار أي يوم من شهر الكشف',
    );
    if (date == null || !mounted) return;
    final month = '${date.year}-${date.month.toString().padLeft(2, '0')}-01';
    final yes = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('توليد كشوف الشهر'),
        content: Text(
          'توليد كشوف $month؟ الفنيين اللي عليهم مستحقات هيتوقف استقبال الطلبات عندهم لحد السداد.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('إلغاء'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('توليد الكشوف'),
          ),
        ],
      ),
    );
    if (yes != true || !mounted) return;
    setState(() => _generating = true);
    try {
      await _repo.generateCommissionStatements({
        'periodMonth': month,
        'idempotencyKey': _idempotencyKeys.putIfAbsent(
          'generate:$month',
          () => const Uuid().v4(),
        ),
      });
      await _load();
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _generating = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(
      title: const Text('كشوف عمولة الفنيين'),
      actions: [
        IconButton(
          tooltip: 'توليد كشوف شهر',
          onPressed: _generating ? null : _generate,
          icon: const Icon(Icons.add_chart),
        ),
      ],
    ),
    body: RefreshIndicator(
      onRefresh: () => _load(),
      child: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          DropdownButtonFormField<String>(
            initialValue: _status ?? 'all',
            decoration: const InputDecoration(labelText: 'الحالة'),
            items: ['all', 'due', 'under_review', 'paid', 'waived']
                .map(
                  (s) => DropdownMenuItem(
                    value: s,
                    child: Text(s == 'all' ? 'الكل' : billingStateLabel(s)),
                  ),
                )
                .toList(),
            onChanged: (v) {
              _status = v == 'all' ? null : v;
              _load();
            },
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _month,
            decoration: InputDecoration(
              labelText: 'الشهر (YYYY-MM)',
              suffixIcon: IconButton(
                tooltip: 'فلترة بالشهر',
                onPressed: () {
                  if (_month.text.isEmpty ||
                      RegExp(
                        r'^\d{4}-(0[1-9]|1[0-2])$',
                      ).hasMatch(_month.text)) {
                    _period = _month.text.isEmpty ? null : '${_month.text}-01';
                    _load();
                  } else {
                    setState(() => _error = 'اكتب الشهر بالشكل ده: 2026-09');
                  }
                },
                icon: const Icon(Icons.filter_list),
              ),
            ),
          ),
          if (_error != null)
            TextButton(onPressed: () => _load(), child: Text(_error!)),
          if (!_loading && _items.isEmpty)
            const Padding(
              padding: EdgeInsets.all(32),
              child: Text('مفيش كشوف مطابقة.'),
            ),
          for (final s in _items)
            Card(
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      s.data['technicianName']?.toString() ?? 'الفني',
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                    Text(
                      '${s.data['periodMonth']} · ${billingMoney(s.data['amountDueMinor'] as int)}',
                    ),
                    Chip(label: Text(billingStateLabel(s.status))),
                    if (s.status == 'due' || s.status=='under_review')
                      TextButton(
                        onPressed: _busy.contains(s.id)
                            ? null
                            : () => _waive(s),
                        child: const Text('إعفاء'),
                      ),
                  ],
                ),
              ),
            ),
          if (_loading || _generating)
            const Center(child: CircularProgressIndicator()),
          if (_cursor != null && !_loading)
            TextButton(
              onPressed: () => _load(more: true),
              child: const Text('عرض المزيد'),
            ),
        ],
      ),
    ),
  );
}import 'package:fixit_pro/features/admin/presentation/pages/payments/commission_billing_widgets.dart';
import 'dart:async';

import 'package:fixit_pro/app/theme/v2_design_tokens.dart';
import 'package:fixit_pro/features/admin/data/repositories/admin_finance_repository.dart';
import 'package:fixit_pro/features/admin/data/services/admin_finance_api.dart';
import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';
import 'package:flutter/material.dart';

class PayCommissionsPage extends StatefulWidget {
  const PayCommissionsPage({super.key, this.repository});

  final AdminFinanceRepository? repository;

  @override
  State<PayCommissionsPage> createState() => _PayCommissionsPageState();
}

class _PayCommissionsPageState extends State<PayCommissionsPage> {
  late final AdminFinanceRepository _repository;
  CommissionSummaryEntity? _summary;
  bool _loading = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    _repository = widget.repository ?? HttpAdminFinanceRepository();
    unawaited(_load());
  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final summary = await _repository.getCommissions();
      if (!mounted) return;
      setState(() {
        _summary = summary;
        _loading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _error = error is AdminFinanceApiException
            ? error.message
            : 'تعذر تحميل العمولات.';
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final summary = _summary;
    return Scaffold(
      backgroundColor: V2Colors.bg,
      appBar: AppBar(
        backgroundColor: V2Colors.surface,
        foregroundColor: V2Colors.ink,
        elevation: 0,
        surfaceTintColor: Colors.transparent,
        title: const Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'إدارة عمولات المنصة',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w900,
                color: V2Colors.ink,
              ),
            ),
            Text(
              'تحديد نسب العمولة لكل قسم ومستوى فني',
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: V2Colors.inkLight,
              ),
            ),
          ],
        ),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _error != null
          ? Center(
              child: TextButton.icon(
                onPressed: _load,
                icon: const Icon(Icons.refresh_rounded),
                label: Text(_error!),
              ),
            )
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                const CommissionSettingsCard(),
                const CommissionAdminLinks(),
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: V2Colors.surface,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: V2Colors.border),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'نسبة العمولة الافتراضية العامة',
                        style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w900,
                          color: V2Colors.ink,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        '${_percentage(summary?.commissionAmountMinor ?? 0, summary?.grossAmountMinor ?? 0)} من إجمالي المعاملات الناجحة',
                        style: const TextStyle(
                          fontSize: 11,
                          color: V2Colors.inkLight,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 16),
                const Text(
                  'النسب المخصصة حسب القسم:',
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w900,
                    color: V2Colors.ink,
                  ),
                ),
                const SizedBox(height: 10),
                ...?summary?.byCategory.map(
                  (category) => _buildCommissionCategoryTile(
                    category.categoryName,
                    _percentage(
                      category.commissionAmountMinor,
                      category.grossAmountMinor,
                    ),
                    _categoryIcon(category.categoryName),
                    _categoryBackground(category.categoryName),
                    _categoryColor(category.categoryName),
                  ),
                ),
              ],
            ),
    );
  }

  String _percentage(int commissionMinor, int grossMinor) {
    if (grossMinor == 0) return '٠٪';
    return toArabicDigits(
      '${(commissionMinor * 100 / grossMinor).toStringAsFixed(1)}٪',
    );
  }

  IconData _categoryIcon(String title) {
    if (title.contains('كهرب')) return Icons.bolt_rounded;
    if (title.contains('سباك')) return Icons.plumbing_rounded;
    if (title.contains('تكييف') || title.contains('تبريد')) {
      return Icons.ac_unit_rounded;
    }
    return Icons.local_shipping_rounded;
  }

  Color _categoryBackground(String title) {
    if (title.contains('كهرب')) return V2Colors.amber;
    if (title.contains('سباك')) return V2Colors.infoSoft;
    if (title.contains('تكييف') || title.contains('تبريد')) {
      return V2Colors.primaryLight;
    }
    return const Color(0xFFFFEDD5);
  }

  Color _categoryColor(String title) {
    if (title.contains('كهرب')) return V2Colors.amberMid;
    if (title.contains('سباك')) return V2Colors.info;
    if (title.contains('تكييف') || title.contains('تبريد')) {
      return V2Colors.primary;
    }
    return V2Colors.accent;
  }

  Widget _buildCommissionCategoryTile(
    String title,
    String percent,
    IconData icon,
    Color bg,
    Color color,
  ) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: V2Colors.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: V2Colors.border),
      ),
      child: Row(
        children: [
          CircleAvatar(
            backgroundColor: bg,
            child: Icon(icon, color: color, size: 20),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              title,
              style: const TextStyle(
                fontSize: 13.5,
                fontWeight: FontWeight.w800,
                color: V2Colors.ink,
              ),
            ),
          ),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
            decoration: BoxDecoration(
              color: V2Colors.primaryLight,
              borderRadius: BorderRadius.circular(8),
            ),
            child: Text(
              percent,
              style: const TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w900,
                color: V2Colors.primaryDark,
              ),
            ),
          ),
        ],
      ),
    );
  }
}import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import 'package:fixit_pro/features/admin/data/repositories/admin_finance_repository.dart';
import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';

class PayCompanyMethodsPage extends StatefulWidget {
  const PayCompanyMethodsPage({super.key});
  @override
  State<PayCompanyMethodsPage> createState() => _PayCompanyMethodsPageState();
}

class _PayCompanyMethodsPageState extends State<PayCompanyMethodsPage> {
  final _repo = HttpAdminFinanceRepository();
  List<AdminCommissionRecord> _items = [];
  String? _error;
  bool _loading = true;
  final Map<String, String> _idempotencyKeys = {};
  final Set<String> _busy = {};
  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _repo.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final page = await _repo.commissionPage('payment-methods');
      if (mounted)
        setState(() {
          _items = page.items;
          _error = null;
        });
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _save(AdminCommissionRecord m, bool active) async {
    if (!_busy.add(m.id)) return;
    setState(() {});
    try {
      await _repo.commissionCommand('payment-methods/${m.id}', {
        for (final k in [
          'methodType',
          'label',
          'accountValue',
          'accountHolder',
          'instructions',
          'sortOrder',
        ])
          k: m.data[k],
        'isActive': active,
        'version': m.version,
        'idempotencyKey': _idempotencyKeys.putIfAbsent(
          '${m.id}:$active',
          () => const Uuid().v4(),
        ),
      });
      _idempotencyKeys.remove('${m.id}:$active');
      await _load();
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    } finally {
      _busy.remove(m.id);
      if (mounted) setState(() {});
    }
  }

  Future<void> _edit([AdminCommissionRecord? item]) async {
    final form = GlobalKey<FormState>();
    final d = item?.data ?? {};
    final label = TextEditingController(text: d['label']?.toString()),
        account = TextEditingController(text: d['accountValue']?.toString()),
        holder = TextEditingController(text: d['accountHolder']?.toString()),
        instructions = TextEditingController(
          text: d['instructions']?.toString(),
        ),
        sort = TextEditingController(text: d['sortOrder']?.toString() ?? '0');
    String type = d['methodType']?.toString() ?? 'vodafone_cash';
    bool active = d['isActive'] != false, saving = false;
    String? error;
    final key = const Uuid().v4();
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      useSafeArea: true,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, set) => Padding(
          padding: EdgeInsets.fromLTRB(
            20,
            8,
            20,
            MediaQuery.viewInsetsOf(ctx).bottom + 20,
          ),
          child: SingleChildScrollView(
            child: Form(
              key: form,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    item == null ? 'إضافة طريقة دفع' : 'تعديل طريقة الدفع',
                    style: Theme.of(ctx).textTheme.titleLarge,
                  ),
                  if (error != null)
                    Text(
                      error!,
                      style: TextStyle(color: Theme.of(ctx).colorScheme.error),
                    ),
                  DropdownButtonFormField<String>(
                    initialValue: type,
                    items:
                        {
                              'vodafone_cash': 'فودافون كاش',
                              'etisalat_cash': 'اتصالات كاش',
                              'orange_cash': 'أورنج كاش',
                              'we_pay': 'وي باي',
                              'instapay': 'إنستاباي',
                              'bank_account': 'حساب بنكي',
                              'other_wallet': 'محفظة تانية',
                            }.entries
                            .map(
                              (e) => DropdownMenuItem(
                                value: e.key,
                                child: Text(e.value),
                              ),
                            )
                            .toList(),
                    onChanged: saving ? null : (v) => set(() => type = v!),
                  ),
                  for (final field in [
                    (label, 'اسم طريقة الدفع', 120),
                    (account, 'الرقم / عنوان إنستاباي / IBAN', 160),
                    (holder, 'اسم صاحب الحساب', 160),
                  ])
                    TextFormField(
                      controller: field.$1,
                      enabled: !saving,
                      maxLength: field.$3,
                      decoration: InputDecoration(labelText: field.$2),
                      onChanged: (_) => set(() {}),
                      validator: (v) => v == null || v.trim().isEmpty
                          ? 'الحقل ده مطلوب'
                          : null,
                    ),
                  TextFormField(
                    controller: instructions,
                    enabled: !saving,
                    maxLength: 1000,
                    decoration: const InputDecoration(
                      labelText: 'تعليمات التحويل',
                    ),
                    onChanged: (_) => set(() {}),
                  ),
                  TextFormField(
                    controller: sort,
                    enabled: !saving,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'ترتيب الظهور',
                    ),
                    validator: (v) {
                      final n = int.tryParse(v ?? '');
                      return n == null || n < 0 || n > 32767
                          ? 'اكتب رقم من ٠ إلى ٣٢٧٦٧'
                          : null;
                    },
                  ),
                  SwitchListTile(
                    title: const Text('متاحة للفنيين'),
                    value: active,
                    onChanged: saving ? null : (v) => set(() => active = v),
                  ),
                  const Divider(),
                  const Text('كده الفني هيشوفها'),
                  ListTile(
                    leading: Icon(
                      type == 'bank_account'
                          ? Icons.account_balance
                          : Icons.account_balance_wallet_outlined,
                    ),
                    title: Text(label.text),
                    subtitle: Text(
                      '${account.text}\n${holder.text}\n${instructions.text}',
                    ),
                  ),
                  FilledButton(
                    onPressed: saving
                        ? null
                        : () async {
                            if (!form.currentState!.validate()) return;
                            set(() => saving = true);
                            try {
                              await _repo.commissionCommand(
                                item == null
                                    ? 'payment-methods'
                                    : 'payment-methods/${item.id}',
                                {
                                  'methodType': type,
                                  'label': label.text.trim(),
                                  'accountValue': account.text.trim(),
                                  'accountHolder': holder.text.trim(),
                                  'instructions': instructions.text.trim(),
                                  'isActive': active,
                                  'sortOrder': int.parse(sort.text),
                                  'version': item?.version ?? 1,
                                  'idempotencyKey': key,
                                },
                                create: item == null,
                              );
                              if (ctx.mounted) Navigator.pop(ctx);
                              await _load();
                            } catch (e) {
                              if (ctx.mounted)
                                set(() {
                                  saving = false;
                                  error = e.toString();
                                });
                            }
                          },
                    child: Text(saving ? 'جاري الحفظ…' : 'حفظ'),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    for (final c in [label, account, holder, instructions, sort]) {
      c.dispose();
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('طرق دفع الشركة')),
    floatingActionButton: FloatingActionButton.extended(
      onPressed: () => _edit(),
      icon: const Icon(Icons.add),
      label: const Text('إضافة طريقة'),
    ),
    body: _loading
        ? const Center(child: CircularProgressIndicator())
        : RefreshIndicator(
            onRefresh: _load,
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 100),
              children: [
                if (_error != null)
                  TextButton(onPressed: _load, child: Text(_error!)),
                if (_items.isEmpty)
                  const Text(
                    'ضيف طريقة دفع علشان الفنيين يقدروا يسددوا مستحقاتهم.',
                  ),
                for (final m in _items)
                  ListTile(
                    title: Text(m.data['label'].toString()),
                    subtitle: Text(
                      '${m.data['accountValue']}\n${m.data['accountHolder']}',
                    ),
                    onTap: () => _edit(m),
                    trailing: Switch(
                      value: m.data['isActive'] == true,
                      onChanged: _busy.contains(m.id)
                          ? null
                          : (v) => _save(m, v),
                    ),
                  ),
              ],
            ),
          ),
  );
}import 'package:fixit_pro/features/technician-billing/data/commission_billing_api.dart';
import 'package:fixit_pro/features/technician-billing/data/models/commission_summary.dart';
import 'package:fixit_pro/features/technician-billing/presentation/widgets/billing_status_banner.dart';
import 'package:fixit_pro/features/technician-billing/presentation/widgets/billing_blocked_sheet.dart';
import 'dart:async';

import 'package:fixit_pro/app/routing/routes/app_routes.dart';
import 'package:fixit_pro/app/theme/v2_design_tokens.dart';
import 'package:fixit_pro/features/technician-time-off/data/time_off_api.dart';
import 'package:fixit_pro/features/technician-time-off/presentation/widgets/active_time_off_banner.dart';
import 'package:fixit_pro/features/technician/data/models/settings_summary.dart';
import 'package:fixit_pro/features/technician/data/technician_settings_api.dart';
import 'package:fixit_pro/features/technician/presentation/widgets/technician_widgets.dart';
import 'package:fixit_pro/features/technician/presentation/pages/technician_my_offers_page.dart';
import 'package:fixit_pro/features/technician-availability/data/presence_api.dart';
import 'package:fixit_pro/features/technician/data/technician_requests_api.dart';
import 'package:fixit_pro/features/technician/data/technician_realtime_client.dart';
import 'package:fixit_pro/features/technician/data/dispatch_runtime_config.dart';
import 'package:fixit_pro/features/permissions/domain/app_permission_service.dart';
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';

class TechnicianDashboardPage extends StatefulWidget {
  const TechnicianDashboardPage({
    super.key,
    this.summarySource,
    this.timeOffSource,
    this.ensureSession,
    this.permissionService,
    this.presenceFactory,
    this.requestsFactory,
    this.realtimeFactory,
  });

  final TechnicianSettingsSummarySource? summarySource;
  final TechnicianTimeOffRepository? timeOffSource;
  final Future<bool> Function()? ensureSession;
  final AppPermissionService? permissionService;
  final PresenceRepository Function()? presenceFactory;
  final TechnicianRequestsApi Function()? requestsFactory;
  final TechnicianRealtimeClient Function()? realtimeFactory;

  @override
  State<TechnicianDashboardPage> createState() =>
      _TechnicianDashboardPageState();
}

class _TechnicianDashboardPageState extends State<TechnicianDashboardPage>
    with WidgetsBindingObserver {
  final _billingApi = CommissionBillingApi();
  CommissionSummary? _billing;
  Future<void> _loadBilling() async {
    try {
      final s = await _billingApi.summary();
      if (mounted)
        setState(() {
          _billing = s;
          if (s.blocked) {
            _isOnline = false;
            _breakUntil = null;
            _heartbeat?.cancel();
            _breakCountdownTimer?.cancel();
            _feed = [];
          }
        });
    } catch (_) {}
  }

  bool _isOnline = false;
  int _heartbeatFailures = 0;
  bool _presenceToggleInFlight = false;
  bool _presenceStateUncertain = false;
  DateTime? _breakUntil;
  int _navIndex = 0;

  late final TechnicianSettingsSummarySource _settingsSource;
  late final bool _ownsSettingsSource;
  late final TechnicianTimeOffRepository _timeOffSource;
  late final bool _ownsTimeOffSource;
  TechnicianSettingsSummary? _settingsSummary;
  bool _settingsLoading = true;
  bool _endingTimeOff = false;
  bool _gpsPermissionMissing = false;
  bool _gpsServiceDisabled = false;
  late final AppPermissionService _permissionService;
  late final PresenceRepository _presence;
  late final TechnicianRequestsApi _requests;
  late final TechnicianRealtimeClient _realtime;
  Timer? _heartbeat;
  Timer? _heartbeatCooldown;
  bool _heartbeatInFlight = false;
  Timer? _breakCountdownTimer;
  Timer? _feedPoll;
  final Set<String> _hiddenRequests = {};
  final Set<String> _handledAssignments = {};
  final Map<String, Timer> _skipTimers = {};
  bool _presenceUnavailable = false;
  bool get _canUsePresence =>
      !_presenceUnavailable && DispatchRuntimeConfig.enabled;
  bool _feedLoading = false;
  bool _feedReloadPending = false;
  String? _feedError;
  List<TechnicianRequest> _feed = const [];
  TechnicianRequest? _currentAssignment;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _presence =
        widget.presenceFactory?.call() ??
        PresenceApi.fromEnvironment(ensureSession: widget.ensureSession);
    _permissionService =
        widget.permissionService ?? const PlatformAppPermissionService();
    _requests =
        widget.requestsFactory?.call() ??
        TechnicianRequestsApi.fromEnvironment(
          ensureSession: widget.ensureSession,
        );
    _realtime =
        widget.realtimeFactory?.call() ??
        TechnicianRealtimeClient(ensureSession: widget.ensureSession);
    _ownsSettingsSource = widget.summarySource == null;
    _settingsSource =
        widget.summarySource ??
        TechnicianSettingsApi.fromEnvironment(
          ensureSession: widget.ensureSession,
        );
    _ownsTimeOffSource = widget.timeOffSource == null;
    _timeOffSource =
        widget.timeOffSource ??
        TechnicianTimeOffApi.fromEnvironment(
          ensureSession: widget.ensureSession,
        );
    unawaited(_loadSettingsSummary());
    unawaited(_loadFeed());
    unawaited(
      _realtime
          .connect(
            onReconnect: () {
              _startFeedPolling();
              unawaited(_loadFeed());
            },
            onEvent: (event) => unawaited(_handleRealtime(event)),
          )
          .then((_) {
            if (mounted) unawaited(_loadPresence());
          }),
    );
    _startHeartbeat();
    _startFeedPolling();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _heartbeat?.cancel();
    _heartbeatCooldown?.cancel();
    _breakCountdownTimer?.cancel();
    _feedPoll?.cancel();
    for (final timer in _skipTimers.values) {
      timer.cancel();
    }
    _skipTimers.clear();
    if (_presence is PresenceApi) _presence.close();
    _billingApi.close();
    _requests.close();
    _realtime.dispose();
    if (_ownsSettingsSource && _settingsSource is TechnicianSettingsApi) {
      _settingsSource.close();
    }
    if (_ownsTimeOffSource && _timeOffSource is TechnicianTimeOffApi) {
      _timeOffSource.close();
    }
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _startHeartbeat();
      unawaited(_loadPresence());
      _startFeedPolling();
      unawaited(_loadFeed());
    } else {
      _heartbeat?.cancel();
      _breakCountdownTimer?.cancel();
      _feedPoll?.cancel();
    }
  }

  void _startHeartbeat() {
    _heartbeat?.cancel();
    if (!_isOnline || !_canUsePresence) return;
    unawaited(_sendHeartbeat());
    _heartbeat = Timer.periodic(
      const Duration(seconds: 60),
      (_) => unawaited(_sendHeartbeat()),
    );
  }

  Future<void> _loadFeed() async {
    if (_feedLoading) {
      _feedReloadPending = true;
      return;
    }
    _feedLoading = true;
    unawaited(_loadBilling());
    try {
      final feed = await _requests.list();
      final assignment = DispatchRuntimeConfig.enabled
          ? await _requests.currentAssignment()
          : null;
      if (mounted)
        setState(() {
          _feed = feed.where((r) => !_hiddenRequests.contains(r.id)).toList();
          _feedError = null;
          _currentAssignment = assignment;
        });
      if (mounted &&
          assignment != null &&
          assignment.data['status'] == 'assigned' &&
          _handledAssignments.add(assignment.id)) {
        unawaited(
          Navigator.of(context).pushNamed<void>(
            AppRoutes.techOrderAccepted,
            arguments: assignment.toEntity(),
          ),
        );
      }
    } on Object {
      if (mounted)
        setState(
          () => _feedError =
              'تعذر تحديث الطلبات. اسحب للتحديث أو حاول مرة تانية.',
        );
    } finally {
      _feedLoading = false;
      if (_feedReloadPending) {
        _feedReloadPending = false;
        if (mounted) unawaited(_loadFeed());
      }
    }
  }

  void _startFeedPolling() {
    _feedPoll?.cancel();
    _feedPoll = Timer.periodic(
      Duration(
        seconds: DispatchRuntimeConfig.limit('FEED_POLL_FALLBACK_SEC', 20),
      ),
      (_) {
        if (!_realtime.isConnected) unawaited(_loadFeed());
      },
    );
  }

  Future<void> _sendHeartbeat() async {
    if (!_canUsePresence ||
        _heartbeatInFlight ||
        (_heartbeatCooldown?.isActive ?? false))
      return;
    _heartbeatInFlight = true;
    _beginHeartbeatCooldown(const Duration(seconds: 60));
    try {
      await _presence.heartbeat();
      _heartbeatFailures = 0;
      if (mounted && _presenceStateUncertain)
        setState(() => _presenceStateUncertain = false);
    } on Object catch (error) {
      if (!mounted) return;
      final statusCode = error is PresenceApiException
          ? error.statusCode
          : null;
      if (statusCode == 429) {
        final suggested =
            (error as PresenceApiException).retryAfter ??
            const Duration(minutes: 2);
        final wait = suggested < const Duration(minutes: 1)
            ? const Duration(minutes: 1)
            : suggested;
        _beginHeartbeatCooldown(wait);
        _heartbeatFailures = 0;
        setState(() => _presenceStateUncertain = true);
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'تم تهدئة الاتصال مؤقتًا. هنحاول تاني بعد ${toArabicDigits(wait.inSeconds)} ثانية.',
            ),
          ),
        );
        return;
      }
      if (statusCode == 401 ||
          statusCode == 404 ||
          statusCode == 409 ||
          statusCode == 403) {
        _heartbeatFailures = 0;
        if (statusCode == 401 || statusCode == 403 || statusCode == 404)
          _presenceUnavailable = true;
        setState(() {
          _isOnline = false;
          _breakUntil = null;
        });
        _heartbeat?.cancel();
        return;
      }
      _heartbeatFailures += 1;
      if (_heartbeatFailures == 1) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('الاتصال ضعيف؛ هنحاول تاني تلقائيًا.')),
        );
      }
      if (_heartbeatFailures >= 3) {
        _heartbeatFailures = 0;
        await _loadPresence();
      }
    } finally {
      _heartbeatInFlight = false;
    }
  }

  void _beginHeartbeatCooldown(Duration wait) {
    _heartbeatCooldown?.cancel();
    _heartbeatCooldown = Timer(wait, () {
      if (mounted &&
          _isOnline &&
          _canUsePresence &&
          (_heartbeat?.isActive ?? false)) {
        unawaited(_sendHeartbeat());
      }
    });
  }

  Future<void> _loadPresence({
    bool reconcileAmbiguousMutation = false,
    bool manualRetry = false,
  }) async {
    if (manualRetry) _presenceUnavailable = false;
    if (!_canUsePresence) return;
    try {
      final state = reconcileAmbiguousMutation
          ? await _presence.reconcileAmbiguousMutation()
          : await _presence.getState();
      if (!mounted) return;
      _heartbeatFailures = 0;
      setState(() {
        _isOnline = state.online && _billing?.blocked != true;
        _breakUntil = state.breakUntil;
        _presenceStateUncertain = false;
      });
      _syncBreakCountdown();
      _startHeartbeat();
    } on Object catch (error) {
      if (error is PresenceApiException &&
          [401, 403, 404].contains(error.statusCode)) {
        _presenceUnavailable = true;
        _heartbeat?.cancel();
        if (mounted) setState(() => _isOnline = false);
      }
      if (mounted) setState(() => _presenceStateUncertain = true);
    }
  }

  void _syncBreakCountdown() {
    _breakCountdownTimer?.cancel();
    if (_breakUntil == null || !_breakUntil!.isAfter(DateTime.now())) return;
    _breakCountdownTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (!_breakUntil!.isAfter(DateTime.now())) timer.cancel();
      setState(() {});
    });
  }

  Future<void> _handleRealtime(Map<String, Object?> event) async {
    if (event['type']?.toString().startsWith('billing.') == true) {
      await _loadBilling();
      await _loadPresence();
      await _loadFeed();
    }
    if (!mounted) return;
    if (event['type'] == 'order.assigned') {
      final id = event['orderId']?.toString();
      if (id != null && _handledAssignments.add(id)) {
        try {
          final assigned = await _requests.assignment(id);
          if (mounted)
            await Navigator.of(context).pushNamed<void>(
              AppRoutes.techOrderAccepted,
              arguments: assigned.toEntity(),
            );
        } on Object {
          _handledAssignments.remove(id);
        }
      }
    } else if (event['type'] == 'offer.lost') {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('العميل اختار عرض تاني. عروضك اتحدثت.')),
      );
    }
    await _loadFeed();
  }

  Future<void> _openRequest(TechnicianRequestItem item) async {
    final request = _feed.firstWhere((r) => r.id == item.id);
    final skipped = await Navigator.of(context).pushNamed<String>(
      AppRoutes.techIncomingRequest,
      arguments: request.toEntity(),
    );
    if (!mounted) return;
    if (skipped != null) _scheduleSkip(skipped);
    await _loadFeed();
  }

  Future<void> _loadSettingsSummary() async {
    try {
      final summary = await _settingsSource.getSummary();
      if (!mounted) return;
      setState(() {
        _settingsSummary = summary;
        _settingsLoading = false;
      });
    } on Object {
      if (!mounted) return;
      setState(() => _settingsLoading = false);
    }
  }

  Future<void> _openAndReload(String route) async {
    await Navigator.of(context).pushNamed<void>(route);
    if (mounted) await _loadSettingsSummary();
  }

  Future<bool> _ensureLocationReady() async {
    final permissionGranted = await _permissionService.hasLocationPermission();
    final locationEnabled =
        kIsWeb || await Geolocator.isLocationServiceEnabled();
    if (!mounted) return false;
    setState(() {
      _gpsPermissionMissing = !permissionGranted;
      _gpsServiceDisabled = permissionGranted && !locationEnabled;
    });
    return permissionGranted && locationEnabled;
  }

  Future<void> _handleGpsAlert() async {
    if (_gpsPermissionMissing) await _permissionService.openSettings();
    await _ensureLocationReady();
  }

  Future<void> _returnToWork() async {
    final leave = _settingsSummary?.timeOff.next;
    if (leave == null || _endingTimeOff) return;
    setState(() => _endingTimeOff = true);
    try {
      await _timeOffSource.endNow(leave.id);
      if (!mounted) return;
      await _loadSettingsSummary();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('رجعت تستقبل الطلبات دلوقتي.')),
        );
      }
    } on TechnicianTimeOffApiException catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(error.message)));
      }
    } finally {
      if (mounted) setState(() => _endingTimeOff = false);
    }
  }

  Future<void> _onToggleOnline(bool val) async {
    if (val && _billing?.blocked == true) {
      await showBillingBlockedSheet(
        context,
        summary: _billing,
        onReturn: _loadBilling,
      );
      return;
    }
    if (!_canUsePresence) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('استقبال الطلبات المباشرة غير متاح حاليًا.'),
        ),
      );
      return;
    }
    if (_presenceToggleInFlight) return;
    _presenceToggleInFlight = true;
    try {
      if (val && !await _ensureLocationReady()) return;
      if (!val && (await _requests.myOffers()).isNotEmpty) {
        if (!mounted) return;
        final confirmed = await _showConfirmWithdrawOffersDialog(
          context,
          title: 'إيقاف استقبال الطلبات؟',
          cta: 'متابعة',
        );
        if (confirmed != true) return;
      }
      final state = await _presence.setOnline(val);
      if (!mounted) return;
      setState(() {
        _isOnline = state.online;
        _breakUntil = state.breakUntil;
        _presenceStateUncertain = false;
      });
      _syncBreakCountdown();
      _startHeartbeat();
      await _loadFeed();
    } on PresenceApiException catch (error) {
      if (error.code == 'COMMISSION_PAYMENT_REQUIRED') {
        if (mounted)
          await showBillingBlockedSheet(
            context,
            summary: _billing,
            onReturn: _loadBilling,
          );
        return;
      }
      if (error.isAmbiguous) {
        await _loadPresence(reconcileAmbiguousMutation: true);
      }
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(error.message)));
      }
      return;
    } on Object {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('تعذر تغيير حالة الاتصال. حاول تاني.')),
        );
      }
      return;
    } finally {
      _presenceToggleInFlight = false;
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          val
              ? 'أنت الآن متصل وتستقبل الطلبات القريبة'
              : 'تم إيقاف استقبال الطلبات مؤقتاً',
        ),
        backgroundColor: val ? V2Colors.primary : V2Colors.inkMuted,
        duration: const Duration(seconds: 2),
      ),
    );
  }

  Future<bool?> _showConfirmWithdrawOffersDialog(
    BuildContext context, {
    required String title,
    required String cta,
  }) {
    return showDialog<bool>(
      context: context,
      builder: (ctx) => Dialog(
        backgroundColor: V2Colors.surface,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(26)),
        insetPadding: const EdgeInsets.symmetric(horizontal: 24),
        child: Padding(
          padding: const EdgeInsets.all(22),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 56,
                height: 56,
                decoration: BoxDecoration(
                  color: V2Colors.amber,
                  borderRadius: BorderRadius.circular(18),
                ),
                alignment: Alignment.center,
                child: const Icon(
                  Icons.pause_rounded,
                  size: 28,
                  color: V2Colors.amberMid,
                ),
              ),
              const SizedBox(height: 14),
              Text(
                title,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.w800,
                  color: V2Colors.ink,
                ),
              ),
              const SizedBox(height: 4),
              const Text(
                'هيتم سحب عروضك المعلقة',
                textAlign: TextAlign.center,
                style: TextStyle(fontSize: 13.5, color: V2Colors.inkMuted),
              ),
              const SizedBox(height: 18),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton(
                      onPressed: () => Navigator.pop(ctx, false),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: V2Colors.inkMuted,
                        backgroundColor: V2Colors.soft,
                        side: BorderSide.none,
                        minimumSize: const Size.fromHeight(46),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                      ),
                      child: const Text(
                        'إلغاء',
                        style: TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: FilledButton(
                      onPressed: () => Navigator.pop(ctx, true),
                      style: FilledButton.styleFrom(
                        backgroundColor: V2Colors.primary,
                        minimumSize: const Size.fromHeight(46),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                        elevation: 0,
