  Future<void> _takeBreak() async {
    if (_billing?.blocked == true) {
      await showBillingBlockedSheet(
        context,
        summary: _billing,
        onReturn: _loadBilling,
      );
      return;
    }
    if (!_canUsePresence) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('استقبال الطلبات المباشرة غير متاح حاليًا.'),
        ),
      );
      return;
    }
    if (_presenceToggleInFlight) return;
    _presenceToggleInFlight = true;
    try {
      final minutes = await showModalBottomSheet<int>(
        context: context,
        backgroundColor: Colors.transparent,
        builder: (ctx) => Container(
          padding: const EdgeInsets.fromLTRB(20, 12, 20, 28),
          decoration: const BoxDecoration(
            color: V2Colors.surface,
            borderRadius: BorderRadius.only(
              topLeft: Radius.circular(28),
              topRight: Radius.circular(28),
            ),
          ),
          child: SafeArea(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Center(
                  child: Container(
                    width: 40,
                    height: 5,
                    decoration: BoxDecoration(
                      color: V2Colors.border,
                      borderRadius: BorderRadius.circular(9),
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                const Text(
                  'مدة الاستراحة',
                  style: TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.w800,
                    color: V2Colors.ink,
                  ),
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    for (final m in [15, 30, 60]) ...[
                      Expanded(
                        child: InkWell(
                          onTap: () => Navigator.pop(ctx, m),
                          borderRadius: BorderRadius.circular(18),
                          child: Container(
                            padding: const EdgeInsets.symmetric(vertical: 16),
                            decoration: BoxDecoration(
                              color: m == 30
                                  ? V2Colors.primaryLight
                                  : V2Colors.surface,
                              borderRadius: BorderRadius.circular(18),
                              border: Border.all(
                                color: m == 30
                                    ? V2Colors.primary
                                    : V2Colors.border,
                                width: 1.5,
                              ),
                            ),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Text(
                                  toArabicDigits(m),
                                  style: TextStyle(
                                    fontSize: 26,
                                    fontWeight: FontWeight.w800,
                                    color: m == 30
                                        ? V2Colors.primaryDark
                                        : V2Colors.ink,
                                  ),
                                ),
                                const SizedBox(height: 2),
                                const Text(
                                  'دقيقة',
                                  style: TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w700,
                                    color: V2Colors.inkMuted,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                      if (m != 60) const SizedBox(width: 8),
                    ],
                  ],
                ),
              ],
            ),
          ),
        ),
      );
      if (minutes == null || !mounted) return;
      final offers = await _requests.myOffers();
      if (!mounted) return;
      if (offers.isNotEmpty) {
        final confirmed = await _showConfirmWithdrawOffersDialog(
          context,
          title: 'بدء الاستراحة؟',
          cta: 'بدء الاستراحة',
        );
        if (confirmed != true || !mounted) return;
      }
      final state = await _presence.takeBreak(minutes);
      if (!mounted) return;
      setState(() {
        _isOnline = state.online;
        _breakUntil = state.breakUntil;
        _presenceStateUncertain = false;
      });
      _syncBreakCountdown();
      _startHeartbeat();
      await _loadFeed();
    } on PresenceApiException catch (error) {
      if (error.code == 'COMMISSION_PAYMENT_REQUIRED') {
        if (mounted)
          await showBillingBlockedSheet(
            context,
            summary: _billing,
            onReturn: _loadBilling,
          );
        return;
      }
      if (error.isAmbiguous) {
        await _loadPresence(reconcileAmbiguousMutation: true);
      }
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(error.message)));
      }
    } on Object {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('تعذر بدء الاستراحة. حاول مرة تانية.')),
        );
      }
    } finally {
      _presenceToggleInFlight = false;
    }
  }

