  Future<void> _openNavDestination(int index) async {
    if (index == 0) return;
    final assignment = _currentAssignment;
    if (index == 2 && assignment == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('مفيش مهمة حالية. اختار طلب من الطلبات الجديدة.'),
        ),
      );
      return;
    }
    setState(() => _navIndex = index);
    try {
      final route = switch (index) {
        1 => AppRoutes.techJobs,
        2 => AppRoutes.techDispatchFlow,
        3 => AppRoutes.techEarnings,
        _ => AppRoutes.profile,
      };
      await Navigator.of(context).pushNamed<void>(
        route,
        arguments: index == 2 ? assignment!.toEntity() : null,
      );
    } finally {
      if (mounted) setState(() => _navIndex = 0);
    }
  }

  TechnicianRequestItem _requestItem(TechnicianRequest request) {
    final created = DateTime.tryParse(
      request.data['createdAt']?.toString() ?? '',
    );
    final minutes = created == null
        ? 0
        : DateTime.now().difference(created).inMinutes;
    return TechnicianRequestItem(
      id: request.id,
      name: request.data['customerFirstName']?.toString() ?? 'العميل',
      service: request.serviceTitle,
      distance: request.data['distanceKm'] == null
          ? request.area
          : '${request.data['distanceKm']} كم · ${request.area}',
      duration: 'من $minutes دقيقة',
      price:
          '${(BigInt.tryParse(request.data['customerOfferMinor']?.toString() ?? '') ?? BigInt.zero) ~/ BigInt.from(100)} ج',
      availableUntil: _visibilityLabel(
        request.data['visibleUntil']?.toString(),
      ),
      offersCount: request.offersCount,
      isNew: request.isNew,
      waitingForCustomer: request.data['myOffer'] != null,
    );
  }

  void _scheduleSkip(String requestId) {
    _skipTimers[requestId]?.cancel();
    setState(() {
      _hiddenRequests.add(requestId);
      _feed = _feed.where((r) => r.id != requestId).toList();
    });
    _skipTimers[requestId] = Timer(const Duration(seconds: 5), () async {
      _skipTimers.remove(requestId);
      try {
        await _requests.skip(requestId);
      } on Object {
        _hiddenRequests.remove(requestId);
        if (mounted) await _loadFeed();
      }
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: const Text('تم إخفاء الطلب'),
        duration: const Duration(seconds: 5),
        action: SnackBarAction(
          label: 'تراجع',
          onPressed: () {
            _skipTimers.remove(requestId)?.cancel();
            _hiddenRequests.remove(requestId);
            unawaited(_loadFeed());
          },
        ),
      ),
    );
  }

  String _visibilityLabel(String? value) {
    final time = DateTime.tryParse(value ?? '')?.toLocal();
    return time == null
        ? '—'
        : 'متاح لحد ${time.hour.toString().padLeft(2, '0')}:${time.minute.toString().padLeft(2, '0')}';
  }

