  Widget _buildProfileCompletionCard(TechnicianSettingsSummary summary) {
    final missing = summary.setup.missing
        .where((item) => summary.workAreas.count > 0 || item != 'work_areas')
        .toList(growable: false);
    if (missing.isEmpty) return const SizedBox.shrink();
    final next = missing.first;
    final message = switch (next) {
      'work_areas' => 'حدد مناطق شغلك عشان توصلك طلبات قريبة منك',
      'work_hours' => 'حدد مواعيد شغلك عشان توصلك طلبات',
      'workshop' => 'أضف مكان شغلك عشان تكمل إعداد ملفك',
      _ => 'راجع إعداداتك عشان تكمل ملفك',
    };
    final route = switch (next) {
      'work_hours' => AppRoutes.providerWorkHours,
      'workshop' => AppRoutes.providerWorkshop,
      _ => AppRoutes.providerWorkAreas,
    };
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 20),
      child: Material(
        color: V2Colors.surface,
        borderRadius: BorderRadius.circular(18),
        child: InkWell(
          onTap: () => unawaited(_openAndReload(route)),
          borderRadius: BorderRadius.circular(18),
          child: Container(
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: V2Colors.border),
            ),
            child: Row(
              children: [
                SizedBox(
                  width: 54,
