import 'package:flutter/material.dart';

class TechnicianMyOffersPage extends StatefulWidget {
  const TechnicianMyOffersPage({this.api, this.realtime, super.key});
  final TechnicianRequestsApi? api;
  final TechnicianRealtimeClient? realtime;

  @override
  State<TechnicianMyOffersPage> createState() => _TechnicianMyOffersPageState();
}

class _TechnicianMyOffersPageState extends State<TechnicianMyOffersPage> {
  late final TechnicianRequestsApi _api;
  late final TechnicianRealtimeClient _realtime;
  Timer? _poll;
  List<TechnicianOffer> _offers = [];
  String? _error;
  bool _loading = true;
  bool _showHistory = false;
  bool _reloadRequested = false;
  bool _loadingMore = false;
  String? _nextCursor;
  Future<void>? _inflight;
  int _loadGeneration = 0;
  final Set<String> _busy = {};

  @override
  void initState() {
    super.initState();
    _api = widget.api ?? TechnicianRequestsApi.fromEnvironment();
    _realtime = widget.realtime ?? TechnicianRealtimeClient();
    unawaited(_load());
    unawaited(
      _realtime.connect(
        onReconnect: () {
          if (!_showHistory) unawaited(_load());
        },
        onEvent: (_) {
          if (!_showHistory) unawaited(_load());
        },
      ),
    );
    _poll = Timer.periodic(const Duration(seconds: 20), (_) {
      if (!_showHistory && !_realtime.isConnected) unawaited(_load());
    });
  }

  @override
  void dispose() {
    _poll?.cancel();
    _realtime.dispose();
    if (widget.api == null) _api.close();
    super.dispose();
  }

  Future<void> _load() {
    final running = _inflight;
    if (running != null) {
      _reloadRequested = true;
      _loadGeneration += 1;
      return running;
    }

    final task = _drainLoads();
    _inflight = task;
    return task.whenComplete(() {
      if (identical(_inflight, task)) _inflight = null;
    });
  }

  Future<void> _drainLoads() async {
    do {
      _reloadRequested = false;
      final generation = ++_loadGeneration;
      await _loadOnce(generation);
    } while (_reloadRequested && mounted);
  }

  Future<void> _loadOnce(int generation) async {
    try {
      final page = await _api.myOffersPage(
        status: _showHistory ? 'all' : 'pending',
        limit: 50,
      );
      if (mounted && generation == _loadGeneration) {
        setState(() {
          _offers = page.offers;
          _nextCursor = page.nextCursor;
          _error = null;
          _loading = false;
          _loadingMore = false;
        });
      }
    } on Object {
      if (mounted && generation == _loadGeneration) {
        setState(() {
          _error = 'تعذر تحميل عروضك. حاول مرة تانية.';
          _loading = false;
          _loadingMore = false;
        });
      }
    }
  }

  Future<void> _loadMoreHistory() async {
    final cursor = _nextCursor;
    if (!_showHistory || cursor == null || _loadingMore || _inflight != null) {
      return;
    }
    final generation = _loadGeneration;
    setState(() => _loadingMore = true);
    try {
      final page = await _api.myOffersPage(
        status: 'all',
        limit: 50,
        cursor: cursor,
      );
      if (!mounted || generation != _loadGeneration) return;
      final seen = <String>{for (final offer in _offers) offer.id};
      setState(() {
        _offers = [
          ..._offers,
          for (final offer in page.offers)
            if (seen.add(offer.id)) offer,
        ];
        _nextCursor = page.nextCursor;
        _loadingMore = false;
      });
    } on Object {
      if (!mounted || generation != _loadGeneration) return;
      setState(() => _loadingMore = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تحميل بقية سجل العروض.')),
      );
    }
  }

  String _money(String minor) {
    final n = BigInt.tryParse(minor) ?? BigInt.zero;
    return '${n ~/ BigInt.from(100)}.${(n % BigInt.from(100)).toString().padLeft(2, '0')} ج';
  }

  String _moneyDisplay(String minor) {
    final n = BigInt.tryParse(minor) ?? BigInt.zero;
    final pounds = n ~/ BigInt.from(100);
    final piastres = n % BigInt.from(100);
    if (piastres == BigInt.zero) {
      return toArabicDigits(pounds);
    }
    return '${toArabicDigits(pounds)}٫${toArabicDigits(piastres.toString().padLeft(2, '0'))}';
  }

  String _label(TechnicianOffer offer) => switch (offer.status) {
    'pending' => 'عرضك مستني تأكيد العميل',
    'accepted' => 'مقبول',
    'rejected' => 'مرفوض',
    'expired' => 'منتهي',
    'withdrawn' => 'مسحوب',
    _ =>
      offer.data['closeReason'] == 'technician_unavailable'
          ? 'الفني غير متاح'
          : 'العميل اختار غيرك',
  };

  Future<void> _withdraw(TechnicianOffer offer) async {
    if (!_busy.add(offer.id)) return;
    setState(() {});
    try {
      await _api.withdraw(offer.id);
      await _load();
    } on TechnicianRequestsApiException catch (error) {
      if (error.code == 'COMMISSION_PAYMENT_REQUIRED') {
        if (mounted) await showBillingBlockedSheet(context);
        return;
      }
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(error.message)));
      }
    } finally {
      if (mounted) setState(() => _busy.remove(offer.id));
    }
  }

  Future<void> _edit(TechnicianOffer offer) async {
    if (!await billingAllowsAction(context)) return;
    final priceController = TextEditingController(
      text: _money(offer.amountMinor).replaceAll(' ج', ''),
    );
    final noteController = TextEditingController(
      text: offer.data['note']?.toString() ?? '',
    );
    final titleAr = offer.data['serviceTitleAr']?.toString() ?? 'طلب خدمة';

    final changed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (context, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(ctx).viewInsets.bottom,
              ),
              child: Container(
                decoration: const BoxDecoration(
                  color: V2Colors.surface,
                  borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
                ),
                padding: const EdgeInsets.fromLTRB(20, 12, 20, 28),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      // Grab handle
                      Center(
                        child: Container(
                          width: 40,
                          height: 4,
                          decoration: BoxDecoration(
                            color: V2Colors.border,
                            borderRadius: BorderRadius.circular(4),
                          ),
                        ),
                      ),
                      const SizedBox(height: 16),
                      // Title & subtitle
                      Text(
                        'تعديل العرض',
                        style: const TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.w800,
                          color: V2Colors.ink,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        '$titleAr · متاح تعديل واحد',
                        style: const TextStyle(
                          fontSize: 12.5,
                          color: V2Colors.inkLight,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                      const SizedBox(height: 18),
                      // Price input card
                      const Text(
                        'السعر بالجنيه',
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w700,
                          color: V2Colors.inkMuted,
                        ),
                      ),
                      const SizedBox(height: 6),
                      Container(
                        height: 64,
                        padding: const EdgeInsets.symmetric(horizontal: 16),
                        decoration: BoxDecoration(
                          color: V2Colors.surface,
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(
                            color: V2Colors.primary,
                            width: 1.5,
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: V2Colors.primaryLight.withValues(
                                alpha: 0.6,
                              ),
                              blurRadius: 10,
                              spreadRadius: 2,
                            ),
                          ],
                        ),
                        child: Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: priceController,
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                style: const TextStyle(
                                  fontSize: 26,
                                  fontWeight: FontWeight.w800,
                                  color: V2Colors.ink,
                                  letterSpacing: -0.5,
                                ),
                                decoration: const InputDecoration(
                                  border: InputBorder.none,
                                  isDense: true,
                                  contentPadding: EdgeInsets.zero,
                                ),
                              ),
                            ),
                            const Text(
                              'جنيه',
                              style: TextStyle(
                                fontSize: 14,
                                fontWeight: FontWeight.w700,
                                color: V2Colors.inkLight,
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 5),
                      Text(
                        'السعر السابق ${_money(offer.amountMinor)}',
                        style: const TextStyle(
                          fontSize: 11,
                          color: V2Colors.inkLight,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                      const SizedBox(height: 16),
                      // Note field
                      const Text(
                        'ملاحظة',
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w700,
                          color: V2Colors.inkMuted,
                        ),
                      ),
                      const SizedBox(height: 6),
                      TextField(
                        controller: noteController,
                        maxLines: 2,
                        maxLength: 300,
                        onChanged: (_) => setSheetState(() {}),
                        decoration: InputDecoration(
                          hintText: 'السعر شامل قطع الغيار الأساسية...',
                          hintStyle: const TextStyle(
                            fontSize: 13,
                            color: V2Colors.inkLight,
                          ),
                          filled: true,
                          fillColor: V2Colors.surface,
                          contentPadding: const EdgeInsets.symmetric(
                            horizontal: 14,
                            vertical: 12,
                          ),
                          counterText: '',
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(14),
                            borderSide: const BorderSide(
                              color: V2Colors.border,
                            ),
                          ),
                          enabledBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(14),
                            borderSide: const BorderSide(
                              color: V2Colors.border,
                            ),
                          ),
                          focusedBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(14),
                            borderSide: const BorderSide(
                              color: V2Colors.primary,
                              width: 1.5,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(height: 4),
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          const Text(
                            'اختياري',
                            style: TextStyle(
                              fontSize: 11,
                              color: V2Colors.inkLight,
                            ),
                          ),
                          Text(
                            '${toArabicDigits(noteController.text.length)} / ٣٠٠',
                            style: const TextStyle(
                              fontSize: 11,
                              color: V2Colors.inkLight,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 20),
                      // Buttons
                      Row(
                        children: [
                          Expanded(
                            flex: 1,
                            child: OutlinedButton(
                              onPressed: () => Navigator.pop(ctx, false),
                              style: OutlinedButton.styleFrom(
                                minimumSize: const Size.fromHeight(50),
                                foregroundColor: V2Colors.ink,
                                side: const BorderSide(color: V2Colors.border),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                              ),
                              child: const Text(
                                'إلغاء',
                                style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            flex: 2,
                            child: ElevatedButton.icon(
                              onPressed: () => Navigator.pop(ctx, true),
                              icon: const Icon(Icons.check_rounded, size: 18),
                              label: const Text(
                                'حفظ',
                                style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                              style: ElevatedButton.styleFrom(
                                minimumSize: const Size.fromHeight(50),
                                backgroundColor: V2Colors.primary,
                                foregroundColor: Colors.white,
                                elevation: 0,
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    if (changed == true && mounted) {
      final parts = priceController.text.trim().split('.');
      final amount =
          RegExp(r'^\d+(\.\d{1,2})?$').hasMatch(priceController.text.trim())
          ? BigInt.parse(parts.first) * BigInt.from(100) +
                BigInt.parse(
                  parts.length == 1 ? '0' : parts.last.padRight(2, '0'),
                )
          : null;
      if (amount == null) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('راجع السعر وأدخل مبلغًا صحيحًا بالجنيه.'),
          ),
        );
      } else {
        setState(() => _busy.add(offer.id));
        try {
          await _api.updateOffer(offer.id, {
            if (amount.toString() != offer.amountMinor)
              'amountMinor': amount.toString(),
            'note': noteController.text.trim(),
          });
          await _load();
        } on TechnicianRequestsApiException catch (error) {
          if (error.code == 'COMMISSION_PAYMENT_REQUIRED') {
            if (mounted) await showBillingBlockedSheet(context);
            return;
          }
          if (mounted) {
            ScaffoldMessenger.of(
              context,
            ).showSnackBar(SnackBar(content: Text(error.message)));
          }
        } finally {
          if (mounted) setState(() => _busy.remove(offer.id));
        }
      }
    }
    priceController.dispose();
    noteController.dispose();
  }

  void _toggleTab(bool showHistory) {
    if (_showHistory == showHistory) return;
    setState(() {
      _showHistory = showHistory;
      _offers = [];
      _nextCursor = null;
      _loading = true;
      _loadingMore = false;
    });
    unawaited(_load());
  }

