  Widget _buildOfferCard(TechnicianOffer offer) {
    final isPending = offer.status == 'pending';
    final isAccepted = offer.status == 'accepted';
    final isRejected = offer.status == 'rejected';

    final revision = (offer.data['revision'] as num?)?.toInt() ?? 1;
    final maxRev = (offer.data['maxOfferRevisions'] as num?)?.toInt() ?? 2;
    final canEdit = revision < maxRev;

    final expiresAtStr = offer.data['expiresAt']?.toString() ?? '';
    final expiresAt = DateTime.tryParse(expiresAtStr);
    final remainingMinutes = expiresAt != null
        ? expiresAt.difference(DateTime.now()).inMinutes.clamp(0, 9999)
        : 0;

    final progressRatio = (remainingMinutes / 30.0).clamp(0.0, 1.0);
    final isUrgentCountdown = remainingMinutes < 6;

    final V2PillTone pillTone = isPending
        ? V2PillTone.amber
        : isAccepted
        ? V2PillTone.green
        : isRejected
        ? V2PillTone.red
        : V2PillTone.gray;

    final IconData pillIcon = isPending
        ? Icons.hourglass_top_rounded
        : isAccepted
        ? Icons.check_circle_rounded
        : isRejected
        ? Icons.cancel_rounded
        : Icons.do_not_disturb_on_rounded;

    final title = offer.data['serviceTitleAr']?.toString() ?? 'طلب خدمة';

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      decoration: BoxDecoration(
        color: V2Colors.surface,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: V2Colors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Top section: title, pill, price
          Padding(
            padding: const EdgeInsets.all(16),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        title,
                        style: const TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          color: V2Colors.ink,
                        ),
                      ),
                      const SizedBox(height: 6),
                      V2Pill(
                        label: _label(offer),
                        tone: pillTone,
                        icon: pillIcon,
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 12),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    const Text(
                      'عرضك',
                      style: TextStyle(
                        fontSize: 10.5,
                        fontWeight: FontWeight.w600,
                        color: V2Colors.inkLight,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Row(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.baseline,
                      textBaseline: TextBaseline.alphabetic,
                      children: [
                        Text(
                          _moneyDisplay(offer.amountMinor),
                          style: TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.w800,
                            letterSpacing: -0.5,
                            color: isPending || isAccepted
                                ? V2Colors.primary
                                : V2Colors.inkMuted,
                          ),
                        ),
                        const SizedBox(width: 3),
                        const Text(
                          'ج',
                          style: TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: V2Colors.inkMuted,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ],
            ),
          ),

          // If Pending: Validity & Actions
          if (isPending) ...[
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Row(
                        children: [
                          Icon(
                            Icons.timer_outlined,
                            size: 14,
                            color: isUrgentCountdown
                                ? V2Colors.danger
                                : V2Colors.amberMid,
                          ),
                          const SizedBox(width: 4),
                          const Text(
                            'الصلاحية المتبقية',
                            style: TextStyle(
                              fontSize: 11.5,
                              fontWeight: FontWeight.w600,
                              color: V2Colors.inkMuted,
                            ),
                          ),
                        ],
                      ),
                      Text(
                        '${toArabicDigits(remainingMinutes)} دقيقة',
                        style: TextStyle(
                          fontSize: 11.5,
                          fontWeight: FontWeight.w800,
                          color: isUrgentCountdown
                              ? V2Colors.danger
                              : V2Colors.ink,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  ClipRRect(
                    borderRadius: BorderRadius.circular(9),
                    child: Container(
                      height: 5,
                      color: V2Colors.soft,
                      alignment: AlignmentDirectional.centerStart,
                      child: FractionallySizedBox(
                        widthFactor: progressRatio,
                        child: Container(
                          decoration: BoxDecoration(
                            color: isUrgentCountdown
                                ? V2Colors.danger
                                : V2Colors.amberMid,
                            borderRadius: BorderRadius.circular(9),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const Divider(height: 1, thickness: 1, color: V2Colors.border),
            IntrinsicHeight(
              child: Row(
                children: [
                  // Edit offer button
                  Expanded(
                    child: InkWell(
                      onTap: _busy.contains(offer.id) || !canEdit
                          ? null
                          : () => unawaited(_edit(offer)),
                      borderRadius: const BorderRadius.only(
                        bottomRight: Radius.circular(20),
                      ),
                      child: Container(
                        height: 48,
                        alignment: Alignment.center,
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              Icons.edit_outlined,
                              size: 17,
                              color: canEdit
                                  ? V2Colors.primary
                                  : V2Colors.inkLight,
                            ),
                            const SizedBox(width: 6),
                            Text(
                              canEdit ? 'تعديل' : 'تعديل (استنفدت التعديلات)',
                              style: TextStyle(
                                fontSize: 13,
                                fontWeight: FontWeight.w700,
                                color: canEdit
                                    ? V2Colors.primary
                                    : V2Colors.inkLight,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                  const VerticalDivider(
                    width: 1,
                    thickness: 1,
                    color: V2Colors.border,
                  ),
                  // Withdraw offer button
                  Expanded(
                    child: InkWell(
                      onTap: _busy.contains(offer.id)
                          ? null
                          : () => unawaited(_withdraw(offer)),
                      borderRadius: const BorderRadius.only(
                        bottomLeft: Radius.circular(20),
                      ),
                      child: Container(
                        height: 48,
                        alignment: Alignment.center,
                        child: const Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              Icons.undo_rounded,
                              size: 17,
                              color: V2Colors.danger,
                            ),
                            SizedBox(width: 6),
                            Text(
                              'سحب',
                              style: TextStyle(
                                fontSize: 13,
                                fontWeight: FontWeight.w700,
                                color: V2Colors.danger,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }
