// ---------------------------------------------------------------------------
// Sparkline Painter for Earnings KPI
// ---------------------------------------------------------------------------
class SparklinePainter extends CustomPainter {
  const SparklinePainter({required this.color, required this.fillColor});

  final Color color;
  final Color fillColor;

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    final fillPath = Path();

    final w = size.width;
    final h = size.height;

    // Control points matching SVG path:
    // M0,32 C20,28 30,20 50,22 C70,24 85,10 105,14 C125,18 140,6 160,8 C175,10 190,4 200,6
    final p0 = Offset(0, h * 0.72);
    final p1 = Offset(w * 0.25, h * 0.50);
    final p2 = Offset(w * 0.525, h * 0.32);
    final p3 = Offset(w * 0.80, h * 0.18);
    final p4 = Offset(w, h * 0.14);

    path.moveTo(p0.dx, p0.dy);
    path.cubicTo(w * 0.10, h * 0.63, w * 0.15, h * 0.45, p1.dx, p1.dy);
    path.cubicTo(w * 0.35, h * 0.55, w * 0.42, h * 0.22, p2.dx, p2.dy);
    path.cubicTo(w * 0.62, h * 0.41, w * 0.70, h * 0.14, p3.dx, p3.dy);
    path.cubicTo(w * 0.87, h * 0.22, w * 0.95, h * 0.09, p4.dx, p4.dy);

    fillPath.addPath(path, Offset.zero);
    fillPath.lineTo(w, h);
    fillPath.lineTo(0, h);
    fillPath.close();

    final fillPaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [
          fillColor.withValues(alpha: 0.5),
          fillColor.withValues(alpha: 0.0),
        ],
      ).createShader(Rect.fromLTWH(0, 0, w, h))
      ..style = PaintingStyle.fill;

    canvas.drawPath(fillPath, fillPaint);

    final strokePaint = Paint()
      ..color = color
      ..strokeWidth = 2.5
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    canvas.drawPath(path, strokePaint);
  }

  @override
  bool shouldRepaint(covariant SparklinePainter oldDelegate) =>
      color != oldDelegate.color || fillColor != oldDelegate.fillColor;
}

