class TechnicianHeroCard extends StatelessWidget {
  const TechnicianHeroCard({
    required this.isOnline,
    required this.onToggleOnline,
    this.breakUntil,
    this.billingBlocked = false,
    this.workHours,
    this.onEditShift,
    this.onTakeBreak,
    super.key,
  });

  final SettingsWorkHours? workHours;
  final bool isOnline;
  final bool billingBlocked;
  final DateTime? breakUntil;
  final ValueChanged<bool> onToggleOnline;
  final VoidCallback? onEditShift;
  final VoidCallback? onTakeBreak;

  @override
  Widget build(BuildContext context) {
    final breakRemaining = breakUntil?.difference(DateTime.now());
    final isOnBreak = breakRemaining != null && breakRemaining > Duration.zero;
    return AnimatedContainer(
      duration: const Duration(milliseconds: 300),
      margin: const EdgeInsets.symmetric(horizontal: 20),
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: isOnline
              ? const [V2Colors.ink, Color(0xFF1A3730)]
              : const [Color(0xFF2A3A35), Color(0xFF3A4A45)],
        ),
        borderRadius: BorderRadius.circular(22),
        boxShadow: [
          BoxShadow(
            color: V2Colors.ink.withValues(alpha: 0.35),
            blurRadius: 24,
            offset: const Offset(0, 12),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Top Row: Live status + switch
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    width: 12,
                    height: 12,
                    decoration: BoxDecoration(
                      color: isOnline
                          ? const Color(0xFF22C55E)
                          : const Color(0xFF94A3B8),
                      shape: BoxShape.circle,
                      boxShadow: isOnline
                          ? [
                              BoxShadow(
                                color: const Color(
                                  0xFF22C55E,
                                ).withValues(alpha: 0.45),
                                blurRadius: 8,
                                spreadRadius: 3,
                              ),
                            ]
                          : null,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        billingBlocked
                            ? 'الخدمة متوقفة · سدد المستحقات'
                            : isOnline
                            ? isOnBreak
                                  ? 'في استراحة · استقبال الطلبات متوقف'
                                  : workHours?.isAvailableNow == false
                                  ? 'متصل · الطلبات واقفة دلوقتي'
                                  : 'متصل الآن — تستقبل الطلبات'
                            : 'غير متصل — الطلبات موقوفة',
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        isOnline
                            ? isOnBreak
                                  ? 'هترجع متاح تلقائيًا بعد انتهاء الاستراحة'
                                  : workHours == null
                                  ? 'بنحمّل مواعيد شغلك'
                                  : workHours!.isAvailableNow
                                  ? 'متاح حسب إعدادات شغلك'
                                  : 'الطلبات واقفة حسب مواعيدك أو إجازتك'
                            : 'لن تصلك طلبات جديدة حتى تعود للاتصال',
                        style: TextStyle(
                          color: Colors.white.withValues(alpha: 0.6),
                          fontSize: 11,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
              GestureDetector(
                key: const ValueKey('online_toggle_switch'),
                onTap: () => onToggleOnline(!isOnline),
                behavior: HitTestBehavior.opaque,
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 250),
                  width: 56,
                  height: 32,
                  padding: const EdgeInsets.all(3),
                  decoration: BoxDecoration(
                    color: isOnline
                        ? V2Colors.primary
                        : Colors.white.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: Colors.white.withValues(alpha: 0.15),
                    ),
                  ),
                  alignment: isOnline
                      ? Alignment.centerRight
                      : Alignment.centerLeft,
                  child: Container(
                    width: 24,
                    height: 24,
                    child: billingBlocked
                        ? const Icon(
                            Icons.lock_outline,
                            size: 16,
                            color: V2Colors.ink,
                          )
                        : null,
                    decoration: BoxDecoration(
                      color: isOnline ? Colors.white : const Color(0xFF8A9994),
                      shape: BoxShape.circle,
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withValues(alpha: 0.25),
                          blurRadius: 4,
                          offset: const Offset(0, 2),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
