              '${toArabicDigits(workHours!.weeklyMinutes % 60)} دقيقة في الأسبوع · '
              '${toArabicDigits(workHours!.openDays.length)} أيام عمل',
              style: TextStyle(
                color: Colors.white.withValues(alpha: 0.88),
                fontSize: 13,
                fontWeight: FontWeight.w600,
              ),
            ),
          if (breakUntil != null) ...[
            const SizedBox(height: 8),
            if (isOnBreak)
              Row(
                children: [
                  Expanded(
                    child: Text(
