// ---------------------------------------------------------------------------
// Urgent Alerts Strip
// ---------------------------------------------------------------------------
class TechnicianAlertItem {
  const TechnicianAlertItem({
    required this.icon,
    required this.title,
    required this.subtitle,
    required this.actionLabel,
    required this.type,
    this.onAction,
  });

  final IconData icon;
  final String title;
  final String subtitle;
  final String actionLabel;
  final AlertType type;
  final VoidCallback? onAction;
}

enum AlertType { error, warning, info }

class TechnicianAlertsStrip extends StatelessWidget {
  const TechnicianAlertsStrip({required this.alerts, super.key});

  final List<TechnicianAlertItem> alerts;

  @override
  Widget build(BuildContext context) {
    if (alerts.isEmpty) return const SizedBox.shrink();

    return SizedBox(
      height: 74,
      child: ListView.separated(
        padding: const EdgeInsets.symmetric(horizontal: 20),
        scrollDirection: Axis.horizontal,
        itemCount: alerts.length,
        separatorBuilder: (_, _) => const SizedBox(width: 10),
        itemBuilder: (context, index) {
          final alert = alerts[index];
          final (bgColor, iconBg, iconColor) = switch (alert.type) {
            AlertType.error => (
              V2Colors.surface,
              V2Colors.dangerSoft,
              V2Colors.danger,
            ),
            AlertType.warning => (
              V2Colors.surface,
              V2Colors.amber,
              V2Colors.amberMid,
            ),
            AlertType.info => (
              V2Colors.surface,
              V2Colors.infoSoft,
              V2Colors.info,
            ),
          };

          return Container(
            width: 300,
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: bgColor,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: V2Colors.border),
            ),
            child: Row(
              children: [
                Container(
                  width: 38,
                  height: 38,
                  decoration: BoxDecoration(
                    color: iconBg,
                    borderRadius: BorderRadius.circular(11),
                  ),
                  child: Icon(alert.icon, size: 20, color: iconColor),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        alert.title,
                        style: const TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w800,
                          color: V2Colors.ink,
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                      const SizedBox(height: 2),
                      Text(
                        alert.subtitle,
                        style: const TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w500,
                          color: V2Colors.inkMuted,
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                InkWell(
                  onTap: alert.onAction,
                  borderRadius: BorderRadius.circular(9),
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 7,
                    ),
                    decoration: BoxDecoration(
                      color: V2Colors.ink,
                      borderRadius: BorderRadius.circular(9),
                    ),
                    child: Text(
                      alert.actionLabel,
                      style: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w700,
                        color: Colors.white,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

