                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      flex: 2,
                      child: ElevatedButton.icon(
                        onPressed: onFinishJob,
                        icon: const Icon(Icons.check_rounded, size: 16),
                        label: const Text('إنهاء المهمة'),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: V2Colors.primary,
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(vertical: 12),
                          elevation: 0,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                          textStyle: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildStepsProgress(int step) {
    const stepTitles = ['القبول', 'التوجّه', 'التنفيذ', 'التسليم'];

    return Row(
      children: List.generate(stepTitles.length * 2 - 1, (index) {
        if (index.isOdd) {
          final lineIndex = index ~/ 2;
          final isDone = lineIndex < (step - 1);
          return Expanded(
            child: Container(
              height: 2,
              color: isDone ? V2Colors.primary : V2Colors.soft,
              margin: const EdgeInsets.only(bottom: 14),
            ),
          );
        }

        final itemIndex = index ~/ 2;
        final isDone = itemIndex < (step - 1);
        final isCurrent = itemIndex == (step - 1);

        return Column(
          children: [
            Container(
              width: 24,
              height: 24,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: isDone
                    ? V2Colors.primary
                    : isCurrent
                    ? Colors.white
                    : V2Colors.soft,
                border: Border.all(
                  color: isDone || isCurrent ? V2Colors.primary : V2Colors.soft,
                  width: 2,
                ),
                boxShadow: isCurrent
                    ? [
                        BoxShadow(
                          color: V2Colors.primary.withValues(alpha: 0.2),
                          spreadRadius: 3,
                        ),
                      ]
                    : null,
              ),
              child: Center(
                child: isDone
                    ? const Icon(Icons.check, size: 12, color: Colors.white)
                    : Text(
                        toArabicDigits(itemIndex + 1),
                        style: TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.w800,
                          color: isCurrent
                              ? V2Colors.primary
                              : V2Colors.inkLight,
                        ),
                      ),
              ),
            ),
            const SizedBox(height: 4),
            Text(
              stepTitles[itemIndex],
              style: TextStyle(
                fontSize: 10,
                fontWeight: FontWeight.w700,
                color: isDone || isCurrent ? V2Colors.ink : V2Colors.inkLight,
              ),
            ),
          ],
        );
      }),
    );
  }
}

