}import 'dart:async';
import 'dart:convert';

import 'package:fixit_pro/app/configuration/app_config.dart';
import 'package:fixit_pro/core/networking/api_uri.dart';
import 'package:fixit_pro/core/networking/backend_http_client.dart';
import 'package:fixit_pro/core/networking/responses/bounded_http_response.dart';
import 'package:fixit_pro/core/storage/secure/auth_session_store.dart';
import 'package:fixit_pro/features/authentication/data/models/auth_session.dart';
import 'package:http/http.dart' as http;
import 'package:uuid/uuid.dart';

class PresenceApiException implements Exception {
  const PresenceApiException(
    this.message, {
    this.statusCode,
    this.retryAfter,
    this.code,
    this.isAmbiguous = false,
  });
  final String message;
  final int? statusCode;
  final String? code;
  final Duration? retryAfter;

  /// True when the server may have committed a mutation but its response was lost.
  final bool isAmbiguous;
  @override
  String toString() => message;
}

class PresenceState {
  const PresenceState({required this.online, this.breakUntil});
  factory PresenceState.fromJson(Map<String, Object?> j) {
    final online = j['online'];
    final rawBreak = j['breakUntil'];
    if (online is! bool || (rawBreak != null && rawBreak is! String)) {
      throw const FormatException('Invalid presence state');
    }
    final breakUntil = rawBreak == null
        ? null
        : DateTime.tryParse(rawBreak as String);
    if (rawBreak != null && breakUntil == null) {
      throw const FormatException('Invalid break date');
    }
    return PresenceState(online: online, breakUntil: breakUntil);
  }
  final bool online;
  final DateTime? breakUntil;
}

abstract interface class PresenceRepository {
  Future<PresenceState> getState();
  Future<PresenceState> reconcileAmbiguousMutation();
  Future<PresenceState> setOnline(bool online);
  Future<PresenceState> takeBreak(int minutes);
  Future<void> heartbeat();
}

class PresenceApi implements PresenceRepository {
  PresenceApi({
    required Uri baseUri,
    required AuthSessionStore sessionStore,
    Future<bool> Function()? ensureSession,
    http.Client? client,
  }) : _baseUri = baseUri,
       _store = sessionStore,
       _ensureSession = ensureSession,
       _client = client ?? BackendHttpClient(),
       _ownsClient = client == null;
  factory PresenceApi.fromEnvironment({
    Future<bool> Function()? ensureSession,
  }) => PresenceApi(
    baseUri: AppConfig.fromEnvironment().backendBaseUri,
    sessionStore: SecureAuthSessionStore(),
    ensureSession: ensureSession,
  );
  final Uri _baseUri;
  final AuthSessionStore _store;
  final Future<bool> Function()? _ensureSession;
  final http.Client _client;
  final bool _ownsClient;
  static const int _maxResponseBytes = 64 * 1024;
  final Map<String, String> _pendingMutationKeys = {};
  final Map<String, (String, String, Map<String, Object?>?)> _pendingMutations =
      {};
  void close() {
    if (_ownsClient) _client.close();
  }

  @override
  Future<PresenceState> getState() =>
      _send('GET', '/v1/technician/presence', null);
  @override
  Future<PresenceState> reconcileAmbiguousMutation() async {
    // Replay with the original key before reading. A timed-out request can
    // still commit after an earlier GET, so that GET cannot settle its outcome.
    for (final pending in _pendingMutations.values.toList()) {
      await _send(pending.$1, pending.$2, pending.$3);
    }
    return getState();
  }

  @override
  Future<PresenceState> setOnline(bool online) =>
      _send('PUT', '/v1/technician/presence', {'online': online});
  @override
  Future<PresenceState> takeBreak(int minutes) =>
      _send('PUT', '/v1/technician/presence', {'breakMinutes': minutes});
  @override
  Future<void> heartbeat() async {
    await _send(
      'POST',
      '/v1/technician/presence/heartbeat',
      null,
      includeIdempotencyKey: false,
    );
  }

  Future<PresenceState> _send(
    String method,
    String path,
    Map<String, Object?>? body, {
    bool includeIdempotencyKey = true,
  }) async {
    try {
      var session = await _session();
      final fingerprint = method == 'GET' || !includeIdempotencyKey
          ? null
          : '$path|${jsonEncode(body)}';
      final key = fingerprint == null
          ? null
          : _pendingMutationKeys.putIfAbsent(
              fingerprint,
              () => const Uuid().v4(),
            );
      if (fingerprint != null) {
        _pendingMutations[fingerprint] = (method, path, body);
      }
      Future<http.Response> send(AuthSession activeSession) async {
        final request = http.Request(method, _baseUri.resolveApiPath(path))
          ..headers.addAll(_headers(activeSession));
        if (method != 'GET' && key != null) {
          request.headers['Idempotency-Key'] = key;
        }
        if (body != null) {
          request.headers['content-type'] = 'application/json; charset=utf-8';
          request.body = jsonEncode(body);
        }
        final streamed = await _client.send(request);
        return readBoundedHttpResponse(streamed, maxBytes: _maxResponseBytes);
      }

      var response = await send(session).timeout(const Duration(seconds: 20));
      final refresh = _ensureSession;
      if (response.statusCode == 401 && refresh != null && await refresh()) {
        final next = await _store.readSession();
        if (next != null) {
          session = next;
          response = await send(session).timeout(const Duration(seconds: 20));
        }
      }
      if (response.statusCode < 200 || response.statusCode >= 300) {
        final retrySeconds = int.tryParse(
          response.headers['retry-after'] ?? '',
        );
        throw PresenceApiException(
          _error(response).message,
          statusCode: response.statusCode,
          code: _error(response).code,
          retryAfter: retrySeconds == null
              ? null
              : Duration(seconds: retrySeconds.clamp(1, 3600).toInt()),
          isAmbiguous: response.statusCode >= 500 && fingerprint != null,
        );
      }
      final decoded = response.body.isEmpty
          ? <String, Object?>{}
          : jsonDecode(response.body);
      if (decoded is! Map) {
        throw PresenceApiException(
          'استجابة الخادم غير صالحة.',
          isAmbiguous: fingerprint != null,
        );
      }
      final PresenceState state;
      if (path.endsWith('/heartbeat')) {
        if (decoded['lastSeenAt'] is! String ||
            DateTime.tryParse(decoded['lastSeenAt'] as String) == null) {
          throw const FormatException('Invalid heartbeat response');
        }
        state = const PresenceState(online: true);
      } else {
        state = PresenceState.fromJson(decoded.cast<String, Object?>());
      }
      if (fingerprint != null) {
        _pendingMutationKeys.remove(fingerprint);
        _pendingMutations.remove(fingerprint);
      }
      return state;
    } on PresenceApiException catch (error) {
      if (!error.isAmbiguous && method != 'GET' && includeIdempotencyKey) {
        _pendingMutationKeys.remove('$path|${jsonEncode(body)}');
        _pendingMutations.remove('$path|${jsonEncode(body)}');
      }
      rethrow;
    } on TimeoutException {
      throw PresenceApiException(
        'الاتصال أخد وقت طويل. بنراجع الحالة الحالية.',
        isAmbiguous: method != 'GET' && includeIdempotencyKey,
      );
    } on http.ClientException {
      throw PresenceApiException(
        'الرد انقطع. بنراجع الحالة الحالية.',
        isAmbiguous: method != 'GET' && includeIdempotencyKey,
      );
    } on ResponseTooLargeException {
      throw PresenceApiException(
        'استجابة الخادم كبيرة جدًا.',
        isAmbiguous: method != 'GET' && includeIdempotencyKey,
      );
    } on FormatException {
      throw PresenceApiException(
        'استجابة الخادم غير صالحة.',
        isAmbiguous: method != 'GET' && includeIdempotencyKey,
      );
    } on Object {
      throw PresenceApiException(
        'تعذر تحديث حالة الاتصال. حاول مرة تانية.',
        isAmbiguous: method != 'GET' && includeIdempotencyKey,
      );
    }
  }

  Map<String, String> _headers(AuthSession s) => {
    'accept': 'application/json',
    'authorization': 'Bearer ${s.accessToken}',
  };
  Future<AuthSession> _session() async {
    var s = await _store.readSession();
    if (s != null && s.isAccessTokenUsable(DateTime.now())) return s;
    final refresh = _ensureSession;
    if (refresh != null && await refresh()) {
      s = await _store.readSession();
      if (s != null) return s;
    }
    throw const PresenceApiException(
      'الجلسة منتهية. سجّل الدخول مرة تانية.',
      statusCode: 401,
    );
  }

  ({String message, String? code}) _error(http.Response r) {
    try {
      final d = jsonDecode(r.body);
      if (d is Map && d['message'] is String)
        return (message: d['message'] as String, code: d['code'] as String?);
    } catch (_) {}
    return (message: 'تعذر تحديث حالة الاتصال.', code: null);
  }
}import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';
