class CommissionStatement {
  const CommissionStatement(this.data);
  factory CommissionStatement.fromJson(Json json) =>
      CommissionStatement(json.value);
  final Map<String, Object?> data;
  String get id => data['id'] as String;
  String get status => data['status'] as String;
  int get amountDueMinor => data['amountDueMinor'] as int;
  int get version => data['version'] as int;
  String get periodLabel =>
      data['periodLabel']?.toString() ??
      data['periodMonth'].toString().substring(0, 7);
  List<Map<String, Object?>> get items => (data['items'] as List? ?? [])
      .map((v) => Map<String, Object?>.from(v as Map))
      .toList();
  List<CommissionSubmission> get submissions =>
      (data['submissions'] as List? ?? [])
          .map((v) => CommissionSubmission.fromJson(Json.from(v)))
          .toList();
}import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';

class CommissionSubmission {
  const CommissionSubmission(this.data);
  factory CommissionSubmission.fromJson(Json json) =>
      CommissionSubmission(json.value);
  final Map<String, Object?> data;
  String get id => data['id'] as String;
  String get status => data['status'] as String;
  int get version => data['version'] as int? ?? 1;
  DateTime get submittedAt =>
      DateTime.parse((data['submittedAt'] ?? data['createdAt']) as String);
  DateTime get reviewDueAt => DateTime.parse(data['reviewDueAt'] as String);
  String? get rejectionReason => data['rejectionReason'] as String?;
  DateTime? get reviewedAt =>
      DateTime.tryParse(data['reviewedAt']?.toString() ?? '');
}import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';
