class CommissionSummary {
  const CommissionSummary({
    required this.blocked,
    required this.state,
    required this.totalDueMinor,
    required this.commissionBps,
    this.oldestDueStatementId,
    this.periodLabel,
    this.latestSubmission,
  });
  factory CommissionSummary.fromJson(Json j) => CommissionSummary(
    blocked: j.value['blocked'] == true,
    state: j.string('state'),
    totalDueMinor: j.integer('totalDueMinor'),
    commissionBps: j.integer('commissionBps'),
    oldestDueStatementId: j.nullableString('oldestDueStatementId'),
    periodLabel: j.nullableString('periodLabel'),
    latestSubmission: j.value['latestSubmission'] == null
        ? null
        : CommissionSubmission.fromJson(Json.from(j.value['latestSubmission'])),
  );
  final bool blocked;
  final String state;
  final int totalDueMinor, commissionBps;
  final String? oldestDueStatementId, periodLabel;
  final CommissionSubmission? latestSubmission;
}import 'package:fixit_pro/features/admin/domain/entities/admin_finance_entities.dart';

