class CommissionBillingException implements Exception {
  const CommissionBillingException(this.message, {this.code, this.statusCode});
  final String message;
  final String? code;
  final int? statusCode;
  @override
  String toString() => message;
}

class CommissionBillingApi {
  CommissionBillingApi({
    Uri? baseUri,
    AuthSessionStore? sessionStore,
    http.Client? client,
  }) : _baseUri = baseUri ?? AppConfig.fromEnvironment().backendBaseUri,
       _store = sessionStore ?? SecureAuthSessionStore(),
       _client = client ?? BackendHttpClient();
  final Uri _baseUri;
  final AuthSessionStore _store;
  final http.Client _client;
  void close() => _client.close();
  Future<Object?> request(
    String method,
    String path, {
    Map<String, Object?>? body,
    Map<String, String>? query,
  }) async {
    final session = await _store.readSession();
    if (session == null) {
      throw const CommissionBillingException(
        'انتهت جلسة الدخول.',
        statusCode: 401,
      );
    }
    final uri = _baseUri.resolveApiPath(path).replace(queryParameters: query);
    requireSecureCredentialUri(uri);
    final headers = {
      'authorization': 'Bearer ${session.accessToken}',
      'accept': 'application/json',
      'content-type': 'application/json',
    };
    final response = await (switch (method) {
      'POST' => _client.post(uri, headers: headers, body: jsonEncode(body)),
      'PATCH' => _client.patch(uri, headers: headers, body: jsonEncode(body)),
      _ => _client.get(uri, headers: headers),
    }).timeout(const Duration(seconds: 30));
    Object? decoded;
    try {
      decoded = jsonDecode(response.body);
    } catch (_) {
      throw const CommissionBillingException(
        'استجابة الخادم مش صحيحة. جرّب تاني.',
      );
    }
    if (response.statusCode < 200 || response.statusCode >= 300) {
      final d = decoded is Map ? decoded : const <String, Object?>{};
      throw CommissionBillingException(
        d['message'] is String ? d['message'] as String : 'تعذر تنفيذ العملية.',
        code: d['code'] as String?,
        statusCode: response.statusCode,
      );
    }
    return decoded;
  }

  static const _prefix = '/v1/technician/commission';
  Future<CommissionSummary> summary() async => CommissionSummary.fromJson(
    Json.from(await request('GET', '$_prefix/summary')),
  );
  Future<Map<String, Object?>> currentMonth() async =>
      Json.from(await request('GET', '$_prefix/current-month')).value;
  Future<AdminFinancePage<CommissionStatement>> statements({
    String? cursor,
  }) async {
    final j = Json.from(
      await request('GET', '$_prefix/statements', query: {'cursor': ?cursor}),
    );
    return AdminFinancePage(
      items: j
          .list('items')
          .map((v) => CommissionStatement.fromJson(Json.from(v)))
          .toList(),
      nextCursor: j.nullableString('nextCursor'),
    );
  }

  Future<CommissionStatement> statement(String id) async =>
      CommissionStatement.fromJson(
        Json.from(await request('GET', '$_prefix/statements/$id')),
      );
  Future<List<CompanyPaymentMethod>> methods() async =>
      (await request('GET', '$_prefix/payment-methods') as List)
          .map((v) => CompanyPaymentMethod.fromJson(Json.from(v)))
          .toList();
  Future<CommissionSubmission> submit(
    String id,
    Map<String, Object?> body,
  ) async => CommissionSubmission.fromJson(
    Json.from(
      await request('POST', '$_prefix/statements/$id/submissions', body: body),
    ),
  );
}import 'package:fixit_pro/app/routing/routes/app_routes.dart';
import 'package:fixit_pro/features/technician-billing/data/commission_billing_api.dart';
import 'package:fixit_pro/features/technician-billing/data/models/commission_statement.dart';
import 'package:fixit_pro/features/technician-billing/presentation/widgets/billing_status_banner.dart';
import 'package:flutter/material.dart';

class TechCommissionPage extends StatefulWidget {
  const TechCommissionPage({super.key});
  @override
  State<TechCommissionPage> createState() => _TechCommissionPageState();
}

class _TechCommissionPageState extends State<TechCommissionPage> {
  final _api = CommissionBillingApi();
  Map<String, Object?>? _month;
  List<CommissionStatement> _statements = [];
  String? _cursor, _error;
  bool _loading = true;
  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _api.close();
    super.dispose();
  }

  Future<void> _load({bool more = false}) async {
    setState(() => _loading = true);
    try {
      final month = await _api.currentMonth();
      final page = await _api.statements(cursor: more ? _cursor : null);
      if (mounted) {
        setState(() {
          _month = month;
          _statements = more ? [..._statements, ...page.items] : page.items;
          _cursor = page.nextCursor;
          _error = null;
        });
      }
    } catch (e) {
      if (mounted) setState(() => _error = 'تعذر تحميل المستحقات. حاول تاني.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('مستحقات المنصة')),
    body: RefreshIndicator(
      onRefresh: () => _load(),
      child: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          if (_error != null)
            TextButton(onPressed: () => _load(), child: Text(_error!)),
          if (_month case final m?)
            Card(
              child: Padding(
                padding: const EdgeInsets.all(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'الشهر الحالي',
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                    const SizedBox(height: 12),
                    Text(
                      'المصنعية لحد النهارده: ${billingMoney(m['laborTotalMinor'] as int)}',
                    ),
                    Text(
                      'عدد الطلبات: ${billingDigits('${m['ordersCount']}')}',
                    ),
                    Text(
                      'العمولة المتوقعة ${billingDigits('${(m['commissionBps'] as int) / 100}')}٪: ${billingMoney(m['estimatedCommissionMinor'] as int)}',
                    ),
                  ],
                ),
              ),
            ),
          const SizedBox(height: 24),
          Text('سجل الكشوف', style: Theme.of(context).textTheme.titleLarge),
          if (!_loading && _statements.isEmpty)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 32),
              child: Text('مفيش كشوف حساب لحد دلوقتي.'),
            ),
          for (final s in _statements)
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: Text(s.periodLabel),
              subtitle: Text(billingMoney(s.amountDueMinor)),
              trailing: Chip(label: Text(billingStateLabel(s.status))),
              onTap: () async {
                await Navigator.of(
                  context,
                ).pushNamed(AppRoutes.techCommissionStatement, arguments: s.id);
                if (mounted) _load();
              },
            ),
          if (_loading) const Center(child: CircularProgressIndicator()),
          if (_cursor != null && !_loading)
            TextButton(
              onPressed: () => _load(more: true),
              child: const Text('عرض المزيد'),
            ),
        ],
      ),
    ),
  );
}import 'package:fixit_pro/features/service-request/data/services/device_photo_picker_service.dart';
import 'package:fixit_pro/features/service-request/data/services/photo_upload_api.dart';
import 'package:fixit_pro/features/service-request/domain/services/photo_upload_service.dart';
import 'package:fixit_pro/features/technician-billing/data/commission_billing_api.dart';
import 'package:fixit_pro/features/technician-billing/data/models/commission_statement.dart';
import 'package:fixit_pro/features/technician-billing/data/models/company_payment_method.dart';
import 'package:fixit_pro/features/technician-billing/presentation/widgets/billing_status_banner.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:uuid/uuid.dart';

class TechCommissionPayPage extends StatefulWidget {
  const TechCommissionPayPage({required this.statementId, super.key});
  final String statementId;
  @override
  State<TechCommissionPayPage> createState() => _TechCommissionPayPageState();
}

class _TechCommissionPayPageState extends State<TechCommissionPayPage> {
  final _api = CommissionBillingApi();
  final _upload = PhotoUploadApi.fromEnvironment();
  final _picker = DevicePhotoPickerService();
  final _idempotencyKey = const Uuid().v4();
  final _sender = TextEditingController(), _reference = TextEditingController();
  CommissionStatement? _statement;
  List<CompanyPaymentMethod> _methods = [];
  CompanyPaymentMethod? _method;
  RequestPhotoMedia? _photo;
  Uint8List? _preview;
  String? _fileId, _error;
  bool _busy = false, _loading = true, _success = false;
  int _reviewHours = 12;
  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _api.close();
    _upload.close();
    _sender.dispose();
    _reference.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final s = await _api.statement(widget.statementId);
      final methods = await _api.methods();
      if (mounted) {
        setState(() {
          _statement = s;
          _methods = methods;
          _error = null;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() => _error = 'تعذر تحميل بيانات الدفع. حاول تاني.');
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _pick(RequestPhotoSource source) async {
    try {
      final photo = await _picker.pickPhoto(source);
      if (photo == null) return;
      if (photo.sizeBytes > 8 * 1024 * 1024) {
        throw const PhotoUploadException(
          'صورة التحويل لازم تكون أقل من ٨ ميجابايت.',
        );
      }
      final bytes =
          photo.bytes ??
          Uint8List.fromList(
            await photo.openRead!().fold<List<int>>([], (a, b) => a..addAll(b)),
          );
      if (mounted) {
        setState(() {
          _photo = photo;
          _preview = bytes;
          _fileId = null;
          _error = null;
        });
      }
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    }
  }

  Future<void> _submit() async {
    if (_busy || _photo == null || _method == null) return;
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      _fileId ??= await _upload.uploadMedia(
        _photo!,
        purpose: 'commission_payment_proof',
      );
      final submission = await _api.submit(widget.statementId, {
        'paymentMethodId': _method!.id,
        'proofFileId': _fileId,
        'senderAccount': _sender.text.trim(),
        'transferReference': _reference.text.trim(),
        'idempotencyKey': _idempotencyKey,
      });
      if (mounted)
        setState(() {
          _success = true;
          _reviewHours =
              (submission.reviewDueAt
                          .difference(submission.submittedAt)
                          .inMinutes /
                      60)
                  .ceil();
        });
    } catch (e) {
      if (mounted) {
        setState(
          () => _error =
              e is CommissionBillingException || e is PhotoUploadException
              ? e.toString()
              : 'تعذر الإرسال. جرّب تاني بنفس البيانات.',
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _copy(String value) async {
    await Clipboard.setData(ClipboardData(text: value));
    if (mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('اتنسخ')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final s = _statement;
    return Scaffold(
      appBar: AppBar(title: const Text('سداد مستحقات المنصة')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _success
          ? Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.check_circle_outline, size: 64),
                    const SizedBox(height: 20),
                    Text(
                      'استلمنا إثبات التحويل، وهنراجعه خلال ${billingDigits('$_reviewHours')} ساعة',
                      textAlign: TextAlign.center,
                    ),
                    const SizedBox(height: 20),
                    FilledButton(
                      onPressed: () => Navigator.pop(context, true),
                      child: const Text('تم'),
                    ),
                  ],
                ),
              ),
            )
          : s == null
          ? Center(
              child: TextButton(
                onPressed: _load,
                child: Text(_error ?? 'حاول تاني'),
              ),
            )
          : s.status != 'due'
          ? Center(
              child: Text(
                s.status == 'under_review'
                    ? 'إثبات الدفع قيد المراجعة بالفعل.'
                    : 'كشف الحساب متسدد بالفعل.',
              ),
            )
          : ListView(
              padding: const EdgeInsets.all(20),
              children: [
                if (_error != null)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 16),
                    child: Text(
                      _error!,
                      style: TextStyle(
                        color: Theme.of(context).colorScheme.error,
                      ),
                    ),
                  ),
                Text(
                  '١. المبلغ المستحق',
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  title: Text(
                    billingMoney(s.amountDueMinor),
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  subtitle: Text(s.periodLabel),
                  trailing: IconButton(
                    tooltip: 'نسخ المبلغ',
                    onPressed: () =>
                        _copy((s.amountDueMinor / 100).toStringAsFixed(2)),
                    icon: const Icon(Icons.copy),
                  ),
                ),
                const SizedBox(height: 24),
                Text(
                  '٢. اختار طريقة الدفع',
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                if (_methods.isEmpty)
                  const Text('مفيش طرق دفع متاحة حاليًا. حاول تاني لاحقًا.'),
                for (final m in _methods)
                  Card(
                    child: Column(
                      children: [
                        RadioListTile<String>(
                          value: m.id,
                          groupValue: _method?.id,
                          onChanged: _busy
                              ? null
                              : (_) => setState(() => _method = m),
                          title: Text(m.label),
                          subtitle: Text(
                            '${m.accountValue}\n${m.accountHolder}',
                          ),
                          secondary: Icon(
                            m.methodType == 'bank_account'
                                ? Icons.account_balance
                                : m.methodType == 'instapay'
                                ? Icons.bolt
                                : Icons.account_balance_wallet_outlined,
                          ),
                        ),
                        if (m.instructions?.isNotEmpty == true)
                          Padding(
                            padding: const EdgeInsets.all(12),
                            child: Text(m.instructions!),
                          ),
                        TextButton.icon(
                          onPressed: () => _copy(m.accountValue),
                          icon: const Icon(Icons.copy),
