Future<void> showBillingBlockedSheet(
  BuildContext context, {
  CommissionSummary? summary,
  Future<void> Function()? onReturn,
}) => showModalBottomSheet<void>(
  context: context,
  showDragHandle: true,
  useSafeArea: true,
  builder: (ctx) => Padding(
    padding: const EdgeInsets.fromLTRB(24, 8, 24, 24),
    child: Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        const Icon(Icons.lock_outline, size: 32),
        const SizedBox(height: 16),
        const Text(
          'يرجى سداد مستحقات المنصة لتستمر الخدمة.',
          textAlign: TextAlign.center,
        ),
        const SizedBox(height: 8),
        const Text(
          'تقدر تتصفح التطبيق وتكمّل طلباتك الشغالة عادي.',
          textAlign: TextAlign.center,
        ),
        const SizedBox(height: 20),
        FilledButton(
          onPressed: () async {
            Navigator.pop(ctx);
            await Navigator.of(context).pushNamed(
              summary?.oldestDueStatementId == null
                  ? AppRoutes.techCommission
                  : AppRoutes.techCommissionPay,
              arguments: summary?.oldestDueStatementId,
            );
            await onReturn?.call();
          },
          child: const Text('عرض المستحقات والدفع'),
        ),
      ],
    ),
  ),
);

/// Check immediately before a dispatch action; a changed server state still gets caught by its error code.
Future<bool> billingAllowsAction(
  BuildContext context, {
  Future<CommissionSummary> Function()? loadSummary,
}) async {
  final api = CommissionBillingApi();
  try {
    final summary = await (loadSummary ?? api.summary)();
    if (!context.mounted) return false;
    if (summary.blocked) {
      await showBillingBlockedSheet(context, summary: summary);
      return false;
    }
    return true;
  } catch (error) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذر التحقق من المستحقات. حاول تاني.')),
      );
    }
    return false;
  } finally {
    api.close();
  }
}import 'dart:async';

import 'package:fixit_pro/app/routing/routes/app_routes.dart';
