String billingDigits(String value) => value.replaceAllMapped(
  RegExp('[0-9]'),
  (m) => '٠١٢٣٤٥٦٧٨٩'[int.parse(m[0]!)],
);
String billingMoney(int minor) =>
    '${billingDigits((minor / 100).toStringAsFixed(minor % 100 == 0 ? 0 : 2))} ج.م';
String billingDate(Object? value) {
  final date = DateTime.tryParse(value?.toString() ?? '')?.toLocal();
  if (date == null) return '—';
  return billingDigits(
    '${date.day}/${date.month}/${date.year} ${date.hour.toString().padLeft(2, '0')}:${date.minute.toString().padLeft(2, '0')}',
  );
}

String billingStateLabel(String state) => switch (state) {
  'due' => 'مستحق',
  'under_review' => 'قيد المراجعة',
  'pending' => 'قيد المراجعة',
  'paid' => 'مدفوع',
  'approved' => 'اتأكد',
  'rejected' => 'مرفوض',
  'waived' => 'معفي',
  _ => state,
};

class BillingStatusBanner extends StatefulWidget {
  const BillingStatusBanner({required this.summary, super.key, this.onChanged});
  final CommissionSummary summary;
  final VoidCallback? onChanged;
  @override
  State<BillingStatusBanner> createState() => _BillingStatusBannerState();
}

class _BillingStatusBannerState extends State<BillingStatusBanner> {
  Timer? _timer;
  bool _dismissed = false;
  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
    _readDismissal();
  }

  Future<void> _readDismissal() async {
    final prefs = await SharedPreferences.getInstance();
    if (mounted) {
      setState(
        () => _dismissed =
            prefs.getString('billing.approval.dismissed') ==
            widget.summary.latestSubmission?.id,
      );
    }
  }

  @override
  void didUpdateWidget(covariant BillingStatusBanner oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.summary.latestSubmission?.id !=
        widget.summary.latestSubmission?.id) {
      _dismissed = false;
      _readDismissal();
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final s = widget.summary;
    final approved = s.latestSubmission?.status == 'approved';
    final reviewed = s.latestSubmission?.reviewedAt;
    if (s.state == 'clear' &&
        (!approved ||
            reviewed == null ||
            DateTime.now().difference(reviewed) > const Duration(hours: 24) ||
            _dismissed)) {
      return const SizedBox.shrink();
    }
    final color = s.state == 'rejected'
        ? Colors.red.shade800
        : s.state == 'under_review'
        ? Colors.blue.shade800
        : s.state == 'clear'
        ? Colors.green.shade800
        : const Color(0xFF805000);
    final remaining = s.latestSubmission?.reviewDueAt.difference(
      DateTime.now(),
    );
    final reviewHours = s.latestSubmission == null
        ? 12
        : (s.latestSubmission!.reviewDueAt
                      .difference(s.latestSubmission!.submittedAt)
                      .inMinutes /
                  60)
              .ceil();
    final text = s.state == 'rejected'
        ? 'التحويل ما اتأكدش: ${s.latestSubmission?.rejectionReason ?? ''}'
        : s.state == 'under_review'
        ? 'استلمنا إثبات التحويل، وهنراجعه خلال ${billingDigits('$reviewHours')} ساعة'
        : s.state == 'clear'
        ? 'تم تأكيد الدفع، الخدمة رجعت تشتغل'
        : 'يرجى سداد مبلغ ${billingMoney(s.totalDueMinor)} لتستمر الخدمة';
    return Container(
      margin: const EdgeInsets.fromLTRB(20, 8, 20, 16),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: color.withValues(alpha: .09),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(
                s.state == 'clear'
                    ? Icons.check_circle_outline
                    : Icons.receipt_long,
                color: color,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  text,
                  style: TextStyle(color: color, fontWeight: FontWeight.w700),
                ),
              ),
              if (s.state == 'clear')
                IconButton(
                  tooltip: 'إغلاق',
                  onPressed: () async {
                    setState(() => _dismissed = true);
                    final prefs = await SharedPreferences.getInstance();
                    await prefs.setString(
                      'billing.approval.dismissed',
                      s.latestSubmission!.id,
                    );
                  },
                  icon: const Icon(Icons.close),
                ),
            ],
          ),
          if (s.periodLabel != null)
            Padding(
              padding: const EdgeInsets.only(top: 8),
              child: Text('مستحقات شهر ${s.periodLabel}'),
            ),
          if (s.state == 'under_review' && remaining != null)
            Text(
              remaining.isNegative
                  ? 'المراجعة اتأخرت، هنراجع تحويلك في أقرب وقت'
                  : 'فاضل ${billingDigits('${remaining.inHours}')} ساعة و${billingDigits('${remaining.inMinutes % 60}')} دقيقة',
            ),
          if (s.state != 'clear')
            TextButton(
              onPressed: () async {
                await Navigator.of(context).pushNamed(
                  s.state == 'under_review'
                      ? AppRoutes.techCommissionStatement
                      : AppRoutes.techCommissionPay,
                  arguments: s.oldestDueStatementId,
                );
                widget.onChanged?.call();
              },
              child: Text(
                s.state == 'rejected'
                    ? 'ارفع إثبات جديد'
                    : s.state == 'under_review'
                    ? 'تفاصيل'
                    : 'ادفع دلوقتي',
              ),
            ),
        ],
      ),
    );
  }
