  }

  Widget _buildPeriodChip(int index, String label) {
    final isSelected = _selectedPeriod == index;
    return InkWell(
      onTap: () => setState(() => _selectedPeriod = index),
      borderRadius: BorderRadius.circular(99),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
        decoration: BoxDecoration(
          color: isSelected ? V2Colors.primary : V2Colors.surface,
          borderRadius: BorderRadius.circular(99),
          border: Border.all(
            color: isSelected ? V2Colors.primary : V2Colors.border,
          ),
          boxShadow: isSelected
              ? [
                  BoxShadow(
                    color: V2Colors.primary.withValues(alpha: 0.25),
                    blurRadius: 8,
                    offset: const Offset(0, 3),
                  ),
                ]
              : null,
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 12,
            fontWeight: isSelected ? FontWeight.w900 : FontWeight.w700,
            color: isSelected ? Colors.white : V2Colors.inkMuted,
          ),
        ),
      ),
    );
  }

