  Widget _buildBar(
    String day,
    double heightFactor,
    String amount, {
    bool isHighest = false,
  }) {
    return Column(
      children: [
        Text(
          amount,
          style: TextStyle(
            fontSize: 9,
            fontWeight: FontWeight.w800,
            color: isHighest ? V2Colors.primary : V2Colors.inkLight,
          ),
        ),
        const SizedBox(height: 4),
        Container(
          width: 28,
          height: 80 * heightFactor,
          decoration: BoxDecoration(
            color: isHighest ? V2Colors.primary : V2Colors.primaryLight,
            borderRadius: BorderRadius.circular(8),
          ),
        ),
        const SizedBox(height: 6),
        Text(
          day,
          style: TextStyle(
            fontSize: 10,
            fontWeight: isHighest ? FontWeight.w900 : FontWeight.w600,
            color: isHighest ? V2Colors.ink : V2Colors.inkMuted,
          ),
        ),
      ],
    );
  }

  Widget _buildTransactionTile(TechTransactionEntity tx) {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: V2Colors.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: V2Colors.border),
      ),
      child: Row(
        children: [
          Container(
            width: 40,
            height: 40,
            decoration: BoxDecoration(
              color: tx.isPositive
                  ? V2Colors.primaryLight
                  : V2Colors.dangerSoft,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(
              tx.isPositive ? Icons.add_rounded : Icons.remove_rounded,
              color: tx.isPositive ? V2Colors.primary : V2Colors.danger,
              size: 22,
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  tx.title,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                    color: V2Colors.ink,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  '${tx.subtitle} · ${tx.date} ${tx.time}',
                  style: const TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w600,
                    color: V2Colors.inkLight,
                  ),
                ),
              ],
            ),
          ),
          Text(
            '${tx.amount} ج.م',
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w900,
              color: tx.isPositive ? V2Colors.primary : V2Colors.ink,
            ),
          ),
        ],
      ),
    );
  }
