class _DispatchStore implements AuthSessionStore {
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _DispatchApi extends TechnicianRequestsApi {
  _DispatchApi()
    : super(
        baseUri: Uri.parse('http://localhost'),
        sessionStore: _DispatchStore(),
      );
  int submissions = 0;
  @override
  Future<TechnicianRequest> details(String id) async => TechnicianRequest({
    'id': id,
    'reference': '#FX-٢٠٤٥',
    'serviceTitleAr': 'كهرباء — تركيب نجفة',
    'area': 'مدينة نصر',
    'distanceKm': 1.5,
    'customerOfferMinor': '15000',
    'capMinor': '25000',
    'description': 'محتاج فك نجفة قديمة وتركيب واحدة جديدة',
    'customerFirstName': 'أحمد',
    'locationPreference': 'customer_site_only',
    'visibleUntil': '2026-10-08T12:40:00Z',
    'scheduledAt': '2026-10-08T12:00:00Z',
    'pendingOffersCount': 3,
  });

  @override
  Future<TechnicianOrderSnapshot> transition(
    String orderId, {
    required String transition,
    required String idempotencyKey,
    String? reason,
    String? otp,
  }) async {
    submissions++;
    return TechnicianOrderSnapshot(
      orderId: orderId,
      status: switch (transition) {
        'depart' => 'on_way',
        'start' => 'in_progress',
        'delay' => 'delayed',
        'cancel' => 'cancelled',
        'emergency' => 'emergency',
        _ => 'assigned',
      },
    );
  }

  @override
  Future<TechnicianOffer> createOffer(
    String id,
    OfferDraft draft, {
    String? idempotencyKey,
  }) async {
    submissions++;
    return const TechnicianOffer({'id': 'offer-1', 'status': 'pending'});
  }
}

class _DepartureApi extends _DispatchApi {
  String currentStatus = 'assigned';
  bool fail = false;
  final departure = DateTime.now().subtract(const Duration(minutes: 2));
  @override
  Future<TechnicianOrderSnapshot> orderSnapshot(String id) async =>
      TechnicianOrderSnapshot(
        orderId: id,
        status: currentStatus,
        departedAt: currentStatus == 'on_way' ? departure : null,
      );
  @override
  Future<TechnicianOrderSnapshot> transition(
    String orderId, {
    required String transition,
    required String idempotencyKey,
    String? reason,
    String? otp,
  }) async {
    submissions++;
    if (fail) throw const TechnicianRequestsApiException('تعذر بدء التوجّه');
    currentStatus = 'on_way';
    return orderSnapshot(orderId);
  }
}

class _FakeAuthRepository implements AuthenticationRepository {
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

void main() {
  testWidgets(
    'departure updates the server before opening the trip and restores it on reopen',
    (tester) async {
      final api = _DepartureApi();
      addTearDown(api.close);
      await tester.pumpWidget(
        MaterialApp(
          home: TechDispatchFlowPage(
            initialStep: 1,
            api: api,
            refreshOnOpen: true,
          ),
        ),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('بدء'));
      await tester.pump();
      await tester.pump();
      expect(api.submissions, 1);
      expect(api.currentStatus, 'on_way');
      expect(find.byType(TechNavigatingPage), findsOneWidget);
      expect(find.textContaining('الوقت منذ بدء التوجّه:'), findsOneWidget);
      await tester.pumpWidget(const SizedBox());
      await tester.pumpWidget(
        MaterialApp(
          home: TechDispatchFlowPage(
            initialStep: 1,
            api: api,
            refreshOnOpen: true,
          ),
        ),
      );
      await tester.pump();
      await tester.pump();
      expect(find.byType(TechNavigatingPage), findsOneWidget);
      expect(find.text('بدء'), findsNothing);
      await tester.pumpWidget(const SizedBox());
    },
  );
  testWidgets('failed departure keeps the accepted page available for retry', (
    tester,
  ) async {
    final api = _DepartureApi()..fail = true;
    addTearDown(api.close);
    await tester.pumpWidget(
      MaterialApp(home: TechDispatchFlowPage(initialStep: 1, api: api)),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('بدء'));
    await tester.pumpAndSettle();
    expect(api.currentStatus, 'assigned');
    expect(find.byType(TechOrderAcceptedPage), findsOneWidget);
    expect(find.byType(TechNavigatingPage), findsNothing);
    expect(find.text('تعذر بدء التوجّه'), findsOneWidget);
  });
  test('departure clock uses the first persisted on-way timeline event', () {
    final snapshot = TechnicianOrderSnapshot.fromJson({
      'order': {'orderId': 'o1', 'status': 'on_way'},
      'timeline': [
        {'toStatus': 'on_way', 'occurredAt': '2026-10-11T12:05:00Z'},
        {'toStatus': 'assigned', 'occurredAt': '2026-10-11T11:55:00Z'},
        {'toStatus': 'on_way', 'occurredAt': '2026-10-11T12:00:00Z'},
      ],
    });
    expect(snapshot.departedAt, DateTime.parse('2026-10-11T12:00:00Z'));
  });

  for (final size in [const Size(390, 844), const Size(768, 1024)]) {
    testWidgets(
      'dispatch details fit ${size.width.toInt()}px and expose all three actions',
      (tester) async {
        tester.view.physicalSize = size;
        tester.view.devicePixelRatio = 1;
        addTearDown(tester.view.resetPhysicalSize);
        addTearDown(tester.view.resetDevicePixelRatio);
        final api = _DispatchApi();
        addTearDown(api.close);
        final capture =
            Platform.environment['DISPATCH_CAPTURE_VISUALS'] == 'true';
        if (capture) {
          final font = File('C:/Windows/Fonts/arial.ttf');
          if (font.existsSync()) {
            final loader = FontLoader('DispatchPreview')
              ..addFont(
                Future.value(ByteData.sublistView(font.readAsBytesSync())),
              );
            await tester.runAsync(loader.load);
          }
        }
        const boundary = ValueKey('dispatch-details');
        await tester.pumpWidget(
          RepaintBoundary(
            key: boundary,
            child: MaterialApp(
              debugShowCheckedModeBanner: false,
              theme: ThemeData(fontFamily: capture ? 'DispatchPreview' : null),
              home: Directionality(
                textDirection: TextDirection.rtl,
                child: TechIncomingPage(
                  api: api,
                  billingSummary: () async => const CommissionSummary(
                    blocked: false,
                    state: 'clear',
                    totalDueMinor: 0,
                    commissionBps: 1000,
                  ),
                ),
              ),
            ),
          ),
        );
        await tester.pumpAndSettle();
        expect(tester.takeException(), isNull);
        expect(find.text('قبول بالسعر'), findsOneWidget);
        expect(find.text('اقتراح سعر'), findsOneWidget);
        expect(find.text('رفض'), findsOneWidget);
        if (capture) {
          final render = tester.renderObject<RenderRepaintBoundary>(
            find.byKey(boundary),
          );
          await tester.runAsync(() async {
            final image = await render.toImage();
            final bytes = await image.toByteData(
              format: ui.ImageByteFormat.png,
            );
            if (bytes != null)
              await File(
                '../../docs/testing/dispatch-details-${size.width.toInt()}.png',
              ).writeAsBytes(bytes.buffer.asUint8List());
            image.dispose();
          });
        }
      },
    );
  }
  group('Technician Dispatch & Navigation Flow Tests', () {
    testWidgets(
