CommissionSummary summary(String state) => CommissionSummary(
  blocked: state != 'clear',
  state: state,
  totalDueMinor: 25000,
  commissionBps: 1000,
  oldestDueStatementId: state == 'clear' ? null : 'statement',
  periodLabel: 'سبتمبر ٢٠٢٦',
  latestSubmission: state == 'due' || state == 'clear'
      ? null
      : CommissionSubmission({
          'id': 'proof',
          'status': state == 'rejected' ? 'rejected' : 'pending',
          'submittedAt': DateTime.now().toUtc().toIso8601String(),
          'reviewDueAt': DateTime.now()
              .add(const Duration(hours: 12))
              .toUtc()
              .toIso8601String(),
          'rejectionReason': state == 'rejected' ? 'الصورة مش واضحة' : null,
        }),
);

