    await tester.tap(find.text('قبول'));
    await tester.pumpAndSettle();
    expect(
      find.text('يرجى سداد مستحقات المنصة لتستمر الخدمة.'),
      findsOneWidget,
    );
    expect(requests, 0);
    await tester.pumpWidget(const SizedBox());
  });
  test(
    'submission retries preserve the caller idempotency key and response identity',
    () async {
      final bodies = <Map<String, Object?>>[];
      final api = CommissionBillingApi(
        baseUri: Uri.parse('https://api.test/base'),
        sessionStore: _Store(),
        client: MockClient((r) async {
          expect(
            r.url.path,
            '/base/v1/technician/commission/statements/statement/submissions',
          );
          bodies.add(Map<String, Object?>.from(jsonDecode(r.body) as Map));
          return http.Response(
            jsonEncode({
              'id': 'same-proof',
              'status': 'pending',
              'version': 1,
              'amountMinor': 25000,
              'createdAt': '2026-10-01T00:00:00Z',
              'reviewDueAt': '2026-10-01T12:00:00Z',
            }),
            201,
          );
        }),
      );
      final body = {
        'paymentMethodId': 'method',
        'proofFileId': 'file',
        'idempotencyKey': 'single-key',
      };
      final a = await api.submit('statement', body);
      final b = await api.submit('statement', body);
      expect(a.id, b.id);
      expect(bodies[0], bodies[1]);
      expect(bodies[0].containsKey('amountMinor'), false);
      api.close();
    },
  );
}المرحلة 0: الفهم والقواعد الثابتة
الفكرة باختصار
المنصة مش بتاخد أي رسوم من العميل. العمولة على الفني بس.
النسبة المبدئية 10% من المصنعية (service_orders.agreed_labor_minor) لكل الطلبات اللي اتقفلت completed خلال الشهر. النسبة دي الأدمن يقدر يغيّرها.
أول كل شهر بيتعمل كشف حساب (Statement) للشهر اللي فات، بس للفنيين اللي عندهم مصنعية أكبر من صفر. اللي ما اشتغلش ملوش كشف.
الأدمن بيضيف طرق دفع الشركة (فودافون كاش، محافظ إلكترونية، إنستاباي، تحويل بنكي)، والفني بيشوفها.
الفني يحوّل ويرفع صورة إثبات التحويل، والأدمن يراجع خلال 12 ساعة ويوافق أو يرفض.
طول ما فيه كشف مستحق ما اتوافقش على دفعه، الفني مقفول عليه: مينفعش يبقى Online، ولا يقبل طلب، ولا يقدّم عرض. لكن يقدر يتصفح التطبيق عادي، وهيظهر له بانر في الـ Home مكتوب فيه "يرجى سداد مبلغ X لتستمر الخدمة".
قواعد ممنوع تخالفها
كل الفلوس bigint بوحدة القرش (minor units). ممنوع float أو numeric في التخزين، والنسبة بالـ bps، يعني 10% = 1000.
ما تلمسش payment_transactions ولا FinanceService الحالي ولا technician_profiles.commission_bps. العمود الأخير ده Legacy قيمته الافتراضية 1500 والنظام الجديد مش هيقرأ منه خالص.
أي عملية بتغيّر حالة لازم يكون فيها idempotencyKey (uuid) وversion (optimistic locking) وAuditLogService.append جوه نفس الـ transaction. ده نفس النمط اللي في FinanceService.reviewPayout، انسخه.
حدود الشهر بتتحسب بتوقيت Africa/Cairo.
أي Exception بيرجع للموبايل يتبعت بالشكل ده: new ForbiddenException({ code: 'COMMISSION_PAYMENT_REQUIRED', message: '...' })، زي ما technician-presence.service.ts بيعمل مع WORK_HOURS_REQUIRED.
رسايل اليوزر بالعربي المصري، ونفس نبرة الرسايل الموجودة.
صفحات المحفظة الحالية (tech_earnings_page، tech_transactions_page، tech_statement_page) شغالة على sample data. ما تعدّلش منطقها، أقصى حاجة تضيف فيها كارت يودّي على الصفحات الجديدة.
المرحلة 1: قاعدة البيانات
اعمل migration جديدة: apps/backend/src/database/migrations/1700000000227-create-technician-commission-billing.ts، وسجّلها في آخر الـ array اسمه applicationMigrations في migration-registry.ts. آخر migration موجودة هي رقم 226.

Copy-- 1) إعدادات العمولة (صف واحد بس)
CREATE TABLE platform_commission_settings (
  id              smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  commission_bps  integer NOT NULL DEFAULT 1000 CHECK (commission_bps BETWEEN 0 AND 5000),
  review_sla_hours smallint NOT NULL DEFAULT 12 CHECK (review_sla_hours BETWEEN 1 AND 168),
  version         integer NOT NULL DEFAULT 1,
  updated_by      uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_at      timestamptz NOT NULL DEFAULT now()
);
INSERT INTO platform_commission_settings (id) VALUES (1);

-- 2) طرق دفع الشركة
CREATE TABLE company_payment_methods (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  method_type      varchar(30) NOT NULL CHECK (method_type IN
                     ('vodafone_cash','etisalat_cash','orange_cash','we_pay','instapay','bank_account','other_wallet')),
  label            varchar(120) NOT NULL,          -- "فودافون كاش - الحساب الرئيسي"
  account_value    varchar(160) NOT NULL,          -- الرقم / عنوان إنستاباي / IBAN
  account_holder   varchar(160) NOT NULL,
  instructions     varchar(1000),
  is_active        boolean NOT NULL DEFAULT true,
  sort_order       smallint NOT NULL DEFAULT 0,
  version          integer NOT NULL DEFAULT 1,
  created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

-- 3) كشوف الحساب الشهرية
CREATE TABLE technician_commission_statements (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_number  bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
  technician_id     uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  period_month      date NOT NULL CHECK (period_month = date_trunc('month', period_month)::date),
  orders_count      integer NOT NULL CHECK (orders_count > 0),
  labor_total_minor bigint NOT NULL CHECK (labor_total_minor > 0),
  commission_bps    integer NOT NULL,              -- snapshot للنسبة وقت الإصدار
  amount_due_minor  bigint NOT NULL CHECK (amount_due_minor >= 0),
  currency          varchar(3) NOT NULL DEFAULT 'EGP',
  status            varchar(20) NOT NULL DEFAULT 'due' CHECK (status IN
                      ('due','under_review','paid','waived')),
  issued_at         timestamptz NOT NULL DEFAULT now(),
  paid_at           timestamptz,
  waived_by         uuid REFERENCES users(id) ON DELETE SET NULL,
  waive_reason      varchar(500),
  version           integer NOT NULL DEFAULT 1,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commission_statement_period_unique UNIQUE (technician_id, period_month),
  CONSTRAINT commission_statement_paid_ck CHECK ((status = 'paid') = (paid_at IS NOT NULL)),
  CONSTRAINT commission_statement_waive_ck CHECK ((status = 'waived') = (waive_reason IS NOT NULL))
);
CREATE INDEX commission_statements_tech_idx
  ON technician_commission_statements (technician_id, period_month DESC);
CREATE INDEX commission_statements_admin_idx
  ON technician_commission_statements (status, created_at DESC, id DESC);

-- 4) الطلبات اللي دخلت في كل كشف (شفافية + منع حساب الطلب مرتين)
CREATE TABLE technician_commission_statement_items (
  statement_id   uuid NOT NULL REFERENCES technician_commission_statements(id) ON DELETE CASCADE,
  order_id       uuid NOT NULL UNIQUE REFERENCES service_orders(id) ON DELETE RESTRICT,
  labor_minor    bigint NOT NULL CHECK (labor_minor > 0),
  completed_at   timestamptz NOT NULL,
  PRIMARY KEY (statement_id, order_id)
);

-- 5) إثباتات الدفع
CREATE TABLE commission_payment_submissions (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_id       uuid NOT NULL REFERENCES technician_commission_statements(id) ON DELETE RESTRICT,
  technician_id      uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  payment_method_id  uuid NOT NULL REFERENCES company_payment_methods(id) ON DELETE RESTRICT,
  proof_file_id      uuid NOT NULL REFERENCES stored_files(id) ON DELETE RESTRICT,
  amount_minor       bigint NOT NULL CHECK (amount_minor > 0),
  sender_account     varchar(160),     -- الرقم اللي حوّل منه
  transfer_reference varchar(120),     -- رقم العملية لو موجود
  note               varchar(500),
  status             varchar(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  review_due_at      timestamptz NOT NULL,
  rejection_reason   varchar(500),
  reviewed_by        uuid REFERENCES users(id) ON DELETE SET NULL,
  reviewed_at        timestamptz,
  idempotency_key    uuid NOT NULL,
  version            integer NOT NULL DEFAULT 1,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commission_submission_idem_unique UNIQUE (technician_id, idempotency_key),
  CONSTRAINT commission_submission_review_ck CHECK (
    (status = 'pending' AND reviewed_at IS NULL AND rejection_reason IS NULL)
    OR (status = 'approved' AND reviewed_at IS NOT NULL AND rejection_reason IS NULL)
    OR (status = 'rejected' AND reviewed_at IS NOT NULL AND rejection_reason IS NOT NULL))
);
CREATE UNIQUE INDEX commission_submission_one_pending_idx
  ON commission_payment_submissions (statement_id) WHERE status = 'pending';
CREATE INDEX commission_submissions_admin_idx
  ON commission_payment_submissions (status, review_due_at ASC, id ASC);

-- 6) دالة الحظر المركزية: المصدر الوحيد للحقيقة
CREATE FUNCTION technician_billing_blocked(p_technician uuid)
RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM technician_commission_statements s
    WHERE s.technician_id = p_technician
      AND s.status IN ('due','under_review')
      AND s.amount_due_minor > 0
  )

$$;
Copy
في دالة down() امسح كل حاجة بالترتيب العكسي.

معايير القبول: الـ migration تشتغل up وdown وup تاني من غير أخطاء، وSELECT technician_billing_blocked(<uuid>) ترجع false لأي فني.

