## حدود التحقق وتجهيز التشغيل

- قاعدة التطوير المشار إليها في `apps/backend/.env` أقدم من baseline المذكور في الخطة: آخر سجل ظاهر اسمه `SparePartTestHardening1700000000215`، بينما registry الحالية تضم migrations حتى 227. لم يتم تشغيل migrations المتراكمة على بيانات هذه القاعدة. يلزم مراجعة/تسوية سجل النسخ القديم ثم تشغيل المسار المعتاد للمشروع قبل تشغيل الإصدار الجديد؛ `migrationsRun` في التطبيق معطلة. نجاح الاختبارات المعزولة لا يعني تحديث قاعدة التطبيق.
- الرفع والتنزيل عبر R2/الكاميرا وFCM على جهاز حقيقي لم يُجرَّبا في هذه الجلسة. تم التحقق من منطق الخادم والتطبيق، وتطبيع الصورة، وسياسات الوصول والرفع، والإشعارات باختبارات محلية. تبقى تجربة النقل الفعلي على بيئة متصلة جزءًا من اختبار النشر.
- migration down تزيل الجداول والدالة بالترتيب العكسي. تبقى قيمة enum الخاملة `commission_payment_proof`؛ PostgreSQL لا يدعم حذف قيمة enum مفردة مباشرة. تم اختبار up/down/up فعليًا.
- الإعفاء متاح للكشف المستحق أو تحت المراجعة؛ عند إعفاء كشف تحت المراجعة يُغلق الإثبات المعلق مع السبب ونسخة جديدة وaudit في المعاملة نفسها، لمنع إبقاء إثبات pending لكشف معفي.
- صفحات المحفظة التجريبية بقيت بمنطقها الحالي؛ أضيفت فقط بطاقة دخول للمستحقات في الأرباح. الملفات والتعديلات الموجودة قبل بدء المهمة لم تُحذف أو تُرجع.# Focused commission-billing review

This bundle contains the NEW feature files in full and the feature's own tests. Changes to existing files appear only in commission-review-changes.patch, with original paths and line numbers. Existing files outside the patch hunks are omitted; do not assume they are absent from the application or fully reviewed. No code compression is used.

Review the phases against commission-billing-plan.txt. Check billing math and Cairo month boundaries, generation catch-up and concurrency, idempotency and stale versions, audit atomicity, authorization and proof privacy, upload quotas and orphan cleanup, dispatch enforcement and bypasses, active-order continuity, notification/reminder duplication, query performance and locking, plus mobile retry/lifecycle/UI integration. If a suspected issue needs unchanged surrounding code, request the specific method rather than the entire module.

The included changes cover app/migration registration; presence/heartbeat; offers and assignment; dispatch SQL; file upload/normalization/download/cleanup; push/outbox; mobile routes, requests/presence error codes, realtime events, dashboard/toggles/offer actions, old-wallet entry card, and admin finance integration.

Backend tests: pnpm --filter @fixit-pro/backend exec vitest run src/modules/commission-billing test/integration/commission-billing.integration.spec.ts . PostgreSQL tests require RUN_INTEGRATION_TESTS=true and a local TEST_DATABASE_URL. Mobile: from apps/mobile, flutter test --no-pub test/features/technician_billing_test.dart . Run in the original checkout, not directly from this packed file.import { BadRequestException, PayloadTooLargeException } from '@nestjs/common';
import { describe, expect, it } from 'vitest';

import { type StorageConfig } from '../../config/storage/storage.config';
import { MediaKind, MediaPurpose } from './entities/stored-file.entity';
import {
  MAX_BOOKING_VOICE_NOTE_DURATION_MS,
  MAX_BOOKING_VIDEO_BYTES,
  MAX_AVATAR_BYTES,
  MAX_COMPLETION_PHOTO_BYTES,
  normalizeContentType,
  validateMediaDuration,
  validateMediaPolicy,
  validatePurposeMediaPolicy,
} from './media-policy';

const config: StorageConfig = {
  enabled: true,
  accountId: 'a'.repeat(32),
  bucket: 'test-bucket',
  endpoint: 'https://example.r2.cloudflarestorage.com',
  accessKeyId: 'key',
  secretAccessKey: 'secret',
  keyPrefix: 'media',
  uploadUrlTtlSeconds: 900,
  downloadUrlTtlSeconds: 300,
  uploadSessionTtlHours: 24,
  multipartThresholdBytes: 100 * 1024 * 1024,
  maxImageBytes: 25 * 1024 * 1024,
  maxAudioBytes: 500 * 1024 * 1024,
  maxVideoBytes: 10 * 1024 * 1024 * 1024,
};

describe('media policy', () => {
  it('restricts commission proofs to four image formats and 8 MiB', () => {
    for (const type of ['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
      expect(() =>
        { validatePurposeMediaPolicy(
          MediaKind.Image,
          MediaPurpose.CommissionPaymentProof,
          8 * 1024 * 1024,
          type,
        ); },
      ).not.toThrow();
    expect(() =>
      { validatePurposeMediaPolicy(
        MediaKind.Image,
        MediaPurpose.CommissionPaymentProof,
        8 * 1024 * 1024 + 1,
        'image/jpeg',
      ); },
    ).toThrow(PayloadTooLargeException);
    for (const type of ['image/avif', 'image/heif', 'image/svg+xml'])
      expect(() =>
        { validatePurposeMediaPolicy(MediaKind.Image, MediaPurpose.CommissionPaymentProof, 100, type); },
      ).toThrow(BadRequestException);
    expect(() =>
      { validatePurposeMediaPolicy(
        MediaKind.Video,
        MediaPurpose.CommissionPaymentProof,
        100,
        'video/mp4',
      ); },
    ).toThrow(BadRequestException);
  });
  it('accepts a spare-part image at exactly 10 MiB and refuses one extra byte', () => {
    expect(() => {
      validatePurposeMediaPolicy(MediaKind.Image, MediaPurpose.SparePart, 10 * 1024 * 1024);
    }).not.toThrow();
    expect(() => {
      validatePurposeMediaPolicy(MediaKind.Image, MediaPurpose.SparePart, 10 * 1024 * 1024 + 1);
    }).toThrow(PayloadTooLargeException);
  });
  it.each([MediaKind.Audio, MediaKind.Video])('refuses %s as spare-part media', (kind) => {
    expect(() => {
      validatePurposeMediaPolicy(kind, MediaPurpose.SparePart, 100);
    }).toThrow(BadRequestException);
  });
  it('normalizes a MIME type and derives a trusted extension', () => {
    expect(
      validateMediaPolicy(MediaKind.Image, 'IMAGE/JPEG; charset=binary', 1024, config),
    ).toEqual({
      contentType: 'image/jpeg',
      extension: 'jpg',
    });
  });

  it('rejects a MIME type that does not belong to the declared media kind', () => {
    expect(() => validateMediaPolicy(MediaKind.Image, 'video/mp4', 1024, config)).toThrow(
      BadRequestException,
    );
  });

  it('rejects objects above the configured per-kind limit', () => {
    expect(() =>
      validateMediaPolicy(MediaKind.Image, 'image/png', config.maxImageBytes + 1, config),
    ).toThrow(PayloadTooLargeException);
  });

  it('removes optional MIME parameters', () => {
    expect(normalizeContentType(' audio/ogg ; codecs=opus ')).toBe('audio/ogg');
  });

  it('accepts a booking voice note at exactly two minutes', () => {
    expect(
      validateMediaDuration(
        MediaKind.Audio,
        MediaPurpose.Booking,
        MAX_BOOKING_VOICE_NOTE_DURATION_MS,
      ),
    ).toBe(MAX_BOOKING_VOICE_NOTE_DURATION_MS);
  });

  it('requires duration for booking voice notes', () => {
    expect(() => validateMediaDuration(MediaKind.Audio, MediaPurpose.Booking, undefined)).toThrow(
      BadRequestException,
    );
  });

  it('requires a declared duration for chat audio and video uploads', () => {
    expect(() => validateMediaDuration(MediaKind.Audio, MediaPurpose.Chat, undefined)).toThrow(
      BadRequestException,
    );
    expect(() => validateMediaDuration(MediaKind.Video, MediaPurpose.Chat, undefined)).toThrow(
      BadRequestException,
    );
  });

  it('rejects booking voice notes longer than two minutes', () => {
    expect(() =>
      validateMediaDuration(
        MediaKind.Audio,
        MediaPurpose.Booking,
        MAX_BOOKING_VOICE_NOTE_DURATION_MS + 1,
      ),
    ).toThrow(BadRequestException);
  });

  it('rejects duration metadata on unrelated media', () => {
    expect(() => validateMediaDuration(MediaKind.Image, MediaPurpose.Booking, 1_000)).toThrow(
      BadRequestException,
    );
  });

  it('rejects booking videos above the product limit', () => {
    expect(() => {
      validatePurposeMediaPolicy(
        MediaKind.Video,
        MediaPurpose.Booking,
        MAX_BOOKING_VIDEO_BYTES + 1,
      );
    }).toThrow(PayloadTooLargeException);
  });

  it('does not apply the booking video limit to other purposes', () => {
    expect(() => {
      validatePurposeMediaPolicy(
        MediaKind.Video,
        MediaPurpose.Portfolio,
        MAX_BOOKING_VIDEO_BYTES + 1,
      );
    }).not.toThrow();
  });

  it('rejects MPEG booking videos before creating an upload session', () => {
    expect(() => {
      validatePurposeMediaPolicy(MediaKind.Video, MediaPurpose.Booking, 1024, 'video/mpeg');
    }).toThrow(BadRequestException);
  });

  it('rejects non-image media declared for avatar use', () => {
    expect(() => {
      validatePurposeMediaPolicy(MediaKind.Audio, MediaPurpose.Avatar, 1024, 'audio/mpeg');
    }).toThrow(BadRequestException);
  });

  it('enforces the avatar limit on the generic upload path', () => {
    expect(() => {
      validatePurposeMediaPolicy(
        MediaKind.Image,
        MediaPurpose.Avatar,
        MAX_AVATAR_BYTES + 1,
        'image/jpeg',
      );
    }).toThrow(PayloadTooLargeException);
  });

  it('accepts only supported image formats for completion evidence and review photos', () => {
    for (const purpose of [MediaPurpose.JobEvidence, MediaPurpose.Review]) {
      expect(() => {
        validatePurposeMediaPolicy(MediaKind.Image, purpose, 1024, 'image/jpeg');
      }).not.toThrow();
      expect(() => {
        validatePurposeMediaPolicy(MediaKind.Image, purpose, 1024, 'image/avif');
      }).toThrow(BadRequestException);
      expect(() => {
        validatePurposeMediaPolicy(MediaKind.Video, purpose, 1024, 'video/mp4');
      }).toThrow(BadRequestException);
      expect(() => {
        validatePurposeMediaPolicy(
          MediaKind.Image,
          purpose,
          MAX_COMPLETION_PHOTO_BYTES + 1,
          'image/jpeg',
        );
      }).toThrow(PayloadTooLargeException);
    }
  });
});import { DISPATCH } from './dispatch.constants';

const DEFAULT_JOB_DURATION_MIN = '__DISPATCH_JOB_DURATION_MIN__';

/**
 * Shared, alias-stable WHERE fragment for the technician feed, request detail,
 * and technician confirmation queries. Callers must join service_orders as `o`,
 * technician_profiles as `tp`, users as `u`, addresses as `a`, and workshops as `tw`.
 */
const ELIGIBILITY_TEMPLATE = `
  AND tp.application_status = 'approved'
  AND NOT technician_billing_blocked(tp.user_id)
  AND u.status = 'active' AND u.deleted_at IS NULL
  AND (o.search_starts_at IS NULL OR o.search_starts_at <= now())
  AND (
    (o.search_starts_at IS NOT NULL AND o.search_starts_at < o.scheduled_at - interval '1 minute')
    OR (tp.is_online IS TRUE AND tp.last_seen_at > now() - interval '3 minutes')
  )
  AND (tp.break_until IS NULL OR tp.break_until < now())
  AND EXISTS (
    SELECT 1 FROM provider_application_services pas
    WHERE pas.technician_id = tp.user_id AND pas.service_id = o.service_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM technician_time_off time_off
    WHERE time_off.technician_id = tp.user_id AND time_off.cancelled_at IS NULL
      AND (COALESCE(o.scheduled_at, now()) AT TIME ZONE 'Africa/Cairo')::date
        BETWEEN time_off.starts_on AND time_off.ends_on
  )
  AND NOT EXISTS (
    SELECT 1
    FROM provider_holidays holiday
    WHERE holiday.technician_id = tp.user_id
      AND (COALESCE(o.scheduled_at, now()) AT TIME ZONE 'Africa/Cairo')::date
            BETWEEN holiday.starts_on AND holiday.ends_on
  )
  AND CASE
    WHEN NOT valid_technician_availability(COALESCE(tp.availability, '[]'::jsonb)) THEN false
    WHEN jsonb_array_length(tp.availability) = 0 THEN false
    WHEN o.is_emergency IS TRUE AND tp.accepts_emergency_orders IS TRUE THEN true
    ELSE EXISTS (
      SELECT 1
      FROM jsonb_array_elements(tp.availability) slot
      CROSS JOIN LATERAL (
        SELECT COALESCE(o.scheduled_at, now()) AT TIME ZONE 'Africa/Cairo' AS local_at
      ) execution
      WHERE (slot->>'dayOfWeek')::int = ((EXTRACT(DOW FROM execution.local_at)::int + 1) % 7)
        AND EXTRACT(HOUR FROM execution.local_at)::int * 60
              + EXTRACT(MINUTE FROM execution.local_at)::int >= (slot->>'startMinute')::int
        AND EXTRACT(HOUR FROM execution.local_at)::int * 60
              + EXTRACT(MINUTE FROM execution.local_at)::int < (slot->>'endMinute')::int
    )
  END
  AND CASE
    WHEN a.latitude IS NULL OR a.longitude IS NULL
      OR tp.work_center_lat IS NULL OR tp.work_center_lng IS NULL
      THEN a.area_code = ANY(tp.work_areas)
        OR EXISTS (
          SELECT 1 FROM technician_work_areas selected_area
          WHERE selected_area.technician_id = tp.user_id
            AND selected_area.area_code = a.area_code
        )
    WHEN o.dispatch_stage = 1 AND tp.work_radius_km IS NOT NULL THEN
      CASE
        WHEN tp.work_center_lat BETWEEN a.latitude - tp.work_radius_km::double precision / 111.0
                                    AND a.latitude + tp.work_radius_km::double precision / 111.0
         AND tp.work_center_lng BETWEEN a.longitude - tp.work_radius_km::double precision / (111.0 * GREATEST(0.000001, abs(cos(radians(GREATEST(abs(a.latitude), abs(tp.work_center_lat)))))))
                                   AND a.longitude + tp.work_radius_km::double precision / (111.0 * GREATEST(0.000001, abs(cos(radians(GREATEST(abs(a.latitude), abs(tp.work_center_lat)))))))
        THEN 6371.0 * 2.0 * asin(sqrt(LEAST(1.0, GREATEST(0.0,
          power(sin(radians(a.latitude - tp.work_center_lat) / 2.0), 2)
          + cos(radians(tp.work_center_lat)) * cos(radians(a.latitude))
          * power(sin(radians(a.longitude - tp.work_center_lng) / 2.0), 2)
        )))) <= tp.work_radius_km
        ELSE false
      END
    WHEN o.dispatch_stage = 2 AND tp.max_request_distance_km IS NOT NULL THEN
      CASE
        WHEN tp.work_center_lat BETWEEN a.latitude - tp.max_request_distance_km::double precision / 111.0
                                    AND a.latitude + tp.max_request_distance_km::double precision / 111.0
         AND tp.work_center_lng BETWEEN a.longitude - tp.max_request_distance_km::double precision / (111.0 * GREATEST(0.000001, abs(cos(radians(GREATEST(abs(a.latitude), abs(tp.work_center_lat)))))))
                                   AND a.longitude + tp.max_request_distance_km::double precision / (111.0 * GREATEST(0.000001, abs(cos(radians(GREATEST(abs(a.latitude), abs(tp.work_center_lat)))))))
        THEN 6371.0 * 2.0 * asin(sqrt(LEAST(1.0, GREATEST(0.0,
          power(sin(radians(a.latitude - tp.work_center_lat) / 2.0), 2)
          + cos(radians(tp.work_center_lat)) * cos(radians(a.latitude))
          * power(sin(radians(a.longitude - tp.work_center_lng) / 2.0), 2)
        )))) <= tp.max_request_distance_km
        ELSE false
      END
    ELSE false
  END
  AND (o.location_preference <> 'workshop_only' OR tw.accepts_workshop_jobs IS TRUE)
  AND NOT EXISTS (
    SELECT 1 FROM service_order_technician_skips skipped
    WHERE skipped.order_id = o.id AND skipped.technician_id = tp.user_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM customer_technician_blocks blocked
    WHERE blocked.customer_id = o.customer_id AND blocked.technician_id = tp.user_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM technician_customer_blocks blocked
    WHERE blocked.technician_id = tp.user_id AND blocked.customer_id = o.customer_id
  )
  AND CASE
    WHEN o.search_starts_at IS NOT NULL
      AND o.search_starts_at < o.scheduled_at - interval '1 minute'
    THEN NOT EXISTS (
      SELECT 1
      FROM service_orders reserved
      WHERE reserved.id <> o.id
        AND reserved.status IN ('assigned', 'on_way', 'in_progress', 'paused', 'delayed', 'emergency')
        AND (reserved.technician_id = tp.user_id OR reserved.backup_technician_id = tp.user_id)
        AND reserved.scheduled_at < o.scheduled_at + make_interval(mins => ${DEFAULT_JOB_DURATION_MIN})
        AND reserved.scheduled_at + make_interval(mins => ${DEFAULT_JOB_DURATION_MIN}) > o.scheduled_at
    )
    ELSE tp.is_busy IS FALSE AND NOT EXISTS (
      SELECT 1
      FROM service_orders busy
      WHERE busy.status IN ('assigned', 'on_way', 'in_progress', 'paused', 'delayed', 'emergency')
        AND (busy.technician_id = tp.user_id OR busy.backup_technician_id = tp.user_id)
    )
  END
`;

export function getDispatchEligibilitySql(): string {
  return ELIGIBILITY_TEMPLATE.replaceAll(
    DEFAULT_JOB_DURATION_MIN,
    String(DISPATCH.DEFAULT_JOB_DURATION_MIN),
  );
}
export const DISPATCH_ELIGIBILITY_SQL = getDispatchEligibilitySql();import 'dart:async';
import 'package:fixit_pro/app/configuration/app_config.dart';
import 'package:fixit_pro/core/app_version/app_version_runtime.dart';
import 'package:fixit_pro/core/networking/api_uri.dart';
import 'package:fixit_pro/core/storage/secure/auth_session_runtime.dart';
import 'package:fixit_pro/core/storage/secure/auth_session_store.dart';
import 'package:fixit_pro/features/technician/data/dispatch_push_client.dart';
import 'package:fixit_pro/features/technician/data/dispatch_runtime_config.dart';
import 'package:socket_io_client/socket_io_client.dart' as io;

class _RealtimeTransport {
  _RealtimeTransport({
    Uri? baseUri,
    AuthSessionStore? sessionStore,
    Future<bool> Function()? ensureSession,
  }) : _baseUri = baseUri ?? AppConfig.fromEnvironment().backendBaseUri,
       _ensureSession = ensureSession ?? AuthSessionRuntime.ensureSession,
       _store = sessionStore ?? SecureAuthSessionStore();
  final Uri _baseUri;
  final AuthSessionStore _store;
  final Future<bool> Function()? _ensureSession;
  io.Socket? _socket;
  DispatchPushClient? _push;
  bool _disposed = false;
  final Set<String> _seen = {};
  bool get isConnected => _socket?.connected ?? false;
  Future<void> connect({
    required void Function() onReconnect,
    void Function(Map<String, Object?> event)? onEvent,
  }) async {
    try {
      requireSecureCredentialUri(_baseUri);
      if (_ensureSession != null && !await _ensureSession()) return;
    } on Object {
      return;
    }
    if (_disposed) return;
    final s = await _store.readSession();
    if (s == null || _disposed) return;
    try {
      await DispatchRuntimeConfig.load(_baseUri, s);
    } on Object {
      return;
    }
    if (!DispatchRuntimeConfig.realtimeEnabled || _disposed) return;
    void deliver(Map<String, Object?> event) {
      if (_disposed) return;
      final id = event['eventId']?.toString();
      final dedupeId = event['notificationOpened'] == true ? '$id:opened' : id;
      if (dedupeId != null && !_seen.add(dedupeId)) return;
      if (_seen.length > 1000) _seen.remove(_seen.first);
      onEvent?.call(event);
    }

    final push = DispatchPushClient(baseUri: _baseUri, store: _store);
    _push = push;
    unawaited(push.connect(deliver));
    final uri = '${_baseUri.scheme}://${_baseUri.authority}/rt';
    final socket = io.io(
      uri,
      io.OptionBuilder()
          .setTransports(['websocket'])
          .setAuth({
            'token': s.accessToken,
            ...?AppVersionRuntime.current?.build.metadata,
          })
          .disableReconnection()
          .setReconnectionAttempts(10)
          .setReconnectionDelay(1000)
          .build(),
    );
    _socket = socket;
    socket.on('app.update_required', (_) => AppVersionRuntime.current?.block());
    socket.on('connect_error', (error) {
      if (error is Map &&
          error['data'] is Map &&
          (error['data'] as Map)['code'] == 'APP_UPDATE_REQUIRED') {
        AppVersionRuntime.current?.block();
        socket.disconnect();
      }
    });
    Timer? reconnectTimer;
    bool refreshing = false;
    Future<void> reconnectWithSession() async {
      if (_disposed ||
          refreshing ||
          AppVersionRuntime.current?.blocked == true) {
        return;
      }
      refreshing = true;
      try {
        if (_ensureSession != null && !await _ensureSession()) return;
        final current = await _store.readSession();
        if (current == null ||
            _disposed ||
            !current.isAccessTokenUsable(DateTime.now())) {
          return;
        }
        socket.auth = {
          'token': current.accessToken,
          ...?AppVersionRuntime.current?.build.metadata,
        };
        socket.connect();
      } on Object {
        /* retry with backoff below */
      } finally {
        refreshing = false;
        if (!_disposed && !socket.connected) {
          reconnectTimer?.cancel();
          reconnectTimer = Timer(
            const Duration(seconds: 5),
            () => unawaited(reconnectWithSession()),
          );
        }
      }
    }

    socket.on('disconnect', (_) {
      if (_disposed) return;
      reconnectTimer?.cancel();
      reconnectTimer = Timer(
        const Duration(seconds: 2),
        () => unawaited(reconnectWithSession()),
      );
    });
    socket.on('connect_error', (_) {
      reconnectTimer?.cancel();
      reconnectTimer = Timer(
        const Duration(seconds: 5),
        () => unawaited(reconnectWithSession()),
      );
    });
    socket.on('connect', (_) {
      reconnectTimer?.cancel();
      onReconnect();
    });
    for (final event in const [
      'spare_part.request.new',
      'spare_part.request.expiring',
      'spare_part.offer.withdrawn',
      'spare_part.offer.rejected',
      'spare_part.offer.lost',
      'spare_part.offer.expired',
      'spare_part.deal.updated',
      'spare_part.offer.created',
      'spare_part.offer.updated',
      'spare_part.request.updated',
      'billing.statement_issued',
      'billing.payment_approved',
      'billing.payment_rejected',
      'billing.statement_waived',
      'request.new',
      'request.updated',
      'request.removed',
      'offer.received',
      'offer.updated',
      'offer.withdrawn',
      'offer.expired',
      'offer.rejected',
      'offer.lost',
      'order.assigned',
      'order.no_provider_found',
      'order.raise_suggested',
    ]) {
      socket.on(event, (payload) {
        if (payload is Map<String, dynamic>) {
          deliver({...payload.cast<String, Object?>(), 'type': event});
        }
      });
    }
  }

  void dispose() {
    _disposed = true;
    _push?.dispose();
    _socket?.dispose();
    _socket = null;
  }
}

class TechnicianRealtimeClient {
  TechnicianRealtimeClient({
    Uri? baseUri,
    AuthSessionStore? sessionStore,
    Future<bool> Function()? ensureSession,
  }) : _uri = baseUri ?? AppConfig.fromEnvironment().backendBaseUri,
       _store = sessionStore ?? SecureAuthSessionStore(),
       _ensure = ensureSession;
  static final Map<String, _RealtimeHub> _hubs = {};
  final Uri _uri;
  final AuthSessionStore _store;
  final Future<bool> Function()? _ensure;
  _RealtimeHub? _hub;
  bool _disposed = false;
  void Function()? _onReconnect;
  void Function(Map<String, Object?>)? _onEvent;
  bool get isConnected => _hub?.transport.isConnected ?? false;
  Future<void> connect({
    required void Function() onReconnect,
    void Function(Map<String, Object?>)? onEvent,
  }) async {
    if (_disposed) return;
    _onReconnect = onReconnect;
    _onEvent = onEvent;
    final hub = _hubs.putIfAbsent(
      _uri.toString(),
      () => _RealtimeHub(
        _RealtimeTransport(
          baseUri: _uri,
          sessionStore: _store,
          ensureSession: _ensure,
        ),
      ),
    );
    _hub = hub;
    hub.clients.add(this);
    await hub.start();
  }

  void dispose() {
    _disposed = true;
    final hub = _hub;
    _hub = null;
    if (hub == null) return;
    hub.clients.remove(this);
    if (hub.clients.isEmpty) {
      hub.transport.dispose();
      _hubs.remove(_uri.toString());
    }
  }

  static void disconnectAll() {
    for (final hub in _hubs.values) {
      hub.transport.dispose();
      for (final client in hub.clients) {
        client._hub = null;
        client._disposed = true;
      }
    }
    _hubs.clear();
  }
}

class _RealtimeHub {
  _RealtimeHub(this.transport);
  final _RealtimeTransport transport;
  final Set<TechnicianRealtimeClient> clients = {};
  Future<void>? _starting;
  Future<void> start() {
    if (transport._socket != null) return Future.value();
    return _starting ??= transport
        .connect(
          onReconnect: () {
            for (final client in List.of(clients)) {
              if (!client._disposed) client._onReconnect?.call();
            }
          },
          onEvent: (event) {
            for (final client in List.of(clients)) {
              if (!client._disposed) client._onEvent?.call(event);
            }
          },
        )
        .whenComplete(() {
          _starting = null;
        });
  }
