class TechnicianRequest {
  const TechnicianRequest(this.data);
  final Map<String, Object?> data;
  String get id => data['id']?.toString() ?? data['orderId']?.toString() ?? '';
  String get serviceTitle =>
      data['serviceTitleAr']?.toString() ??
      data['serviceTitle']?.toString() ??
      'طلب خدمة';
  String get area => data['area']?.toString() ?? 'غير محدد';
  int get offersCount =>
      ((data['offersCount'] ?? data['pendingOffersCount']) as num?)?.toInt() ??
      0;
  bool get isNew => data['isNew'] is bool ? data['isNew'] as bool : false;
  TechIncomingRequestEntity toEntity() => TechIncomingRequestEntity(
    id: id,
    status: data['status']?.toString(),
    orderNumber: data['reference']?.toString() ?? id,
    serviceCategory: data['categoryTitleAr']?.toString() ?? '',
    serviceTitle: serviceTitle,
    area: area,
    distanceKm: (data['distanceKm'] as num?)?.toDouble() ?? 0,
    hasDistance: data['distanceKm'] != null,
    timeRequirement: data['scheduledAt']?.toString() ?? 'غير محدد',
    paymentMethod: data['paymentMethod']?.toString() ?? 'غير محدد',
    priceMin:
        ((BigInt.tryParse(data['customerOfferMinor']?.toString() ?? '') ??
                    BigInt.zero) ~/
                BigInt.from(100))
            .toInt(),
    priceMax:
        ((BigInt.tryParse(
                      (data['offerCapMinor'] ?? data['capMinor'])?.toString() ??
                          '',
                    ) ??
                    BigInt.zero) ~/
                BigInt.from(100))
            .toInt(),
    customerOfferMinor: data['customerOfferMinor']?.toString(),
    offerCapMinor: (data['offerCapMinor'] ?? data['capMinor'])?.toString(),
    locationPreference:
        data['locationPreference']?.toString() ?? 'customer_site_only',
    acceptsWorkshopJobs: data['acceptsWorkshopJobs'] == true,
    visibleUntil: (data['visibleUntil'] ?? data['searchExpiresAt'])?.toString(),
    photos: ((data['photos'] as List<Object?>?) ?? const [])
        .whereType<Map<String, Object?>>()
        .toList(),
    answers: ((data['answers'] as List<Object?>?) ?? const [])
        .whereType<Map<String, Object?>>()
        .toList(),
    offersCount: offersCount,
    description: data['description']?.toString() ?? '',
    voiceNoteDuration: '',
    photoCount: ((data['photos'] as List?)?.length ?? 0),
    videoDuration: '',
    isUrgent: (data['isEmergency'] ?? data['isUrgent']) as bool? ?? false,
    clientName:
        (data['customerFullName'] ?? data['customerFirstName'])?.toString() ??
        'العميل',
    clientPhone: data['customerPhone']?.toString(),
    latitude: (data['latitude'] as num?)?.toDouble(),
    longitude: (data['longitude'] as num?)?.toDouble(),
    serviceLocation: data['serviceLocation']?.toString() ?? 'customer_site',
    clientRating: (data['customerRating'] as num?)?.toDouble() ?? 0,
    clientAddress: data['address']?.toString() ?? area,
    clientAddressDetail: '',
    etaMinutes: (data['etaMinutes'] as num?)?.toInt() ?? 0,
    countdownSeconds: 0,
  );
  factory TechnicianRequest.fromJson(Map<String, Object?> j) =>
      TechnicianRequest(j);
}

class TechnicianOrderSnapshot {
  const TechnicianOrderSnapshot({
    required this.orderId,
    required this.status,
    this.departedAt,
    this.completionV2Enabled = false,
  });

  factory TechnicianOrderSnapshot.fromJson(Map<String, Object?> json) {
    final rawOrder = json['order'];
    if (rawOrder is! Map ||
        rawOrder['orderId'] is! String ||
        rawOrder['status'] is! String) {
      throw const FormatException('Invalid tracking snapshot.');
    }
    final departures =
        (json['timeline'] as List? ?? const [])
            .whereType<Map<Object?, Object?>>()
            .where((event) => event['toStatus'] == 'on_way')
            .map(
              (event) =>
                  DateTime.tryParse(event['occurredAt']?.toString() ?? ''),
            )
            .whereType<DateTime>()
            .toList()
          ..sort();
    return TechnicianOrderSnapshot(
      orderId: rawOrder['orderId']! as String,
      status: rawOrder['status']! as String,
      departedAt: departures.firstOrNull,
      completionV2Enabled: rawOrder['completionV2Enabled'] == true,
    );
  }

  final String orderId;
  final String status;
  final DateTime? departedAt;
  final bool completionV2Enabled;
}

