  const _PendingMutationIntent(this.fingerprint, this.key);
  final String fingerprint;
  final String key;
}

class TechnicianRequestsApi {
  TechnicianRequestsApi({
    required Uri baseUri,
    required AuthSessionStore sessionStore,
    Future<bool> Function()? ensureSession,
    http.Client? client,
    Duration requestTimeout = const Duration(seconds: 20),
    Future<Position> Function()? arrivalPosition,
  }) : _baseUri = baseUri,
       _store = sessionStore,
       _ensureSession = ensureSession,
       _client = client ?? BackendHttpClient(),
       _ownsClient = client == null,
       _requestTimeout = requestTimeout,
       _arrivalPosition = arrivalPosition;
  factory TechnicianRequestsApi.fromEnvironment({
    Future<bool> Function()? ensureSession,
  }) => TechnicianRequestsApi(
    baseUri: AppConfig.fromEnvironment().backendBaseUri,
    sessionStore: SecureAuthSessionStore(),
    ensureSession: ensureSession,
  );
  final Uri _baseUri;
  final AuthSessionStore _store;
  final Future<bool> Function()? _ensureSession;
  final http.Client _client;
  final bool _ownsClient;
  final Duration _requestTimeout;
  final Future<Position> Function()? _arrivalPosition;
  final Uuid _uuid = const Uuid();
  final Map<String, _PendingMutationIntent> _pendingMutationIntents = {};
  final Set<String> _arrivalReportedIntents = {};
  void close() {
    _arrivalReportedIntents.clear();
    if (_ownsClient) _client.close();
  }

  bool billingBlocked = false;
  Future<List<TechnicianRequest>> list({String? cursor, int limit = 30}) async {
    final query = <String, String>{'limit': '$limit'};
    if (cursor != null) query['cursor'] = cursor;
    final d = await _send('GET', '/v1/technician/requests', query: query);
    billingBlocked = d['billingBlocked'] == true;
    return _items(d).map(TechnicianRequest.fromJson).toList(growable: false);
  }

  Future<TechnicianRequest> details(String id) async {
    try {
      final response = await _send('GET', '/v1/technician/requests/$id');
      final raw = response['data'];
      if (raw is! Map || raw.keys.any((key) => key is! String)) {
        throw const TechnicianRequestsApiException(
          'استجابة غير صالحة من الخادم.',
        );
      }
      return TechnicianRequest.fromJson(Map<String, Object?>.from(raw));
    } on FormatException {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    } on TypeError {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    }
  }

  Future<TechnicianOrderSnapshot> orderSnapshot(String id) async =>
      TechnicianOrderSnapshot.fromJson(
        await _send('GET', '/v1/tracking/orders/$id'),
      );

  Future<TechnicianRequest> assignment(String id) async =>
      TechnicianRequest.fromJson(
        (await _send(
              'GET',
              '/v1/technician/orders/$id/dispatch-details',
            ))['data']!
            as Map<String, Object?>,
      );
  Future<TechnicianRequest?> currentAssignment() async {
    final data = (await _send('GET', '/v1/technician/active-order'))['data'];
    return data is Map<String, Object?>
        ? TechnicianRequest.fromJson(data)
        : null;
  }

  Future<TechnicianOffer> createOffer(
    String requestId,
    OfferDraft draft, {
    String? idempotencyKey,
  }) => _postOffer(
    requestId,
    '/offers',
    draft.toJson(),
    idempotencyKey: idempotencyKey,
  );
  Future<TechnicianOffer> updateOffer(
    String offerId,
    Map<String, Object?> body, {
    String? idempotencyKey,
  }) async {
    final identity = 'offer.update:$offerId';
    final key = idempotencyKey ?? _intentKey(identity, body);
    final result = await _send(
      'PATCH',
      '/v1/technician/offers/$offerId',
      body: body,
      idempotencyKey: key,
    );
    if (idempotencyKey == null) _clearIntentKey(identity, key);
    return TechnicianOffer.fromJson(result);
  }

  Future<void> withdraw(String offerId, {String? idempotencyKey}) async {
    final identity = 'offer.withdraw:$offerId';
    final key = idempotencyKey ?? _intentKey(identity, {'offerId': offerId});
    await _send(
      'DELETE',
      '/v1/technician/offers/$offerId',
      idempotencyKey: key,
    );
    if (idempotencyKey == null) _clearIntentKey(identity, key);
  }

  Future<void> skip(
    String requestId, {
    String? reason,
    String? idempotencyKey,
  }) async {
    final body = <String, Object?>{};
    if (reason != null && reason.trim().isNotEmpty) {
      body['reason'] = reason.trim();
    }
    final identity = 'request.skip:$requestId';
    final key = idempotencyKey ?? _intentKey(identity, body);
    await _send(
      'POST',
      '/v1/technician/requests/$requestId/skip',
      body: body,
      idempotencyKey: key,
    );
    if (idempotencyKey == null) _clearIntentKey(identity, key);
  }

  Future<TechnicianOrderSnapshot> transition(
    String orderId, {
    required String transition,
    required String idempotencyKey,
    String? reason,
    String? otp,
  }) async {
    final arrivalIntent = '$orderId:$idempotencyKey';
    if (transition == 'start' &&
        !_arrivalReportedIntents.contains(arrivalIntent)) {
      await _reportArrivalLocation(orderId);
      _arrivalReportedIntents.add(arrivalIntent);
    }
    late final Map<String, Object?> response;
    try {
      response = await _send(
        'POST',
        '/v1/tracking/orders/$orderId/transitions',
        body: <String, Object?>{
          'transition': transition,
          'idempotencyKey': idempotencyKey,
          if (reason != null) 'reason': reason,
          if (otp != null) 'otp': normalizeOtpDigits(otp),
        },
        idempotencyKey: idempotencyKey,
      );
    } on TechnicianRequestsApiException catch (error) {
      final status = error.statusCode;
      if (status != null && status >= 400 && status < 500) {
        _arrivalReportedIntents.remove(arrivalIntent);
      }
      rethrow;
    }
    try {
      final snapshot = TechnicianOrderSnapshot.fromJson(response);
      _arrivalReportedIntents.remove(arrivalIntent);
      return snapshot;
    } on FormatException {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    } on TypeError {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    }
  }

  Future<Map<String, Object?>> customerRatingSummary(String orderId) =>
      _send('GET', '/v1/tracking/orders/$orderId/customer-rating-summary');

  Future<void> reportCompletionLocation(String orderId) =>
      _reportArrivalLocation(orderId);

  Future<void> _reportArrivalLocation(String orderId) async {
    try {
      final position =
          await (_arrivalPosition?.call() ?? _currentArrivalPosition());
      if (!position.accuracy.isFinite ||
          position.accuracy <= 0 ||
          position.accuracy > 100) {
        throw const TechnicianRequestsApiException(
          'دقة الموقع ضعيفة. حاول تحديد موقعك تاني قبل بدء الشغل.',
        );
      }
      await _send(
        'POST',
        '/v1/tracking/orders/$orderId/location',
        body: {
          'latitude': position.latitude,
          'longitude': position.longitude,
          'accuracyMeters': position.accuracy,
          'recordedAt': position.timestamp.toUtc().toIso8601String(),
          'sequence': DateTime.now().millisecondsSinceEpoch,
        },
      );
    } on TechnicianRequestsApiException {
      rethrow;
    } on Object {
      throw const TechnicianRequestsApiException(
        'تعذر تحديد موقعك. فعّل GPS واسمح بالوصول للموقع وحاول تاني.',
      );
    }
  }

  Future<Position> _currentArrivalPosition() async {
    if (!await Geolocator.isLocationServiceEnabled()) {
      throw const TechnicianRequestsApiException('فعّل GPS قبل بدء الشغل.');
    }
    var permission = await Geolocator.checkPermission();
    if (permission == LocationPermission.denied)
      permission = await Geolocator.requestPermission();
    if (permission == LocationPermission.denied ||
        permission == LocationPermission.deniedForever) {
      throw const TechnicianRequestsApiException(
        'اسمح للتطبيق بالوصول للموقع قبل بدء الشغل.',
      );
    }
    return Geolocator.getCurrentPosition(
      locationSettings: const LocationSettings(
        accuracy: LocationAccuracy.high,
        timeLimit: Duration(seconds: 12),
      ),
    );
  }

  Future<List<TechnicianOffer>> myOffers({String status = 'pending'}) async =>
      (await myOffersPage(status: status)).offers;

  Future<TechnicianOffersPage> myOffersPage({
    String status = 'pending',
    int limit = 50,
    String? cursor,
  }) async {
    final d = await _send(
      'GET',
      '/v1/technician/offers',
      query: {
        'status': status,
        'limit': '$limit',
        if (cursor != null) 'cursor': cursor,
      },
    );
    final nextCursor = d['nextCursor'];
    if (nextCursor != null && nextCursor is! String) {
      throw const FormatException('Invalid technician offers cursor.');
    }
    return TechnicianOffersPage(
      offers: _items(d).map(TechnicianOffer.fromJson).toList(growable: false),
      nextCursor: nextCursor as String?,
    );
  }

  Future<TechnicianOffer> _postOffer(
    String id,
    String suffix,
    Map<String, Object?> body, {
    String method = 'POST',
    String? idempotencyKey,
  }) async {
    final identity = 'offer.create:$id$suffix';
    final key = idempotencyKey ?? _intentKey(identity, body);
    final d = await _send(
      method,
      '/v1/technician/requests${id.isEmpty ? '' : '/$id'}$suffix',
      body: body,
      idempotencyKey: key,
    );
    if (idempotencyKey == null) _clearIntentKey(identity, key);
    return TechnicianOffer.fromJson(d);
  }

  List<Map<String, Object?>> _items(Map<String, Object?> d) =>
      ((d['data'] ?? d['items']) as List? ?? const [])
          .whereType<Map<String, dynamic>>()
          .map((e) => e.cast<String, Object?>())
          .toList();
  Future<Map<String, Object?>> _send(
    String method,
    String path, {
    Map<String, String>? query,
    Map<String, Object?>? body,
    String? idempotencyKey,
  }) async {
    try {
      var s = await _session();
      Future<http.Response> send(AuthSession a) async {
        var uri = _baseUri.resolveApiPath(path);
        if (query != null) uri = uri.replace(queryParameters: query);
        final abort = Completer<void>();
        final request =
            http.AbortableRequest(method, uri, abortTrigger: abort.future)
              ..headers.addAll({
                'accept': 'application/json',
                'authorization': 'Bearer ${a.accessToken}',
                if (idempotencyKey != null) 'Idempotency-Key': idempotencyKey,
                if (method != 'GET' && method != 'DELETE')
                  'content-type': 'application/json',
              });
        if (method != 'GET' && method != 'DELETE') {
          request.body = jsonEncode(body ?? <String, Object?>{});
        }
        try {
          final response = _client.send(request).then((streamed) {
            if (abort.isCompleted) {
              throw TimeoutException('Technician request timed out.');
            }
            return readBoundedHttpResponse(streamed, maxBytes: 128 * 1024);
          });
          return await response.timeout(_requestTimeout);
        } on TimeoutException {
          if (!abort.isCompleted) abort.complete();
          rethrow;
        }
      }

      var response = await send(s);
      final refresh = _ensureSession;
      if (response.statusCode == 401 && refresh != null && await refresh()) {
        final refreshed = await _store.readSession();
        if (refreshed != null &&
            refreshed.isAccessTokenUsable(DateTime.now())) {
          s = refreshed;
          response = await send(s);
        }
      }
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw TechnicianRequestsApiException(
          _error(response).message,
          statusCode: response.statusCode,
          code: _error(response).code,
        );
      }
      if (response.bodyBytes.isEmpty) return <String, Object?>{};
      final decoded = jsonDecode(response.body);
      if (decoded is! Map || decoded.keys.any((key) => key is! String)) {
        throw const FormatException('Invalid technician API response.');
      }
      return decoded.cast<String, Object?>();
    } on TechnicianRequestsApiException {
      rethrow;
    } on TimeoutException {
      throw const TechnicianRequestsApiException(
        'الاتصال أخد وقت طويل. حاول تاني.',
      );
    } on ResponseTooLargeException {
      throw const TechnicianRequestsApiException('استجابة الخادم كبيرة جدًا.');
    } on http.ClientException {
      throw const TechnicianRequestsApiException(
        'تعذر الاتصال بالخادم. حاول مرة تانية.',
      );
    } on FormatException {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    } on TypeError {
      throw const TechnicianRequestsApiException(
        'استجابة غير صالحة من الخادم.',
      );
    }
  }

  String _intentKey(String identity, Object payload) {
    final fingerprint = jsonEncode(payload);
    final existing = _pendingMutationIntents[identity];
    if (existing != null && existing.fingerprint == fingerprint)
      return existing.key;
    final key = _uuid.v4();
    _pendingMutationIntents[identity] = _PendingMutationIntent(
      fingerprint,
      key,
    );
    return key;
  }

  void _clearIntentKey(String identity, String key) {
    if (_pendingMutationIntents[identity]?.key == key) {
      _pendingMutationIntents.remove(identity);
    }
  }

  Future<AuthSession> _session() async {
    var s = await _store.readSession();
    if (s != null && s.isAccessTokenUsable(DateTime.now())) return s;
    final refresh = _ensureSession;
    if (refresh != null && await refresh()) {
      s = await _store.readSession();
      if (s != null) return s;
    }
    throw const TechnicianRequestsApiException(
      'الجلسة منتهية. سجّل الدخول مرة تانية.',
      statusCode: 401,
    );
  }

  ({String message, String? code}) _error(http.Response r) {
    try {
      final d = jsonDecode(r.body);
      if (d is Map && d['message'] is String)
        return (message: d['message'] as String, code: d['code'] as String?);
    } catch (_) {}
    return (message: 'تعذر تنفيذ العملية.', code: null);
  }
