class TechIncomingPage extends StatefulWidget {
  const TechIncomingPage({
    this.request = TechIncomingRequestEntity.sample,
    this.onAccept,
    this.onReject,
    this.onExpired,
    this.api,
    this.billingSummary,
    super.key,
  });

  final TechIncomingRequestEntity request;
  final VoidCallback? onAccept, onExpired;
  final ValueChanged<String?>? onReject;
  final TechnicianRequestsApi? api;
  final Future<CommissionSummary> Function()? billingSummary;

  @override
  State<TechIncomingPage> createState() => _TechIncomingPageState();
}

class _TechIncomingPageState extends State<TechIncomingPage> {
  late final TechnicianRequestsApi _api;
  late TechIncomingRequestEntity _request;
  bool _loading = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    _request = widget.request;
    _api = widget.api ?? TechnicianRequestsApi.fromEnvironment();
    unawaited(_load());
  }

  @override
  void dispose() {
    if (widget.api == null) _api.close();
    super.dispose();
  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final detail = await _api.details(widget.request.id);
      if (mounted) setState(() => _request = detail.toEntity());
    } on Object {
      if (mounted) setState(() => _error = 'تعذر تحميل الطلب. حاول مرة تانية.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _offer(bool counter) async {
    if (!await billingAllowsAction(
          context,
          loadSummary: widget.billingSummary,
        ) ||
        !mounted)
      return;
    await showTechnicianOfferSheet(
      context,
      request: _request,
      api: _api,
      billingSummary: widget.billingSummary,
      counter: counter,
      onSubmitted: () {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('عرضك مستني تأكيد العميل')),
        );
        widget.onAccept?.call();
        if (Navigator.canPop(context)) Navigator.pop(context);
      },
    );
  }

  String _time(String? raw) {
    final t = DateTime.tryParse(raw ?? '')?.toLocal();
    return t == null
        ? '—'
        : '${t.hour.toString().padLeft(2, '0')}:${t.minute.toString().padLeft(2, '0')}';
  }

  String _schedule(String raw) {
    final time = DateTime.tryParse(raw)?.toLocal();
    return time == null
        ? raw
        : '${time.day}/${time.month}/${time.year} · ${_time(raw)}';
  }

  String _money(String? raw, int fallback) {
    final n =
        BigInt.tryParse(raw ?? '') ?? BigInt.from(fallback) * BigInt.from(100);
    return '${n ~/ BigInt.from(100)}.${(n % BigInt.from(100)).toString().padLeft(2, '0')} ج';
  }

  String _initials(String name) {
    final parts = name.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty || parts.first.isEmpty) return 'ف';
    if (parts.length == 1) return parts.first.characters.first;
    return '${parts.first.characters.first} ${parts[1].characters.first}';
  }

