Future<void> showTechnicianOfferSheet(
  BuildContext context, {
  required TechIncomingRequestEntity request,
  required VoidCallback onSubmitted,
  bool counter = false,
  TechnicianRequestsApi? api,
  Future<CommissionSummary> Function()? billingSummary,
}) async {
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    backgroundColor: Colors.transparent,
    builder: (_) => TechnicianOfferSheet(
      request: request,
      onSubmitted: onSubmitted,
      counter: counter,
      api: api,
      billingSummary: billingSummary,
    ),
  );
}

class TechnicianOfferSheet extends StatefulWidget {
  const TechnicianOfferSheet({
    required this.request,
    required this.onSubmitted,
    this.counter = false,
    this.api,
    this.billingSummary,
    super.key,
  });

  final TechIncomingRequestEntity request;
  final VoidCallback onSubmitted;
  final bool counter;
  final TechnicianRequestsApi? api;
  final Future<CommissionSummary> Function()? billingSummary;

  @override
  State<TechnicianOfferSheet> createState() => _TechnicianOfferSheetState();
}

class _TechnicianOfferSheetState extends State<TechnicianOfferSheet> {
  late final TechnicianRequestsApi _api;
  late final TextEditingController _price;
  final _note = TextEditingController();
  final _form = GlobalKey<FormState>();
  String _location = 'customer_site';
  bool _sending = false;
  String? _error, _key, _attemptBody;

  BigInt get _minimum =>
      BigInt.tryParse(widget.request.customerOfferMinor ?? '') ??
      BigInt.from(widget.request.priceMin) * BigInt.from(100);

  BigInt get _maximum =>
      BigInt.tryParse(widget.request.offerCapMinor ?? '') ??
      BigInt.from(widget.request.priceMax) * BigInt.from(100);

  bool get _workshopAllowed =>
      widget.request.acceptsWorkshopJobs &&
      widget.request.locationPreference != 'customer_site_only';

  @override
  void initState() {
    super.initState();
    _api = widget.api ?? TechnicianRequestsApi.fromEnvironment();
    _price = TextEditingController(
      text: _format(widget.counter ? _minimum + BigInt.one : _minimum),
    );
    if (widget.request.locationPreference == 'workshop_only') {
      _location = 'provider_workshop';
    }
  }

  @override
  void dispose() {
    _price.dispose();
    _note.dispose();
    if (widget.api == null) _api.close();
    super.dispose();
  }

  String _format(BigInt minor) =>
      '${minor ~/ BigInt.from(100)}.${(minor % BigInt.from(100)).toString().padLeft(2, '0')}';

  BigInt? _parse(String text) {
    if (!RegExp(r'^\d+(\.\d{1,2})?$').hasMatch(text.trim())) return null;
    final parts = text.trim().split('.');
    return BigInt.parse(parts.first) * BigInt.from(100) +
        BigInt.parse(parts.length > 1 ? parts.last.padRight(2, '0') : '0');
  }

  Future<void> _submit() async {
    if (!await billingAllowsAction(context, loadSummary: widget.billingSummary))
      return;
    if (_sending || !_form.currentState!.validate()) return;
    final amount = widget.counter ? _parse(_price.text)! : _minimum;
    final draft = OfferDraft(
      kind: widget.counter ? 'counter' : 'accept',
      serviceLocation: _location,
      amountMinor: amount.toString(),
      note: _note.text.trim(),
    );
    final body = draft.toJson().toString();
    if (_attemptBody != body) {
      _key = const Uuid().v4();
      _attemptBody = body;
    }
    setState(() {
      _sending = true;
      _error = null;
    });
    try {
      await _api.createOffer(widget.request.id, draft, idempotencyKey: _key);
      if (!mounted) return;
      Navigator.pop(context);
      widget.onSubmitted();
    } on TechnicianRequestsApiException catch (error) {
      if (error.code == 'COMMISSION_PAYMENT_REQUIRED') {
        if (mounted) await showBillingBlockedSheet(context);
        return;
      }
      if (mounted) setState(() => _error = error.message);
    } on Object {
      if (mounted) setState(() => _error = 'تعذر إرسال العرض. حاول مرة تانية.');
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final r = widget.request;
    final amount = widget.counter ? _parse(_price.text) : _minimum;
    final bottomInset = MediaQuery.viewInsetsOf(context).bottom;

    return Container(
      decoration: const BoxDecoration(
        color: V2Colors.surface,
        borderRadius: BorderRadius.only(
          topLeft: Radius.circular(28),
          topRight: Radius.circular(28),
        ),
      ),
      child: SafeArea(
        child: Padding(
          padding: EdgeInsets.only(bottom: bottomInset),
