                        label: const Text('في المقر'),
                        enabled: _workshopAllowed,
                      ),
                    ],
                    selected: {_location},
                    style: ButtonStyle(
                      shape: WidgetStateProperty.all(
                        RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(16),
                        ),
                      ),
                    ),
                    onSelectionChanged: _sending
                        ? null
