                  ),
                  if (!_workshopAllowed)
                    Padding(
                      padding: const EdgeInsets.only(top: 8),
                      child: Row(
                        children: [
                          const Icon(
                            Icons.info_outline_rounded,
                            size: 15,
                            color: V2Colors.inkMuted,
                          ),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(
                              r.locationPreference == 'customer_site_only'
                                  ? 'العميل طلب التنفيذ في مكانه.'
