                              style: const TextStyle(
                                fontSize: 12.5,
                                color: V2Colors.inkMuted,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),

                  // Counter price input & slider
                  if (widget.counter) ...[
                    const SizedBox(height: 16),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 14,
                        vertical: 10,
                      ),
                      decoration: BoxDecoration(
                        color: V2Colors.surface,
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(color: V2Colors.accent, width: 1.5),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'السعر بالجنيه',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w600,
                              color: V2Colors.inkMuted,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Row(
                            children: [
                              Expanded(
                                child: TextFormField(
                                  controller: _price,
                                  enabled: !_sending,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  style: const TextStyle(
                                    fontSize: 24,
                                    fontWeight: FontWeight.w800,
                                    color: V2Colors.ink,
                                  ),
                                  decoration: const InputDecoration(
                                    isDense: true,
                                    border: InputBorder.none,
                                    contentPadding: EdgeInsets.zero,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                  validator: (v) {
                                    final n = _parse(v ?? '');
                                    return n == null ||
                                            n <= _minimum ||
                                            n > _maximum
                                        ? 'السعر لازم يكون أكبر من ${_format(_minimum)} ولحد ${_format(_maximum)} ج'
                                        : null;
                                  },
                                ),
                              ),
                              const Text(
                                'ج',
                                style: TextStyle(
                                  fontSize: 16,
                                  fontWeight: FontWeight.w700,
                                  color: V2Colors.inkLight,
                                ),
                              ),
                            ],
                          ),
