                        : _submit,
                    child: Text(
                      _sending ? 'جاري الإرسال…' : 'إرسال العرض',
                      style: const TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}import { CommissionBillingModule } from '../modules/commission-billing/commission-billing.module';
