export class AppModule {}import { realtimeEnabled } from './realtime-enabled';
import { observeJob, registerJob } from '../../common/observability/observe-job';
import { reportError } from '../../common/observability/error-reporting';
import { jobRuns } from '../../common/observability/metrics';
import { reserveSparePartNotification } from '../spare-parts/spare-part-notification-quota';
import {
  Injectable,
  Logger,
  type OnApplicationBootstrap,
  type OnApplicationShutdown,
} from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { ConfigService } from '@nestjs/config';
import { randomUUID } from 'node:crypto';
import { DataSource, type EntityManager } from 'typeorm';

import { getDispatchEligibilitySql } from '../orders/dispatch-eligibility.sql';
import { queryRows } from '../../common/database/query-rows';
import { DISPATCH } from '../orders/dispatch.constants';
import { RealtimeGateway } from './realtime.gateway';
import { PushDeliveryError, RealtimePushService } from './realtime-push.service';

const BATCH_SIZE = 100;
const RUN_INTERVAL_MS = 1_000;
const MAX_ATTEMPTS = 20;
const CLAIM_RENEW_INTERVAL_MS = 30_000;

interface OutboxRow {
  id: string;
  event_type: string;
  aggregate_id: string;
  recipients: unknown[];
  payload: Record<string, unknown>;
  attempts: number;
  push_retry_tokens: string[];
  socket_published_at: Date | string | null;
}

interface ClaimHeartbeat {
  isLost(): boolean;
  stop(): void;
}

@Injectable()
export class RealtimeOutboxPublisher implements OnApplicationBootstrap, OnApplicationShutdown {
  private readonly logger = new Logger(RealtimeOutboxPublisher.name);
  private timer: NodeJS.Timeout | null = null;
  private running = false;
  private readonly workerId = randomUUID();

  constructor(
    @InjectDataSource() private readonly dataSource: DataSource,
    private readonly gateway: RealtimeGateway,
    private readonly push: RealtimePushService,
    private readonly config: ConfigService,
  ) {}

  onApplicationBootstrap(): void {
    if (realtimeEnabled(this.config)) registerJob('realtime_outbox');
    void this.runOnceSafely();
    this.timer = setInterval(() => void this.runOnceSafely(), RUN_INTERVAL_MS);
    this.timer.unref();
  }

  onModuleDestroy(): void {
    this.onApplicationShutdown();
  }

  onApplicationShutdown(): void {
    if (this.timer != null) clearInterval(this.timer);
    this.timer = null;
  }

  async publishOnce(): Promise<number> {
    if (!realtimeEnabled(this.config)) return 0;
    // A previous process version may have left an event at the retry limit
    // while it still held a lease. Terminalize it once that lease is gone.
    await this.dataSource.query(
      `UPDATE domain_event_outbox
       SET failed_at = COALESCE(failed_at, now()),
           failure_reason = LEFT(COALESCE(last_error, 'maximum attempts reached'), 500),
           next_attempt_at = NULL, claimed_by = NULL, claim_expires_at = NULL
       WHERE published_at IS NULL AND failed_at IS NULL AND attempts >= $1
         AND (claim_expires_at IS NULL OR claim_expires_at < now())`,
      [MAX_ATTEMPTS],
    );
    const claimed = await this.dataSource.transaction(async (manager) => {
      return await manager.query<OutboxRow[]>(
        `WITH candidates AS (
           SELECT id FROM domain_event_outbox
           WHERE published_at IS NULL
             AND failed_at IS NULL AND attempts < $3
             AND (next_attempt_at IS NULL OR next_attempt_at <= now())
             AND (claim_expires_at IS NULL OR claim_expires_at < now())
           ORDER BY id LIMIT $1 FOR UPDATE SKIP LOCKED
         )
         UPDATE domain_event_outbox o
         SET claimed_by = $2, claim_expires_at = now() + interval '2 minutes'
         FROM candidates c WHERE o.id = c.id
         RETURNING o.id, o.event_type, o.aggregate_id, o.recipients, o.payload, o.attempts,
                   o.push_retry_tokens, o.socket_published_at`,
        [BATCH_SIZE, this.workerId, MAX_ATTEMPTS],
      );
    });
    const rows = queryRows<OutboxRow>(claimed);
    let published = 0;
    for (const row of rows) {
      let heartbeat: ClaimHeartbeat | null = null;
      try {
        // Earlier rows can exhaust the batch's lease. Reclaim/renew this row
        // before side effects; an expired row claimed by another worker is skipped.
        const owned = await this.dataSource.query<Array<{ id: string }>>(
          `UPDATE domain_event_outbox SET claim_expires_at = now() + interval '2 minutes'
           WHERE id = $1 AND claimed_by = $2 AND published_at IS NULL AND failed_at IS NULL
           RETURNING id`,
          [row.id, this.workerId],
        );
        if (queryRows<{ id: string }>(owned).length === 0) continue;
        heartbeat = this.renewClaimWhileWorking(row.id);
        let recipients =
          row.event_type === 'request.new'
            ? await this.dataSource.transaction((manager) =>
                this.resolveEligibleTechnicians(manager, row.aggregate_id, row.recipients),
              )
            : row.event_type === 'spare_part.request.new'
              ? await this.dataSource.transaction((manager) =>
                  this.resolveEligibleSparePartTechnicians(manager, row.aggregate_id, row.id),
                )
              : this.normalizeRecipients(row.recipients);
        if (row.event_type === 'order.assigned' && recipients.length > 0) {
          const current = await this.dataSource.query<Array<{ id: string }>>(
            `SELECT u.id FROM users u JOIN service_orders o ON o.id = $1
             WHERE u.id = ANY($2::uuid[])
               AND u.id IN (o.customer_id, o.technician_id, o.backup_technician_id)`,
            [row.aggregate_id, recipients],
          );
          recipients = current.map((recipient) => recipient.id);
        }
        const eventPayload =
          row.event_type === 'chat.message.created' && row.payload.systemMessage === true
            ? await this.materializeSystemChatMessage(row)
            : row.payload;
        const payload = { ...eventPayload, eventId: row.id };
        if (heartbeat.isLost()) continue;
        if (row.socket_published_at == null) {
          if (heartbeat.isLost()) continue;
          if (row.event_type === 'chat.message.created') {
            await this.gateway.emitChatMessage(row.aggregate_id, payload);
          } else {
            await this.gateway.emitEvent(
              row.event_type,
              row.id,
              row.aggregate_id,
              recipients,
              payload,
            );
          }
          const markedSocket = await this.dataSource.query<Array<{ id: string }>>(
            `UPDATE domain_event_outbox SET socket_published_at = now()
             WHERE id = $1 AND claimed_by = $2 AND published_at IS NULL AND failed_at IS NULL
             RETURNING id`,
            [row.id, this.workerId],
          );
          if (queryRows<{ id: string }>(markedSocket).length === 0) {
            this.logger.warn(`Outbox lease for ${row.id} was lost after socket delivery.`);
            continue;
          }
        }
        // Each delivery channel is at-least-once; avoid starting push if the
        // lease heartbeat failed while the socket channel was in flight.
        if (heartbeat.isLost()) continue;
        const pushRecipients =
          row.event_type === 'chat.message.created' && typeof row.payload.senderId === 'string'
            ? recipients.filter((recipient) => recipient !== row.payload.senderId)
            : recipients;
        // EntityManager outside a transaction uses autocommit queries, so no
        // row lock or long-lived transaction spans the FCM network request.
        // Firebase sendEach has no AbortSignal. Do not race it against a local
        // timeout that would schedule a duplicate while the first send remains
        // live. Renew this row's lease until Firebase settles; delivery remains
        // at-least-once if the process itself dies mid-request.
        await this.push.notify(this.dataSource.manager, row.event_type, pushRecipients, payload, {
          ...(row.event_type.startsWith('billing.') ? { persistInApp: false } : {}),
          ...(row.push_retry_tokens.length > 0 ? { tokenAllowlist: row.push_retry_tokens } : {}),
        });
        const finalized = await this.dataSource.query<Array<{ id: string }>>(
          `UPDATE domain_event_outbox
           SET published_at = now(), last_error = NULL, next_attempt_at = NULL,
               claimed_by = NULL, claim_expires_at = NULL, recipients = $3::jsonb,
               push_retry_tokens = '{}'::text[]
           WHERE id = $1 AND claimed_by = $2 AND published_at IS NULL
           RETURNING id`,
          [
            row.id,
            this.workerId,
            JSON.stringify(
              row.event_type === 'request.new'
                ? recipients.map((id) => ({ kind: 'technician', id }))
                : row.recipients,
            ),
          ],
        );
        if (queryRows<{ id: string }>(finalized).length > 0) published += 1;
      } catch (error) {
        jobRuns.inc({ job: 'outbox_delivery', outcome: 'failure' });
        reportError(error, 'outbox_delivery');
        if (heartbeat?.isLost()) continue;
        const failedTokens = error instanceof PushDeliveryError ? [...error.failedTokens] : null;
        await this.dataSource.query(
          `UPDATE domain_event_outbox
           SET attempts = LEAST(attempts + 1, 32767),
               failed_at = CASE WHEN attempts + 1 >= $4 THEN COALESCE(failed_at, now()) ELSE failed_at END,
               failure_reason = CASE WHEN attempts + 1 >= $4 THEN LEFT($3, 500) ELSE failure_reason END,
               next_attempt_at = CASE WHEN attempts + 1 >= $4 THEN NULL
                 ELSE now() + make_interval(secs => LEAST(300.0, power(2, LEAST(attempts + 1, 9)))::int)
               END,
               last_error = LEFT($3, 500), claimed_by = NULL, claim_expires_at = NULL,
               push_retry_tokens = CASE WHEN $5::boolean THEN $6::text[] ELSE push_retry_tokens END
           WHERE id = $1 AND claimed_by = $2`,
          [
            row.id,
            this.workerId,
            this.errorMessage(error),
            MAX_ATTEMPTS,
            failedTokens != null,
            failedTokens,
          ],
        );
        if (row.attempts + 1 >= MAX_ATTEMPTS) {
          this.logger.error(
            `Outbox event ${row.id} moved to terminal failure after ${String(MAX_ATTEMPTS)} attempts.`,
          );
        }
      } finally {
        heartbeat?.stop();
      }
    }
    return published;
  }
  private async materializeSystemChatMessage(row: OutboxRow): Promise<Record<string, unknown>> {
    const senderId = row.payload.senderId;
    const clientMessageId = row.payload.clientMessageId;
    const text = row.payload.text;
    const status = row.payload.status;
    if (
      typeof senderId !== 'string' ||
      typeof clientMessageId !== 'string' ||
      typeof text !== 'string' ||
      typeof status !== 'string'
    ) {
      throw new Error('Outbox system-chat message payload is invalid.');
    }
    const inserted = await this.dataSource.query<Array<{ id: string; created_at: Date | string }>>(
      `INSERT INTO service_order_chat_messages
         (order_id,sender_id,client_message_id,kind,body,was_filtered,filter_reasons,metadata)
       VALUES($1,$2,$3::uuid,'system',$4,false,'[]'::jsonb,jsonb_build_object('status',$5::text))
       ON CONFLICT(sender_id,client_message_id) WHERE client_message_id IS NOT NULL DO NOTHING
       RETURNING id,created_at`,
      [row.aggregate_id, senderId, clientMessageId, text, status],
    );
    let message = queryRows<{ id: string; created_at: Date | string }>(inserted)[0];
    if (!message) {
      const existing = await this.dataSource.query<
        Array<{ id: string; created_at: Date | string }>
      >(
        `SELECT id,created_at FROM service_order_chat_messages
         WHERE sender_id=$1 AND client_message_id=$2::uuid LIMIT 1`,
        [senderId, clientMessageId],
      );
      message = queryRows<{ id: string; created_at: Date | string }>(existing)[0];
    }
    if (!message) throw new Error('Could not persist the outbox system-chat message.');
    return {
      id: message.id,
      clientMessageId,
      orderId: row.aggregate_id,
      senderId,
      kind: 'system',
      text,
      wasFiltered: false,
      warning: null,
      attachment: null,
      location: null,
      createdAt: message.created_at,
      readByPeer: false,
    };
  }

  private async resolveEligibleSparePartTechnicians(
    manager: EntityManager,
    requestId: string,
    eventId: string,
  ): Promise<string[]> {
    const rows = await manager.query<Array<{ technician_id: string }>>(
      `SELECT tp.user_id AS technician_id
       FROM spare_part_requests r
       JOIN technician_profiles tp ON true
       JOIN users u ON u.id=tp.user_id AND u.status='active' AND u.deleted_at IS NULL AND u.role='technician' AND u.provider_application_status='approved'
       JOIN service_subcategories sc ON sc.id=r.subcategory_id AND sc.is_active AND sc.spare_parts_enabled AND sc.deleted_at IS NULL
       JOIN service_categories cat ON cat.id=sc.category_id AND cat.is_active AND cat.deleted_at IS NULL
       WHERE r.id=$1 AND r.status='open' AND r.offers_deadline>now() AND tp.application_status='approved' AND tp.user_id<>r.owner_id
         AND EXISTS(SELECT 1 FROM provider_application_services pas JOIN services s ON s.id=pas.service_id WHERE pas.technician_id=tp.user_id AND s.subcategory_id=r.subcategory_id AND s.status='published' AND s.is_active AND s.deleted_at IS NULL)
         AND NOT EXISTS(SELECT 1 FROM risk_profiles rp WHERE rp.user_id=tp.user_id AND rp.level IN ('suspension_review','safety_hold','ban_review'))
         AND NOT EXISTS(SELECT 1 FROM discipline_cases dc WHERE dc.user_id=tp.user_id AND dc.case_type IN ('safety_hold','ban_review') AND dc.status IN ('open','escalated','enforced'))
         AND technician_within_work_hours(tp.user_id, now(), false)
       ORDER BY hashtextextended(tp.user_id::text || $2::text,0),tp.user_id LIMIT 200`,
      [requestId, eventId],
    );
    const eligible: string[] = [];
    for (const row of rows) {
      if (await reserveSparePartNotification(manager, row.technician_id, eventId))
        eligible.push(row.technician_id);
    }
    return eligible;
  }
  private async resolveEligibleTechnicians(
    manager: EntityManager,
    orderId: string,
    fallbackRecipients: readonly unknown[],
  ): Promise<string[]> {
    const rows = await manager.query<Array<{ technician_id: string }>>(
      `SELECT tp.user_id AS technician_id
       FROM service_orders o
       JOIN services s ON s.id = o.service_id
       JOIN technician_profiles tp ON true
       JOIN users u ON u.id = tp.user_id
       LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       WHERE o.id = $1 AND o.status = 'searching' AND o.search_expires_at > now()
         AND (o.search_starts_at IS NULL OR o.search_starts_at <= now())
         AND (o.pending_offers_count < $4 OR EXISTS (
           SELECT 1 FROM service_order_offers own_offer
           WHERE own_offer.order_id = o.id AND own_offer.technician_id = tp.user_id
             AND own_offer.status = 'pending' AND own_offer.expires_at > now()
         ))
         AND ($3::uuid[] IS NULL OR tp.user_id = ANY($3::uuid[]))
         ${getDispatchEligibilitySql()}
       ORDER BY CASE
         WHEN a.latitude IS NOT NULL AND a.longitude IS NOT NULL
           AND tp.work_center_lat IS NOT NULL AND tp.work_center_lng IS NOT NULL
         THEN geo_distance_km(tp.work_center_lat, tp.work_center_lng, a.latitude, a.longitude)
       END NULLS LAST, tp.user_id
       LIMIT $2`,
      [
        orderId,
        200,
        fallbackRecipients.length > 0 ? this.normalizeRecipients(fallbackRecipients) : null,
        DISPATCH.MAX_PENDING_OFFERS_PER_ORDER,
      ],
    );
    return rows.map((row) => row.technician_id);
  }

  private normalizeRecipients(value: unknown): string[] {
    if (!Array.isArray(value)) return [];
    return [
      ...new Set(
        value.flatMap((entry: unknown) => {
          if (typeof entry === 'string') return [entry];
          if (
            entry != null &&
            typeof entry === 'object' &&
            'id' in entry &&
            typeof entry.id === 'string'
          )
            return [entry.id];
          return [];
        }),
      ),
    ];
  }

  private renewClaimWhileWorking(id: string): ClaimHeartbeat {
    let renewing = false;
    let lost = false;
    const timer = setInterval(() => {
      if (renewing || lost) return;
      renewing = true;
      void this.dataSource
        .query(
          `UPDATE domain_event_outbox SET claim_expires_at = now() + interval '2 minutes'
           WHERE id = $1 AND claimed_by = $2 AND published_at IS NULL AND failed_at IS NULL
           RETURNING id`,
          [id, this.workerId],
        )
        .then((result: unknown) => {
          if (queryRows<{ id: string }>(result).length === 0) {
            lost = true;
            this.logger.warn(`Lost ownership while renewing outbox lease ${id}.`);
          }
        })
        .catch((error: unknown) => {
          lost = true;
          this.logger.warn(`Unable to renew outbox lease ${id}: ${this.errorMessage(error)}`);
        })
        .finally(() => {
          renewing = false;
        });
    }, CLAIM_RENEW_INTERVAL_MS);
    timer.unref();
    return {
      isLost: () => lost,
      stop: () => {
        clearInterval(timer);
      },
    };
  }

  private async runOnceSafely(): Promise<void> {
    if (this.running) return;
    this.running = true;
    try {
      if (realtimeEnabled(this.config))
        await observeJob('realtime_outbox', () => this.publishOnce());
    } catch (error) {
      this.logger.error(`Outbox publisher failed: ${this.errorMessage(error)}`);
    } finally {
      this.running = false;
    }
  }

  private errorMessage(error: unknown): string {
    return error instanceof Error ? error.message : 'unknown error';
  }
}import { randomUUID } from 'node:crypto';
