      [
        technicianId,
        JSON.stringify(
          Array.from({ length: 7 }, (_, dayOfWeek) => ({
            dayOfWeek,
            startMinute: 0,
            endMinute: 1440,
          })),
        ),
      ],
    );
    await db().query(`INSERT INTO services (id) VALUES ($1)`, [serviceId]);
    await db().query(
      `INSERT INTO provider_application_services (technician_id, service_id) VALUES ($1, $2)`,
      [technicianId, serviceId],
    );
    await db().query(
      `INSERT INTO user_addresses (id, area_code, latitude, longitude)
       VALUES ($1, 'cairo-nasr-city', 30.062, 31.340)`,
      [addressId],
    );
    await db().query(
      `INSERT INTO service_orders
         (id, service_id, status, selected_address_id, scheduled_at, search_starts_at,
          search_expires_at, location_preference, dispatch_stage)
       VALUES ($1, $2, 'searching', $3, now(), now(), now() + interval '1 hour',
               'customer_site_only', 1)`,
      [orderId, serviceId, addressId],
    );
    return { technicianId, serviceId, orderId, addressId };
  };

  const isEligible = async ({ technicianId, orderId }: Fixture): Promise<boolean> => {
    const rows = await db().query<Array<{ eligible: boolean }>>(
      `SELECT EXISTS (
         SELECT 1
         FROM service_orders o
         JOIN technician_profiles tp ON tp.user_id = $2
         JOIN users u ON u.id = tp.user_id
         LEFT JOIN user_addresses a ON a.id = o.selected_address_id
         LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
         WHERE o.id = $1
         ${DISPATCH_ELIGIBILITY_SQL}
       ) AS eligible`,
      [orderId, technicianId],
    );
    return rows[0]?.eligible === true;
  };

  beforeAll(async () => {
    if (!databaseUrl) throw new Error('TEST_DATABASE_URL or DATABASE_URL is required.');
    admin = new DataSource({ type: 'postgres', url: databaseUrl });
    await admin.initialize();
    await admin.query(`CREATE SCHEMA "${schema}"`);
    const connectionUrl = new URL(databaseUrl);
    connectionUrl.searchParams.set('options', `-c search_path="${schema}",public`);
    connectionUrl.searchParams.set('application_name', schema);
    database = new DataSource({ type: 'postgres', url: connectionUrl.toString(), logging: false });
    await database.initialize();
    await database.query(`
      CREATE TABLE users (id uuid PRIMARY KEY, status text NOT NULL, deleted_at timestamptz);
      CREATE TABLE services (id uuid PRIMARY KEY);
      CREATE TABLE technician_profiles (
        user_id uuid PRIMARY KEY, application_status text NOT NULL, is_busy boolean NOT NULL DEFAULT false,
        is_online boolean NOT NULL DEFAULT false, last_seen_at timestamptz, break_until timestamptz,
        work_center_lat double precision, work_center_lng double precision,
        work_radius_km smallint, max_request_distance_km smallint,
        accepts_emergency_orders boolean NOT NULL DEFAULT false,
        availability jsonb NOT NULL DEFAULT '[]'::jsonb, work_areas text[] NOT NULL DEFAULT '{}'
      );
      CREATE TABLE customer_technician_blocks (customer_id uuid, technician_id uuid);
      CREATE TABLE technician_customer_blocks (technician_id uuid, customer_id uuid);
      CREATE TABLE domain_event_outbox (id bigserial PRIMARY KEY, event_type text, aggregate_id uuid, recipients jsonb, payload jsonb);
      CREATE TABLE provider_application_services (technician_id uuid, service_id uuid);
      CREATE TABLE technician_work_areas (technician_id uuid, area_code text);
      CREATE TABLE user_addresses (id uuid PRIMARY KEY, area_code text, latitude double precision, longitude double precision);
      CREATE TABLE technician_workshops (technician_id uuid, accepts_workshop_jobs boolean NOT NULL DEFAULT false);
      CREATE TABLE provider_holidays (technician_id uuid, starts_on date NOT NULL, ends_on date NOT NULL);
      CREATE TABLE technician_time_off (technician_id uuid, starts_on date NOT NULL, ends_on date NOT NULL, cancelled_at timestamptz);
      CREATE TABLE service_order_technician_skips (order_id uuid, technician_id uuid);
      CREATE TABLE request_views (order_id uuid, technician_id uuid, PRIMARY KEY (order_id, technician_id));
      CREATE TABLE service_orders (
        version int NOT NULL DEFAULT 0, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now(), pending_offers_count smallint DEFAULT 0,
        is_emergency boolean NOT NULL DEFAULT false,
        id uuid PRIMARY KEY, customer_id uuid, service_id uuid NOT NULL, status text NOT NULL,
        selected_address_id uuid, scheduled_at timestamptz NOT NULL, search_starts_at timestamptz,
        search_expires_at timestamptz, location_preference text NOT NULL, dispatch_stage smallint NOT NULL,
        technician_id uuid, backup_technician_id uuid
      );
      CREATE FUNCTION technician_on_time_off(p_technician uuid, p_at timestamptz)
      RETURNS boolean LANGUAGE sql STABLE AS $$
        SELECT EXISTS (
          SELECT 1 FROM technician_time_off t
          WHERE t.technician_id = p_technician AND t.cancelled_at IS NULL
            AND (p_at AT TIME ZONE 'Africa/Cairo')::date BETWEEN t.starts_on AND t.ends_on
        )
      $$;
    `);
    // Reuse the real validator rather than leaving this fixture without the
    // database function required by dispatch eligibility.
    const runner = db().createQueryRunner();
    try {
      await runner.connect();
      const statements: string[] = [];
      await new TechnicianAvailabilityAndBreakGuards1700000000150().up({
        query: (sql: string) => {
          statements.push(sql);
          return Promise.resolve();
        },
      } as unknown as QueryRunner);
      const validator = statements.find((sql) =>
        sql.includes('CREATE OR REPLACE FUNCTION valid_technician_availability'),
      );
      if (validator === undefined) throw new Error('Availability validator is missing.');
      await runner.query(validator);
      await runner.query(
        `CREATE TABLE technician_commission_statements(technician_id uuid REFERENCES users(id),status text,amount_due_minor bigint); ${TECHNICIAN_BILLING_BLOCKED_SQL}`,
      );
    } finally {
      await runner.release();
    }
  });

  beforeEach(async () => {
    await db().query(
      'TRUNCATE domain_event_outbox, technician_customer_blocks, request_views, customer_technician_blocks, service_orders, service_order_technician_skips, provider_holidays, technician_time_off, technician_workshops, technician_work_areas, user_addresses, provider_application_services, technician_profiles, services, users CASCADE',
    );
  });

  afterAll(async () => {
    if (database?.isInitialized) await database.destroy();
    if (admin?.isInitialized) {
      await admin.query(`DROP SCHEMA IF EXISTS "${schema}" CASCADE`);
      await admin.destroy();
    }
  });
  it('excludes due and under-review technicians and restores eligibility immediately after settlement', async () => {
    const f = await fixture();
    expect(await isEligible(f)).toBe(true);
    await db().query(
      `INSERT INTO technician_commission_statements(technician_id,status,amount_due_minor) VALUES($1,'due',100)`,
      [f.technicianId],
    );
    expect(await isEligible(f)).toBe(false);
    await db().query(`UPDATE technician_commission_statements SET status='under_review'`);
    expect(await isEligible(f)).toBe(false);
    await db().query(`UPDATE technician_commission_statements SET status='paid'`);
    expect(await isEligible(f)).toBe(true);
  });
  it.each([
    { longitudeOffset: 0.145, events: 0 },
    { longitudeOffset: 0.2, events: 1 },
  ])(
    'expands east-west coverage without notifying original recipients again: $longitudeOffset',
    async ({ longitudeOffset, events }) => {
      const row = await fixture();
      await db().query('UPDATE user_addresses SET latitude=30, longitude=31 WHERE id=$1', [
        row.addressId,
      ]);
      await db().query(
        'UPDATE technician_profiles SET work_center_lat=30, work_center_lng=$2, work_radius_km=15, max_request_distance_km=30 WHERE user_id=$1',
        [row.technicianId, 31 + longitudeOffset],
      );
      await db().query(
        `UPDATE service_orders SET search_starts_at=now()-interval '10 minutes' WHERE id=$1`,
        [row.orderId],
      );
      const [result] = await db().query<
        Array<{ escalatedCount: number; queuedEventCount: number }>
      >(DISPATCH_STAGE_ESCALATION_SQL, [5, 250]);
      expect(result).toEqual({ escalatedCount: 1, queuedEventCount: events });
      expect(await db().query('SELECT * FROM domain_event_outbox')).toHaveLength(events);
    },
  );

  it('1. includes only approved technicians with an active, non-deleted account', async () => {
    const row = await fixture();
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `UPDATE technician_profiles SET application_status = 'pending' WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE technician_profiles SET application_status = 'approved' WHERE user_id = $1`,
      [row.technicianId],
    );
    await db().query(`UPDATE users SET status = 'suspended' WHERE id = $1`, [row.technicianId]);
    expect(await isEligible(row)).toBe(false);
    await db().query(`UPDATE users SET status = 'banned' WHERE id = $1`, [row.technicianId]);
    expect(await isEligible(row)).toBe(false);
    await db().query(`UPDATE users SET status = 'active', deleted_at = now() WHERE id = $1`, [
      row.technicianId,
    ]);
    expect(await isEligible(row)).toBe(false);
  });

  it('2. requires fresh online presence for immediate orders but not scheduled ones', async () => {
    const row = await fixture();
    await db().query(
      `UPDATE technician_profiles SET is_online = false, last_seen_at = now() - interval '10 minutes' WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE service_orders SET scheduled_at = now() + interval '4 hours', search_starts_at = now() WHERE id = $1`,
      [row.orderId],
    );
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `UPDATE technician_profiles SET is_online = true, last_seen_at = now() - interval '4 minutes' WHERE user_id = $1`,
      [row.technicianId],
    );
    await db().query(
      `UPDATE service_orders SET scheduled_at = now(), search_starts_at = now() WHERE id = $1`,
      [row.orderId],
    );
    expect(await isEligible(row)).toBe(false);
  });

  it('3. excludes a technician during a break and includes them after it ends', async () => {
    const row = await fixture();
    await db().query(
      `UPDATE technician_profiles SET break_until = now() + interval '10 minutes' WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE technician_profiles SET break_until = now() - interval '1 second' WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
  });

  it('4. requires an exact service specialty match', async () => {
    const row = await fixture();
    expect(await isEligible(row)).toBe(true);
    await db().query(`DELETE FROM provider_application_services WHERE technician_id = $1`, [
      row.technicianId,
    ]);
    expect(await isEligible(row)).toBe(false);
  });

  it('5. excludes holidays and existing time off on the Cairo execution date', async () => {
    const row = await fixture();
    await db().query(
      `INSERT INTO provider_holidays (technician_id, starts_on, ends_on)
       VALUES ($1, (now() AT TIME ZONE 'Africa/Cairo')::date, (now() AT TIME ZONE 'Africa/Cairo')::date)`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(`DELETE FROM provider_holidays WHERE technician_id = $1`, [row.technicianId]);
    await db().query(
      `INSERT INTO technician_time_off (technician_id, starts_on, ends_on)
       VALUES ($1, (now() AT TIME ZONE 'Africa/Cairo')::date, (now() AT TIME ZONE 'Africa/Cairo')::date)`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
  });

  it('fails closed for an empty schedule even when emergency orders are enabled', async () => {
    const row = await fixture();
    await db().query(
      `UPDATE technician_profiles SET availability = '[]'::jsonb, accepts_emergency_orders = true WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(`UPDATE service_orders SET is_emergency = true WHERE id = $1`, [row.orderId]);
    expect(await isEligible(row)).toBe(false);
  });
  it('6. checks Cairo availability windows but permits an opted-in emergency outside them', async () => {
    const row = await fixture();
    // LOW-2: derive the day from the order's own stored scheduled_at instead of
    // a separate now() call, so a midnight crossover in Africa/Cairo between
    // the two queries cannot make this test flaky.
    const [clock] = await db().query<Array<{ day: number }>>(
      `SELECT ((EXTRACT(DOW FROM (scheduled_at AT TIME ZONE 'Africa/Cairo'))::int + 1) % 7) AS day FROM service_orders WHERE id = $1`,
      [row.orderId],
    );
    const wrongDay = ((clock?.day ?? 0) + 1) % 7;
    await db().query(`UPDATE technician_profiles SET availability = $2::jsonb WHERE user_id = $1`, [
      row.technicianId,
      JSON.stringify([{ dayOfWeek: wrongDay, startMinute: 0, endMinute: 1440 }]),
    ]);
    expect(await isEligible(row)).toBe(false);
    await db().query(`UPDATE service_orders SET is_emergency = true WHERE id = $1`, [row.orderId]);
    await db().query(
      `UPDATE technician_profiles SET accepts_emergency_orders = true WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
    for (const schedule of ['[]', '{}', '[{"dayOfWeek":"invalid"}]']) {
      await db().query(
        'UPDATE technician_profiles SET availability = $2::jsonb WHERE user_id = $1',
        [row.technicianId, schedule],
      );
      expect(await isEligible(row)).toBe(false);
    }
  });

  it('7. applies stage-specific distance with a bounding box and area fallback for missing coordinates', async () => {
    const row = await fixture();
    await db().query(`UPDATE user_addresses SET latitude = 30.112 WHERE id = $1`, [row.addressId]);
    await db().query(
      `UPDATE technician_profiles SET work_radius_km = 10, max_request_distance_km = 5 WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
    await db().query(`UPDATE service_orders SET dispatch_stage = 2 WHERE id = $1`, [row.orderId]);
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE technician_profiles SET work_center_lat = NULL, work_center_lng = NULL WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `UPDATE technician_profiles SET work_areas = ARRAY['giza-dokki']::text[] WHERE user_id = $1`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE technician_profiles SET work_areas = ARRAY['مدينة نصر']::text[] WHERE user_id = $1`,
      [row.technicianId],
    );
    await db().query(
      `INSERT INTO technician_work_areas (technician_id, area_code) VALUES ($1, 'cairo-nasr-city')`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
  });

  it('8. requires workshop acceptance only for workshop_only orders', async () => {
    const row = await fixture();
    await db().query(
      `UPDATE service_orders SET location_preference = 'workshop_only' WHERE id = $1`,
      [row.orderId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `INSERT INTO technician_workshops (technician_id, accepts_workshop_jobs) VALUES ($1, true)`,
      [row.technicianId],
    );
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `UPDATE service_orders SET location_preference = 'workshop_ok' WHERE id = $1`,
      [row.orderId],
    );
    expect(await isEligible(row)).toBe(true);
  });

  it('9. excludes a request explicitly skipped by the technician', async () => {
    const row = await fixture();
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `INSERT INTO service_order_technician_skips (order_id, technician_id) VALUES ($1, $2)`,
      [row.orderId, row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query('DELETE FROM service_order_technician_skips');
    expect(await isEligible(row)).toBe(true);
    const customerId = randomUUID();
    await db().query('UPDATE service_orders SET customer_id = $2 WHERE id = $1', [
      row.orderId,
      customerId,
    ]);
    await db().query(
      'INSERT INTO customer_technician_blocks (customer_id, technician_id) VALUES ($1, $2)',
      [customerId, row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
  });

  it('10. blocks in-flight work for immediate orders and only overlapping reservations for scheduled orders', async () => {
    const row = await fixture();
    const reservedId = randomUUID();
    await db().query(
      `INSERT INTO service_orders (id, service_id, status, scheduled_at, search_starts_at,
                                  location_preference, dispatch_stage, technician_id)
       VALUES ($1, $2, 'assigned', now(), now(), 'customer_site_only', 1, $3)`,
      [reservedId, row.serviceId, row.technicianId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE service_orders SET scheduled_at = now() + interval '4 hours', search_starts_at = now() WHERE id = $1`,
      [row.orderId],
    );
    expect(await isEligible(row)).toBe(true);
    await db().query(
      `UPDATE service_orders SET scheduled_at = now() + interval '4 hours', search_starts_at = now() WHERE id = $1`,
      [reservedId],
    );
    expect(await isEligible(row)).toBe(false);
    await db().query(
      `UPDATE service_orders SET scheduled_at = now() + interval '7 hours' WHERE id = $1`,
      [reservedId],
    );
    expect(await isEligible(row)).toBe(true);
  });
  it('uses latitude-adjusted longitude bounds without excluding eligible east-west requests', async () => {
    const value = await fixture();
    await db().query('UPDATE user_addresses SET longitude = 31.490 WHERE id = $1', [
      value.addressId,
    ]);
    expect(await isEligible(value)).toBe(true);
    await db().query('UPDATE service_orders SET dispatch_stage = 2 WHERE id = $1', [value.orderId]);
    expect(await isEligible(value)).toBe(true);
    await db().query('UPDATE user_addresses SET longitude = 31.540 WHERE id = $1', [
      value.addressId,
    ]);
    expect(await isEligible(value)).toBe(false);
  });
