T? _argumentAs<T>(Object? value) => value is T ? value : null;

/// Returns the fully materialised [OrderTrackingEntity] from a live-tracking
/// route argument, or `null` when the caller only supplied a
/// [LiveTrackingArgs] deep-link descriptor / no argument at all.
OrderTrackingEntity? _liveTrackingEntity(Object? argument) =>
    argument is OrderTrackingEntity ? argument : null;

/// Extracts the authoritative order id from either a full
/// [OrderTrackingEntity] or a [LiveTrackingArgs] deep-link descriptor.
/// Used by live-tracking sub-routes to support notifications, external
/// links and process-death recovery (M-19): sub-pages receive only the id
/// and load authoritative state themselves.
String? _liveTrackingOrderId(Object? argument) {
  if (argument is OrderTrackingEntity) return argument.orderId;
  if (argument is LiveTrackingArgs) return argument.orderId;
  return null;
}

