  Route<dynamic> onGenerateRoute(RouteSettings settings) {
    final serviceLink = Uri.tryParse(settings.name ?? '');
    if (serviceLink?.path == AppRoutes.serviceDetail &&
        serviceLink!.queryParameters['service']?.isNotEmpty == true) {
      return _slideFadeRoute<void>(
        ServiceDetailLinkPage(
          slug: serviceLink.queryParameters['service']!,
          ensureSession: authenticationRepository.restoreSession,
          authenticationRepository: authenticationRepository,
        ),
        settings,
      );
    }
    final guardedRedirect = _guardedRedirectFor(settings.name);
    if (guardedRedirect != null) {
      return onGenerateRoute(RouteSettings(name: guardedRedirect));
    }
    if (!_hasRequiredRouteArgument(settings)) {
      return _slideFadeRoute<void>(const NotFoundPage(), settings);
    }
    switch (settings.name) {
      case AppRoutes.splash:
        return MaterialPageRoute<void>(
          settings: settings,
          builder: (context) => SplashPage(
            authenticationRepository: authenticationRepository,
            onboardingRepository: onboardingRepository,
            permissionService: permissionService,
          ),
        );
      case AppRoutes.languageSelection:
        return _fadeRoute(const LanguageSelectionPage(), settings);
      case AppRoutes.locationPermission:
        final args = settings.arguments is RequiredPermissionsArguments
            ? settings.arguments! as RequiredPermissionsArguments
            : null;
        return _fadeRoute(
          LocationPermissionPage(
            permissionService: permissionService,
            isRequired: args != null,
            destination: args?.destination,
          ),
          settings,
        );
      case AppRoutes.notificationsPermission:
        final args = settings.arguments is RequiredPermissionsArguments
            ? settings.arguments! as RequiredPermissionsArguments
            : null;
        return _fadeRoute(
          NotificationsPermissionPage(
            permissionService: permissionService,
            destination: args?.destination,
          ),
          settings,
        );
      case AppRoutes.onboarding:
        return _fadeRoute(
          OnboardingPage(onboardingRepository: onboardingRepository),
          settings,
        );
      case AppRoutes.login:
        return _fadeRoute(
          LoginPage(
            authenticationRepository: authenticationRepository,
            permissionService: permissionService,
          ),
          settings,
        );
      case AppRoutes.signUp:
        return _fadeRoute(
          SignUpPage(authenticationRepository: authenticationRepository),
          settings,
        );
      case AppRoutes.forgotPassword:
        return _fadeRoute(
          ForgotPasswordPage(
            onSubmit: authenticationRepository.startPasswordRecovery,
            onSendEmailLink: authenticationRepository.sendPasswordResetEmail,
          ),
          settings,
        );
      case AppRoutes.twoFactorVerification:
        return _fadeRoute(
          TwoFactorVerificationPage(
            authenticationRepository: authenticationRepository,
            permissionService: permissionService,
          ),
          settings,
        );
      case AppRoutes.accountType:
        return _fadeRoute(
          AccountTypePage(authenticationRepository: authenticationRepository),
          settings,
        );
      case AppRoutes.home:
        return _fadeRoute(
          HomePage(authenticationRepository: authenticationRepository),
          settings,
        );
      case AppRoutes.serviceCategories:
        return _fadeRoute(const ServiceCategoriesPage(), settings);
      case AppRoutes.serviceSearch:
        // Returns the submitted query as a String to the caller.
        return _slideFadeRoute<String>(
          ServiceSearchPage(userId: authenticationRepository.currentUser?.id),
          settings,
        );
      case AppRoutes.categoryServices:
        final selection =
            _argumentAs<({ServiceCategory category, String subcategory})>(
              settings.arguments,
            );
        final category =
            selection?.category ??
            _argumentAs<ServiceCategory>(settings.arguments);
        if (category == null) {
          return _slideFadeRoute<void>(const NotFoundPage(), settings);
        }
        return _slideFadeRoute<void>(
          CategoryServicesPage(
            category: category,
            initialSubcategory: selection?.subcategory,
          ),
          settings,
        );
      case AppRoutes.serviceDetail:
        final selection =
            settings.arguments
                as ({ServiceCategory category, ServiceOption service});
        return _slideFadeRoute<void>(
          ServiceDetailPage(
            category: selection.category,
            service: selection.service,
            ensureSession: authenticationRepository.restoreSession,
            authenticationRepository: authenticationRepository,
          ),
          settings,
        );
      case AppRoutes.nearbyTechnicians:
        final selection =
            settings.arguments
                as ({ServiceCategory category, ServiceOption service});
        return _slideFadeRoute<void>(
          NearbyTechniciansPage(
            category: selection.category,
            service: selection.service,
          ),
          settings,
        );
      case AppRoutes.notifications:
        return _fadeRoute(const NotificationsPage(), settings);
      case AppRoutes.orders:
        final args = settings.arguments;
        final orderId = args is Map ? args['orderId']?.toString() : null;
        return _slideFadeRoute<void>(
          OrdersFlowPage(initialOrderId: orderId),
          settings,
        );
      case AppRoutes.ordersActive:
        return _slideFadeRoute<void>(
          const OrdersFlowPage(initialTab: OrdersFlowTab.active),
          settings,
        );
      case AppRoutes.ordersUpcoming:
        return _slideFadeRoute<void>(
          const OrdersFlowPage(initialTab: OrdersFlowTab.upcoming),
          settings,
        );
      case AppRoutes.ordersCompleted:
        return _slideFadeRoute<void>(
          const OrdersFlowPage(initialTab: OrdersFlowTab.completed),
          settings,
        );
      case AppRoutes.ordersCancelled:
        return _slideFadeRoute<void>(
          const OrdersFlowPage(initialTab: OrdersFlowTab.cancelled),
          settings,
        );
      case AppRoutes.ordersEmpty:
        return _slideFadeRoute<void>(
          const OrdersFlowPage(showEmpty: true),
          settings,
        );
      case AppRoutes.paymentFlow:
        final args =
            _argumentAs<PaymentFlowArgs>(settings.arguments) ??
            const PaymentFlowArgs();
        return _slideFadeRoute<bool>(PaymentFlowPage(args: args), settings);
      case AppRoutes.wallet:
        return _slideFadeRoute<bool>(
          const PaymentFlowPage(
            args: PaymentFlowArgs(entry: PaymentEntry.wallet),
          ),
          settings,
        );
      case AppRoutes.coupons:
        final args = _argumentAs<PaymentFlowArgs>(settings.arguments);
        return _slideFadeRoute<bool>(
          PaymentFlowPage(
            args: PaymentFlowArgs(
              amountMinor: args?.amountMinor ?? 40000,
              currency: args?.currency ?? 'EGP',
              initialMethod: args?.initialMethod ?? 'cash',
              entry: PaymentEntry.coupons,
              couponCode: args?.couponCode,
            ),
          ),
          settings,
        );
      case AppRoutes.cashReceipt:
        final args =
            _argumentAs<PaymentFlowArgs>(settings.arguments) ??
            const PaymentFlowArgs(entry: PaymentEntry.cashReceipt);
        return _slideFadeRoute<bool>(
          PaymentFlowPage(
            args: PaymentFlowArgs(
              amountMinor: args.amountMinor,
              currency: args.currency,
              initialMethod: args.initialMethod,
              entry: PaymentEntry.cashReceipt,
            ),
          ),
          settings,
        );
      case AppRoutes.serviceRequestFlow:
        final args = settings.arguments;
        int categoryIndex = 0;
        int initialStepIndex = 0;
        ServiceRequestDraft? draft;
        if (args is ServiceRequestFlowArguments) {
          draft = args.draft;
          categoryIndex = draft.selectedCategoryIndex;
          initialStepIndex = args.initialStepIndex;
        } else if (args is int) {
          categoryIndex = args;
        } else if (args is ServiceRequestDraft) {
          draft = args;
        } else if (args is Map<String, dynamic>) {
          categoryIndex = _argumentAs<int>(args['categoryIndex']) ?? 0;
          final requestedService =
              _argumentAs<String>(args['requestedService'])?.trim() ?? '';
          if (requestedService.isNotEmpty) {
            draft = ServiceRequestDraft(
              selectedCategoryIndex: categoryIndex,
              customIssueText: requestedService,
              description: 'طلب خدمة غير موجودة بالقائمة: $requestedService',
              photos: const [],
            );
          }
        }
        return _slideFadeRoute<void>(
          ServiceRequestFlowPage(
            initialCategoryIndex: categoryIndex,
            initialDraft: draft,
            initialStepIndex: initialStepIndex,
            authenticationRepository: authenticationRepository,
          ),
          settings,
        );
      case AppRoutes.chooseTechnicianFlow:
        final args = settings.arguments;
        String title = 'طلب طوارئ • كهرباء';
        ChooseTechnicianStep step = ChooseTechnicianStep.matching;
        TechnicianEntity? tech;
        if (args is String) {
          title = args;
        } else if (args is Map<String, dynamic>) {
          title = _argumentAs<String>(args['serviceTitle']) ?? title;
          step = _argumentAs<ChooseTechnicianStep>(args['initialStep']) ?? step;
          tech = _argumentAs<TechnicianEntity>(args['technician']);
        }
        return _slideFadeRoute<void>(
          ChooseTechnicianFlowPage(
            serviceTitle: title,
            initialStep: step,
            initialTechnician: tech,
          ),
          settings,
        );
      case AppRoutes.technicianProfile:
        final tech = _argumentAs<TechnicianEntity>(settings.arguments);
        if (tech == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          Builder(
            builder: (context) => ProfileScreen(
              technician: tech,
              onBack: () => Navigator.of(context).maybePop(),
              onSelect: () => Navigator.of(
                context,
              ).pushNamed(AppRoutes.confirmBooking, arguments: tech),
              onUnavailable: () {},
            ),
          ),
          settings,
        );
      case AppRoutes.confirmBooking:
        final tech = _argumentAs<TechnicianEntity>(settings.arguments);
        if (tech == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          Builder(
            builder: (context) => ConfirmScreen(
              technician: tech,
              onBack: () => Navigator.of(context).maybePop(),
              onConfirm: () => Navigator.of(context).pushNamedAndRemoveUntil(
                AppRoutes.bookingSuccess,
                (route) => route.isFirst,
                arguments: tech,
              ),
            ),
          ),
          settings,
        );
      case AppRoutes.bookingSuccess:
        final tech = _argumentAs<TechnicianEntity>(settings.arguments);
        if (tech == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          Builder(
            builder: (context) => SuccessScreen(
              technician: tech,
              onDone: () =>
                  Navigator.of(context).popUntil((route) => route.isFirst),
            ),
          ),
          settings,
        );
      case AppRoutes.roadsideEmergency:
        return _slideFadeRoute<void>(const RoadsideUnavailablePage(), settings);
      case AppRoutes.liveTracking:
        // H-06 / M-19: accept either the fully materialised tracking entity
        // or a [LiveTrackingArgs] deep-link descriptor. The main page loads
        // authoritative state via the repository regardless.
        final order = _liveTrackingEntity(settings.arguments);
        final args = _argumentAs<LiveTrackingArgs>(settings.arguments);
        if (order == null && args == null) {
          return _fadeRoute(const NotFoundPage(), settings);
        }
        return _slideFadeRoute<void>(
          LiveTrackingMainPage(order: order, deepLink: args),
          settings,
        );
      case AppRoutes.liveTrackingTimeline:
        final order = _liveTrackingEntity(settings.arguments);
        final orderId = _liveTrackingOrderId(settings.arguments);
        if (order == null && orderId == null) {
          return _fadeRoute(const NotFoundPage(), settings);
        }
        // H-02: when only a deep-link orderId is available (no hydrated
        // entity), redirect to the main tracking page which loads
        // authoritative state from the repository. Passing placeholder
        // data to the timeline would show fabricated events.
        if (order == null) {
          return _slideFadeRoute<void>(
            LiveTrackingMainPage(deepLink: LiveTrackingArgs(orderId!)),
            settings,
          );
        }
        return _slideFadeRoute<void>(FullTimelinePage(order: order), settings);
      case AppRoutes.liveTrackingMap:
        final order = _liveTrackingEntity(settings.arguments);
        final orderId = _liveTrackingOrderId(settings.arguments);
        if (order == null && orderId == null) {
          return _fadeRoute(const NotFoundPage(), settings);
        }
        // H-02: same rationale — the map page needs real technician data
        // and coordinates. Deep-linking with a placeholder entity would
        // show zeros for ETA/distance and a default technician name.
        if (order == null) {
          return _slideFadeRoute<void>(
            LiveTrackingMainPage(deepLink: LiveTrackingArgs(orderId!)),
            settings,
          );
        }
        return _slideFadeRoute<void>(
          LiveTrackingMapPage(order: order),
          settings,
        );
      case AppRoutes.liveTrackingChat:
        final args = settings.arguments;
        if (args is LiveChatArgs) {
          return _slideFadeRoute<void>(
            TechnicianChatPage(peerName: args.peerName, orderId: args.orderId),
            settings,
          );
        }
        debugPrint('liveTrackingChat requires LiveChatArgs with an orderId');
        return _fadeRoute(const NotFoundPage(), settings);
      case AppRoutes.liveTrackingSupport:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(LiveSupportPage(order: order), settings);
      case AppRoutes.liveTrackingReschedule:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          RescheduleAppointmentPage(order: order),
          settings,
        );
      case AppRoutes.liveTrackingCancel:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(CancelOrderPage(order: order), settings);
      case AppRoutes.liveTrackingCancelFees:
        final args = _argumentAs<CancelFeesArgs>(settings.arguments);
        final order = args?.order ?? _liveTrackingEntity(settings.arguments);
        if (order == null) {
          return _fadeRoute(const NotFoundPage(), settings);
        }
        return _slideFadeRoute<void>(
          CancelFeesPage(order: order, cancellationReason: args?.reason),
          settings,
        );
      case AppRoutes.liveTrackingWaitingAlternative:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          WaitingAlternativePage(order: order),
          settings,
        );
      case AppRoutes.liveTrackingAcceptAlternative:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          AcceptAlternativePage(order: order),
          settings,
        );
      case AppRoutes.liveTrackingOtp:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          OtpConfirmationPage(order: order),
          settings,
        );
      case AppRoutes.liveTrackingDelay:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(DelayTrackingPage(order: order), settings);
      case AppRoutes.liveTrackingComplete:
        final order = _liveTrackingEntity(settings.arguments);
        if (order == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(OrderCompletePage(order: order), settings);

      // ── Quotations & Inspection (12 Screens) ──
      case AppRoutes.inspectionStarted:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
        if (quote == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          InspectionStartedPage(quotation: quote),
          settings,
        );
      case AppRoutes.quoteReceived:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
        if (quote == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          QuoteReceivedPage(quotation: quote),
          settings,
        );
      case AppRoutes.quoteDetails:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
        if (quote == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          QuoteDetailsPage(quotation: quote),
          settings,
        );
      case AppRoutes.quoteAcceptedSuccess:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
        if (quote == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          QuoteAcceptedSuccessPage(quotation: quote),
          settings,
        );
      case AppRoutes.rejectQuote:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
        if (quote == null) return _fadeRoute(const NotFoundPage(), settings);
        return _slideFadeRoute<void>(
          RejectQuotePage(quotation: quote),
          settings,
        );
      case AppRoutes.requestQuoteModification:
        final quote = _argumentAs<QuotationEntity>(settings.arguments);
