  static bool _hasRequiredRouteArgument(RouteSettings settings) {
    final route = settings.name;
    final argument = settings.arguments;
    if (route == AppRoutes.categoryServices) {
      return argument is ServiceCategory;
    }
    if (route == AppRoutes.serviceDetail ||
        route == AppRoutes.nearbyTechnicians) {
      return argument is ({ServiceCategory category, ServiceOption service});
    }
    if (_technicianArgumentRoutes.contains(route)) {
      return argument is TechnicianEntity;
    }
    if (_trackingHydratableRoutes.contains(route)) {
      // Accept either the fully materialised tracking entity or a minimal
      // deep-link descriptor carrying just the order id; the page is
      // responsible for loading authoritative state from the repository.
      return argument is OrderTrackingEntity || argument is LiveTrackingArgs;
    }
    if (_trackingActionArgumentRoutes.contains(route)) {
      // H-02: action pages must never render or submit placeholder data.
      // A [LiveTrackingArgs] deep-link on its own is not enough.
      if (route == AppRoutes.liveTrackingCancelFees) {
        return argument is OrderTrackingEntity || argument is CancelFeesArgs;
      }
      return argument is OrderTrackingEntity;
    }
    if (route == AppRoutes.liveTrackingChat) {
      return argument is LiveChatArgs;
    }
    if (_quotationArgumentRoutes.contains(route)) {
      return argument is QuotationEntity;
    }
    if (route == AppRoutes.jobExecutionFlow) {
      if (argument is JobExecutionEntity) return true;
      if (argument is! Map<String, dynamic> ||
          argument['job'] is! JobExecutionEntity) {
        return false;
      }
      final step = argument['initialStep'];
      return step == null || (step is int && step >= 0 && step <= 17);
    }
    if (_jobArgumentRoutes.contains(route)) {
      return argument is JobExecutionEntity;
    }
    if (_techIncomingArgumentRoutes.contains(route)) {
      return argument is TechIncomingRequestEntity;
    }
    if (route == AppRoutes.techOrderDetails) {
      return argument is TechJobEntity;
    }
    if (route == AppRoutes.adminStaffDetails) {
      return argument is AdminStaffEntity;
    }
    if (route == AppRoutes.adminReviewJoinRequest) {
      return argument is TechJoinRequestEntity;
    }
    if (route == AppRoutes.adminTechProfile ||
        route == AppRoutes.adminTechAction) {
      return argument is AdminTechEntity;
    }
    if (route == AppRoutes.adminSubCategories) {
      return argument is AdminCategoryEntity;
    }
    if (route == AppRoutes.adminServicesList ||
        route == AppRoutes.adminAddService) {
      return argument is AdminSubCategoryEntity;
    }
    if (route == AppRoutes.adminEditService ||
        route == AppRoutes.adminQuestions ||
        route == AppRoutes.adminSpareParts) {
      return argument is AdminServiceEntity;
    }
    if (_adminOrderArgumentRoutes.contains(route)) {
      return argument is AdminOrderEntity;
    }
    if (route == AppRoutes.ratingSuccess) {
      return argument is ReviewSubmissionEntity;
    }
    if (route == AppRoutes.complaintDetails ||
        route == AppRoutes.complaintResponse) {
      return argument is String;
    }
    if (route == AppRoutes.warrantyClaim) {
      return argument is WarrantyItemEntity;
    }
    return true;
  }

  String? _guardedRedirectFor(String? routeName) {
    if (routeName == null) {
      return null;
    }
    if (kDebugMode &&
        enableTechnicianDashboardPreview &&
        _technicianPreviewRoutes.contains(routeName)) {
      return null;
    }
    if (_unavailableProviderRoutes.contains(routeName)) {
      return AppRoutes.providerSettingsHub;
    }

    AccountType? accountType;
    var isAuthenticated = false;
    try {
      isAuthenticated = authenticationRepository.isAuthenticated;
      accountType = authenticationRepository.accountType;
    } on Object {
      // Authentication/role lookup failures must fail closed.
      isAuthenticated = false;
      accountType = null;
    }
    final requiresAuthentication =
        _authenticatedRoutes.contains(routeName) ||
        _authenticatedRoutePrefixes.any(routeName.startsWith);
    if (requiresAuthentication && !isAuthenticated) {
      return AppRoutes.login;
    }
    if (requiresAuthentication &&
        accountType == null &&
        routeName != AppRoutes.accountType) {
      return AppRoutes.accountType;
    }
    if (routeName.startsWith('/admin/') && accountType != AccountType.admin) {
      return AppRoutes.home;
    }
    if (_customerOnlyRoutes.contains(routeName) &&
        accountType != AccountType.customer) {
      return accountType == AccountType.admin
          ? AppRoutes.adminDashboard
          : AppRoutes.home;
    }
    // Applying to become a provider is a customer-facing route. Other
    // technician routes remain restricted to approved service providers.
    if (routeName == AppRoutes.providerOnboarding) {
      return accountType == AccountType.admin ? AppRoutes.adminDashboard : null;
    }
    if (routeName.startsWith('/technician/') &&
        accountType != AccountType.serviceProvider) {
      return accountType == AccountType.admin
          ? AppRoutes.adminDashboard
          : AppRoutes.home;
    }
    // Order chat is shared with the assigned technician. Other live-tracking
    // routes are customer-facing. Defence-in-depth only; the
    // backend still authorises every subscribe/fetch/action per user. Admin
    // and technician accounts have their own tracking surfaces and should not
    // land on the customer flow if they open a deep-link internally.
    if (routeName.startsWith('/live-tracking') &&
        accountType != AccountType.customer &&
        !(routeName == AppRoutes.liveTrackingChat &&
            accountType == AccountType.serviceProvider)) {
      return accountType == AccountType.admin
          ? AppRoutes.adminDashboard
          : AppRoutes.home;
    }
    return null;
  }

  static PageRoute<void> _fadeRoute(Widget page, RouteSettings settings) {
    return PageRouteBuilder<void>(
      settings: settings,
      transitionDuration: const Duration(milliseconds: 450),
      pageBuilder: (context, animation, secondaryAnimation) => page,
      transitionsBuilder: (context, animation, secondaryAnimation, child) {
        return FadeTransition(
          opacity: CurvedAnimation(parent: animation, curve: Curves.easeOut),
          child: child,
        );
      },
    );
  }

  /// Smooth "open" transition: quick fade + subtle upward slide.
  /// Pairs with the shared `Hero` on the search bar for a fluid feel.
  static PageRoute<T> _slideFadeRoute<T>(Widget page, RouteSettings settings) {
    return PageRouteBuilder<T>(
      settings: settings,
      transitionDuration: const Duration(milliseconds: 350),
      pageBuilder: (context, animation, secondaryAnimation) => page,
      transitionsBuilder: (context, animation, secondaryAnimation, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
          reverseCurve: Curves.easeInCubic,
        );
        return FadeTransition(
          opacity: curved,
          child: SlideTransition(
            position: Tween<Offset>(
              begin: const Offset(0, 0.04),
              end: Offset.zero,
            ).animate(curved),
            child: child,
          ),
        );
      },
    );
  }
