interface BufferedUpload {
  originalname: string;
  mimetype: string;
  size: number;
  buffer?: Buffer;
  path?: string;
}

const MIB = 1024 * 1024;
const MIN_MULTIPART_PART_SIZE = 5 * MIB;
const TARGET_MULTIPART_PART_SIZE = 16 * MIB;
const MAX_MULTIPART_PARTS = 10_000;
const MAX_AVATAR_DIMENSION = 10_000;
const MAX_AVATAR_PIXELS = 25_000_000;
const MAX_VERIFICATION_WAITERS = 20;
const VERIFICATION_QUEUE_TIMEOUT_MS = 30_000;
const ORPHAN_AVATAR_GRACE_MS = 24 * 60 * 60_000;
const ORPHAN_ONBOARDING_GRACE_MS = 48 * 60 * 60_000;

@Injectable()
export class FilesService {
  private readonly logger = new Logger(FilesService.name);
  private verificationActive = 0;
  private readonly verificationWaiters: Array<() => void> = [];

  constructor(
    @InjectRepository(StoredFileEntity)
    private readonly files: Repository<StoredFileEntity>,
    private readonly storage: R2StorageService,
    private readonly audioMetadata: AudioMetadataService,
    private readonly videoMetadata: VideoMetadataService,
    private readonly dataSource: DataSource,
  ) {}

  async createUpload(
    owner: UserEntity,
    input: CreateFileUploadDto,
  ): Promise<Record<string, unknown>> {
    const settings = this.storage.settings;
    if (!settings.enabled)
      throw new ServiceUnavailableException('Object storage is not configured.');

    if (input.purpose === MediaPurpose.Avatar) {
      throw new BadRequestException('Use the protected avatar upload endpoint for profile images.');
    }
    if(input.purpose===MediaPurpose.CommissionPaymentProof && owner.role!==UserRole.Technician) {
      throw new BadRequestException({code:'TECHNICIAN_ONLY',message:'رفع إثبات دفع العمولة متاح للفنيين بس.'});
    }
    const requiresCompletionImageNormalization =
      input.purpose === MediaPurpose.JobEvidence ||
      input.purpose === MediaPurpose.Review ||
      input.purpose === MediaPurpose.CommissionPaymentProof;
    if (
      requiresCompletionImageNormalization &&
      input.purpose !== MediaPurpose.CommissionPaymentProof &&
      !isCompletionV2Enabled()
    ) {
      throw new ServiceUnavailableException('Completion V2 media uploads are disabled.');
    }
    const policy = validateMediaPolicy(input.kind, input.contentType, input.size, settings);
    validatePurposeMediaPolicy(input.kind, input.purpose, input.size, policy.contentType);
    const durationMs = validateMediaDuration(input.kind, input.purpose, input.durationMs);
    const originalName = this.sanitizeOriginalName(input.fileName);
    if (!originalName) throw new BadRequestException('fileName must not be blank.');

    const id = randomUUID();
    const now = new Date();
    const yyyy = String(now.getUTCFullYear());
    const mm = String(now.getUTCMonth() + 1).padStart(2, '0');
    const objectKey = [
      settings.keyPrefix,
      input.kind,
      yyyy,
      mm,
      owner.id,
      `${id}.${requiresCompletionImageNormalization ? 'webp' : policy.extension}`,
    ].join('/');
    const uploadProtocol =
      !requiresCompletionImageNormalization && input.size >= settings.multipartThresholdBytes
        ? UploadProtocol.Multipart
        : UploadProtocol.Single;
    const partSize =
      uploadProtocol === UploadProtocol.Multipart ? this.calculatePartSize(input.size) : null;
    const uploadExpiresAt = new Date(
      now.getTime() + settings.uploadSessionTtlHours * 60 * 60 * 1000,
    );
    const file = this.files.create({
      id,
      ownerId: owner.id,
      kind: input.kind,
      purpose: input.purpose,
      status: StoredFileStatus.Pending,
      uploadProtocol,
      objectKey,
      originalName,
      contentType: policy.contentType,
      expectedSize: String(input.size),
      actualSize: null,
      durationMs,
      etag: null,
      multipartUploadId: null,
      multipartPartSize: partSize,
      uploadExpiresAt,
      completedAt: null,
      deletedAt: null,
    });
    const identity = {
      key: objectKey,
      fileId: id,
      ownerId: owner.id,
      contentType: policy.contentType,
      contentLength: input.size,
      ...(durationMs === null ? {} : { durationMs }),
    };

    if (uploadProtocol === UploadProtocol.Single) {
      await this.reserveUpload(file);
      let uploadUrl: string;
      try {
        uploadUrl = await this.storage.createSingleUploadUrl(identity);
      } catch (error) {
        await this.cancelUnissuedUpload(file).catch((cleanupError: unknown) => {
          this.logCleanupFailure('single-presign-cancel', file.id, cleanupError);
        });
        throw error;
      }
      return {
        file: this.serialize(file),
        upload: {
          protocol: UploadProtocol.Single,
          url: uploadUrl,
          method: 'PUT',
          contentLength: input.size,
          headers: {
            'Cache-Control': 'private, no-store',
            'Content-Type': policy.contentType,
            'If-None-Match': '*',
            'x-amz-meta-file-id': id,
            'x-amz-meta-owner-id': owner.id,
            ...(durationMs === null ? {} : { 'x-amz-meta-duration-ms': String(durationMs) }),
          },
          expiresInSeconds: settings.uploadUrlTtlSeconds,
        },
      };
    }

    const uploadId = await this.storage.createMultipartUpload(identity);
    file.multipartUploadId = uploadId;
    try {
      await this.reserveUpload(file);
    } catch (error) {
      await this.storage.abortMultipartUpload(objectKey, uploadId).catch((abortError: unknown) => {
        this.logCleanupFailure('reservation-abort', file.id, abortError);
      });
      throw error;
    }
    return {
      file: this.serialize(file),
      upload: {
        protocol: UploadProtocol.Multipart,
        partSize,
        partCount: Math.ceil(input.size / (partSize ?? TARGET_MULTIPART_PART_SIZE)),
        maxPresignedPartsPerRequest: 100,
        expiresInSeconds: settings.uploadUrlTtlSeconds,
      },
    };
  }

  async uploadAvatar(owner: UserEntity, upload: BufferedUpload): Promise<Record<string, unknown>> {
    try {
      return await this.processAvatarUpload(owner, upload);
    } finally {
      if (upload.path) {
        try {
          await unlink(upload.path);
        } catch (error) {
          const reason = error instanceof Error ? error.name : 'UnknownError';
          this.logger.warn({
            event: 'avatar_temp_cleanup_failed',
            file: basename(upload.path),
            reason,
          });
        }
      }
    }
  }

  private async processAvatarUpload(
    owner: UserEntity,
    upload: BufferedUpload,
  ): Promise<Record<string, unknown>> {
    const settings = this.storage.settings;
    if (!settings.enabled) {
      throw new ServiceUnavailableException('Object storage is not configured.');
    }
    validatePurposeMediaPolicy(MediaKind.Image, MediaPurpose.Avatar, upload.size);
    const policy = validateMediaPolicy(MediaKind.Image, upload.mimetype, upload.size, settings);
    const originalName = this.sanitizeOriginalName(upload.originalname);
    if (!originalName) throw new BadRequestException('fileName must not be blank.');

    const id = randomUUID();
    const now = new Date();
    const normalizedBytes = await this.withVerificationSlot(async () => {
      const bytes = upload.buffer ?? (upload.path ? await readFile(upload.path) : null);
      if (!bytes) throw new BadRequestException('Avatar image is required.');
      return await this.normalizeAvatarBytes(bytes, policy.contentType);
    });
    if (normalizedBytes.length > MAX_AVATAR_BYTES) {
      throw new BadRequestException('The normalized avatar exceeds the 5 MiB limit.');
    }
    const objectKey = [
      settings.keyPrefix,
      MediaKind.Image,
      String(now.getUTCFullYear()),
      String(now.getUTCMonth() + 1).padStart(2, '0'),
      owner.id,
      `${id}.webp`,
    ].join('/');
    const file = this.files.create({
      id,
      ownerId: owner.id,
      kind: MediaKind.Image,
      purpose: MediaPurpose.Avatar,
      status: StoredFileStatus.Pending,
      uploadProtocol: UploadProtocol.Single,
      objectKey,
      originalName,
      contentType: 'image/webp',
      expectedSize: String(normalizedBytes.length),
      actualSize: null,
      durationMs: null,
      etag: null,
      multipartUploadId: null,
      multipartPartSize: null,
      uploadExpiresAt: new Date(now.getTime() + settings.uploadSessionTtlHours * 3600000),
      completedAt: null,
      deletedAt: null,
    });
    await this.reserveUpload(file);
    let objectStored = false;
    try {
      await this.storage.putObject(
        {
          key: objectKey,
          fileId: id,
          ownerId: owner.id,
          contentType: file.contentType,
          contentLength: normalizedBytes.length,
        },
        normalizedBytes,
      );
      objectStored = true;
      const claimed = await this.claimForCompletion(owner.id, id);
      Object.assign(file, claimed);
      await this.verifyAndMarkReady(claimed, normalizedBytes, true);
      Object.assign(file, claimed);
      return { file: this.serialize(file) };
    } catch (error) {
      if (objectStored && file.status === StoredFileStatus.Completing) {
        await this.releaseCompletionClaim(file);
      } else if (!objectStored) {
        await this.rejectUploadedFile(file).catch((cleanupError: unknown) => {
          this.logCleanupFailure('avatar-reject', file.id, cleanupError);
        });
      }
      throw error;
    }
  }

  async presignParts(
    owner: UserEntity,
    id: string,
    input: PresignMultipartPartsDto,
  ): Promise<Record<string, unknown>> {
    const file = await this.getOwned(id, owner.id);
    this.assertPending(file, UploadProtocol.Multipart);
    const partSize = file.multipartPartSize;
    const uploadId = file.multipartUploadId;
    if (!partSize || !uploadId) throw new ConflictException('Multipart upload is not initialized.');
    const expectedPartCount = Math.ceil(Number(file.expectedSize) / partSize);
    const unique = [...new Set(input.partNumbers)].sort((a, b) => a - b);
    if (
      unique.length !== input.partNumbers.length ||
      unique.some((part) => part > expectedPartCount)
    ) {
      throw new BadRequestException(
        'Part numbers must be unique and within the upload part count.',
      );
    }
    const parts = await Promise.all(
      unique.map(async (partNumber) => {
        const start = (partNumber - 1) * partSize;
        const contentLength = Math.min(partSize, Number(file.expectedSize) - start);
        return {
          partNumber,
          contentLength,
          url: await this.storage.createPartUploadUrl(
            file.objectKey,
            uploadId,
            partNumber,
            contentLength,
          ),
        };
      }),
    );
    return {
      parts,
      expiresInSeconds: this.storage.settings.uploadUrlTtlSeconds,
    };
  }

  async completeSingle(owner: UserEntity, id: string): Promise<Record<string, unknown>> {
    const existing = await this.getOwned(id, owner.id);
    if (existing.status === StoredFileStatus.Ready) return { file: this.serialize(existing) };
    this.assertPending(existing, UploadProtocol.Single);
    const file = await this.claimForCompletion(owner.id, id);
    if (file.status === StoredFileStatus.Ready) return { file: this.serialize(file) };
    try {
      await this.verifyAndMarkReady(file);
      return { file: this.serialize(file) };
    } catch (error) {
      await this.releaseCompletionClaim(file);
      throw error;
    }
  }

  async completeMultipart(
    owner: UserEntity,
    id: string,
    input: CompleteMultipartUploadDto,
  ): Promise<Record<string, unknown>> {
    const existing = await this.getOwned(id, owner.id);
    if (existing.status === StoredFileStatus.Ready) return { file: this.serialize(existing) };
    this.assertPending(existing, UploadProtocol.Multipart);
    const uploadId = existing.multipartUploadId;
    const partSize = existing.multipartPartSize;
    if (!uploadId || !partSize) throw new ConflictException('Multipart upload is not initialized.');
    const expectedCount = Math.ceil(Number(existing.expectedSize) / partSize);
    const sorted = [...input.parts].sort((a, b) => a.partNumber - b.partNumber);
    if (
      sorted.length !== expectedCount ||
      sorted.some((part, index) => part.partNumber !== index + 1)
    ) {
      throw new BadRequestException('Completed parts must contain every part exactly once.');
    }

    const file = await this.claimForCompletion(owner.id, id);
    if (file.status === StoredFileStatus.Ready) return { file: this.serialize(file) };

    try {
      await this.storage.completeMultipartUpload(
        file.objectKey,
        uploadId,
        sorted.map((part) => ({ PartNumber: part.partNumber, ETag: this.quoteEtag(part.etag) })),
      );
    } catch (completionError) {
      // R2 may complete the upload while its response is lost. HEAD makes retries idempotent.
      if (await this.reconcileAmbiguousCompletion(file)) {
        return { file: this.serialize(file) };
      }
      await this.releaseCompletionClaim(file);
      throw completionError;
    }
    try {
      await this.verifyAndMarkReady(file);
      return { file: this.serialize(file) };
    } catch (error) {
      await this.releaseCompletionClaim(file);
      throw error;
    }
  }

  async getFile(owner: UserEntity, id: string): Promise<Record<string, unknown>> {
    const file = await this.getOwned(id, owner.id);
    return { file: this.serialize(file) };
  }

  async createDownload(owner: UserEntity, id: string): Promise<Record<string, unknown>> {
    const file = await this.getOwned(id, owner.id);
    if (file.purpose === MediaPurpose.CommissionPaymentProof)
      return await this.createCommissionProofDownload(id);
    if (file.status !== StoredFileStatus.Ready) {
      throw new ConflictException('File is not ready for download.');
    }
    return {
      url: await this.storage.createDownloadUrl(
        file.objectKey,
        file.originalName,
        file.contentType,
      ),
      expiresInSeconds: this.storage.settings.downloadUrlTtlSeconds,
    };
  }

  async assertCommissionPaymentProof(
    manager: EntityManager,
    ownerId: string,
    id: string,
  ): Promise<void> {
    const rows = await manager.query<Array<{ id: string }>>(
      `SELECT id FROM stored_files WHERE id=$1 AND owner_id=$2
      AND purpose='commission_payment_proof' AND status='ready' AND deleted_at IS NULL FOR UPDATE`,
      [id, ownerId],
    );
    if (!rows.length)
      throw new BadRequestException({
        code: 'INVALID_PAYMENT_PROOF',
        message: 'اختار صورة تحويل مكتملة الرفع ومن حسابك.',
      });
  }

  /** Internal only: callers must authorize FinanceRead or ownership before signing. */
  async createCommissionProofDownload(id: string): Promise<Record<string, unknown>> {
    const [file] = await this.dataSource.query<Array<{ object_key: string; content_type: string }>>(
      `SELECT object_key,content_type FROM stored_files
      WHERE id=$1 AND purpose='commission_payment_proof' AND status='ready' AND deleted_at IS NULL`,
      [id],
    );
    if (!file)
      throw new NotFoundException({ code: 'PROOF_NOT_FOUND', message: 'صورة التحويل مش موجودة.' });
    return {
      url: await this.storage.createDownloadUrl(
        file.object_key,
        'transfer.webp',
        file.content_type,
        300,
      ),
      expiresInSeconds: 300,
    };
  }

  async createSparePartImageDownload(
    requestId: string,
    fileId: string,
  ): Promise<Record<string, unknown>> {
    const rows = await this.dataSource.query<
      Array<{ object_key: string; original_name: string; content_type: string }>
    >(
      `SELECT object_key,original_name,content_type FROM stored_files f WHERE f.id=$2 AND f.purpose='spare_part' AND f.status='ready' AND f.deleted_at IS NULL AND (EXISTS(SELECT 1 FROM spare_part_request_media m WHERE m.request_id=$1 AND m.file_id=f.id) OR EXISTS(SELECT 1 FROM spare_part_offer_media m JOIN spare_part_offers o ON o.id=m.offer_id WHERE o.request_id=$1 AND m.file_id=f.id))`,
      [requestId, fileId],
    );
    const file = rows[0];
    if (!file) throw new NotFoundException('Image not found.');
    return {
      url: await this.storage.createDownloadUrl(
        file.object_key,
        file.original_name,
        file.content_type,
        600,
      ),
      expiresInSeconds: 600,
    };
  }

  async createChatAttachmentDownload(
    user: UserEntity,
    orderId: string,
    fileId: string,
  ): Promise<Record<string, unknown>> {
    const rows = await this.dataSource.query<
      Array<{ object_key: string; original_name: string; content_type: string }>
    >(
      `SELECT f.object_key,f.original_name,f.content_type
       FROM service_order_chat_messages m
       JOIN stored_files f ON f.id=m.attachment_file_id
       JOIN service_orders o ON o.id=m.order_id
       WHERE m.order_id=$1 AND f.id=$2 AND f.status='ready'
         AND f.deleted_at IS NULL AND (o.customer_id=$3 OR o.technician_id=$3)
       LIMIT 1`,
      [orderId, fileId, user.id],
    );
    const file = rows[0];
    if (!file) throw new NotFoundException('Chat attachment not found.');
    return {
      url: await this.storage.createDownloadUrl(
        file.object_key,
        file.original_name,
        file.content_type,
        600,
      ),
      expiresInSeconds: 600,
    };
  }

  async createChatPeerAvatarDownload(orderId: string, viewerId: string): Promise<string | null> {
    const rows = await this.dataSource.query<
      Array<{ object_key: string; original_name: string; content_type: string }>
    >(
      `
      SELECT f.object_key,f.original_name,f.content_type FROM service_orders o
      JOIN users peer ON peer.id=CASE WHEN o.customer_id=$2 THEN o.technician_id ELSE o.customer_id END
      JOIN stored_files f ON f.id=peer.avatar_file_id AND f.kind='image' AND f.purpose='avatar'
      WHERE o.id=$1 AND (o.customer_id=$2 OR o.technician_id=$2) AND f.status='ready' AND f.deleted_at IS NULL LIMIT 1`,
      [orderId, viewerId],
    );
    const file = rows[0];
    return file
      ? await this.storage.createDownloadUrl(
          file.object_key,
          file.original_name,
          file.content_type,
          600,
        )
      : null;
  }
  async createBookingDownload(
    orderId: string,
    technicianId: string,
    fileId: string,
  ): Promise<Record<string, unknown>> {
    // Independent authorization protects this method even when called outside
    // dispatch detail. Only approved photos on a visible eligible order qualify.
    const rows = await this.dataSource.query<Array<{ owner_id: string }>>(
      `SELECT f.owner_id FROM service_order_attachments attachment
       JOIN service_orders o ON o.id = attachment.order_id
       JOIN stored_files f ON f.id = attachment.file_id AND f.owner_id = o.customer_id
       JOIN technician_profiles tp ON tp.user_id = $3
       JOIN users u ON u.id = tp.user_id
       LEFT JOIN user_addresses a ON a.id = o.selected_address_id
       LEFT JOIN technician_workshops tw ON tw.technician_id = tp.user_id
       WHERE o.id = $1 AND f.id = $2 AND attachment.role = 'photo'
         AND f.kind = 'image' AND f.purpose = 'booking' AND f.status = 'ready' AND f.deleted_at IS NULL
         AND o.status = 'searching' AND o.search_expires_at > now()
         ${getDispatchEligibilitySql()}`,
      [orderId, fileId, technicianId],
    );
    if (!rows[0]) throw new NotFoundException('Booking photo not found.');
    const file = await this.getOwned(fileId, rows[0].owner_id);
    return {
      url: await this.storage.createDownloadUrl(
        file.objectKey,
        file.originalName,
        file.contentType,
      ),
      expiresInSeconds: this.storage.settings.downloadUrlTtlSeconds,
    };
  }

  /**
   * Phase 2: signed download for order evidence (customer "before" photos
   * and technician "after" photos). Independent authorization mirroring
   * createBookingDownload: only files attached to the order as before-photos
   * or recorded as after-evidence qualify, and only the order's customer,
   * its assigned technician, or an admin may download them.
   */
  async createEvidenceDownload(
    orderId: string,
    fileId: string,
    viewer: UserEntity,
  ): Promise<{ url: string; expiresInSeconds: number }> {
    const isAdmin = viewer.role === UserRole.Admin;
    const rows = await this.dataSource.query<
      Array<{ object_key: string; original_name: string; content_type: string }>
    >(
      `SELECT f.object_key, f.original_name, f.content_type
       FROM stored_files f
       JOIN service_orders o ON o.id = $1
       WHERE f.id = $2 AND f.status = 'ready' AND f.deleted_at IS NULL
         AND ($4 OR o.customer_id = $3 OR o.technician_id = $3)
         AND (
           EXISTS (SELECT 1 FROM service_order_attachments a
                   WHERE a.order_id = $1 AND a.file_id = f.id AND a.role = 'photo')
           OR EXISTS (SELECT 1 FROM service_order_evidence e
                      WHERE e.order_id = $1 AND e.file_id = f.id)
         )
       LIMIT 1`,
      [orderId, fileId, viewer.id, isAdmin],
    );
    const file = rows[0];
    if (!file) throw new NotFoundException('Evidence not found.');
    return {
      url: await this.storage.createDownloadUrl(
        file.object_key,
        file.original_name,
        file.content_type,
      ),
      expiresInSeconds: this.storage.settings.downloadUrlTtlSeconds,
    };
  }

  /**
   * Batch-6 (L7): public (unauthenticated) single-photo download for the
   * gallery path. Signs the prepared public derivative (public-review/*)
   * with a fixed filename and a short TTL — never the private object key.
   *
   * Batch-7 (F-13): lock-free read path. The old version opened a
   * transaction and took FOR UPDATE on every anonymous GET (and did R2 I/O
   * under the lock when the derivative was missing). If the derivative is
   * not prepared yet, return 404 and let the sweeper backfill prepare it —
   * never do R2 I/O while holding a row lock on a public endpoint.
   */
  async createPublicReviewPhotoDownload(photoId: string): Promise<Record<string, unknown>> {
    const rows = await this.dataSource.query<Array<{ public_object_key: string | null }>>(
      `SELECT p.public_object_key
       FROM service_order_review_photos p
       JOIN service_order_reviews r ON r.id = p.review_id
       JOIN service_orders o ON o.id = r.order_id
       JOIN stored_files f ON f.id = p.file_id
       WHERE p.id = $1 AND p.moderation_status = 'approved' AND p.gallery_consent
         AND f.status = 'ready' AND f.deleted_at IS NULL AND f.purpose = 'review'
         AND r.published_at IS NOT NULL AND r.hidden_reason IS NULL
         AND o.status = 'completed'`,
      [photoId],
    );
    const key = rows[0]?.public_object_key;
    if (!key) throw new NotFoundException('Photo not found.');
    return {
      url: await this.storage.createDownloadUrl(key, 'review.webp', 'image/webp', 300),
      expiresInSeconds: 300,
    };
  }

  async createPublicReviewPhotoDownloads(
    photoIds: string[],
  ): Promise<Map<string, { url: string; expiresInSeconds: number }>> {
    const result = new Map<string, { url: string; expiresInSeconds: number }>();
    if (photoIds.length === 0) return result;
    const rows = await this.dataSource.query<
      Array<{ id: string; public_object_key: string | null }>
    >(
      `SELECT p.id, p.public_object_key
       FROM service_order_review_photos p
       JOIN service_order_reviews r ON r.id = p.review_id
       JOIN service_orders o ON o.id = r.order_id
       JOIN stored_files f ON f.id = p.file_id
       WHERE p.id = ANY($1::uuid[])
         AND p.moderation_status = 'approved' AND p.gallery_consent
         AND f.status = 'ready' AND f.deleted_at IS NULL AND f.purpose = 'review'
         AND r.published_at IS NOT NULL AND r.hidden_reason IS NULL AND o.status = 'completed'`,
      [photoIds],
    );
    for (const row of rows) {
      if (!row.public_object_key) continue;
      result.set(row.id, {
        url: await this.storage.createDownloadUrl(
          row.public_object_key,
          'review.webp',
          'image/webp',
          300,
        ),
        expiresInSeconds: 300,
      });
    }
    return result;
  }

  /**
   * Batch presigned technician avatar URLs for a gallery page. One SELECT,
   * no per-technician round trips.
   */
  async createPublicTechnicianAvatars(
    technicianIds: string[],
  ): Promise<Map<string, string | null>> {
    const result = new Map<string, string | null>();
    for (const id of technicianIds) result.set(id, null);
    if (technicianIds.length === 0) return result;
    const rows = await this.dataSource.query<
      Array<{ id: string; object_key: string; content_type: string }>
    >(
      `SELECT u.id, f.object_key, f.content_type
       FROM users u
       JOIN stored_files f ON f.id = u.avatar_file_id
       JOIN technician_profiles tp ON tp.user_id = u.id
       WHERE u.id = ANY($1::uuid[])
         AND u.deleted_at IS NULL
         AND tp.application_status = 'approved'
         AND f.status = 'ready' AND f.deleted_at IS NULL AND f.purpose = 'avatar'`,
      [technicianIds],
    );
    for (const row of rows) {
      result.set(
        row.id,
        await this.storage.createDownloadUrl(row.object_key, 'avatar.webp', row.content_type, 300),
      );
    }
    return result;
  }

  /**
   * Phase 6 backfill: prepare public derivatives for approved gallery photos
   * that predate migration 223 (public_object_key IS NULL). Runs from the
   * completion sweeper in small batches — never on the public read path, so
   * R2 I/O never happens under a row lock held by an unauthenticated
   * request.
   */
  async backfillPublicReviewDerivatives(limit = 50): Promise<{ processed: number }> {
    const rows = await this.dataSource.query<Array<{ id: string }>>(
      `SELECT p.id
       FROM service_order_review_photos p
       JOIN service_order_reviews r ON r.id = p.review_id
       JOIN service_orders o ON o.id = r.order_id
       JOIN stored_files f ON f.id = p.file_id
       WHERE p.public_object_key IS NULL
         AND p.moderation_status = 'approved' AND p.gallery_consent
         AND f.status = 'ready' AND f.deleted_at IS NULL AND f.purpose = 'review'
         AND r.published_at IS NOT NULL AND r.hidden_reason IS NULL AND o.status = 'completed'
       ORDER BY p.created_at
       LIMIT $1`,
      [Math.max(1, Math.min(limit, 200))],
    );
    let processed = 0;
    for (const row of rows) {
      try {
        await this.dataSource.transaction(
          async (manager) => await this.publicReviewKey(manager, row.id, true),
        );
        processed += 1;
      } catch (error) {
        this.logger.warn(
          `gallery derivative backfill skipped photo ${row.id}: ${
            error instanceof Error ? error.message : String(error)
          }`,
        );
      }
    }
    return { processed };
  }

  async preparePublicReviewImage(manager: EntityManager, photoId: string): Promise<void> {
    await this.publicReviewKey(manager, photoId, false);
  }

  private async publicReviewKey(
    manager: EntityManager,
    photoId: string,
    requirePublished: boolean,
  ): Promise<string | null> {
    // Neither the private object path nor its owner metadata may appear in public URLs.
    const rows = await manager.query<
      Array<{ object_key: string; public_object_key: string | null }>
    >(
      `SELECT f.object_key,p.public_object_key FROM service_order_review_photos p
       JOIN service_order_reviews r ON r.id=p.review_id JOIN service_orders o ON o.id=r.order_id
       JOIN stored_files f ON f.id=p.file_id
       WHERE p.id=$1 AND p.moderation_status='approved' AND p.gallery_consent
         AND f.status='ready' AND f.deleted_at IS NULL AND f.purpose='review'
         ${requirePublished ? "AND r.published_at IS NOT NULL AND r.hidden_reason IS NULL AND o.status='completed'" : ''}
       FOR UPDATE OF p`,
      [photoId],
    );
    const photo = rows[0];
    if (!photo) return null;
    if (photo.public_object_key) return photo.public_object_key;
    const publicKey = `${this.storage.settings.keyPrefix}/public-review/${photoId}.webp`;
    await this.withVerificationSlot(async () => {
      const bytes = await this.storage.getObjectBuffer(
        photo.object_key,
        MAX_COMPLETION_PHOTO_BYTES,
      );
      await this.storage.putPublicReviewImage(publicKey, bytes);
    });
    await manager.query(`UPDATE service_order_review_photos SET public_object_key=$2 WHERE id=$1`, [
      photoId,
      publicKey,
    ]);
    return publicKey;
  }

  async createPublicTechnicianAvatar(technicianId: string): Promise<string | null> {
    const rows = await this.dataSource.query<Array<{ object_key: string; content_type: string }>>(
      `SELECT f.object_key,f.content_type FROM users u JOIN stored_files f ON f.id=u.avatar_file_id
       JOIN technician_profiles tp ON tp.user_id=u.id WHERE u.id=$1 AND u.deleted_at IS NULL
       AND tp.application_status='approved' AND f.status='ready' AND f.deleted_at IS NULL AND f.purpose='avatar'`,
      [technicianId],
    );
    return rows[0]
      ? await this.storage.createDownloadUrl(
          rows[0].object_key,
          'avatar.webp',
          rows[0].content_type,
          300,
        )
      : null;
  }

  async createAdministrativeDownload(id: string): Promise<Record<string, unknown>> {
    const file = await this.files.findOne({ where: { id } });
    if (!file) throw new NotFoundException('File not found.');
    if (file.status !== StoredFileStatus.Ready) {
      throw new ConflictException('File is not ready for download.');
    }
    return {
      url: await this.storage.createDownloadUrl(
        file.objectKey,
        file.originalName,
        file.contentType,
      ),
      expiresInSeconds: this.storage.settings.downloadUrlTtlSeconds,
    };
  }

  /**
   * Batch-5 (M7): public portfolio photo download. Unlike
   * createAdministrativeDownload this verifies the technician is active
   * with an approved profile and the file is a ready portfolio item, then
   * signs with a fixed filename and a short TTL — the private object key
   * is never handed out with the owner's original name and the default
   * TTL on an unauthenticated endpoint.
   */
  async createPortfolioPhotoDownload(
    technicianId: string,
    fileId: string,
  ): Promise<{ url: string; expiresInSeconds: number }> {
    const rows = await this.dataSource.query<Array<{ objectKey: string; contentType: string }>>(
      `SELECT f.object_key AS "objectKey", f.content_type AS "contentType"
       FROM provider_portfolio_items p
       JOIN stored_files f ON f.id = p.file_id
       JOIN technician_profiles tp ON tp.user_id = p.technician_id
       JOIN users u ON u.id = p.technician_id
       WHERE p.technician_id = $1 AND p.file_id = $2
         AND tp.application_status = 'approved'
         AND u.status = 'active' AND u.deleted_at IS NULL
         AND f.status = 'ready' AND f.deleted_at IS NULL AND f.purpose = 'portfolio'`,
      [technicianId, fileId],
    );
    const file = rows[0];
    if (!file) throw new NotFoundException('Portfolio photo not found.');
    return {
      url: await this.storage.createDownloadUrl(
        file.objectKey,
        'portfolio.webp',
        file.contentType,
        300,
      ),
      expiresInSeconds: 300,
    };
  }

  /**
   * Batch-5 (M9): delete a review photo's public derivative from object
   * storage and clear its key (Egypt DPL 151/2020 — the webp must not
   * outlive the gallery consent). Used on consent withdrawal and when a
   * review is hidden. Best-effort on the storage side; the DB key is
   * always cleared so the photo can never resurface in the gallery.
   */
  async removePublicReviewDerivative(photoId: string): Promise<void> {
    const rows = await this.dataSource.query<Array<{ public_object_key: string | null }>>(
      `SELECT public_object_key FROM service_order_review_photos WHERE id = $1`,
      [photoId],
    );
    const key = rows[0]?.public_object_key;
    if (key) {
      try {
        await this.storage.deleteObject(key);
      } catch (error) {
        // Batch-7 (F-14): do NOT clear the key on failure — mark it so the
        // sweeper retries. Clearing it would orphan a file the user asked
        // to delete (DPL 151/2020) with no reference left to retry.
        this.logger.error(
          `removePublicReviewDerivative: storage delete failed for photo ${photoId}`,
          error as Error,
        );
        await this.dataSource.query(
          `UPDATE service_order_review_photos SET public_object_delete_failed_at = now() WHERE id = $1`,
          [photoId],
        );
        return;
      }
    }
    await this.dataSource.query(
      `UPDATE service_order_review_photos
       SET public_object_key = NULL, public_object_delete_failed_at = NULL WHERE id = $1`,
      [photoId],
    );
  }

  /**
   * Batch-7 (F-14): retry derivative deletions that failed earlier.
   * Called from the completion-confirmation sweeper.
   */
  async retryFailedPublicReviewDeletions(limit = 50): Promise<{ retried: number }> {
    const rows = await this.dataSource.query<Array<{ id: string; public_object_key: string }>>(
      `SELECT id, public_object_key FROM service_order_review_photos
       WHERE public_object_delete_failed_at IS NOT NULL AND public_object_key IS NOT NULL
       ORDER BY public_object_delete_failed_at ASC LIMIT $1`,
      [limit],
    );
    let retried = 0;
    for (const row of rows) {
      try {
        await this.storage.deleteObject(row.public_object_key);
        await this.dataSource.query(
          `UPDATE service_order_review_photos
           SET public_object_key = NULL, public_object_delete_failed_at = NULL WHERE id = $1`,
          [row.id],
        );
        retried += 1;
      } catch (error) {
        this.logger.error(
          `retryFailedPublicReviewDeletions: still failing for photo ${row.id}`,
          error as Error,
        );
      }
    }
    return { retried };
  }

  async remove(
    owner: UserEntity,
    id: string,
  ): Promise<{ deleted: boolean; deletionPending?: true }> {
    const existing = await this.getOwned(id, owner.id);
    if (existing.status === StoredFileStatus.Deleted) return { deleted: true };
    if (
      existing.status === StoredFileStatus.Deleting &&
      existing.deletionTargetStatus === StoredFileStatus.Deleted
    ) {
      return await this.finishRequestedDeletion(existing);
    }
    const file = await this.claimForDeletion(owner.id, id, true);
    if (file.status === StoredFileStatus.Deleted) return { deleted: true };
    if (file.multipartUploadId) {
      await this.storage
        .abortMultipartUpload(file.objectKey, file.multipartUploadId)
        .catch((error: unknown) => {
          this.logCleanupFailure('requested-abort', file.id, error);
        });
    }
    return await this.finishRequestedDeletion(file);
  }

  async retireAvatar(ownerId: string, id: string): Promise<void> {
    const file = await this.claimForDeletion(ownerId, id, false);
    if (file.status === StoredFileStatus.Deleted) return;
    await this.storage.deleteObject(file.objectKey);
    await this.finalizeDeletion(file, StoredFileStatus.Deleted);
  }

  async resumeAvatarRetirement(ownerId: string, id: string): Promise<void> {
    const file = await this.getOwned(id, ownerId);
    if (file.status === StoredFileStatus.Deleted) return;
    if (file.status !== StoredFileStatus.Deleting) {
      throw new ConflictException('Avatar is not scheduled for deletion.');
    }
    if (await this.hasReferences(id)) {
      throw new ConflictException('File became referenced again; cleanup was cancelled.');
    }
    await this.storage.deleteObject(file.objectKey);
    await this.finalizeDeletion(file, this.resolveDeletionTarget(file.deletionTargetStatus));
  }

  async cleanupExpiredUploads(limit = 100): Promise<{ cleaned: number }> {
    if (!this.storage.settings.enabled || !Number.isSafeInteger(limit) || limit <= 0) {
      return { cleaned: 0 };
    }
    let cleaned = await this.reconcileTransientFiles(limit);
    cleaned += await this.cleanupOrphanedCommissionProofs(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupExpiredSparePartFiles(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupTerminalBookingFiles(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupOrphanedAvatars(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupOrphanedBookingFiles(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupOrphanedOnboardingFiles(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupOrphanedSparePartFiles(Math.max(0, limit - cleaned));
    cleaned += await this.cleanupOrphanedCatalogFiles(Math.max(0, limit - cleaned));
    if (isCompletionV2Enabled())
      cleaned += await this.cleanupOrphanedCompletionFiles(Math.max(0, limit - cleaned));
    const remaining = Math.max(0, limit - cleaned);
    if (remaining === 0) return { cleaned };
    const expired = await this.files.find({
      where: { status: StoredFileStatus.Pending, uploadExpiresAt: LessThan(new Date()) },
      order: { uploadExpiresAt: 'ASC' },
      take: remaining,
    });
    for (const file of expired) {
      const claim = await this.files.update(
        { id: file.id, status: StoredFileStatus.Pending },
        {
          status: StoredFileStatus.Deleting,
          deletionTargetStatus: StoredFileStatus.Cancelled,
        },
      );
      if (claim.affected !== 1) continue;
      file.status = StoredFileStatus.Deleting;
      if (file.multipartUploadId) {
        await this.storage
          .abortMultipartUpload(file.objectKey, file.multipartUploadId)
          .catch((error: unknown) => {
            this.logCleanupFailure('expired-abort', file.id, error);
          });
      }
      try {
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Cancelled);
        cleaned += 1;
      } catch (error) {
        this.logCleanupFailure('expired-delete', file.id, error);
        // Keep the durable Deleting state so the next sweep retries safely.
      }
    }
    return { cleaned };
  }

  private async reconcileTransientFiles(limit: number): Promise<number> {
    const staleBefore = new Date(Date.now() - 15 * 60_000);
    const stale = await this.files.find({
      where: [
        { status: StoredFileStatus.Completing, updatedAt: LessThan(staleBefore) },
        {
          status: StoredFileStatus.Deleting,
          updatedAt: LessThan(staleBefore),
          retentionAttempts: 0,
        },
      ],
      order: { updatedAt: 'ASC' },
      take: limit,
    });
    let reconciled = 0;
    for (const file of stale) {
      if (file.status === StoredFileStatus.Completing) {
        try {
          await this.verifyAndMarkReady(file);
          reconciled += 1;
          continue;
        } catch (error) {
          const current = await this.files.findOne({ where: { id: file.id } });
          if (current?.status !== StoredFileStatus.Completing) {
            reconciled += 1;
            continue;
          }
          if (!this.isConfirmedObjectMissing(error)) {
            this.logger.warn(
              `Keeping completing file ${file.id} for retry after an inconclusive verification failure.`,
            );
            continue;
          }
          if (current.uploadExpiresAt.getTime() <= Date.now()) {
            const claim = await this.files.update(
              { id: current.id, status: StoredFileStatus.Completing },
              {
                status: StoredFileStatus.Deleting,
                deletionTargetStatus: StoredFileStatus.Cancelled,
              },
            );
            if (claim.affected !== 1) continue;
            current.status = StoredFileStatus.Deleting;
            current.deletionTargetStatus = StoredFileStatus.Cancelled;
            try {
              if (current.multipartUploadId) {
                await this.storage
                  .abortMultipartUpload(current.objectKey, current.multipartUploadId)
                  .catch((abortError: unknown) => {
                    this.logCleanupFailure('abort', current.id, abortError);
                  });
              }
              await this.storage.deleteObject(current.objectKey);
              await this.finalizeDeletion(current, StoredFileStatus.Cancelled);
              reconciled += 1;
            } catch (cleanupError) {
              this.logCleanupFailure('delete', current.id, cleanupError);
            }
            continue;
          }
        }
        // The object is definitely absent but the session can still be retried.
        const released = await this.files.update(
          { id: file.id, status: StoredFileStatus.Completing },
          { status: StoredFileStatus.Pending },
        );
        reconciled += released.affected === 1 ? 1 : 0;
        continue;
      }
      const claimed = await this.files.update(
        // PostgreSQL timestamps retain microseconds; JS Dates retain only
        // milliseconds. Equality could permanently strand deletion retries.
        { id: file.id, status: file.status, updatedAt: LessThan(staleBefore) },
        {
          status: StoredFileStatus.Deleting,
          deletionTargetStatus: file.deletionTargetStatus ?? StoredFileStatus.Deleted,
        },
      );
      if (claimed.affected !== 1) continue;
      file.status = StoredFileStatus.Deleting;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) {
          reconciled += 1;
          continue;
        }
        if (file.multipartUploadId) {
          await this.storage
            .abortMultipartUpload(file.objectKey, file.multipartUploadId)
            .catch((error: unknown) => {
              this.logCleanupFailure('abort', file.id, error);
            });
        }
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, this.resolveDeletionTarget(file.deletionTargetStatus));
        reconciled += 1;
      } catch (error) {
        this.logCleanupFailure('delete', file.id, error);
        // Keep deleting so a later sweep can safely retry the external operation.
      }
    }
    return reconciled;
  }

  private calculatePartSize(size: number): number {
    const required = Math.ceil(size / MAX_MULTIPART_PARTS);
    const target = Math.max(MIN_MULTIPART_PART_SIZE, TARGET_MULTIPART_PART_SIZE, required);
    return Math.ceil(target / MIB) * MIB;
  }

  private async verifyAndMarkReady(
    file: StoredFileEntity,
    knownBytes?: Buffer,
    imageAlreadyVerified = false,
  ): Promise<void> {
    await this.normalizeCompletionPhoto(file);
    const head = await this.storage.headObject(file.objectKey);
    const metadataMatches =
      head.metadata['file-id'] === file.id && head.metadata['owner-id'] === file.ownerId;
    const isChatTimedMedia =
      file.purpose === MediaPurpose.Chat &&
      (file.kind === MediaKind.Audio || file.kind === MediaKind.Video);
    const durationMatches =
      isChatTimedMedia ||
      file.durationMs === null ||
      head.metadata['duration-ms'] === String(file.durationMs);
    const matches =
      head.contentLength === Number(file.expectedSize) &&
      normalizeContentType(head.contentType) === file.contentType &&
      metadataMatches &&
      durationMatches;
    if (!matches) {
      await this.rejectUploadedFile(file);
      throw new BadRequestException('Uploaded object metadata does not match the upload request.');
    }
    if (file.kind === MediaKind.Image && !imageAlreadyVerified) {
      try {
        await this.withVerificationSlot(async () => {
          const bytes =
            knownBytes ??
            (await this.storage.getObjectBuffer(
              file.objectKey,
              file.purpose === MediaPurpose.Avatar
                ? MAX_AVATAR_BYTES
                : this.storage.settings.maxImageBytes,
            ));
          await this.validateImageBytes(
            bytes,
            file.contentType,
            file.purpose === MediaPurpose.Avatar,
          );
        });
      } catch (error) {
        await this.handleMediaVerificationFailure(file, error);
        throw error;
      }
    }
    if (file.kind === MediaKind.Audio) {
      try {
        file.durationMs = await this.withVerificationSlot(async () => {
          const bytes = await this.storage.getObjectBuffer(
            file.objectKey,
            this.storage.settings.maxAudioBytes,
          );
          const durationMs =
            file.purpose === MediaPurpose.Booking
              ? await this.audioMetadata.readBookingVoiceNoteDurationMs(bytes, file.contentType)
              : await this.audioMetadata.readAudioDurationMs(bytes, file.contentType);
          validateMediaDuration(file.kind, file.purpose, durationMs);
          return durationMs;
        });
      } catch (error) {
        await this.handleMediaVerificationFailure(file, error);
        throw error;
      }
    }
    if (file.kind === MediaKind.Video) {
      try {
        file.durationMs = await this.withVerificationSlot(async () => {
          if (file.purpose === MediaPurpose.Booking) {
            const bytes = await this.storage.getObjectBuffer(
              file.objectKey,
              MAX_BOOKING_VIDEO_BYTES,
            );
            return this.videoMetadata.readBookingVideoDurationMs(bytes, file.contentType);
          }
          const bytes = await this.storage.getObjectBuffer(
            file.objectKey,
            file.purpose === MediaPurpose.Chat
              ? MAX_CHAT_VIDEO_BYTES
              : this.storage.settings.maxVideoBytes,
          );
          if (file.purpose === MediaPurpose.Chat) {
            const durationMs = this.videoMetadata.readVideoDurationMs(bytes, file.contentType);
            validateMediaDuration(file.kind, file.purpose, durationMs);
            return durationMs;
          }
          this.videoMetadata.validateVideoContainer(bytes, file.contentType);
          return file.durationMs;
        });
      } catch (error) {
        await this.handleMediaVerificationFailure(file, error);
        throw error;
      }
    }
    const completedAt = new Date();
    const result = await this.files.update(
      { id: file.id, status: StoredFileStatus.Completing },
      {
        status: StoredFileStatus.Ready,
        actualSize: String(head.contentLength),
        durationMs: file.durationMs,
        etag: head.etag,
        multipartUploadId: null,
        completedAt,
      },
    );
    if (result.affected !== 1) {
      throw new ConflictException('File completion no longer owns this upload.');
    }
    file.status = StoredFileStatus.Ready;
    file.actualSize = String(head.contentLength);
    file.etag = head.etag;
    file.multipartUploadId = null;
    file.completedAt = completedAt;
  }

  private async reconcileAmbiguousCompletion(file: StoredFileEntity): Promise<boolean> {
    const delays = [0, 250, 750, 1_500];
    for (const delay of delays) {
      if (delay > 0) {
        await new Promise<void>((resolve) => setTimeout(resolve, delay));
      }
      try {
        await this.verifyAndMarkReady(file);
        return true;
      } catch (error) {
        // A real validation failure already moved the object to a terminal
        // cleanup state and must not be disguised as an ambiguous timeout.
        if (file.status !== StoredFileStatus.Completing) throw error;
      }
    }
    return false;
  }

  private async getOwned(id: string, ownerId: string): Promise<StoredFileEntity> {
    const file = await this.files.findOne({ where: { id, ownerId } });
    if (!file) throw new NotFoundException('File not found.');
    return file;
  }

  private async rejectUploadedFile(file: StoredFileEntity): Promise<void> {
    const claim = await this.files.update(
      { id: file.id, status: In([StoredFileStatus.Pending, StoredFileStatus.Completing]) },
      { status: StoredFileStatus.Deleting, deletionTargetStatus: StoredFileStatus.Failed },
    );
    if (claim.affected !== 1 && file.status !== StoredFileStatus.Deleting) return;
    file.status = StoredFileStatus.Deleting;
    await this.storage.deleteObject(file.objectKey);
    await this.finalizeDeletion(file, StoredFileStatus.Failed);
  }

  private async handleMediaVerificationFailure(
    file: StoredFileEntity,
    error: unknown,
  ): Promise<void> {
    // Validation/decoder failures are permanent. Storage/network/capacity
    // failures are retryable and must not delete a potentially valid object.
    if (error instanceof BadRequestException) {
      await this.rejectUploadedFile(file);
      return;
    }
    await this.releaseCompletionClaim(file);
  }

  private async cancelUnissuedUpload(file: StoredFileEntity): Promise<void> {
    const result = await this.files.update(
      { id: file.id, status: StoredFileStatus.Pending },
      {
        status: StoredFileStatus.Failed,
        deletedAt: new Date(),
        multipartUploadId: null,
        deletionTargetStatus: null,
      },
    );
    if (result.affected === 1) {
      file.status = StoredFileStatus.Failed;
      file.deletedAt = new Date();
    }
  }

  private async reserveUpload(file: StoredFileEntity): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      // Serialize quota decisions for this owner across all application replicas.
      await manager.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [file.ownerId]);
      const repository = manager.getRepository(StoredFileEntity);
      if (file.purpose === MediaPurpose.CommissionPaymentProof) {
        const [recent] = await manager.query<Array<{ count: string }>>(
          `SELECT count(*)::text count FROM stored_files WHERE owner_id=$1 AND purpose='commission_payment_proof' AND created_at>=now()-interval '1 hour'`,
          [file.ownerId],
        );
        if (Number(recent?.count ?? 0) >= 10)
          throw new HttpException(
            { code: 'PROOF_UPLOAD_LIMIT', message: 'وصلت لحد رفع الصور. جرّب تاني بعد ساعة.' },
            HttpStatus.TOO_MANY_REQUESTS,
          );
      }
      if (file.purpose === MediaPurpose.Chat) {
        const recent = await manager.query<Array<{ count: string }>>(
          "SELECT count(*)::text AS count FROM stored_files WHERE owner_id=$1 AND purpose='chat' AND created_at>=now()-interval '1 hour'",
          [file.ownerId],
        );
        if (Number(recent[0]?.count ?? 0) >= 20)
          throw new HttpException('Chat upload limit exceeded.', HttpStatus.TOO_MANY_REQUESTS);
      }
      const active = await repository.count({
        where: {
          ownerId: file.ownerId,
          status: In([StoredFileStatus.Pending, StoredFileStatus.Completing]),
        },
      });
      if (active >= (this.storage.settings.maxActiveUploadsPerOwner ?? 10)) {
        throw new ConflictException(
          'Too many active upload sessions. Complete or cancel one first.',
        );
      }
      const rows = await repository
        .createQueryBuilder('file')
        .select(
          `COALESCE(SUM(CASE
            WHEN "file"."status" = :ready THEN "file"."actual_size"
            WHEN "file"."status" IN (:...reservedStatuses)
              THEN COALESCE("file"."actual_size", "file"."expected_size")
            ELSE 0
          END), 0)`,
          'bytes',
        )
        .where('file.ownerId = :ownerId', { ownerId: file.ownerId })
        .andWhere('file.status IN (:...quotaStatuses)')
        .setParameters({
          ready: StoredFileStatus.Ready,
          reservedStatuses: [
            StoredFileStatus.Pending,
            StoredFileStatus.Completing,
            StoredFileStatus.Deleting,
          ],
          quotaStatuses: [
            StoredFileStatus.Pending,
            StoredFileStatus.Completing,
            StoredFileStatus.Ready,
            StoredFileStatus.Deleting,
          ],
        })
        .getRawMany<{ bytes: string }>();
      const reservedBytes = Number(rows[0]?.bytes ?? 0);
      if (
        reservedBytes + Number(file.expectedSize) >
        (this.storage.settings.maxBytesPerOwner ?? 20 * 1024 * MIB)
      ) {
        throw new ConflictException('Storage quota exceeded.');
      }
      await repository.save(file);
    });
  }

  private async claimForCompletion(ownerId: string, id: string): Promise<StoredFileEntity> {
    const result = await this.files.update(
      { id, ownerId, status: StoredFileStatus.Pending },
      { status: StoredFileStatus.Completing },
    );
    if (result.affected !== 1) {
      const current = await this.getOwned(id, ownerId);
      if (current.status === StoredFileStatus.Ready) return current;
      throw new ConflictException('File is already being completed or deleted.');
    }
    const claimed = await this.getOwned(id, ownerId);
    claimed.status = StoredFileStatus.Completing;
    return claimed;
  }

  private async releaseCompletionClaim(file: StoredFileEntity): Promise<void> {
    if (file.status !== StoredFileStatus.Completing) return;
    const result = await this.files.update(
      { id: file.id, status: StoredFileStatus.Completing },
      { status: StoredFileStatus.Pending },
    );
    if (result.affected === 1) file.status = StoredFileStatus.Pending;
  }

  private async claimForDeletion(
    ownerId: string,
    id: string,
    rejectCurrentAvatar: boolean,
  ): Promise<StoredFileEntity> {
    return await this.dataSource.transaction(async (manager) => {
      const repository = manager.getRepository(StoredFileEntity);
      const file = await repository.findOne({
        where: { id, ownerId },
        lock: { mode: 'pessimistic_write' },
      });
      if (!file) throw new NotFoundException('File not found.');
      if (file.status === StoredFileStatus.Deleted) return file;
      if (
        file.status === StoredFileStatus.Completing ||
        file.status === StoredFileStatus.Deleting
      ) {
        throw new ConflictException('File is already being completed or deleted.');
      }
      const [includeOrderAttachments, includePortfolioItems] = await Promise.all([
        this.hasServiceOrderAttachmentsTable(manager),
        this.hasProviderPortfolioItemsTable(manager),
      ]);
      const references: unknown[] = await manager.query(
        this.fileReferencesQuery(includeOrderAttachments, includePortfolioItems),
        [id],
      );
      if (references.length > 0) {
        if (rejectCurrentAvatar) {
          throw new ConflictException('Remove the file from the profile before deleting it.');
        }
        throw new ConflictException('File became referenced again; cleanup was cancelled.');
      }
      file.status = StoredFileStatus.Deleting;
      file.deletionTargetStatus = StoredFileStatus.Deleted;
      return await repository.save(file);
    });
  }

  private async finalizeDeletion(
    file: StoredFileEntity,
    finalStatus: StoredFileStatus.Deleted | StoredFileStatus.Cancelled | StoredFileStatus.Failed,
  ): Promise<void> {
    const deletedAt = new Date();
    const result = await this.files.update(
      { id: file.id, status: StoredFileStatus.Deleting },
      {
        status: finalStatus,
        deletedAt,
        multipartUploadId: null,
        deletionTargetStatus: null,
      },
    );
    if (result.affected !== 1) {
      // Another cleanup worker may have deleted the same storage object and
      // finalized the row first. Treat the identical terminal state as an
      // idempotent success; only a genuinely different state is a conflict.
      const current = await this.files.findOne({ where: { id: file.id } });
      if (current?.status === finalStatus) {
        file.status = finalStatus;
        file.deletedAt = current.deletedAt ?? deletedAt;
        file.multipartUploadId = null;
        file.deletionTargetStatus = null;
        return;
      }
      throw new ConflictException('File deletion no longer owns this object.');
    }
    file.status = finalStatus;
    file.deletedAt = deletedAt;
    file.multipartUploadId = null;
    file.deletionTargetStatus = null;
  }

  private async normalizeAvatarBytes(bytes: Buffer, contentType: string): Promise<Buffer> {
    await this.validateImageBytes(bytes, contentType, true, false);
    try {
      return await sharp(bytes, {
        failOn: 'warning',
        limitInputPixels: MAX_AVATAR_PIXELS,
        animated: false,
      })
        .rotate()
        .webp({ quality: 85 })
        .toBuffer();
    } catch {
      throw new BadRequestException('Uploaded image must be valid and safely decodable.');
    }
  }

  private async normalizeCompletionPhoto(file: StoredFileEntity): Promise<void> {
    if (
      file.purpose !== MediaPurpose.JobEvidence &&
      file.purpose !== MediaPurpose.Review &&
      file.purpose !== MediaPurpose.CommissionPaymentProof
    )
      return;

    const head = await this.storage.headObject(file.objectKey);
    if (head.contentLength > MAX_COMPLETION_PHOTO_BYTES) {
      throw new PayloadTooLargeException(
        'Completion evidence and review images must not exceed 10 MiB.',
      );
    }
    if (
      head.contentLength !== Number(file.expectedSize) ||
      normalizeContentType(head.contentType) !== file.contentType ||
      head.metadata['file-id'] !== file.id ||
      head.metadata['owner-id'] !== file.ownerId
    ) {
      throw new BadRequestException('Uploaded object metadata does not match the upload request.');
    }
    const source = await this.storage.getObjectBuffer(file.objectKey, MAX_COMPLETION_PHOTO_BYTES);
    const sourceContentType = normalizeContentType(head.contentType);
    validatePurposeMediaPolicy(
      MediaKind.Image,
      file.purpose,
      head.contentLength,
      sourceContentType,
    );
    await this.validateImageBytes(source, sourceContentType, false, false);

    let normalized: Buffer;
    try {
      normalized = await sharp(source, {
        failOn: 'warning',
        limitInputPixels: MAX_AVATAR_PIXELS,
        animated: false,
      })
        .rotate()
        .webp({ quality: 85 })
        .toBuffer();
    } catch {
      throw new BadRequestException('Uploaded image must be valid and safely decodable.');
    }
    if (normalized.length > MAX_COMPLETION_PHOTO_BYTES) {
      throw new PayloadTooLargeException('The normalized image must not exceed 10 MiB.');
    }
    if (file.purpose === MediaPurpose.CommissionPaymentProof && normalized.length > 8 * MIB) {
      throw new PayloadTooLargeException('صورة التحويل لازم تكون أقل من ٨ ميجابايت.');
    }

    await this.storage.putObject(
      {
        key: file.objectKey,
        fileId: file.id,
        ownerId: file.ownerId,
        contentType: 'image/webp',
        contentLength: normalized.length,
      },
      normalized,
    );
    const updated = await this.files.update(
      { id: file.id, status: StoredFileStatus.Completing },
      { contentType: 'image/webp', expectedSize: String(normalized.length) },
    );
    if (updated.affected !== 1) {
      throw new ConflictException('File normalization no longer owns this upload.');
    }
    file.contentType = 'image/webp';
    file.expectedSize = String(normalized.length);
  }

  private async validateImageBytes(
    bytes: Buffer,
    contentType: string,
    avatar: boolean,
    fullDecode = true,
  ): Promise<void> {
    let metadata: Metadata;
    try {
      metadata = await sharp(bytes, {
        failOn: 'warning',
        limitInputPixels: MAX_AVATAR_PIXELS,
      }).metadata();
    } catch {
      throw new BadRequestException('Uploaded image must be valid and safely decodable.');
    }
    const expectedFormats: Readonly<Record<string, ReadonlySet<string>>> = {
      'image/jpeg': new Set(['jpeg']),
      'image/png': new Set(['png']),
      'image/webp': new Set(['webp']),
      'image/avif': new Set(['heif']),
      'image/heic': new Set(['heif']),
      'image/heif': new Set(['heif']),
    };
    if (!expectedFormats[contentType]?.has(metadata.format)) {
      throw new BadRequestException('Uploaded image content does not match its content type.');
    }
    const width = metadata.width;
    const height = metadata.height;
    if (
      !Number.isSafeInteger(width) ||
      !Number.isSafeInteger(height) ||
      (metadata.pages ?? 1) !== 1 ||
      width <= 0 ||
      height <= 0 ||
      width * height > MAX_AVATAR_PIXELS ||
      (avatar && (width > MAX_AVATAR_DIMENSION || height > MAX_AVATAR_DIMENSION))
    ) {
      throw new BadRequestException('Uploaded image dimensions are not allowed.');
    }
    if (!fullDecode) return;
    try {
      await sharp(bytes, {
        failOn: 'warning',
        limitInputPixels: MAX_AVATAR_PIXELS,
        animated: false,
      })
        .raw()
        .toBuffer();
    } catch {
      throw new BadRequestException('Uploaded image is truncated or cannot be decoded safely.');
    }
  }

  private async withVerificationSlot<T>(operation: () => Promise<T>): Promise<T> {
    if (this.verificationActive < (this.storage.settings.verificationConcurrency ?? 4)) {
      this.verificationActive += 1;
    } else {
      if (this.verificationWaiters.length >= MAX_VERIFICATION_WAITERS) {
        throw new ServiceUnavailableException('Media verification is temporarily at capacity.');
      }
      await new Promise<void>((resolve, reject) => {
        const waiter = (): void => {
          clearTimeout(timer);
          resolve();
        };
        const timer = setTimeout(() => {
          const index = this.verificationWaiters.indexOf(waiter);
          if (index >= 0) this.verificationWaiters.splice(index, 1);
          reject(new ServiceUnavailableException('Timed out waiting for media verification.'));
        }, VERIFICATION_QUEUE_TIMEOUT_MS);
        timer.unref();
        this.verificationWaiters.push(waiter);
      });
    }
    try {
      return await operation();
    } finally {
      const next = this.verificationWaiters.shift();
      if (next) {
        next();
      } else {
        this.verificationActive -= 1;
      }
    }
  }

  private async hasReferences(id: string): Promise<boolean> {
    const rows: unknown[] = await this.dataSource.query(
      `SELECT 1 FROM users WHERE avatar_file_id = $1 LIMIT 1`,
      [id],
    );
    return rows.length > 0;
  }

  private resolveDeletionTarget(
    status: StoredFileStatus | null,
  ): StoredFileStatus.Deleted | StoredFileStatus.Cancelled | StoredFileStatus.Failed {
    return status === StoredFileStatus.Cancelled || status === StoredFileStatus.Failed
      ? status
      : StoredFileStatus.Deleted;
  }

  private async cleanupOrphanedAvatars(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const cutoff = new Date(Date.now() - ORPHAN_AVATAR_GRACE_MS);
    const claimed: Array<{ id: string }> = await this.dataSource.transaction(async (manager) => {
      return queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (
           SELECT sf.id
             FROM stored_files sf
            WHERE sf.status = 'ready'
              AND sf.purpose = 'avatar'
              AND sf.completed_at < $1
              AND NOT EXISTS (SELECT 1 FROM users u WHERE u.avatar_file_id = sf.id)
            ORDER BY sf.completed_at
            LIMIT $2
            FOR UPDATE SKIP LOCKED
         )
         UPDATE stored_files sf
            SET status = 'deleting',
                deletion_target_status = 'deleted',
                updated_at = now()
           FROM candidates
          WHERE sf.id = candidates.id
         RETURNING sf.id`,
          [cutoff, limit],
        ),
      );
    });
    let cleaned = 0;
    for (const row of claimed) {
      if (typeof row.id !== 'string') continue;
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned += 1;
      } catch (error) {
        this.logCleanupFailure('orphan-avatar-delete', file.id, error);
        // The durable Deleting state is retried by reconciliation.
      }
    }
    return cleaned;
  }

  private async cleanupTerminalBookingFiles(limit: number): Promise<number> {
    if (limit <= 0 || !(await this.hasServiceOrderAttachmentsTable(this.dataSource))) return 0;
    const cutoff = new Date(
      Date.now() - (this.storage.settings.completedBookingRetentionDays ?? 7) * 24 * 60 * 60_000,
    );
    const claimed = await this.dataSource.transaction(async (manager) => {
      // Lock both orders and files: retry/assignment and new attachment writes
      // must finish before the terminal status and references can be inspected.
      const candidates = await manager.query<Array<{ id: string; order_id: string }>>(
        `SELECT sf.id, o.id AS order_id
         FROM service_orders o
         JOIN service_order_attachments a ON a.order_id = o.id
         JOIN stored_files sf ON sf.id = a.file_id
         WHERE sf.purpose = 'booking' AND sf.status = 'ready'
           AND (o.status IN ('no_provider_found', 'cancelled')
                OR (o.status = 'completed' AND o.completed_at < $1))
         ORDER BY o.id, sf.id
         LIMIT $2 FOR UPDATE OF o, sf SKIP LOCKED`,
        [cutoff, limit],
      );
      if (candidates.length === 0) return [];
      await manager.query(
        `DELETE FROM service_order_attachments a
         USING jsonb_to_recordset($1::jsonb) AS x(id uuid, order_id uuid)
         WHERE a.file_id = x.id AND a.order_id = x.order_id`,
        [JSON.stringify(candidates)],
      );
      const includePortfolio = await this.hasProviderPortfolioItemsTable(manager);
      const ids: string[] = [];
      for (const id of new Set(candidates.map((row) => row.id))) {
        const references: unknown[] = await manager.query(
          this.fileReferencesQuery(true, includePortfolio),
          [id],
        );
        if (references.length > 0) continue;
        const claim = await manager
          .getRepository(StoredFileEntity)
          .update(
            { id, status: StoredFileStatus.Ready },
            { status: StoredFileStatus.Deleting, deletionTargetStatus: StoredFileStatus.Deleted },
          );
        if (claim.affected === 1) ids.push(id);
      }
      return ids;
    });
    let cleaned = 0;
    for (const id of claimed) {
      const file = await this.files.findOne({ where: { id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned += 1;
      } catch (error) {
        // Committed deleting state survives storage outages and process restarts.
        this.logCleanupFailure('terminal-booking-delete', id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedBookingFiles(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    if (!(await this.hasServiceOrderAttachmentsTable(this.dataSource))) {
      // During a rolling deployment, application instances may briefly run
      // before migration 0042. Skipping is safer than deleting booking media
      // whose authoritative attachment table is not available yet.
      return 0;
    }
    const graceHours = this.storage.settings.orphanBookingGraceHours ?? 6;
    const cutoff = new Date(Date.now() - graceHours * 60 * 60_000);
    const claimed: Array<{ id: string }> = await this.dataSource.transaction(async (manager) => {
      return queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (
           SELECT sf.id
             FROM stored_files sf
            WHERE sf.status = 'ready'
              AND sf.purpose = 'booking'
              AND sf.completed_at < $1
              AND NOT EXISTS (
                SELECT 1 FROM service_order_attachments soa WHERE soa.file_id = sf.id
              )
            ORDER BY sf.completed_at
            LIMIT $2
            FOR UPDATE SKIP LOCKED
         )
         UPDATE stored_files sf
            SET status = 'deleting',
                deletion_target_status = 'deleted',
                updated_at = now()
           FROM candidates
          WHERE sf.id = candidates.id
         RETURNING sf.id`,
          [cutoff, limit],
        ),
      );
    });
    let cleaned = 0;
    for (const row of claimed) {
      if (typeof row.id !== 'string') continue;
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned += 1;
      } catch (error) {
        this.logCleanupFailure('orphan-booking-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedOnboardingFiles(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const includePortfolioItems = await this.hasProviderPortfolioItemsTable(this.dataSource);
    const cutoff = new Date(Date.now() - ORPHAN_ONBOARDING_GRACE_MS);
    const claimed: Array<{ id: string }> = await this.dataSource.transaction(async (manager) => {
      return queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (
           SELECT sf.id
             FROM stored_files sf
            WHERE sf.status = 'ready'
              AND sf.completed_at < $1
              AND (
                (sf.purpose = 'verification' AND NOT EXISTS (
                  SELECT 1 FROM technician_documents td WHERE td.file_id = sf.id
                ))
                ${
                  includePortfolioItems
                    ? `OR (sf.purpose = 'portfolio' AND NOT EXISTS (
                         SELECT 1 FROM provider_portfolio_items ppi WHERE ppi.file_id = sf.id
                       ) AND NOT EXISTS (
                         SELECT 1 FROM technician_workshops tw WHERE tw.photo_file_id = sf.id
                       ))`
                    : ''
                }
              )
            ORDER BY sf.completed_at
            LIMIT $2
            FOR UPDATE SKIP LOCKED
         )
         UPDATE stored_files sf
            SET status = 'deleting',
                deletion_target_status = 'deleted',
                updated_at = now()
           FROM candidates
          WHERE sf.id = candidates.id
         RETURNING sf.id`,
          [cutoff, limit],
        ),
      );
    });
    let cleaned = 0;
    for (const row of claimed) {
      if (typeof row.id !== 'string') continue;
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        // Re-check every reference after claiming. A draft save racing with the
        // sweep restores the row to ready and prevents object deletion.
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned += 1;
      } catch (error) {
        this.logCleanupFailure('orphan-onboarding-delete', file.id, error);
      }
    }
    return cleaned;
  }

  async cleanupExpiredSparePartFiles(limit = 100): Promise<number> {
    if (limit <= 0) return 0;
    const claimed = await this.dataSource.transaction(async (manager) => {
      // Lock the file before detaching it. A durable deleting claim survives R2 failures.
      const rows = await manager.query<Array<{ id: string }>>(
        `SELECT sf.id FROM stored_files sf WHERE sf.purpose IN ('spare_part','complaint') AND sf.status='ready'
         AND (EXISTS(SELECT 1 FROM spare_part_request_media m JOIN spare_part_requests r ON r.id=m.request_id
                     WHERE m.file_id=sf.id AND r.offers_deadline<=now())
           OR EXISTS(SELECT 1 FROM spare_part_offer_media m JOIN spare_part_offers o ON o.id=m.offer_id
                     JOIN spare_part_requests r ON r.id=o.request_id WHERE m.file_id=sf.id AND r.offers_deadline<=now())
           OR EXISTS(SELECT 1 FROM service_complaints c JOIN spare_part_deals d ON d.id=c.spare_part_deal_id
                     JOIN spare_part_requests r ON r.id=d.request_id
                     WHERE sf.id=ANY(c.evidence_file_ids || c.response_file_ids) AND r.offers_deadline<=now()))
         ORDER BY sf.id LIMIT $1 FOR UPDATE OF sf SKIP LOCKED`,
        [limit],
      );
      const ids = rows.map((r) => r.id);
      if (!ids.length) return [];
      await manager.query(
        `DELETE FROM spare_part_request_media m USING spare_part_requests r
         WHERE m.request_id=r.id AND r.offers_deadline<=now() AND m.file_id=ANY($1::uuid[])`,
        [ids],
      );
      await manager.query(
        `DELETE FROM spare_part_offer_media m USING spare_part_offers o,spare_part_requests r
         WHERE m.offer_id=o.id AND o.request_id=r.id AND r.offers_deadline<=now() AND m.file_id=ANY($1::uuid[])`,
        [ids],
      );
      await manager.query(
        `UPDATE service_complaints c SET
           evidence_file_ids=ARRAY(SELECT id FROM unnest(c.evidence_file_ids) AS id WHERE NOT id=ANY($1::uuid[])),
           response_file_ids=ARRAY(SELECT id FROM unnest(c.response_file_ids) AS id WHERE NOT id=ANY($1::uuid[]))
         FROM spare_part_deals d,spare_part_requests r
         WHERE c.spare_part_deal_id=d.id AND d.request_id=r.id AND r.offers_deadline<=now()
           AND (c.evidence_file_ids || c.response_file_ids) && $1::uuid[]`,
        [ids],
      );
      return queryRows<{ id: string }>(
        await manager.query(
          `UPDATE stored_files sf SET status='deleting',deletion_target_status='deleted',updated_at=now()
         WHERE sf.id=ANY($1::uuid[]) AND sf.status='ready'
         AND NOT EXISTS(SELECT 1 FROM spare_part_request_media m WHERE m.file_id=sf.id)
         AND NOT EXISTS(SELECT 1 FROM spare_part_offer_media m WHERE m.file_id=sf.id)
         RETURNING sf.id`,
          [ids],
        ),
      );
    });
    let cleaned = 0;
    for (const row of claimed) {
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned++;
      } catch (error) {
        this.logCleanupFailure('expired-spare-part-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedSparePartFiles(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const claimed = await this.dataSource.transaction(async (manager) =>
      queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (SELECT sf.id FROM stored_files sf WHERE sf.status='ready' AND sf.purpose='spare_part' AND sf.completed_at<now()-interval '48 hours'
      AND NOT EXISTS(SELECT 1 FROM spare_part_request_media m WHERE m.file_id=sf.id)
      AND NOT EXISTS(SELECT 1 FROM spare_part_offer_media m WHERE m.file_id=sf.id)
      ORDER BY sf.completed_at LIMIT $1 FOR UPDATE SKIP LOCKED)
      UPDATE stored_files sf SET status='deleting',deletion_target_status='deleted',updated_at=now() FROM candidates WHERE sf.id=candidates.id RETURNING sf.id`,
          [limit],
        ),
      ),
    );
    let cleaned = 0;
    for (const row of claimed) {
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned++;
      } catch (error) {
        this.logCleanupFailure('orphan-spare-part-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedCompletionFiles(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const attachments = await this.hasServiceOrderAttachmentsTable(this.dataSource);
    const portfolio = await this.hasProviderPortfolioItemsTable(this.dataSource);
    const references = this.fileReferencesQuery(attachments, portfolio).replace('$1', 'sf.id');
    const claimed = await this.dataSource.transaction(async (manager) =>
      queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (
        SELECT sf.id FROM stored_files sf WHERE sf.status='ready'
          AND sf.purpose IN ('job_evidence','review') AND sf.created_at < now()-interval '24 hours'
          AND NOT EXISTS (${references}) ORDER BY sf.created_at,sf.id LIMIT $1 FOR UPDATE SKIP LOCKED
      ) UPDATE stored_files sf SET status='deleting',deletion_target_status='deleted',updated_at=now()
        FROM candidates WHERE sf.id=candidates.id RETURNING sf.id`,
          [limit],
        ),
      ),
    );
    let cleaned = 0;
    for (const row of claimed) {
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned++;
      } catch (error) {
        this.logCleanupFailure('orphan-completion-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedCommissionProofs(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const claimed = await this.dataSource.transaction(async (m) =>
      queryRows<{ id: string }>(
        await m.query(
          `WITH candidates AS (
      SELECT sf.id FROM stored_files sf WHERE sf.purpose='commission_payment_proof' AND sf.status='ready'
        AND sf.completed_at<now()-interval '24 hours'
        AND NOT EXISTS(SELECT 1 FROM commission_payment_submissions p WHERE p.proof_file_id=sf.id)
        ORDER BY sf.id LIMIT $1 FOR UPDATE SKIP LOCKED)
      UPDATE stored_files sf SET status='deleting',deletion_target_status='deleted',updated_at=now()
        FROM candidates c WHERE sf.id=c.id RETURNING sf.id`,
          [limit],
        ),
      ),
    );
    let cleaned = 0;
    for (const row of claimed) {
      const file = await this.files.findOneBy({ id: row.id });
      if (!file) continue;
      try {
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned++;
      } catch (error) {
        this.logCleanupFailure('orphan-commission-proof-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async cleanupOrphanedCatalogFiles(limit: number): Promise<number> {
    if (limit <= 0) return 0;
    const includeAttachments = await this.hasServiceOrderAttachmentsTable(this.dataSource);
    const includePortfolio = await this.hasProviderPortfolioItemsTable(this.dataSource);
    const references = this.fileReferencesQuery(includeAttachments, includePortfolio).replace(
      '$1',
      'sf.id',
    );
    const claimed = await this.dataSource.transaction(async (manager) =>
      queryRows<{ id: string }>(
        await manager.query(
          `WITH candidates AS (
           SELECT sf.id FROM stored_files sf
           WHERE sf.status = 'ready'
             AND sf.catalog_orphaned_at < now() - interval '24 hours'
             AND NOT EXISTS (${references})
           ORDER BY sf.catalog_orphaned_at, sf.id LIMIT $1 FOR UPDATE SKIP LOCKED
         )
         UPDATE stored_files sf SET status = 'deleting', deletion_target_status = 'deleted', updated_at = now()
         FROM candidates WHERE sf.id = candidates.id RETURNING sf.id`,
          [limit],
        ),
      ),
    );
    let cleaned = 0;
    for (const row of claimed) {
      if (typeof row.id !== 'string') continue;
      const file = await this.files.findOne({ where: { id: row.id } });
      if (!file) continue;
      try {
        if (await this.releaseDeletionClaimIfReferenced(file.id)) continue;
        await this.storage.deleteObject(file.objectKey);
        await this.finalizeDeletion(file, StoredFileStatus.Deleted);
        cleaned += 1;
      } catch (error) {
        this.logCleanupFailure('orphan-catalog-delete', file.id, error);
      }
    }
    return cleaned;
  }

  private async finishRequestedDeletion(
    file: StoredFileEntity,
  ): Promise<{ deleted: boolean; deletionPending?: true }> {
    try {
      await this.storage.deleteObject(file.objectKey);
      await this.finalizeDeletion(file, StoredFileStatus.Deleted);
      return { deleted: true };
    } catch (error) {
      this.logCleanupFailure('requested-delete', file.id, error);
      return { deleted: false, deletionPending: true };
    }
  }

  private async releaseDeletionClaimIfReferenced(fileId: string): Promise<boolean> {
    return await this.dataSource.transaction(async (manager) => {
      const [includeOrderAttachments, includePortfolioItems] = await Promise.all([
        this.hasServiceOrderAttachmentsTable(manager),
        this.hasProviderPortfolioItemsTable(manager),
      ]);
      const references: unknown[] = await manager.query(
        this.fileReferencesQuery(includeOrderAttachments, includePortfolioItems),
        [fileId],
      );
      if (references.length === 0) return false;
      const result = await manager.getRepository(StoredFileEntity).update(
        {
          id: fileId,
          status: StoredFileStatus.Deleting,
          deletionTargetStatus: StoredFileStatus.Deleted,
        },
        { status: StoredFileStatus.Ready, deletionTargetStatus: null },
      );
      return result.affected === 1;
    });
  }

  private async hasServiceOrderAttachmentsTable(
    manager: Pick<DataSource, 'query'>,
  ): Promise<boolean> {
    const rows = await manager.query<Array<{ exists: boolean }>>(
      `SELECT to_regclass('service_order_attachments') IS NOT NULL AS exists`,
    );
    return rows[0]?.exists === true;
  }

  private async hasProviderPortfolioItemsTable(
    manager: Pick<DataSource, 'query'>,
  ): Promise<boolean> {
    const rows = await manager.query<Array<{ exists: boolean }>>(
      `SELECT to_regclass('provider_portfolio_items') IS NOT NULL AS exists`,
    );
    return rows[0]?.exists === true;
  }

  private fileReferencesQuery(
    includeOrderAttachments: boolean,
    includePortfolioItems = true,
  ): string {
    return `SELECT 1
       FROM (
         SELECT avatar_file_id AS file_id FROM users
         UNION ALL SELECT file_id FROM technician_documents
         ${includePortfolioItems ? 'UNION ALL SELECT file_id FROM provider_portfolio_items' : ''}
         UNION ALL SELECT photo_file_id FROM technician_workshops
         UNION ALL SELECT image_file_id FROM service_categories
         UNION ALL SELECT image_file_id FROM service_subcategories
         UNION ALL SELECT image_file_id FROM services
         UNION ALL SELECT icon_file_id FROM services
         UNION ALL SELECT file_id FROM service_order_evidence
         UNION ALL SELECT file_id FROM service_order_review_photos
           UNION ALL SELECT proof_file_id FROM commission_payment_submissions
         UNION ALL SELECT file_id FROM spare_part_request_media
         UNION ALL SELECT file_id FROM spare_part_offer_media
         UNION ALL SELECT unnest(evidence_file_ids) FROM risk_appeals
         UNION ALL SELECT unnest(evidence_file_ids || response_file_ids) FROM service_complaints
         UNION ALL SELECT m.attachment_file_id FROM service_order_chat_messages m
           JOIN service_orders o ON o.id=m.order_id
           WHERE o.status::text NOT IN ('completed','cancelled')
             OR (CASE WHEN o.status::text='cancelled' THEN o.cancelled_at ELSE o.completed_at END)>=now()-interval '90 days'
             OR EXISTS(SELECT 1 FROM service_complaints c WHERE c.order_id=o.id AND c.status NOT IN ('resolved','dismissed','closed'))
             OR EXISTS(SELECT 1 FROM risk_incidents i WHERE i.order_id=o.id
               AND (i.status IN ('active','review') OR EXISTS(
                 SELECT 1 FROM risk_appeals a WHERE a.incident_id=i.id AND a.status='pending')))
         ${includeOrderAttachments ? 'UNION ALL SELECT file_id FROM service_order_attachments' : ''}
       ) AS ref_files
      WHERE file_id = $1
      LIMIT 1`;
  }

  private isConfirmedObjectMissing(error: unknown): boolean {
    if (!error || typeof error !== 'object') return false;
    const candidate = error as {
      name?: unknown;
      Code?: unknown;
      $metadata?: { httpStatusCode?: unknown };
    };
    return (
      candidate.$metadata?.httpStatusCode === 404 ||
      candidate.name === 'NotFound' ||
      candidate.name === 'NoSuchKey' ||
      candidate.Code === 'NoSuchKey'
    );
  }

  private logCleanupFailure(operation: string, fileId: string, error: unknown): void {
    const reason = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
    this.logger.warn(`File cleanup ${operation} failed for ${fileId}: ${reason}`);
  }

  private assertPending(file: StoredFileEntity, protocol: UploadProtocol): void {
    if (file.status !== StoredFileStatus.Pending || file.uploadProtocol !== protocol) {
      throw new ConflictException(`File is not a pending ${protocol} upload.`);
    }
    if (file.uploadExpiresAt.getTime() <= Date.now()) {
      throw new ConflictException('Upload session has expired.');
    }
  }

  private quoteEtag(etag: string): string {
    const unquoted = etag.replace(/^"|"$/g, '');
    return `"${unquoted}"`;
  }

  private sanitizeOriginalName(fileName: string): string {
    return Array.from(fileName)
      .map((character) => {
        const code = character.charCodeAt(0);
        return code < 32 || code === 127 || character === '/' || character === '\\'
          ? '_'
          : character;
      })
      .join('')
      .trim();
  }

  private serialize(file: StoredFileEntity): Record<string, unknown> {
    return {
      id: file.id,
      kind: file.kind,
      purpose: file.purpose,
      status: file.status,
      uploadProtocol: file.uploadProtocol,
      originalName: file.originalName,
      contentType: file.contentType,
      expectedSize: Number(file.expectedSize),
      actualSize: file.actualSize === null ? null : Number(file.actualSize),
      durationMs: file.durationMs,
      etag: file.etag,
      uploadExpiresAt: file.uploadExpiresAt,
      completedAt: file.completedAt,
      createdAt: file.createdAt,
    };
  }

  /**
   * Phase 6: short-lived signed download URL for a gallery/moderation photo.
   * The caller owns the visibility decision (moderation status, gallery
   * consent, publish state); this only presigns. Object keys are passed in
   * so gallery listings can sign a whole page without N+1 file lookups.
   */
  async createGalleryPhotoUrl(
    objectKey: string,
    originalName: string,
    contentType: string,
  ): Promise<{ url: string; expiresInSeconds: number }> {
    return {
      url: await this.storage.createDownloadUrl(objectKey, originalName, contentType),
      expiresInSeconds: this.storage.settings.downloadUrlTtlSeconds,
    };
  }
}
